// ── Optional ChatGPT (OpenAI) engine ─────────────────────────────────
// Admin-only toggle (sidebar → AI Engine). The choice, model and key live in
// localStorage on this device only — same pattern as bar-model.html. When
// active, askGemini/askGeminiVision route through OpenAI first and fall back
// to Gemini on any failure, so students without a key are never affected.
const AI_ENGINE_STORE = { engine: 'sq_ai_engine', key: 'sq_openai_key', model: 'sq_openai_model', imageModel: 'sq_openai_image_model' };
const OPENAI_DEFAULT_MODEL = 'gpt-5.6-sol';
function getAiEngine() { try { return localStorage.getItem(AI_ENGINE_STORE.engine) || 'gemini'; } catch (e) { return 'gemini'; } }
function getOpenAiKey() { try { return (localStorage.getItem(AI_ENGINE_STORE.key) || '').trim(); } catch (e) { return ''; } }
function getOpenAiModel() { try { return localStorage.getItem(AI_ENGINE_STORE.model) || OPENAI_DEFAULT_MODEL; } catch (e) { return OPENAI_DEFAULT_MODEL; } }
function openAiActive() { return getAiEngine() === 'openai' && !!getOpenAiKey(); }

async function askOpenAI(prompt, media, { maxOutputTokens = 512, temperature, json = false } = {}) {
  const model = getOpenAiModel();
  const content = [{ type: 'text', text: prompt }];
  (media || []).forEach((m, i) => {
    if (/^image\//.test(m.mimeType || '')) content.push({ type: 'image_url', image_url: { url: 'data:' + m.mimeType + ';base64,' + m.data, detail: 'high' } });
    else content.push({ type: 'file', file: { filename: 'upload-' + (i + 1) + '.pdf', file_data: 'data:' + (m.mimeType || 'application/pdf') + ';base64,' + m.data } });
  });
  const body = { model, messages: [{ role: 'user', content }], max_completion_tokens: Math.max(1024, maxOutputTokens) };
  if (json) body.response_format = { type: 'json_object' };
  // gpt-5.x models only run at their default temperature; sending one is a 400
  if (temperature !== undefined && !/^gpt-5/.test(model)) body.temperature = temperature;
  const res = await fetch('https://api.openai.com/v1/chat/completions', {
    method: 'POST',
    headers: { 'Content-Type': 'application/json', 'Authorization': 'Bearer ' + getOpenAiKey() },
    body: JSON.stringify(body)
  });
  if (!res.ok) {
    let detail = '';
    try { const ej = await res.json(); detail = ej && ej.error ? ej.error.message : ''; } catch (e) { /* non-JSON error body */ }
    throw new Error('OpenAI API error ' + res.status + (detail ? ': ' + detail : ''));
  }
  const data = await res.json();
  const text = data && data.choices && data.choices[0] && data.choices[0].message && data.choices[0].message.content;
  if (typeof text !== 'string' || !text) throw new Error('OpenAI returned an unexpected response shape.');
  return text.trim();
}

// ── ChatGPT image generation (Realm of Embers TCG → Card Art) ──────────────
// Same key/device-local settings as the text engine, but a separate image
// model (the chat model cannot draw). Two modes:
//   • text only            → the trading-card art
//   • with a reference PNG → the battle avatar, redrawn FROM the card art so
//                            both pictures are unmistakably the same creature.
const OPENAI_IMAGE_DEFAULT_MODEL = 'gpt-image-1';
function getOpenAiImageModel() { try { return localStorage.getItem(AI_ENGINE_STORE.imageModel) || OPENAI_IMAGE_DEFAULT_MODEL; } catch (e) { return OPENAI_IMAGE_DEFAULT_MODEL; } }

function _dataUrlToBlob(dataUrl) {
  const parsed = _parseImageDataUrl(dataUrl);
  if (!parsed) throw new Error('reference image is not an image');
  return new Blob([parsed.bytes], { type: parsed.mime });
}

async function _openAiImageRequest(path, body, isForm) {
  const res = await fetch('https://api.openai.com/v1/images/' + path, {
    method: 'POST',
    headers: Object.assign({ 'Authorization': 'Bearer ' + getOpenAiKey() }, isForm ? {} : { 'Content-Type': 'application/json' }),
    body: isForm ? body : JSON.stringify(body)
  });
  if (!res.ok) {
    let detail = '';
    try { const ej = await res.json(); detail = ej && ej.error ? ej.error.message : ''; } catch (e) { /* non-JSON error body */ }
    const err = new Error('OpenAI image API error ' + res.status + (detail ? ': ' + detail : ''));
    err.status = res.status; err.detail = detail;
    throw err;
  }
  const data = await res.json();
  const item = data && data.data && data.data[0];
  if (item && item.b64_json) return 'data:image/png;base64,' + item.b64_json;
  if (item && item.url) return await _urlToDataUrlRobust(item.url);
  throw new Error('OpenAI did not return an image');
}

// Older image models (and some accounts) reject the newer extras — transparent
// background, output_format, quality — with a 400. Retry once with the bare
// minimum rather than failing the whole batch.
function _isUnsupportedImageParam(e) {
  return !!e && e.status === 400 && /unknown parameter|unsupported|not supported|invalid value|additional properties/i.test(e.detail || e.message || '');
}

async function openAiGenerateImageDataUrl(prompt, { size = '1024x1024', transparent = false, refDataUrl = null, quality = 'high' } = {}) {
  if (!getOpenAiKey()) throw new Error('No OpenAI API key saved on this device');
  const model = getOpenAiImageModel();
  if (refDataUrl) {
    const buildForm = (extras) => {
      const fd = new FormData();
      fd.append('model', model);
      fd.append('prompt', prompt);
      fd.append('size', size);
      fd.append('n', '1');
      fd.append('image', _dataUrlToBlob(refDataUrl), 'reference.png');
      if (extras) {
        fd.append('output_format', 'png');
        fd.append('quality', quality);
        if (transparent) fd.append('background', 'transparent');
      }
      return fd;
    };
    try { return await _openAiImageRequest('edits', buildForm(true), true); }
    catch (e) {
      if (!_isUnsupportedImageParam(e)) throw e;
      return await _openAiImageRequest('edits', buildForm(false), true);
    }
  }
  const base = { model, prompt, size, n: 1 };
  const full = Object.assign({}, base, { output_format: 'png', quality }, transparent ? { background: 'transparent' } : {});
  try { return await _openAiImageRequest('generations', full, false); }
  catch (e) {
    if (!_isUnsupportedImageParam(e)) throw e;
    return await _openAiImageRequest('generations', base, false);
  }
}

// Single swap-point for all model calls. Returns trimmed text.
// thinkingLevel:"minimal" keeps Gemini "thinking" to a minimum so the whole
// token budget goes to the actual answer (faster + cheaper for our short
// tasks). Gemini 3.x rejects the older numeric thinkingBudget with
// 400 INVALID_ARGUMENT.
async function askGemini(prompt, { maxOutputTokens = 512, temperature = 0.3, json = false } = {}) {
  if (openAiActive()) {
    try { return await askOpenAI(prompt, null, { maxOutputTokens, temperature, json }); }
    catch (e) { console.warn('ChatGPT engine failed, falling back to Gemini:', e); }
  }
  if (!geminiModel) throw new Error("AI is not configured yet");
  const generationConfig = { maxOutputTokens, temperature, thinkingConfig: { thinkingLevel: "minimal" } };
  if (json) generationConfig.responseMimeType = "application/json";
  const res = await geminiModel.generateContent({
    contents: [{ role: "user", parts: [{ text: prompt }] }],
    generationConfig
  });
  return (res.response.text() || "").trim();
}

// Tolerant JSON parse for model output (strips code fences, finds the array/object).
function _parseAIJson(raw) {
  let s = (raw || '').trim();
  if (!s) throw new Error('empty AI response — please try again');
  s = s.replace(/^```(?:json)?/i, '').replace(/```$/, '').trim();
  const start = s.search(/[\[{]/);
  if (start > 0) s = s.slice(start);
  try { return JSON.parse(s); }
  catch (firstErr) {
    try { return JSON.parse(_repairAIJson(s)); }
    catch (_) { throw firstErr; }
  }
}
// Best-effort repair for slightly-malformed or TRUNCATED model JSON: escapes
// unescaped inner quotes and raw newlines/tabs inside strings, closes an
// unterminated string, drops a dangling half-written key, balances any open
// brackets, and drops trailing commas — so a broken response still parses.
function _repairAIJson(s) {
  s = String(s || '');
  let out = '', inString = false, escaped = false;
  const closers = [];
  for (let i = 0; i < s.length; i++) {
    const ch = s[i];
    if (inString) {
      if (escaped) { out += ch; escaped = false; continue; }
      if (ch === '\\') { out += ch; escaped = true; continue; }
      if (ch === '"') {
        // Only a real close-quote if what follows continues the JSON
        // structure; otherwise it's an unescaped quote INSIDE the string
        // (e.g. feedback text quoting the word "friction") — escape it.
        let j = i + 1;
        while (j < s.length && ' \t\r\n'.includes(s[j])) j++;
        const nxt = j < s.length ? s[j] : '';
        let close = false;
        if (!nxt || ':}]'.includes(nxt)) close = true;
        else if (nxt === ',') {
          // A real close is followed by the NEXT element after the comma —
          // a quoted key/value, number, object/array or literal. Prose
          // (like: "no", so the toy…) is not, so the quote is internal.
          let k = j + 1;
          while (k < s.length && ' \t\r\n'.includes(s[k])) k++;
          close = k >= s.length || '"{[}]-0123456789'.includes(s[k]) ||
                  /^(true|false|null)\b/.test(s.slice(k, k + 6));
        }
        if (close) { out += ch; inString = false; } else out += '\\"';
        continue;
      }
      if (ch === '\n') { out += '\\n'; continue; }
      if (ch === '\r') { continue; }
      if (ch === '\t') { out += '\\t'; continue; }
      out += ch; continue;
    }
    if (ch === '"') { out += ch; inString = true; continue; }
    if (ch === '{') closers.push('}');
    else if (ch === '[') closers.push(']');
    else if ((ch === '}' || ch === ']') && closers[closers.length - 1] === ch) closers.pop();
    out += ch;
  }
  if (inString) out += '"';
  // A response cut off in the middle of a KEY (e.g. …,"feedb or …,"feedback":)
  // leaves a dangling key that no amount of bracket-closing fixes — drop it.
  out = out.replace(/([{,]\s*)"(?:[^"\\]|\\.)*"\s*:?\s*$/, '$1').replace(/,\s*$/, '');
  while (closers.length) out += closers.pop();
  return out.replace(/,\s*([}\]])/g, '$1');
}

// Cache identical requests for the session so repeats are free/instant.
function _aiHash(str) {
  let h = 5381;
  for (let i = 0; i < str.length; i++) h = ((h << 5) + h + str.charCodeAt(i)) | 0;
  return "ai:" + (h >>> 0).toString(36);
}
async function askGeminiCached(prompt, opts) {
  const key = _aiHash(prompt);
  try { const c = sessionStorage.getItem(key); if (c !== null) return c; } catch (e) {}
  const out = await askGemini(prompt, opts);
  try { sessionStorage.setItem(key, out); } catch (e) {}
  return out;
}
window.__aiReady = () => !!geminiModel || openAiActive();

