function _notesSetStatus(msg) {
  const el = document.getElementById('notesStatus');
  if (el) el.innerHTML = msg ? escapeHtml(msg) : '';
  const btn = document.getElementById('notesUploadBtn');
  if (btn) btn.disabled = !!msg;
}

async function notesHandleFiles(files) {
  files = Array.isArray(files) ? files : [files];
  if (!files.length || !currentUser || currentUser.role !== 'admin') return;
  if (!window.__aiReady || !window.__aiReady()) { showToast("AI isn't set up yet — add your reCAPTCHA site key in the code", 'info'); return; }
  for (const f of files) {
    const ok = f.type === 'application/pdf' || (f.type && f.type.startsWith('image/'));
    if (!ok) { showToast(`“${f.name}” isn't a PDF or image — please choose PDFs and/or images only`, 'error'); return; }
  }
  const totalSize = files.reduce((s, f) => s + f.size, 0);
  if (totalSize > 18 * 1024 * 1024) { showToast('Files are too large together (max ~18 MB in one upload) — split them into two uploads', 'error'); return; }
  const comment = (document.getElementById('notesComment') ? document.getElementById('notesComment').value : '').trim();
  _notesSetStatus(files.length === 1
    ? `⏳ Reading “${files[0].name}” and extracting topics, keywords and marking standards…`
    : `⏳ Reading ${files.length} files together and extracting topics, keywords and marking standards…`);
  try {
    const media = [];
    for (const f of files) media.push({ mimeType: f.type, data: await _fileToBase64(f) });
    const topics = currentTopics();
    const docDesc = files.length === 1
      ? `the attached ${files[0].type === 'application/pdf' ? 'PDF' : 'image'}`
      : `the ${files.length} attached files, which together form ONE set of notes — read them in the order attached and analyse them as a single document`;
    const prompt =
      `You are analysing a science teacher's reference notes (${docDesc}) for a Singapore primary-school (PSLE) science question bank.\n` +
      (comment ? `The teacher says about this document: "${comment}".\n` : '') +
      `Extract the teaching content and return ONLY JSON:\n` +
      `{"title":"short descriptive title for these notes",` +
      `"topics":["every syllabus topic this document covers, chosen from EXACTLY: ${topics.join('; ')}"],` +
      `"keywords":["the EXACT science keywords and key phrases students are expected to use in exam answers, most important first — copy the document's own wording"],` +
      `"markingStandards":"how answers should be phrased and marked according to this document: required sentence patterns, terms that MUST appear for full marks, acceptable alternatives, common mistakes to penalise (plain text, at most 1200 characters)",` +
      `"keyFacts":"the key facts and concepts taught, one short line each, separated by \\n (plain text, at most 1500 characters)"}\n` +
      `Rules:\n- 10 to 40 keywords, each 1-4 words, no duplicates, most important first.\n- "topics" only from the given list; include every topic the document genuinely covers.\n- Plain text only, no markdown.`;
    const raw = await askGeminiVision(prompt, media, { maxOutputTokens: 3072, json: true });
    const p = _parseAIJson(raw) || {};
    const topicLc = new Map(topics.map(t => [t.toLowerCase().trim(), t]));
    const note = {
      title: String(p.title || files[0].name || 'Untitled notes').slice(0, 140),
      fileName: files.map(f => f.name || '').filter(Boolean).join(', '),
      comment,
      topics: (Array.isArray(p.topics) ? p.topics : []).map(t => topicLc.get(String(t).toLowerCase().trim())).filter(Boolean),
      keywords: (Array.isArray(p.keywords) ? p.keywords : []).map(s => String(s).trim()).filter(Boolean).slice(0, 60),
      markingStandards: String(p.markingStandards || '').slice(0, 1600),
      keyFacts: String(p.keyFacts || '').slice(0, 2000),
      createdAt: new Date().toISOString(),
      updatedAt: new Date().toISOString()
    };
    const id = 'note_' + Date.now().toString(36) + Math.random().toString(36).slice(2, 7);
    await setDoc(doc(db, 'users', currentUser.uid, 'teachingNotes', id), note);
    note.id = id;
    teachingNotes.unshift(note);
    _notesSetStatus('');
    notesRenderBody();
    showToast(`✅ “${note.title}” analysed — ${note.keywords.length} keywords extracted. The AI will use them from now on.`, 'success');
  } catch (e) {
    console.error('notes analysis failed', e);
    _notesSetStatus('');
    showToast('Analysis failed: ' + (e && e.message ? e.message : e), 'error');
  }
}

let _noteEditId = null;
function notesEditOpen(id) {
  const n = teachingNotes.find(x => x.id === id);
  if (!n) return;
  _noteEditId = id;
  document.getElementById('nteTitle').value = n.title || '';
  document.getElementById('nteTopics').value = (n.topics || []).join(', ');
  document.getElementById('nteKeywords').value = (n.keywords || []).join(', ');
  document.getElementById('nteStandards').value = n.markingStandards || '';
  document.getElementById('nteFacts').value = n.keyFacts || '';
  document.getElementById('nteComment').value = n.comment || '';
  document.getElementById('noteEditOverlay').classList.add('active');
}
function notesEditClose() {
  document.getElementById('noteEditOverlay').classList.remove('active');
  _noteEditId = null;
}
async function notesEditSave() {
  const n = teachingNotes.find(x => x.id === _noteEditId);
  if (!n) { notesEditClose(); return; }
  const topics = currentTopics();
  const topicLc = new Map(topics.map(t => [t.toLowerCase().trim(), t]));
  n.title = (document.getElementById('nteTitle').value || '').trim().slice(0, 140) || n.fileName || 'Untitled notes';
  n.topics = (document.getElementById('nteTopics').value || '').split(',').map(s => topicLc.get(s.toLowerCase().trim())).filter(Boolean);
  n.keywords = (document.getElementById('nteKeywords').value || '').split(/[,\n]/).map(s => s.trim()).filter(Boolean).slice(0, 60);
  n.markingStandards = (document.getElementById('nteStandards').value || '').trim().slice(0, 1600);
  n.keyFacts = (document.getElementById('nteFacts').value || '').trim().slice(0, 2000);
  n.comment = (document.getElementById('nteComment').value || '').trim();
  n.updatedAt = new Date().toISOString();
  try {
    const { id, ...data } = n;
    await setDoc(doc(db, 'users', currentUser.uid, 'teachingNotes', id), data, { merge: false });
    notesEditClose();
    notesRenderBody();
    showToast('Note updated', 'success');
  } catch (e) { showToast('Could not save: ' + (e && e.message ? e.message : e), 'error'); }
}
async function notesDelete(id) {
  const n = teachingNotes.find(x => x.id === id);
  if (!n) return;
  if (!confirm(`Delete “${n.title || n.fileName || 'this note'}”?\n\nThe AI will stop using its keywords and marking standards.`)) return;
  try {
    await deleteDoc(doc(db, 'users', currentUser.uid, 'teachingNotes', id));
    teachingNotes = teachingNotes.filter(x => x.id !== id);
    notesRenderBody();
    showToast('Note deleted', 'info');
  } catch (e) { showToast('Could not delete: ' + (e && e.message ? e.message : e), 'error'); }
}

