let _lastTopicValue = 'Heat';
document.getElementById('topicSelect').addEventListener('change', function() {
  if (this.value === '__custom__') {
    // Restore the previous real selection, then open the topic manager.
    this.value = (_lastTopicValue && Array.from(this.options).some(o => o.value === _lastTopicValue && o.value !== '__custom__')) ? _lastTopicValue : (currentTopics()[0] || '');
    openManageTopics();
  } else {
    _lastTopicValue = this.value;
  }
});

