// Schedule question from create page (saves to bank then opens schedule dialog)
function openScheduleFromCreate() {
  if (blocks.length === 0) {
    showToast('Add some blocks first', 'error');
    return;
  }

  // Collect and save the question to bank first
  const q = collectQuestionData();
  questionBank.push(q);
  saveQuestion(q);
  updateCounts();
  renderQuestionBank();

  // Now open the schedule dialog with this question pre-selected
  openScheduleQuestionDialog();

  // Auto-select this question in the schedule dialog after a brief delay
  setTimeout(() => {
    selectedScheduleQuestionId = q.id;
    const infoEl = document.getElementById('scheduleSelectedInfo');
    const cardEl = document.getElementById('scheduleSelectedCard');
    if (infoEl) infoEl.style.display = '';
    if (cardEl) cardEl.innerHTML = `<strong>${escapeHtml(q.title)}</strong><br><span style="font-size:0.8rem;color:var(--text-muted);">${escapeHtml(q.category)} &middot; ${escapeHtml(q.topic)}</span>`;
  }, 200);

  clearForm();
  showToast('Question added to bank. Now set the scheduled release date.', 'info');
}

function getYouTubeEmbedUrl(url) {
  if (!url) return null;
  const regex = /(?:youtube\.com\/(?:watch\?v=|embed\/)|youtu\.be\/)([a-zA-Z0-9_-]{11})/;
  const match = url.match(regex);
  return match ? `https://www.youtube.com/embed/${match[1]}` : null;
}

function transformImageUrl(url) {
  if (!url) return url;
  try {
    const u = new URL(url);
    // Dropbox: convert share links to direct download
    if (u.hostname.endsWith('dropbox.com') && u.hostname !== 'dl.dropboxusercontent.com') {
      u.hostname = 'dl.dropboxusercontent.com';
      u.searchParams.delete('dl');
      return u.toString();
    }
    // Google Drive: convert share/view links to direct image
    if (u.hostname === 'drive.google.com') {
      let fileId = null;
      const pathMatch = u.pathname.match(/\/file\/d\/([^/]+)/);
      if (pathMatch) fileId = pathMatch[1];
      if (!fileId) {
        fileId = u.searchParams.get('id');
      }
      if (fileId) {
        return `https://drive.google.com/uc?export=view&id=${fileId}`;
      }
    }
  } catch (e) {}
  return url;
}

function handleImgError(img) {
  // Retry once with a cache-bust param
  if (!img.dataset.retried) {
    img.dataset.retried = '1';
    const sep = img.src.includes('?') ? '&' : '?';
    img.src = img.src + sep + '_retry=' + Date.now();
    return;
  }
  // Show placeholder after retry failure
  const wrapper = document.createElement('div');
  wrapper.style.cssText = 'padding:16px;text-align:center;color:var(--text-muted);font-size:0.82rem;border:1.5px dashed var(--border);border-radius:8px;background:var(--surface-alt);';
  wrapper.innerHTML = '<div style="font-size:1.5rem;margin-bottom:4px;">&#x1F5BC;&#xFE0F;</div>Image could not be loaded';
  img.parentNode.replaceChild(wrapper, img);
}

// =====================================================================
// IMAGE PRELOADER
// =====================================================================
// Collects all image URLs from a list of questions
function collectImageUrls(questions) {
  const urls = new Set();
  questions.forEach(q => {
    if (!q.blocks) return;
    q.blocks.forEach(block => {
      if (block.type === 'image' && block.url) {
        urls.add(transformImageUrl(block.url));
      }
      // Also scan text/answer content for inline <img> tags
      const htmlFields = [];
      if (block.type === 'text' && block.content) htmlFields.push(block.content);
      if (block.type === 'answer') {
        if (block.claim) htmlFields.push(block.claim);
        if (block.evidence) htmlFields.push(block.evidence);
        if (block.reasoning) htmlFields.push(block.reasoning);
      }
      if (block.type === 'plainanswer' && block.content) htmlFields.push(block.content);
      if (block.type === 'explanation' && block.content) htmlFields.push(block.content);
      htmlFields.forEach(html => {
        const imgRe = /<img[^>]+src=["']([^"']+)["']/gi;
        let m;
        while ((m = imgRe.exec(html)) !== null) {
          urls.add(transformImageUrl(m[1]));
        }
      });
    });
  });
  return Array.from(urls);
}

// Preloads images with progress UI, returns a Promise
function preloadImages(urls) {
  return new Promise(resolve => {
    if (urls.length === 0) { resolve(); return; }

    const overlay = document.getElementById('preloadOverlay');
    const fill = document.getElementById('preloadProgressFill');
    const countEl = document.getElementById('preloadCount');
    const textEl = document.getElementById('preloadText');

    overlay.style.display = '';
    overlay.classList.remove('hidden');
    textEl.textContent = 'Loading images...';
    fill.style.width = '0%';
    countEl.textContent = `0 / ${urls.length}`;

    let loaded = 0;
    const timeout = 8000; // 8s max per image

    function tick() {
      loaded++;
      const pct = Math.round((loaded / urls.length) * 100);
      fill.style.width = pct + '%';
      countEl.textContent = `${loaded} / ${urls.length}`;
      if (loaded >= urls.length) finish();
    }

    function finish() {
      textEl.textContent = 'Ready!';
      fill.style.width = '100%';
      setTimeout(() => {
        overlay.classList.add('hidden');
        setTimeout(() => { overlay.style.display = 'none'; }, 400);
        resolve();
      }, 300);
    }

    urls.forEach(url => {
      const img = new Image();
      let done = false;
      const timer = setTimeout(() => {
        if (!done) { done = true; tick(); } // count as loaded after timeout
      }, timeout);
      img.onload = () => { if (!done) { done = true; clearTimeout(timer); tick(); } };
      img.onerror = () => { if (!done) { done = true; clearTimeout(timer); tick(); } };
      img.src = url;
    });
  });
}

// Preload all images from the full question bank
async function preloadAllQuestionImages() {
  const urls = collectImageUrls(questionBank);
  if (urls.length === 0) return;
  await preloadImages(urls);
}

// Preload images from a specific question queue (for practice sessions)
async function preloadQueueImages(queue) {
  const urls = collectImageUrls(queue);
  if (urls.length === 0) return;
  await preloadImages(urls);
}

// Quietly warm the browser image cache in the BACKGROUND (no overlay, on idle,
// a few at a time). Used for admins so images in the Question Bank, Question
// Doctor and Past Papers appear instantly instead of loading on demand.
const _warmedImages = new Set();
const _warmImageQueue = [];
let _warmImageActive = 0;
function warmImageCacheInBackground(questions) {
  try {
    collectImageUrls(questions || []).forEach(u => {
      if (u && !_warmedImages.has(u)) { _warmedImages.add(u); _warmImageQueue.push(u); }
    });
    _pumpWarmImages();
  } catch (e) { console.warn('warm image cache', e); }
}
function _pumpWarmImages() {
  const CONC = 6;
  const schedule = fn => (window.requestIdleCallback ? requestIdleCallback(fn, { timeout: 2000 }) : setTimeout(fn, 60));
  while (_warmImageActive < CONC && _warmImageQueue.length) {
    const url = _warmImageQueue.shift();
    _warmImageActive++;
    schedule(() => {
      const img = new Image();
      const done = () => { _warmImageActive--; _pumpWarmImages(); };
      img.onload = done; img.onerror = done;
      try { img.decoding = 'async'; img.src = url; } catch (_) { done(); }
    });
  }
}

// =====================================================================
// SAVE / LOAD QUESTION
// =====================================================================

// Firestore forbids nested arrays (array-of-arrays).
// Convert table block.data  [[r0c0, r0c1], [r1c0, r1c1]]
//   →  { "0": { "0": r0c0, "1": r0c1 }, "1": { "0": r1c0, "1": r1c1 } }
function tableDataToFirestore(data) {
  if (!Array.isArray(data)) return data; // already converted
  const out = {};
  data.forEach((row, r) => {
    out[String(r)] = {};
    const rowArr = Array.isArray(row) ? row : Object.values(row);
    rowArr.forEach((cell, c) => {
      out[String(r)][String(c)] = cell ?? '';
    });
  });
  return out;
}

// Reverse: convert Firestore object-of-objects back to array-of-arrays
function tableDataFromFirestore(data) {
  if (Array.isArray(data)) return data; // already in array form
  if (!data || typeof data !== 'object') return [];
  return Object.keys(data)
    .sort((a, b) => parseInt(a) - parseInt(b))
    .map(r => {
      const row = data[r];
      if (Array.isArray(row)) return row;
      if (!row || typeof row !== 'object') return [];
      return Object.keys(row)
        .sort((a, b) => parseInt(a) - parseInt(b))
        .map(c => row[c] ?? '');
    });
}

// Normalise a question loaded from Firestore back to in-memory format
function normalizeLoadedQuestion(q) {
  if (!q || !Array.isArray(q.blocks)) return q;
  q.category = normalizeCategoryValue(q.category);
  applyMcqCategory(q); // MCQ questions always sit in the Multiple Choice Question category
  // Optional 2nd category: normalise it, and drop it if it just duplicates the primary.
  if (q.category2 && typeof q.category2 === 'string') {
    const c2 = normalizeCategoryValue(q.category2.trim());
    q.category2 = (c2 && c2 !== q.category) ? c2 : '';
  }
  if (q.topic2 && typeof q.topic2 === 'string' && q.topic2.trim() === (q.topic || '').trim()) q.topic2 = '';
  q.blocks.forEach(block => {
    if (block.type !== 'table') return;
    // Restore data
    if (block.data && !Array.isArray(block.data)) {
      block.data = tableDataFromFirestore(block.data);
    }
    if (!block.data) block.data = [];
    // Restore colWidths (saved as object to avoid Firestore sparse-array issues)
    if (block.colWidths && !Array.isArray(block.colWidths)) {
      const arr = Array(block.cols || 3).fill(null);
      Object.keys(block.colWidths).forEach(i => { arr[parseInt(i)] = block.colWidths[i]; });
      block.colWidths = arr;
    }
    if (!block.colWidths) block.colWidths = Array(block.cols || 3).fill(null);
    if (!block.rowHeights) block.rowHeights = {};
    if (!block.merges) block.merges = [];
    if (!block.cellStyles) block.cellStyles = {};
    if (!block.cellPadding) block.cellPadding = {};
  });
  return q;
}

// Pull the latest typed content from the editor DOM into blocks[], so that
// saving AND every AI-generate feature work from the question exactly as it
// stands (what the preview would show), never a stale copy.
function syncEditorDomToBlocks() {
  // Sync contenteditable text/explanation blocks from DOM → blocks[]
  document.querySelectorAll('.content-editable[data-block-id]').forEach(el => {
    const bid = el.dataset.blockId;
    const field = el.dataset.field;
    const block = blocks.find(b => b.id === bid);
    if (block && field) block[field] = el.innerHTML;
  });

  // Sync table cells from DOM → blocks[].data
  document.querySelectorAll('[data-table-block]').forEach(table => {
    const bid = table.dataset.tableBlock;
    const block = blocks.find(b => b.id === bid);
    if (!block) return;
    table.querySelectorAll('td[data-row][data-col]').forEach(cell => {
      const r = parseInt(cell.dataset.row);
      const c = parseInt(cell.dataset.col);
        if (block.data[r]) block.data[r][c] = cell.innerHTML;
    });
  });
}

function collectQuestionData() {
  syncEditorDomToBlocks();

  // Deep-clone blocks so we don't mutate the live editor state
  const blocksClone = JSON.parse(JSON.stringify(blocks));

  // Convert nested arrays → Firestore-safe objects for every table block
  blocksClone.forEach(block => {
    if (block.type !== 'table') return;
    if (Array.isArray(block.data)) {
      block.data = tableDataToFirestore(block.data);
    }
    // colWidths: store as object so Firestore won't reject sparse arrays
    if (Array.isArray(block.colWidths)) {
      const cw = {};
      block.colWidths.forEach((w, i) => { if (w !== null && w !== undefined) cw[String(i)] = w; });
      block.colWidths = cw;
    }
  });
  
  const primaryCat = normalizeCategoryValue(document.getElementById('categorySelect').value);
  const primaryTopic = document.getElementById('topicSelect').value;
  const rawCat2 = (document.getElementById('categorySelect2')?.value || '').trim();
  const cat2 = rawCat2 ? normalizeCategoryValue(rawCat2) : '';
  const rawTopic2 = (document.getElementById('topicSelect2')?.value || '').trim();
  return applyMcqCategory({
    id: 'q_' + Date.now() + '_' + Math.random().toString(36).substr(2, 6),
    title: document.getElementById('questionTitle').value || 'Untitled',
    category: primaryCat,
    category2: (cat2 && cat2 !== primaryCat) ? cat2 : '',
    topic: primaryTopic,
    topic2: (rawTopic2 && rawTopic2 !== primaryTopic) ? rawTopic2 : '',
    markingGuide: (document.getElementById('questionMarkingGuide')?.value || '').trim(),
    answerKeyNote: (document.getElementById('questionAnswerKeyNote')?.value || '').trim(),
    answerKeyImage: (document.getElementById('questionAnswerKeyImage')?.value || '').trim(),
    annotation: !!(document.getElementById('questionAnnotation') && document.getElementById('questionAnnotation').checked),
    notInSyllabus: !!(document.getElementById('questionNotInSyllabus') && document.getElementById('questionNotInSyllabus').checked),
    tags: _snapTagsToBank(parseTagInput(document.getElementById('questionTags')?.value || '')),
    blocks: blocksClone,
    blanks: JSON.parse(JSON.stringify(selectedBlanks)),
    createdAt: new Date().toISOString(),
    createdBy: currentUser?.name || 'Admin'
  });
}

function setEditMode(isEditing) {
  const title = document.getElementById('createPageTitle');
  const subtitle = document.getElementById('createPageSubtitle');
  const createActions = document.getElementById('createModeActions');
  const editActions = document.getElementById('editModeActions');
  const regenBtn = document.getElementById('regenInlineBtn');
  if (isEditing) {
    title.textContent = 'Edit Question';
    subtitle.textContent = 'Modify and save your question';
    createActions.style.display = 'none';
    editActions.style.display = '';
    if (regenBtn) regenBtn.style.display = '';
    _syncBackToPapersBtn();
  } else {
    title.textContent = 'Create Question';
    subtitle.textContent = 'Build a question with blocks. Answers and blanks are optional — every question is marked by AI.';
    createActions.style.display = '';
    editActions.style.display = 'none';
    if (regenBtn) regenBtn.style.display = 'none';
    const b = document.getElementById('backToPapersBtn'); if (b) b.style.display = 'none';
  }
}

function addToBank() {
  if (blocks.length === 0) {
    showToast('Add some blocks before saving', 'error');
    return;
  }
  const q = collectQuestionData();
  questionBank.push(q);
  updateCounts();
  // Reset form right away so user cannot double-add
  blocks = [];
  selectedBlanks = {};
  currentEditingQuestion = null;
  renderBlocks();
  renderQuestionBank();
  showToast('Question added to bank ✓', 'success');
  if (window.ppHasPendingAttach && window.ppHasPendingAttach()) ppConsumePendingAttach(q, false);
  else navigateTo('bank');
  saveQuestion(q); // async, non-blocking
}

// Everything collectQuestionData() builds from the editor form. Anything else
// on a stored question (provenance, measured difficulty, flags, future fields)
// has no field in the editor, so a save would silently drop it.
// 'tags' MUST be in here: without it, carryOverQuestionMeta below would restore
// the old tags every time an admin cleared the box, and a tag could never be
// removed.
const EDITOR_OWNED_QUESTION_FIELDS = new Set([
  'id', 'title', 'category', 'category2', 'topic', 'topic2', 'markingGuide',
  'answerKeyNote', 'answerKeyImage', 'annotation', 'notInSyllabus', 'tags',
  'blocks', 'blanks', 'createdAt', 'createdBy',
]);

// An edited question is rebuilt from scratch by collectQuestionData(), so every
// stored field the editor does NOT own (source, concepts, q.usage, …) would be
// lost on save. Carry them all over from the stored copy — an allowlist, not a
// hand-maintained list of names, so a new field can never quietly go missing.
function carryOverQuestionMeta(q) {
  const prev = questionBank.find(qb => qb.id === q.id) || vettingList.find(v => v.id === q.id);
  if (!prev) return;
  Object.keys(prev).forEach(k => {
    if (EDITOR_OWNED_QUESTION_FIELDS.has(k)) return;
    if (q[k] === undefined) q[k] = prev[k];
  });
  if (prev.createdAt) q.createdAt = prev.createdAt;   // editor stamps a fresh one
}

function saveEditedQuestion() {
  if (blocks.length === 0) {
    showToast('Add some blocks before saving', 'error');
    return;
  }
  if (!currentEditingQuestion) {
    showToast('No question being edited', 'error');
    return;
  }
  const q = collectQuestionData();
    q.id = currentEditingQuestion;
  carryOverQuestionMeta(q);

  let savedToVetting = false;
  const qIdx = questionBank.findIndex(qb => qb.id === currentEditingQuestion);
  if (qIdx !== -1) {
    questionBank[qIdx] = q;
  } else {
    const vIdx = vettingList.findIndex(v => v.id === currentEditingQuestion);
    if (vIdx !== -1) {
      vettingList[vIdx] = q;
      savedToVetting = true;
    } else {
      questionBank.push(q);
    }
  }

  currentEditingQuestion = null;
  setEditMode(false);
  updateCounts();
  renderQuestionBank();
  showToast('Question saved ✓', 'success');
  _afterEditNavigate();
  if (savedToVetting) saveVettingQuestion(q);
  else saveQuestion(q);
}

// Edit mode: commit the current edits straight into the Question Bank (the live
// database students see). If the question is in the vetting list, it's approved
// out of vetting in the same step — no separate trip back to approve it.
function saveEditToBank() {
  if (blocks.length === 0) { showToast('Add some blocks before saving', 'error'); return; }
  if (!currentEditingQuestion) { showToast('No question being edited', 'error'); return; }
  const id = currentEditingQuestion;
  const q = collectQuestionData();
  q.id = id;
  carryOverQuestionMeta(q);
  q.status = 'approved';

  const wasVetting = vettingList.some(v => v.id === id);
  if (wasVetting) {
    vettingList = vettingList.filter(v => v.id !== id);
    // Keep an approved question in its original owner's bank, like approveVetting.
    if (_ownerUidByVettingId[id]) _ownerUidByQuestionId[id] = _ownerUidByVettingId[id];
  }
  const bIdx = questionBank.findIndex(qb => qb.id === id);
  if (bIdx !== -1) questionBank[bIdx] = q; else questionBank.push(q);
  _rapidJustAdded.delete(id);

  currentEditingQuestion = null;
  setEditMode(false);
  blocks = [];
  selectedBlanks = {};
  renderBlocks();
  updateCounts();
  renderQuestionBank();
  renderVettingList();
  showToast('Saved to question bank ✓', 'success');
  _afterEditNavigate();
  saveQuestion(q);                       // upsert into the questions subcollection
  if (wasVetting) deleteVettingDoc(id);  // remove from the vetting subcollection
}

function cancelEdit() {
  const backDest = _editReturnPage === 'papers' ? 'PSLE Papers'
    : _editReturnPage === 'vetting' ? 'the vetting list'
    : (_editReturnPage === 'myworksheets' || _editReturnPage === 'worksheet') ? 'the worksheet preview'
    : 'the question bank';
  showConfirm('Cancel Edit', `Discard changes and go back to ${backDest}?`, () => {
    currentEditingQuestion = null;
    setEditMode(false);
    blocks = [];
    selectedBlanks = {};
    renderBlocks();
    _afterEditNavigate();
  });
}

function addToVetting() {
  if (blocks.length === 0) {
    showToast('Add some blocks before saving', 'error');
    return;
  }
  const q = collectQuestionData();
  q.status = 'pending';
  vettingList.push(q);
  updateCounts();
  // Reset form right away so user cannot double-add
  blocks = [];
  selectedBlanks = {};
  currentEditingQuestion = null;
  renderBlocks();
  renderVettingList();
  showToast('Question added to vetting list ✓', 'success');
  if (window.ppHasPendingAttach && window.ppHasPendingAttach()) ppConsumePendingAttach(q, true);
  else navigateTo('vetting');
  saveVettingQuestion(q); // async, non-blocking
}

function clearForm() {
  showConfirm('Clear Form', 'This will remove all blocks and reset the form. Are you sure?', () => {
    blocks = [];
    selectedBlanks = {};
    currentEditingQuestion = null;
    document.getElementById('questionTitle').value = '';
    document.getElementById('categorySelect').value = 'CER';
    document.getElementById('topicSelect').value = 'Heat';
    const cs2 = document.getElementById('categorySelect2'); if (cs2) cs2.value = '';
    const ts2 = document.getElementById('topicSelect2'); if (ts2) ts2.value = '';
  if (typeof _setAnswerKeyFields === 'function') _setAnswerKeyFields('', '');
    const mgEl = document.getElementById('questionMarkingGuide');
    if (mgEl) mgEl.value = '';
    const annEl = document.getElementById('questionAnnotation');
    if (annEl) annEl.checked = false;
    _setAnswerKeyFields('', '');
    const nisEl = document.getElementById('questionNotInSyllabus');
    if (nisEl) nisEl.checked = false;
    setQuestionTagsField(null);
    _hideDupBanner();
    renderBlocks();
    setEditMode(false);
    showToast('Form cleared', 'info');
  });
}

// =====================================================================
// QUESTION BANK RENDERING
// =====================================================================
function stripHtmlToText(html) {
  if (!html) return '';
  return String(html)
    .replace(/<[^>]*>/g, ' ')
    .replace(/&nbsp;/gi, ' ')
    .replace(/\s+/g, ' ')
    .trim();
}

function extractQuestionSearchText(q) {
  const parts = [q.title || '', q.topic || '', qSecondaryTopic(q), q.category || '', qSecondaryCategory(q), getTopicLevel(q.topic || ''), questionSource(q)];
  parts.push(qTagList(q).join(' '));   // searching "elastic spring" finds everything tagged with it
  (q.blocks || []).forEach(block => {
    if (!block || !block.type) return;
    if (block.type === 'text') parts.push(stripHtmlToText(block.content));
    else if (block.type === 'image') parts.push(stripHtmlToText(block.caption));
    else if (block.type === 'video') {
      parts.push(stripHtmlToText(block.title));
      parts.push(stripHtmlToText(block.description));
    } else if (block.type === 'answer') {
      parts.push(stripHtmlToText(block.claim));
      parts.push(stripHtmlToText(block.evidence));
      parts.push(stripHtmlToText(block.reasoning));
    } else if (block.type === 'table') {
      if (Array.isArray(block.data)) {
        block.data.forEach(row => {
          if (Array.isArray(row)) row.forEach(cell => parts.push(stripHtmlToText(cell)));
        });
      }
    } else if (block.type === 'part') {
      parts.push(block.label || '');
      parts.push(stripHtmlToText(block.content));
    } else if (block.type === 'mcq') {
      (block.options || []).forEach(o => parts.push(stripHtmlToText(o.text)));
    } else if (block.type === 'answerLine') {
      parts.push(block.label || '');
      parts.push(stripHtmlToText(block.answer));
    } else if (block.type === 'commonMistake') {
      parts.push(block.title || '');
      parts.push(stripHtmlToText(block.text));
    } else if (block.type === 'studentAnswer') {
      parts.push(stripHtmlToText(block.answer));
    } else if (block.type === 'answerKey') {
      parts.push(stripHtmlToText(block.text));
    } else if (block.type === 'fillblank') {
      // [[answer]] markers become plain words so the blanked answers are searchable too
      parts.push(stripHtmlToText(String(block.text || '').replace(/\[\[|\]\]/g, ' ')));
    }
  });
  return parts.join(' ').toLowerCase();
}

function parseSearchTokens(raw) {
  const tokens = [];
  const re = /"([^"]+)"|(\S+)/g;
  let match;
  while ((match = re.exec(raw)) !== null) {
    const token = (match[1] || match[2] || '').trim().toLowerCase();
    if (token) tokens.push(token);
  }
  return tokens;
}

// ---- AI question search: rank the bank by a natural-language instruction ----
let bankAiRanking = null;   // Map(question id -> relevance score 0-100), null when inactive
let bankAiBusy = false;

function _bankAiStatus(msg, isError = false) {
  const el = document.getElementById('bankAiSearchStatus');
  if (!el) return;
  if (!msg) { el.style.display = 'none'; el.textContent = ''; return; }
  el.style.display = 'block';
  el.classList.toggle('error', isError);
  el.textContent = msg;
}

function _bankAiSnippet(q) {
  return extractQuestionSearchText(q).slice(0, 240);
}

async function runBankAiSearch() {
  const instruction = (document.getElementById('bankAiSearch')?.value || '').trim();
  if (!instruction) { _bankAiStatus('Type an instruction first, e.g. "find all questions that involve expansion of objects".', true); return; }
  if (bankAiBusy) return;
  if (!geminiModel) { _bankAiStatus('AI is not ready yet — please wait a moment and try again.', true); return; }
  if (questionBank.length === 0) { _bankAiStatus('The question bank is empty.', true); return; }

  bankAiBusy = true;
  const btn = document.getElementById('bankAiSearchBtn');
  if (btn) { btn.disabled = true; btn.textContent = 'Searching…'; }
  // Small batches keep each JSON response well under the model's output-token
  // cap — a big batch with many matches used to overflow and truncate the JSON,
  // which then failed to parse and sank the whole search.
  const CHUNK = 40;
  const scores = new Map();
  let failedChunks = 0, totalChunks = 0;
  try {
    for (let i = 0; i < questionBank.length; i += CHUNK) {
      const batch = questionBank.slice(i, i + CHUNK);
      totalChunks++;
      _bankAiStatus(`AI is reading the bank… (${Math.min(i + CHUNK, questionBank.length)}/${questionBank.length} questions)`);
      const lines = batch.map(q => `${q.id} | ${_bankAiSnippet(q)}`).join('\n');
      const prompt = `You are helping a science teacher search a question bank.
Teacher's instruction: "${instruction}"

Below is a list of questions, one per line, in the format: id | text.
Find every question that matches the instruction and rate how relevant each one is.

Rules:
- Return ONLY a JSON array, nothing else — no markdown, no commentary.
- Each element must be exactly: {"id":"<id copied exactly from the list>","score":<integer 1-100, 100 = most relevant>}.
- Include ONLY genuinely relevant questions; omit the rest. If nothing matches, return [].

Questions:
${lines}`;
      let data;
      try {
        const raw = await askGemini(prompt, { maxOutputTokens: 8192, temperature: 0, json: true });
        data = _parseAIJson(raw);
      } catch (chunkErr) {
        // One unparseable batch (e.g. a truncated response) shouldn't sink the
        // whole search — skip it and keep going with the rest.
        console.warn('AI search: skipping a batch that failed to parse', chunkErr);
        failedChunks++;
        continue;
      }
      const arr = Array.isArray(data) ? data : (data && Array.isArray(data.results) ? data.results : []);
      const batchIds = new Set(batch.map(q => q.id));
      arr.forEach(item => {
        if (!item || typeof item.id !== 'string' || !batchIds.has(item.id)) return;
        let score = Math.round(Number(item.score));
        if (!Number.isFinite(score)) score = 50;   // ranked but unscored → middling relevance
        score = Math.max(1, Math.min(100, score));
        scores.set(item.id, score);
      });
    }
    if (failedChunks === totalChunks) {
      // Every batch failed — surface it as an error rather than "no matches".
      _bankAiStatus('AI search could not be completed right now — please try again.', true);
      return;
    }
    bankAiRanking = scores;
    const clearBtn = document.getElementById('bankAiClearBtn');
    if (clearBtn) clearBtn.style.display = '';
    const partialNote = failedChunks ? ` (${failedChunks} of ${totalChunks} batches couldn't be read — results may be incomplete)` : '';
    _bankAiStatus(scores.size === 0
      ? `AI found no questions matching "${instruction}". Try rephrasing your instruction.${partialNote}`
      : `AI found ${scores.size} relevant question${scores.size === 1 ? '' : 's'} for "${instruction}" — sorted from most to least relevant.${partialNote}`);
    renderQuestionBank();
  } catch (err) {
    console.error('AI bank search failed', err);
    _bankAiStatus(`AI search failed: ${err.message || err}. Please try again.`, true);
  } finally {
    bankAiBusy = false;
    if (btn) { btn.disabled = false; btn.textContent = 'AI Search'; }
  }
}

function clearBankAiSearch() {
  bankAiRanking = null;
  const input = document.getElementById('bankAiSearch');
  if (input) input.value = '';
  const clearBtn = document.getElementById('bankAiClearBtn');
  if (clearBtn) clearBtn.style.display = 'none';
  _bankAiStatus('');
  renderQuestionBank();
}

// =====================================================================
// DIFFICULTY — measured from real student usage, nothing else.
//
// The difficulty of a question is the percentage of marks real students have
// actually earned on it: every attempt ever logged to the `questionAttempts`
// collection, added up. High percentage = students get it right = easy. Low
// percentage = hard. No simulation, no AI estimate, no hand-set rating — if
// nobody has attempted a question, it simply has no difficulty yet.
//
// Every attempt row carries { questionId, score, totalBlanks, uid }, and rows
// have been written since the app went live, so one pass over the collection
// gives the full backdated picture for every question in the bank.
//
// The aggregate is cached in memory for the session, and written back onto each
// question doc as q.usage so the number lives in the database next to the
// question (and is available to anything that reads a question without doing a
// collection scan).
//
// Deliberately NOT wired into rpgQuestionDifficulty: that drives gold/XP, and
// silently repricing every reward in the game is a separate decision.
// =====================================================================
const USAGE_MIN_ATTEMPTS = 3;   // below this the number is shown but flagged as thin

// Bands only name the colour for the filter dropdown; the card tint itself is a
// continuous green→red scale so "very green" really is very green.
const USAGE_BANDS = [
  { min: 85, band: 'very easy' },
  { min: 70, band: 'easy'      },
  { min: 50, band: 'medium'    },
  { min: 30, band: 'hard'      },
  { min: 0,  band: 'very hard' },
];
function usageBandFor(pct) { return (USAGE_BANDS.find(b => pct >= b.min) || USAGE_BANDS[USAGE_BANDS.length - 1]).band; }

// Green at 100% correct (easy) → red at 0% (hard). The curve is deliberately
// bent (^1.6) rather than linear: a straight mapping leaves anything under half
// marks looking beige, when a question most students fail should look alarming.
// So red arrives early — 30% correct is already firmly red, 50% is orange, and
// only genuinely well-answered questions get the strong greens.
function usageHue(pct) { return Math.round(130 * Math.pow(Math.max(0, Math.min(100, pct)) / 100, 1.6)); }
function usageColor(pct)    { return `hsl(${usageHue(pct)} 72% 31%)`; }
function usageTint(pct)     { return `hsl(${usageHue(pct)} 78% 93%)`; }
function usageEdge(pct)     { return `hsl(${usageHue(pct)} 62% 58%)`; }

// { '<questionId>': { attempts, students, earned, marks, pct } } across ALL students.
let _qUsage = null;
let _qUsageAt = 0;
let _qUsageLoading = null;

// The one reading for a question: the live aggregate if this session has
// scanned the log, otherwise whatever was last written onto the question doc.
function qUsage(q) {
  if (!q || q.id == null) return null;
  const live = _qUsage ? _qUsage[String(q.id)] : null;
  const rec = live || (q.usage && typeof q.usage.pct === 'number' ? q.usage : null);
  return (rec && rec.attempts > 0 && typeof rec.pct === 'number') ? rec : null;
}
// Sort key: hardest first. A question nobody has attempted sorts last either
// way — no usage is not evidence of being hard or easy.
function qUsagePct(q) { const u = qUsage(q); return u ? u.pct : null; }

// One pass over every attempt ever logged, aggregated per question. Admin only
// (students may only read their own rows).
async function loadQuestionUsage(force) {
  if (!db || !_isAdmin()) return _qUsage || {};
  if (_qUsage && !force && (Date.now() - _qUsageAt) < 10 * 60 * 1000) return _qUsage;
  if (_qUsageLoading) return _qUsageLoading;
  _qUsageLoading = (async () => {
    try {
      // Accounts retired by a password reset are skipped — their work is
      // already counted again under the new uid.
      const retired = new Set();
      try {
        const profs = await getDocs(collection(db, 'userProfiles'));
        profs.forEach(d => { const p = d.data() || {}; if (p.supersededBy || p.retired) retired.add(p.uid || d.id); });
      } catch (e) { console.warn('usage: profiles', e); }

      const snap = await getDocs(collection(db, 'questionAttempts'));
      const agg = {};
      const seenUids = {};
      snap.forEach(d => {
        const a = d.data();
        if (!a || a.questionId == null) return;
        if (retired.has(a.uid)) return;
        const marks = Number(a.totalBlanks) || 0;
        if (marks <= 0) return;                                  // nothing was marked — not evidence
        const earned = Math.max(0, Math.min(marks, Number(a.score) || 0));
        const id = String(a.questionId);
        const r = agg[id] || (agg[id] = { attempts: 0, students: 0, earned: 0, marks: 0, pct: 0, full: 0 });
        r.attempts++; r.earned += earned; r.marks += marks;
        if (earned >= marks) r.full++;                            // attempts that were fully correct
        const u = seenUids[id] || (seenUids[id] = new Set());
        if (a.uid) u.add(a.uid);
      });
      Object.keys(agg).forEach(id => {
        const r = agg[id];
        r.students = (seenUids[id] || new Set()).size;
        r.pct = Math.round((r.earned / r.marks) * 100);
      });
      _qUsage = agg;
      _qUsageAt = Date.now();
      _persistQuestionUsage().catch(e => console.warn('usage persist', e));   // store it in the database, non-blocking
    } catch (e) {
      console.warn('question usage load', e);
      _qUsage = _qUsage || {};
    }
    return _qUsage;
  })();
  try { return await _qUsageLoading; } finally { _qUsageLoading = null; }
}

// Write each question's reading onto its own doc, so the percentage lives in
// the database beside the question. Only writes what actually changed. The same
// pass drops q.calib, the old AI-simulated rating, wherever it is still stored.
async function _persistQuestionUsage() {
  if (!_qUsage || !_isAdmin()) return;
  const at = new Date().toISOString();
  const dirty = [];
  let purged = 0, foreign = 0;
  questionBank.forEach(q => {
    if (!q || q.id == null) return;
    // Only ever write to questions THIS account owns. The bank is a union across
    // every admin account, and another admin's docs are not ours to write —
    // Firestore rejects it, and one rejection per question is how a routine
    // background pass turned into a wall of error toasts.
    if (_qOwner(q.id) !== currentUser.uid) { foreign++; return; }
    let changed = false;
    if (q.calib !== undefined) { delete q.calib; changed = true; purged++; }
    const r = _qUsage[String(q.id)];
    const prev = q.usage || null;
    if (!r) {
      if (prev) { delete q.usage; changed = true; }    // every attempt on it is gone
    } else if (!prev || prev.attempts !== r.attempts || prev.pct !== r.pct || prev.marks !== r.marks) {
      q.usage = { pct: r.pct, attempts: r.attempts, students: r.students, earned: r.earned, marks: r.marks, full: r.full, at };
      changed = true;
    }
    if (changed) dirty.push(q);
  });
  if (purged) console.info('Removed simulated difficulty ratings from ' + purged + ' question(s)');
  if (foreign) console.info('Skipped ' + foreign + ' question(s) owned by another admin account — not ours to write');
  // The first run rewrites every question that has ever been attempted, so go in
  // small batches rather than firing hundreds of writes at once. Quiet saves: a
  // failure here is logged once at the end, never toasted per question. If a
  // whole batch fails the pass gives up rather than grinding through hundreds
  // more writes that will fail the same way.
  let failed = 0;
  for (let i = 0; i < dirty.length; i += 15) {
    const batch = dirty.slice(i, i + 15);
    const results = await Promise.all(batch.map(q => saveQuestion(q, { quiet: true })));
    const bad = results.filter(ok => !ok).length;
    failed += bad;
    if (bad === batch.length) { failed += dirty.length - (i + batch.length); break; }
  }
  if (failed) {
    console.warn('Difficulty backfill: ' + failed + ' of ' + dirty.length +
      ' question(s) could not be updated (' + (_saveQuestionLastError || 'unknown') + ')');
  }
}

// Pull fresh numbers and redraw. Wired to the bank's refresh button.
async function refreshQuestionUsage() {
  const btn = document.getElementById('bankUsageBtn');
  if (btn) { btn.disabled = true; btn.textContent = '⏳ Reading usage…'; }
  await loadQuestionUsage(true);
  renderQuestionBank();
  if (btn) { btn.disabled = false; btn.textContent = '🔄 Refresh difficulty'; }
  showToast('Difficulty updated from student usage ✓', 'success');
}

// Load once, quietly, the first time an admin opens the bank — so the grid is
// colour-coded on arrival without anyone pressing anything.
function ensureQuestionUsage() {
  if (!_isAdmin() || _qUsage || _qUsageLoading) return;
  loadQuestionUsage().then(() => renderQuestionBank()).catch(() => {});
}

function usageBadgeHtml(q) {
  const u = qUsage(q);
  if (!u) return '<span class="qb-tag usage-none" title="No student has attempted this question yet, so it has no measured difficulty">📊 no attempts yet</span>';
  const thin = u.attempts < USAGE_MIN_ATTEMPTS;
  const tip = 'Students scored ' + u.earned + ' of ' + u.marks + ' marks (' + u.pct + '%) over ' +
    u.attempts + ' attempt' + (u.attempts === 1 ? '' : 's') +
    (u.students ? ' by ' + u.students + ' student' + (u.students === 1 ? '' : 's') : '') +
    '. ' + u.full + ' attempt' + (u.full === 1 ? ' was' : 's were') + ' fully correct.' +
    (thin ? ' Only a few attempts so far — treat it as a rough reading.' : '');
  return '<span class="qb-tag" style="background:' + usageTint(u.pct) + ';color:' + usageColor(u.pct) +
    ';border:1px ' + (thin ? 'dashed' : 'solid') + ' ' + usageEdge(u.pct) + ';" title="' + escapeHtml(tip) + '">📊 ' +
    u.pct + '% · ' + usageBandFor(u.pct) + ' · ' + u.attempts + '×</span>';
}

// The card itself: green when students find it easy, red when they don't. The
// colours ride in as custom properties so the stylesheet keeps ownership of the
// hover state instead of an inline style winning over it.
function usageCardAttrs(q) {
  const u = qUsage(q);
  if (!u) return '';
  return ' class="qb-card has-usage" style="--u-tint:' + usageTint(u.pct) + ';--u-edge:' + usageEdge(u.pct) +
    ';--u-ink:' + usageColor(u.pct) + ';"';
}

(function injectUsageStyles() {
  const css = `
  .qb-tag.usage-none { background: var(--bg-tertiary, #f2f1ec); color: var(--text-muted, #666c71); }
  .qb-card.has-usage {
    background: var(--u-tint);
    border-color: var(--u-edge);
    box-shadow: inset 7px 0 0 var(--u-ink);
    padding-left: 27px;
  }
  .qb-card.has-usage:hover {
    border-color: var(--u-ink);
    box-shadow: inset 7px 0 0 var(--u-ink), var(--shadow-sm);
  }`;
  const s = document.createElement('style'); s.textContent = css; document.head.appendChild(s);
})();

// ── Bank view mode & sort ────────────────────────────────────────────────────
// "list" is the original stacked-row bank. "grid" lays the same questions out as
// picture tiles across the full width, so a diagram can be recognised at a
// glance and clicked straight into a worksheet selection. Both remember what
// they were left on.
const BANK_VIEW_KEY = 'cerBankView';
const BANK_SORT_KEY = 'cerBankSort';
let bankView = (() => { try { return localStorage.getItem(BANK_VIEW_KEY) === 'grid' ? 'grid' : 'list'; } catch (_) { return 'list'; } })();
let bankSort = (() => { try { return localStorage.getItem(BANK_SORT_KEY) || 'newest'; } catch (_) { return 'newest'; } })();

function setBankView(mode) {
  bankView = mode === 'grid' ? 'grid' : 'list';
  try { localStorage.setItem(BANK_VIEW_KEY, bankView); } catch (_) {}
  _syncBankViewChrome();
  renderQuestionBank();
}

function setBankSort(value) {
  bankSort = value || 'newest';
  try { localStorage.setItem(BANK_SORT_KEY, bankSort); } catch (_) {}
  renderQuestionBank();
}

// The toggle buttons' pressed state, and the wide page body the tiles need.
function _syncBankViewChrome() {
  document.querySelectorAll('#bankViewToggle [data-bank-view]').forEach(b => {
    b.classList.toggle('active', b.dataset.bankView === bankView);
  });
  const body = document.querySelector('#page-bank .page-body');
  if (body) body.classList.toggle('bank-wide', bankView === 'grid');
  const sortSel = document.getElementById('bankSortBy');
  if (sortSel && sortSel.value !== bankSort) sortSel.value = bankSort;
}

// Exactly what the bank is showing right now — search, every filter, and the AI
// search ranking. The grid and the "measure difficulty" button read the same
// function so the button can never act on a different set than the eye sees.
function _bankFilteredQuestions() {
  const searchRaw = (document.getElementById('bankSearch')?.value || '').trim();
  const searchTokens = parseSearchTokens(searchRaw);
  const topicSel = bankTopicSel;   // empty = every topic
  const catFilter = document.getElementById('bankFilterCategory')?.value || '';
  const levelFilter = document.getElementById('bankFilterLevel')?.value || '';
  const sourceFilter = document.getElementById('bankFilterSource')?.value || '';
  const diffFilter = document.getElementById('bankFilterDifficulty')?.value || '';
  const tagFilter = document.getElementById('bankFilterTag')?.value || '';

  let filtered = questionBank.filter(q => {
    if (topicSel.size && !qTopicList(q).some(t => topicSel.has(t))) return false;
    if (tagFilter === '__none__') { if (qTagList(q).length) return false; }
    else if (tagFilter && !qMatchesTag(q, tagFilter)) return false;
    if (catFilter && !qMatchesCategory(q, catFilter)) return false;
    if (sourceFilter && questionSource(q) !== sourceFilter) return false;
    const qLevel = getTopicLevel(q.topic || '');
    if (levelFilter && qLevel !== levelFilter) return false;
    if (diffFilter) {
      const u = qUsage(q);
      if (diffFilter === 'none') { if (u) return false; }
      else if (!u || usageBandFor(u.pct) !== diffFilter) return false;
    }
    if (searchTokens.length > 0) {
      const haystack = extractQuestionSearchText(q);
      if (!searchTokens.every(token => haystack.includes(token))) return false;
    }
    return true;
  });

  // AI relevance always wins — you asked it a question, its ranking IS the
  // answer. Otherwise the chosen sort applies; "bank" keeps the old behaviour
  // (load order, or hardest-first while a difficulty filter is on).
  if (bankAiRanking) {
    filtered = filtered
      .filter(q => bankAiRanking.has(q.id))
      .sort((a, b) => bankAiRanking.get(b.id) - bankAiRanking.get(a.id));
  } else if (bankSort === 'newest') {
    filtered.sort((a, b) => _questionRecency(b) - _questionRecency(a));
  } else if (bankSort === 'oldest') {
    filtered.sort((a, b) => _questionRecency(a) - _questionRecency(b));
  } else if (bankSort === 'title') {
    filtered.sort((a, b) => String(a.title || '').localeCompare(String(b.title || '')));
  } else if (diffFilter) {
    filtered.sort((a, b) => (qUsagePct(a) ?? 999) - (qUsagePct(b) ?? 999));   // hardest first
  }
  return filtered;
}

// The picture a question is recognised by: its first image block, else the
// answer-key picture. Questions with neither get a text tile instead.
function _qThumbUrl(q) {
  const b = ((q && q.blocks) || []).find(x => x && x.type === 'image' && x.url);
  if (b) return b.url;
  const ak = (q && typeof q.answerKeyImage === 'string') ? q.answerKeyImage.trim() : '';
  return ak || '';
}

function renderQuestionBank() {
  const container = document.getElementById('questionBankGrid');
  // A preview left open would be pointing at a tile that is about to be replaced.
  qbTileHoverLeave();
  ppHoverHide();
  // Keep the tag list current — a tag typed a moment ago should be selectable now.
  // Not while it has focus: rebuilding the options under an open dropdown closes it.
  if (document.activeElement !== document.getElementById('bankFilterTag')) populateTagFilter();
  const filtered = _bankFilteredQuestions();
  ensureQuestionUsage();   // first admin visit: colour the grid without being asked
  _syncBankViewChrome();
  _renderBankPickBar(filtered);
  container.classList.toggle('as-tiles', bankView === 'grid');

  if (filtered.length === 0) {
    container.innerHTML = bankAiRanking ? `
      <div class="empty-state">
        <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5"><circle cx="11" cy="11" r="8"/><line x1="21" y1="21" x2="16.65" y2="16.65"/></svg>
        <h3>No matching questions</h3>
        <p>AI found no questions for that instruction — try rephrasing it, or clear the AI search</p>
      </div>` : `
      <div class="empty-state">
        <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5"><path d="M4 19.5A2.5 2.5 0 0 1 6.5 17H20"/><path d="M6.5 2H20v20H6.5A2.5 2.5 0 0 1 4 19.5v-15A2.5 2.5 0 0 1 6.5 2z"/></svg>
        <h3>No questions yet</h3>
        <p>Create your first question to get started</p>
      </div>`;
    return;
  }

  if (bankView === 'grid') { container.innerHTML = filtered.map(bankTileHtml).join(''); return; }

  container.innerHTML = filtered.map(q => {
    const preview = getQuestionPreview(q);
    const qLevel = getTopicLevel(q.topic || '');
    const qCategory = normalizeCategoryValue(q.category);
    const qSource = questionSource(q);
    const aiScore = bankAiRanking ? bankAiRanking.get(q.id) : null;
    return `
      <div${usageCardAttrs(q) || ' class="qb-card"'} ondblclick="editQuestion('${q.id}')">
        <div class="qb-card-header">
          <div>
            <div class="qb-card-title">${escapeHtml(q.title)}</div>
            <div class="qb-card-meta">
              ${aiScore != null ? `<span class="qb-tag ai-match" title="AI relevance to your instruction">★ ${aiScore}% match</span>` : ''}
              <span class="qb-tag category">${escapeHtml(qCategory)}</span>
              <span class="qb-tag topic">${escapeHtml(q.topic)}</span>
              ${qSecondaryTagsHtml(q)}
              <span class="qb-tag">${escapeHtml(qLevel)}</span>
              ${usageBadgeHtml(q)}
              ${q.notInSyllabus ? `<span class="qb-tag" style="background:#fdf4e3;color:#7a5410;border:1px solid #e0b768;" title="Hidden from practice; still shown in PSLE Papers">🚫 Not in syllabus</span>` : ''}
              ${qSource ? `<span class="qb-tag source" title="${escapeHtml(qSource)}">${escapeHtml(qSource)}</span>` : ''}
              ${qTagChipsHtml(q)}
            </div>
          </div>
          <div class="qb-card-actions">
            <button class="qb-action-btn" title="Edit" onclick="event.stopPropagation();editQuestion('${q.id}')">
              <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M11 4H4a2 2 0 0 0-2 2v14a2 2 0 0 0 2 2h14a2 2 0 0 0 2-2v-7"/><path d="M18.5 2.5a2.121 2.121 0 0 1 3 3L12 15l-4 1 1-4 9.5-9.5z"/></svg>
            </button>
            <button class="qb-action-btn" title="Duplicate" onclick="event.stopPropagation();duplicateQuestion('${q.id}')">
              <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><rect x="9" y="9" width="13" height="13" rx="2" ry="2"/><path d="M5 15H4a2 2 0 0 1-2-2V4a2 2 0 0 1 2-2h9a2 2 0 0 1 2 2v1"/></svg>
            </button>
            <button class="qb-action-btn delete-qb" title="Delete" onclick="event.stopPropagation();deleteQuestion('${q.id}')">
              <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><polyline points="3 6 5 6 21 6"/><path d="M19 6v14a2 2 0 0 1-2 2H7a2 2 0 0 1-2-2V6m3 0V4a2 2 0 0 1 2-2h4a2 2 0 0 1 2 2v2"/></svg>
            </button>
          </div>
        </div>
        <div class="qb-card-preview">${escapeHtml(preview)}</div>
      </div>`;
  }).join('');
}

// ── Grid view: one question as a picture tile ────────────────────────────────
// A portrait card you can scan a screenful of at a time: the question's diagram
// (or its opening words when it has none) above the title and its tags. Click
// picks it for a worksheet; the pencil edits it; double-click still edits, same
// as the list rows.
function bankTileHtml(q) {
  const picked = wsSelectedIds.has(q.id);
  const thumb = _qThumbUrl(q);
  const preview = getQuestionPreview(q);
  const qLevel = getTopicLevel(q.topic || '');
  const qCategory = normalizeCategoryValue(q.category);
  const u = qUsage(q);
  const tint = u ? ` style="--u-ink:${usageColor(u.pct)};"` : '';
  return `
    <div class="qb-tile${picked ? ' picked' : ''}${u ? ' has-usage' : ''}"${tint} data-qid="${escapeHtml(String(q.id))}"
         onclick="toggleBankPick('${q.id}', event)" ondblclick="editQuestion('${q.id}')"
         onmouseenter="qbTileHoverEnter(event,'${q.id}')" onmousemove="qbTileHoverMove(event)" onmouseleave="qbTileHoverLeave()"
         title="Click to add this question to your worksheet selection · double-click to edit · rest on it to read it">
      <div class="qb-tile-thumb">
        ${thumb
          ? `<img src="${escapeHtml(transformImageUrl(thumb))}" alt="" loading="lazy" decoding="async" onerror="this.closest('.qb-tile-thumb').classList.add('no-img')">`
          : `<div class="qb-tile-text">${escapeHtml(preview)}</div>`}
        <span class="qb-tile-check" aria-hidden="true">✓</span>
        <button class="qb-tile-edit" title="Edit this question" onclick="event.stopPropagation();editQuestion('${q.id}')">
          <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M11 4H4a2 2 0 0 0-2 2v14a2 2 0 0 0 2 2h14a2 2 0 0 0 2-2v-7"/><path d="M18.5 2.5a2.121 2.121 0 0 1 3 3L12 15l-4 1 1-4 9.5-9.5z"/></svg>
        </button>
      </div>
      <div class="qb-tile-body">
        <div class="qb-tile-title">${escapeHtml(q.title)}</div>
        <div class="qb-tile-meta">
          <span class="qb-tag category">${escapeHtml(qCategory)}</span>
          <span class="qb-tag topic">${escapeHtml(q.topic)}</span>
          <span class="qb-tag">${escapeHtml(qLevel)}</span>
          ${usageBadgeHtml(q)}
        </div>
      </div>
    </div>`;
}

// ── Rest on a tile to read the question ─────────────────────────────────────
// A thumbnail tells you which question it is; it doesn't tell you what the
// question ASKS. Resting on one opens the full preview card — the same card
// Past Papers uses — so a sheet can be chosen without opening anything.
//
// The delay is what makes it usable: sweeping the cursor across a screenful of
// tiles on the way to somewhere else must not strobe previews open. 2.5s is
// long enough to be deliberate, short enough not to feel broken.
const BANK_HOVER_MS = 2500;
let _bankHoverTimer = null;
let _bankHoverId = null;    // the tile the pending preview belongs to
let _bankHoverPt = null;    // latest cursor position, so the card opens where the cursor IS

function qbTileHoverEnter(ev, qid) {
  // Touch devices synthesise a mouseenter on tap — there is no "resting" there,
  // and a card that opens under the finger just gets in the way.
  if (window.matchMedia && !window.matchMedia('(hover: hover)').matches) return;
  clearTimeout(_bankHoverTimer);
  _bankHoverId = qid;
  _bankHoverPt = { clientX: ev.clientX, clientY: ev.clientY };
  _bankHoverTimer = setTimeout(() => {
    if (_bankHoverId !== qid) return;
    ppHoverShowBank(_bankHoverPt || { clientX: 0, clientY: 0 }, qid,
      'Click the tile to add this question to your worksheet selection.');
    ppHoverExpand();   // the wait was deliberate — open it read-to-the-end, not a teaser
    // The diagram inside is still loading when we first measure, so the card
    // grows after it is placed. Anchor it again once it has its real height,
    // or it hangs off the bottom of the screen.
    _bankHoverTimer = setTimeout(ppHoverExpand, 420);
  }, BANK_HOVER_MS);
}

function qbTileHoverMove(ev) {
  _bankHoverPt = { clientX: ev.clientX, clientY: ev.clientY };
  ppHoverMove(ev);   // no-op until the card is up
}

function qbTileHoverLeave() {
  clearTimeout(_bankHoverTimer);
  _bankHoverId = null;
  ppHoverChipLeave();   // keeps the card open long enough to move into it
}

// Clicking a tile adds the question to (or takes it out of) the SAME selection
// the worksheet builder uses, so a pick made here is already waiting there.
function toggleBankPick(id, event) {
  if (event && event.target && event.target.closest && event.target.closest('.qb-tile-edit')) return;
  if (wsSelectedIds.has(id)) wsSelectedIds.delete(id); else wsSelectedIds.add(id);
  const tile = document.querySelector(`.qb-tile[data-qid="${CSS.escape(String(id))}"]`);
  if (tile) tile.classList.toggle('picked', wsSelectedIds.has(id));
  _renderBankPickBar();
  updateWsCount();
}

function clearBankPicks() {
  wsSelectedIds.clear();
  updateWsCount();
  renderQuestionBank();
}

// Take everything currently on screen, so a filtered search can be picked whole.
function pickAllBankVisible() {
  _bankFilteredQuestions().forEach(q => wsSelectedIds.add(q.id));
  updateWsCount();
  renderQuestionBank();
}

function bankPicksToWorksheet() {
  if (!wsSelectedIds.size) { showToast('Pick some questions first', 'error'); return; }
  navigateTo('worksheet');
}

function bankPicksToPractice() {
  const selected = questionBank.filter(q => wsSelectedIds.has(q.id));
  if (!selected.length) { showToast('Pick some questions first', 'error'); return; }
  launchWorksheetPractice(selected);
}

// The bar that says what you have picked and what you can do with it. Shown
// whenever a selection exists, in either view — switching to the list must not
// make a selection you cannot see feel lost.
function _renderBankPickBar(filtered) {
  const bar = document.getElementById('bankPickBar');
  if (!bar) return;
  const n = wsSelectedIds.size;
  if (!n) { bar.style.display = 'none'; bar.innerHTML = ''; return; }
  const shown = filtered || _bankFilteredQuestions();
  const allPicked = shown.length > 0 && shown.every(q => wsSelectedIds.has(q.id));
  bar.style.display = '';
  bar.innerHTML = `
    <span class="bank-pick-count">${n} question${n === 1 ? '' : 's'} picked</span>
    ${allPicked ? '' : `<button class="btn btn-outline btn-sm" onclick="pickAllBankVisible()">Pick all ${shown.length} shown</button>`}
    <button class="btn btn-outline btn-sm" onclick="clearBankPicks()">Clear</button>
    <span style="flex:1;"></span>
    ${_canAuthor() ? `<button class="btn btn-outline btn-sm" onclick="openBulkTags('picked')" title="Add or remove tags on all ${n} at once, or have the AI tag each one">🏷 Tag these</button>` : ''}
    <button class="btn btn-outline btn-sm" onclick="bankPicksToPractice()">✏️ Practice these</button>
    <button class="btn btn-primary btn-sm" onclick="bankPicksToWorksheet()">📄 Build worksheet</button>`;
}

function getQuestionPreview(q) {
  const clean = s => (s || '').replace(/<[^>]*>/g, ' ').replace(/&nbsp;/g, ' ').replace(/\s+/g, ' ').trim();
  for (const block of q.blocks) {
    if (block.type === 'text' && block.content) return clean(block.content).substring(0, 150);
    if (block.type === 'part' && block.content) return clean((block.label || '') + ' ' + block.content).substring(0, 150);
    if (block.type === 'mcq' && (block.options || []).some(o => o.text)) {
      return clean('Multiple choice: ' + (block.options || []).map(o => o.text).join(' / ')).substring(0, 150);
    }
    if (block.type === 'fillblank' && (block.text || '').trim()) {
      return clean('Fill in the blanks: ' + _fbParse(block.text).map(p => p.type === 'blank' ? '____' : p.text).join('')).substring(0, 150);
    }
  }
  return 'No text content';
}

function editQuestion(id) {
  const q = questionBank.find(qb => qb.id === id) || vettingList.find(v => v.id === id);
  if (!q) return;
  _editReturnPage = null;   // default: return to the Bank (callers may override after)
  _ppReturnFocus = null;
  _vetReturnFocus = null;
  _vetReturnScroll = 0;
  // A vetting question goes back to the Vetting List afterwards, restoring the
  // exact view (scroll position) so the admin can carry straight on vetting.
  if (vettingList.some(v => v.id === id)) {
    _editReturnPage = 'vetting';
    _vetReturnFocus = id;
    const vetPage = document.getElementById('page-vetting');
    if (vetPage && vetPage.classList.contains('active')) _vetReturnScroll = window.scrollY || 0;
  }
  _hideDupBanner();
  currentEditingQuestion = q.id;
  document.getElementById('questionTitle').value = q.title;
  // Set the category, tolerating one that's no longer in the list (e.g. a
  // removed custom category) by inserting a one-off option — mirrors topics.
  const catSel = document.getElementById('categorySelect');
  const qCat = normalizeCategoryValue(q.category);
  if (qCat && !Array.from(catSel.options).some(o => o.value === qCat)) {
    const catOpt = document.createElement('option');
    catOpt.value = qCat;
    catOpt.textContent = qCat;
    const catManage = catSel.querySelector('optgroup[label="── Manage ──"]');
    if (catManage) catSel.insertBefore(catOpt, catManage); else catSel.appendChild(catOpt);
  }
  catSel.value = qCat;
  _lastCategoryValue = qCat;
  // Optional 2nd category
  const catSel2 = document.getElementById('categorySelect2');
  if (catSel2) {
    const qCat2 = qSecondaryCategory(q);
    if (qCat2 && !Array.from(catSel2.options).some(o => o.value === qCat2)) {
      const o = document.createElement('option'); o.value = qCat2; o.textContent = qCat2; catSel2.appendChild(o);
    }
    catSel2.value = qCat2 || '';
  }
  const mgEl = document.getElementById('questionMarkingGuide');
  if (mgEl) mgEl.value = q.markingGuide || '';
  const annEl = document.getElementById('questionAnnotation');
  if (annEl) annEl.checked = !!q.annotation;
  _setAnswerKeyFields(q.answerKeyNote || '', q.answerKeyImage || '');
  const nisEl = document.getElementById('questionNotInSyllabus');
  if (nisEl) nisEl.checked = !!q.notInSyllabus;
  setQuestionTagsField(q);

  // Try to set topic, handle custom topics
  const topicSelect = document.getElementById('topicSelect');
  const existingOption = Array.from(topicSelect.options).find(opt => opt.value === q.topic);
  if (!existingOption && q.topic) {
    // The question's topic isn't in the current list (e.g. it was removed) —
    // add a one-off option so it still shows, without persisting it.
    const opt = document.createElement('option');
    opt.value = q.topic;
    opt.textContent = q.topic;
    const manageGroup = topicSelect.querySelector('optgroup[label="── Manage ──"]');
    if (manageGroup) topicSelect.insertBefore(opt, manageGroup); else topicSelect.appendChild(opt);
  }
  topicSelect.value = q.topic;
  _lastTopicValue = q.topic;
  // Optional 2nd topic
  const topicSelect2 = document.getElementById('topicSelect2');
  if (topicSelect2) {
    const qTopic2 = qSecondaryTopic(q);
    if (qTopic2 && !Array.from(topicSelect2.options).some(o => o.value === qTopic2)) {
      const o = document.createElement('option'); o.value = qTopic2; o.textContent = qTopic2; topicSelect2.appendChild(o);
    }
    topicSelect2.value = qTopic2 || '';
  }

  blocks = JSON.parse(JSON.stringify(q.blocks));
  selectedBlanks = JSON.parse(JSON.stringify(q.blanks || {}));
  
  renderBlocks();
  if (window.ppCancelPendingAttach) window.ppCancelPendingAttach();
  _skipCreateReset = true;
  navigateTo('create');
  showToast('Editing: ' + q.title, 'info');
}

function duplicateQuestion(id) {
  const q = questionBank.find(qb => qb.id === id);
  if (!q) return;
  const clone = JSON.parse(JSON.stringify(q));
  clone.id = 'q_' + Date.now() + '_' + Math.random().toString(36).substr(2, 6);
  clone.title = q.title + ' (Copy)';
  clone.createdAt = new Date().toISOString();
  questionBank.push(clone);
  renderQuestionBank();
  updateCounts();
  showToast('Question duplicated', 'success');
  saveQuestion(clone);
}

// ── Regenerate: clone the question currently open in the editor with AI,
// keeping the same picture, applying teacher instructions. Uses the live
// editor context (what's on screen) and NEVER overwrites the original. ───────
let _regenSource = null;       // snapshot of the question being regenerated
let _regenSourceOrigId = null; // id of the original (currentEditingQuestion)

function openRegenerateModal() {
  if (!Array.isArray(blocks) || blocks.length === 0) {
    showToast('Open a question first, then Regenerate', 'info');
    return;
  }
  if (!window.__aiReady || !window.__aiReady()) {
    showToast("AI isn't set up yet — add your reCAPTCHA site key in the code", 'info');
    return;
  }
  // Snapshot exactly what's on screen so the AI uses this question's context.
  _regenSource = collectQuestionData();
  _regenSourceOrigId = currentEditingQuestion || null;
  const ta = document.getElementById('regenRemark');
  if (ta) ta.value = '';
  const status = document.getElementById('regenStatus');
  if (status) status.textContent = '';
  const btn = document.getElementById('regenConfirmBtn');
  if (btn) { btn.disabled = false; btn.textContent = 'Regenerate copy'; }
  document.getElementById('regenOverlay').classList.add('active');
  if (ta) setTimeout(() => ta.focus(), 50);
}

function closeRegenerateModal() {
  document.getElementById('regenOverlay').classList.remove('active');
  _regenSource = null;
  _regenSourceOrigId = null;
}

// Turn an existing question into plain text the AI can read and rewrite.
function _serializeQuestionForRegen(q) {
  const lines = [];
  if (q.title) lines.push('Title: ' + q.title);
  if (q.topic) lines.push('Topic: ' + q.topic);
  if (q.category) lines.push('Category: ' + normalizeCategoryValue(q.category));
  lines.push('Blocks (in order):');
  (q.blocks || []).forEach((b, i) => {
    const n = i + 1;
    if (b.type === 'text') lines.push(`${n}. TEXT: ${stripHtml(b.content || '')}`);
    else if (b.type === 'part') lines.push(`${n}. TEXT: ${((b.label || '') + ' ' + stripHtml(b.content || '')).trim()}`);
    else if (b.type === 'image') lines.push(`${n}. IMAGE PLACEHOLDER${b.caption ? ' (caption: ' + stripHtml(b.caption) + ')' : ''}`);
    else if (b.type === 'mcq') {
      const opts = (b.options || []);
      const correct = opts.findIndex(o => o.id === b.correctId);
      lines.push(`${n}. MCQ options:`);
      opts.forEach((o, oi) => lines.push(`     (${oi + 1}) ${stripHtml(o.text || '')}${oi === correct ? '  <-- correct' : ''}`));
    }
    else if (b.type === 'answer') lines.push(`${n}. ANSWER (Claim/Evidence/Reasoning): Claim: ${stripHtml(b.claim || '')} | Evidence: ${stripHtml(b.evidence || '')} | Reasoning: ${stripHtml(b.reasoning || '')}`);
    else if (b.type === 'plainanswer') lines.push(`${n}. PLAIN ANSWER: ${stripHtml(b.content || b.text || '')}`);
    else if (b.type === 'explanation') lines.push(`${n}. EXPLANATION: ${stripHtml(b.content || '')}`);
  });
  return lines.join('\n');
}

function _regenPrompt(q, remark) {
  const categories = ['CER', 'Single Relationship', 'Double Relationship', 'Reliability', 'Fairness', 'Accuracy', 'Constant Variable', 'Hypothesis', 'Aim', 'Conclusion', 'Definition', 'Explanation', 'Stating', 'Key Concepts'];
  return `You are helping a Singapore primary-school science teacher create a NEW VARIATION of an existing practice question.\n` +
    _genPreamble() +
    `TEACHER'S INSTRUCTIONS for this new copy (follow them closely): ${remark || 'Create a fresh variation that tests the same concept; vary the wording and any numbers but keep the same difficulty.'}\n\n` +
    `Here is the ORIGINAL question — do NOT copy it word-for-word; produce a fresh variation that follows the instructions above while keeping the SAME overall structure, topic, answer type and any diagram placeholders in the same positions:\n` +
    `------------------\n${_serializeQuestionForRegen(q)}\n------------------\n\n` +
    `Return ONLY JSON with this exact shape:\n` +
    `{"title":"short title","topic":"<closest topic>","category":"<closest category>","blocks":[ ...ordered blocks... ]}\n` +
    `Each item in "blocks" is ONE of these objects:\n` +
    `  {"type":"text","text":"a part of the question wording, plain text"}\n` +
    `  {"type":"image"}   (a placeholder marking where the diagram/picture goes — keep one for EVERY image placeholder the original had, in the same position; the teacher's original picture is reused automatically)\n` +
    `  {"type":"mcq","options":["option 1","option 2","option 3","option 4"],"correctIndex":0}\n` +
    `  {"type":"answer","claim":"...","evidence":"...","reasoning":"..."}\n` +
    `  {"type":"plainanswer","text":"..."}\n` +
    `  {"type":"explanation","text":"teacher explanation of the model answer"}\n` +
    `Rules:\n` +
    `- Keep the SAME block types in the SAME order as the original (same number of image placeholders, same answer type, mcq stays mcq) — except ALWAYS finish with ONE "explanation" block (2-4 teacher sentences on WHY the answer is correct), even if the original had none.\n` +
    `- If a text block lists labelled items or options inline, put EACH on its own line separated by a real line break ("\\n").\n` +
    `- For "answer"/"plainanswer" fields only, wrap each KEY science keyword a student should recall in [[double brackets]] (whole words, about 3 to 8 total). Do NOT bracket anything in text, options or explanation.\n` +
    `- Choose topic from EXACTLY this list: ${currentTopics().join('; ')}.\n` +
    `- Choose category from EXACTLY this list: ${categories.join('; ')}.\n` +
    `- Use plain text only, no markdown.`;
}

async function confirmRegenerate() {
  const orig = _regenSource;
  if (!orig) { showToast('Question not found', 'error'); closeRegenerateModal(); return; }
  const remark = (document.getElementById('regenRemark')?.value || '').trim();
  const status = document.getElementById('regenStatus');
  const btn = document.getElementById('regenConfirmBtn');
  if (btn) { btn.disabled = true; btn.textContent = 'Regenerating…'; }
  if (status) status.textContent = 'Asking the AI to build a new copy…';
  try {
    // Give the AI the original picture (if any) so the variation fits the diagram.
    let media = [];
    const srcImg = (orig.blocks || []).find(b => b.type === 'image' && b.url);
    if (srcImg) {
      try {
        const dataUrl = await _urlToDataUrlRobust(transformImageUrl(srcImg.url));
        const parsed = _parseImageDataUrl(dataUrl);
        if (parsed) media = [{ mimeType: parsed.mime, data: dataUrl.split(',')[1] || '' }];
      } catch (e) { console.warn('regen image for AI', e); }
    }
    const prompt = _regenPrompt(orig, remark);
    const raw = media.length
      ? await askGeminiVision(prompt, media, { maxOutputTokens: 4096, json: true })
      : await askGemini(prompt, { maxOutputTokens: 4096, temperature: 0.5, json: true });
    const parsed = _parseAIJson(raw);
    if (!parsed || typeof parsed !== 'object') { showToast('AI did not return a question — try again', 'error'); if (status) status.textContent = ''; if (btn) { btn.disabled = false; btn.textContent = 'Regenerate copy'; } return; }
    const built = buildBlocksFromAi(parsed);
    const newBlocks = built.blocks;

    // Re-attach the ORIGINAL pictures so they stay exactly the same.
    const origImages = (orig.blocks || []).filter(b => b.type === 'image');
    let imgIdx = 0;
    newBlocks.forEach(b => {
      if (b.type === 'image' && imgIdx < origImages.length) {
        const src = origImages[imgIdx++];
        b.url = src.url || '';
        if (src.caption) b.caption = src.caption;
        if (src.scale) b.scale = src.scale;
      }
    });
    // Safety net: never lose a picture if the AI dropped a placeholder.
    while (imgIdx < origImages.length) {
      const src = origImages[imgIdx++];
      newBlocks.push({ id: generateBlockId(), type: 'image', url: src.url || '', caption: src.caption || '', scale: src.scale || 0.6 });
    }

    const origInBank = _regenSourceOrigId ? questionBank.find(q => q.id === _regenSourceOrigId) : null;
    const clone = {
      id: 'q_' + Date.now() + '_' + Math.random().toString(36).slice(2, 9),
      title: (parsed.title ? String(parsed.title) : orig.title) + ' (Regenerated)',
      category: normalizeCategoryValue(orig.category),
      category2: qSecondaryCategory(orig),
      topic: orig.topic,
      topic2: qSecondaryTopic(orig),
      markingGuide: orig.markingGuide || '',
      // A regenerated copy tests the same idea as the original, so it inherits the
      // original's tags rather than starting untagged.
      tags: qTagList(orig),
      annotation: !!orig.annotation,
      notInSyllabus: !!orig.notInSyllabus,
      blocks: newBlocks,
      blanks: built.selectedBlanks,
      status: (origInBank && origInBank.status) || 'approved',
      createdAt: new Date().toISOString(),
      createdBy: (currentUser && currentUser.name) || orig.createdBy || 'Admin',
      regeneratedFrom: _regenSourceOrigId || orig.id
    };
    questionBank.push(clone);
    renderQuestionBank();
    updateCounts();
    saveQuestion(clone);
    closeRegenerateModal();
    showToast('New copy created in the bank — the original is untouched', 'success');
  } catch (e) {
    console.error('Regenerate failed:', e);
    showToast('Regenerate failed: ' + (e && e.message ? e.message : e), 'error');
    if (status) status.textContent = '';
    if (btn) { btn.disabled = false; btn.textContent = 'Regenerate copy'; }
  }
}

function deleteQuestion(id) {
  showConfirm('Delete Question', 'Are you sure you want to permanently delete this question?', () => {
    questionBank = questionBank.filter(q => q.id !== id);
    renderQuestionBank();
    updateCounts();
    showToast('Question deleted', 'info');
    deleteQuestionDoc(id);
  });
}

// =====================================================================
// VETTING LIST
// =====================================================================
// When a question entered the vetting list: its vettedAt if set (e.g. a bank
// question flagged back to vetting), otherwise its createdAt. Lets the admin
// see at a glance which pending questions are recent / still relevant.
function _vetAddedAt(q) { return (q && (q.vettedAt || q.createdAt)) || ''; }
// Small "🕓 Added …" stamp for a vetting card. Relative time (e.g. "3h ago"),
// with the full local date/time on hover.
function _vetTimeLabel(q) {
  const iso = _vetAddedAt(q);
  if (!iso) return '';
  const rel = _commTimeAgo(iso);
  if (!rel) return '';
  let full = iso;
  try { full = new Date(iso).toLocaleString(); } catch (_) {}
  return `<div class="vetting-added" title="Added to vetting: ${escapeHtml(full)}">🕓 Added ${escapeHtml(rel)}</div>`;
}

function renderVettingList() {
  const container = document.getElementById('vettingListGrid');
  // Live "processing" / "failed" placeholders from Rapid add, shown on top.
  const jobCards = rapidJobs.map(_rapidJobCardHtml).join('');

  if (vettingList.length === 0 && rapidJobs.length === 0) {
    container.innerHTML = `
      <div class="empty-state">
        <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5"><path d="M9 11l3 3L22 4"/><path d="M21 12v7a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2V5a2 2 0 0 1 2-2h11"/></svg>
        <h3>Vetting list is empty</h3>
        <p>Questions added for review will appear here</p>
      </div>`;
    return;
  }

  // Search filter — same engine as the Question Bank: every token (or "quoted
  // phrase") must appear somewhere in the title, tags or block content.
  const searchTokens = parseSearchTokens((document.getElementById('vettingSearch')?.value || '').trim());
  const visible = searchTokens.length === 0 ? vettingList : vettingList.filter(q => {
    const haystack = extractQuestionSearchText(q);
    return searchTokens.every(token => haystack.includes(token));
  });

  if (visible.length === 0 && searchTokens.length > 0) {
    container.innerHTML = jobCards + `
      <div class="empty-state">
        <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5"><circle cx="11" cy="11" r="8"/><line x1="21" y1="21" x2="16.65" y2="16.65"/></svg>
        <h3>No matching questions</h3>
        <p>No vetting questions match your search — try fewer or different words</p>
      </div>`;
    return;
  }

  // Newest additions first, so the most recently added (most relevant to review
  // now) sit at the top. Falls back to array order when timestamps are missing.
  const ordered = visible
    .map((q, i) => ({ q, i }))
    .sort((a, b) => {
      const ta = Date.parse(_vetAddedAt(a.q)) || 0, tb = Date.parse(_vetAddedAt(b.q)) || 0;
      return tb - ta || a.i - b.i;
    })
    .map(x => x.q);

  const qCards = ordered.map(q => {
    const statusClass = q.status || 'pending';
    const isNew = _rapidJustAdded.has(q.id); // freshly added via Rapid add this session
    const preview = getQuestionPreview(q);
    // Only surface the duplicate warning if the suspected original still exists.
    const dup = (q._dupOf && q._dupOf.id && questionBank.some(b => b.id === q._dupOf.id)) ? q._dupOf : null;
    const dupBorder = dup ? ' style="border-color:#f59e0b;box-shadow:0 0 0 1px #f59e0b;"' : (isNew ? ' style="border-color:var(--accent-orange);box-shadow:0 0 0 1px var(--accent-orange);"' : '');
    return `
      <div class="qb-card" data-vetid="${q.id}"${dupBorder}>
        <div class="qb-card-header">
          <div>
            <div class="qb-card-title">${escapeHtml(q.title)}</div>
            <div class="qb-card-meta">
              <span class="qb-tag category">${escapeHtml(q.category)}</span>
              <span class="qb-tag topic">${escapeHtml(q.topic)}</span>
              ${dup ? `<span class="qb-tag" style="background:#fdf4e3;color:#7a5410;border:1px solid #e0b768;" title="Looks ${dup.pct}% similar to “${escapeHtml(dup.title)}” already in the bank">🟡 Possible duplicate</span>` : ''}
              ${isNew ? '<span class="qb-tag" style="background:var(--accent-orange-light);color:var(--accent-orange);" title="Just added by Rapid add — review and approve">⚡ Just added</span>' : ''}
              ${q.topicConfidence === 'low' ? '<span class="qb-tag" style="background:#fee2e2;color:#dc2626;" title="AI was unsure of this topic — please check it">⚠ check topic</span>' : q.topicConfidence === 'medium' ? '<span class="qb-tag" style="background:#fdf4e3;color:#b45309;" title="AI was fairly sure of this topic — worth a glance">~ topic?</span>' : ''}
              <span class="vetting-badge ${statusClass}">${statusClass.charAt(0).toUpperCase() + statusClass.slice(1)}</span>
              ${_vetTimeLabel(q)}
              ${qTagChipsHtml(q, { plain: true })}
            </div>
          </div>
          <div class="qb-card-actions">
            <button class="qb-action-btn" title="Approve & Add to Bank" onclick="approveVetting('${q.id}')" style="color:var(--primary);">
              <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><polyline points="20 6 9 17 4 12"/></svg>
            </button>
            <button class="qb-action-btn" title="Edit" onclick="editQuestion('${q.id}')">
              <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M11 4H4a2 2 0 0 0-2 2v14a2 2 0 0 0 2 2h14a2 2 0 0 0 2-2v-7"/><path d="M18.5 2.5a2.121 2.121 0 0 1 3 3L12 15l-4 1 1-4 9.5-9.5z"/></svg>
            </button>
            <button class="qb-action-btn delete-qb" title="Delete" onclick="deleteVetting('${q.id}')">
              <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><polyline points="3 6 5 6 21 6"/><path d="M19 6v14a2 2 0 0 1-2 2H7a2 2 0 0 1-2-2V6m3 0V4a2 2 0 0 1 2-2h4a2 2 0 0 1 2 2v2"/></svg>
            </button>
          </div>
        </div>
        <div class="qb-card-preview">${escapeHtml(preview)}</div>
        ${dup ? `<div class="vetting-flag-note" style="background:#fffbeb;border-color:#e0b768;color:#7a5410;display:flex;align-items:center;gap:10px;flex-wrap:wrap;">🟡 <b>Possible duplicate</b> of “${escapeHtml(dup.title)}” (${dup.pct}% match). ${_dupSeeOriginalBtn(dup, 'font-size:0.76rem;padding:4px 10px;border-color:#e0b768;color:#7a5410;')}</div>` : ''}
        ${q.status === 'flagged' && q._flag ? `<div class="vetting-flag-note">🚩 <b>Flagged by ${escapeHtml(q._flag.by || 'a student')}</b>${q._flag.when ? ' · ' + escapeHtml(q._flag.when) : ''}${q._flag.comment ? `<div class="vfn-comment">“${escapeHtml(q._flag.comment)}”</div>` : ''}</div>` : ''}
        ${isNew ? `<div style="margin-top:10px;"><button class="btn btn-outline" style="font-size:0.78rem;padding:5px 12px;" onclick="editQuestion('${q.id}')"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" style="width:13px;height:13px;vertical-align:-2px;margin-right:4px;"><path d="M11 4H4a2 2 0 0 0-2 2v14a2 2 0 0 0 2 2h14a2 2 0 0 0 2-2v-7"/><path d="M18.5 2.5a2.121 2.121 0 0 1 3 3L12 15l-4 1 1-4 9.5-9.5z"/></svg>Open in editor</button></div>` : ''}
      </div>`;
  }).join('');
  container.innerHTML = jobCards + qCards;
}

// Returning to the Vetting List after an edit: put the list back exactly as it
// was (same scroll position) and flash the card that was just edited, so the
// admin can carry straight on with the next question.
function _vetFocusScroll() {
  const y = _vetReturnScroll, id = _vetReturnFocus;
  _vetReturnScroll = 0; _vetReturnFocus = null;
  requestAnimationFrame(() => {
    window.scrollTo(0, y);
    if (!id) return;
    const sel = '[data-vetid="' + (window.CSS && CSS.escape ? CSS.escape(id) : id) + '"]';
    const el = document.querySelector('#vettingListGrid ' + sel);
    if (!el) return;   // approved/deleted out of vetting — the restored scroll is enough
    const r = el.getBoundingClientRect();
    if (r.bottom < 0 || r.top > window.innerHeight) {
      try { el.scrollIntoView({ behavior: 'smooth', block: 'center' }); } catch (_) { el.scrollIntoView(); }
    }
    const prevShadow = el.style.boxShadow;   // keep the duplicate-warning outline, if any
    el.style.transition = 'box-shadow .3s ease';
    el.style.boxShadow = '0 0 0 3px var(--primary, #0b6b4f)';
    setTimeout(() => { el.style.boxShadow = prevShadow; }, 2200);
  });
}

function approveVetting(id) {
  const idx = vettingList.findIndex(q => q.id === id);
  if (idx === -1) return;
  const q = vettingList[idx];
  q.status = 'approved';
  if (q._flag) { delete q._flag; _resolveFlagsForQuestion(id); } // re-approved a flagged question
  delete q._dupOf;   // the admin has vetted it — drop the duplicate-suspicion marker
  questionBank.push(q);
  vettingList.splice(idx, 1);
  renderVettingList();
  updateCounts();
  showToast('Question approved and added to bank', 'success');
  // If this vetting item belonged to another admin, keep the approved
  // question in that admin's bank rather than copying it into ours.
  if (_ownerUidByVettingId[id]) {
    _ownerUidByQuestionId[id] = _ownerUidByVettingId[id];
  }
  saveQuestion(q);       // add to questions subcollection
  deleteVettingDoc(id);  // remove from vetting subcollection
}

function deleteVetting(id) {
  showConfirm('Delete from Vetting', 'Remove this question from the vetting list?', () => {
    vettingList = vettingList.filter(q => q.id !== id);
    renderVettingList();
    updateCounts();
    showToast('Question removed from vetting list', 'info');
    deleteVettingDoc(id);
  });
}

// =====================================================================
// AI AUTO-VET
// Walks the vetting list and, for each pending question, asks the AI to pick
// the best topic + category, write/fix the model answers, fill an empty
// marking guide, and supply a question prompt when the question is answer-only
// — then approves the whole batch into the bank. Questions are handled by a
// small pool of concurrent AI workers (the "subagents").
// =====================================================================
const AUTOVET_CONCURRENCY = 3;
const AUTOVET_CATEGORIES = ['CER', 'Single Relationship', 'Double Relationship', 'Reliability', 'Fairness', 'Accuracy', 'Constant Variable', 'Hypothesis', 'Aim', 'Conclusion', 'Definition', 'Explanation', 'Stating', 'Key Concepts'];
// Lazy: topicLevelMap is declared further down the module, so reading it at
// call time (not module-eval time) avoids the temporal-dead-zone error.
function autoVetTopics() { return currentTopics(); }

// The editable model-answer slots in a question, in document order. Each slot
// points back at its block + field so the AI's text lands where the marker reads it.
function _vetAnswerSlots(q) {
  const slots = [];
  (q.blocks || []).forEach(b => {
    if (b.type === 'answer') {
      ['claim', 'evidence', 'reasoning'].forEach(f =>
        slots.push({ block: b, field: f, kind: f, current: stripHtml(b[f] || '') }));
    } else if (b.type === 'plainanswer' || b.type === 'explanation') {
      slots.push({ block: b, field: 'content', kind: b.type, current: stripHtml(b.content || '') });
    }
  });
  return slots;
}

// True when the question already shows the student some wording (so we don't
// bolt on a redundant intro).
function _vetHasPrompt(q) {
  return (q.blocks || []).some(b =>
    (b.type === 'text' && stripHtml(b.content || '').trim()) ||
    (b.type === 'part' && (stripHtml(b.content || '').trim() || (b.label || '').trim())) ||
    (b.type === 'mcq' && (b.options || []).some(o => stripHtml(o.text || '').trim())));
}

function _vetMcqBlock(q) {
  return (q.blocks || []).find(b => b.type === 'mcq' && (b.options || []).some(o => stripHtml(o.text || '').trim()));
}

function _vetBuildPrompt(q, slots, mcq) {
  const ctx = _questionContext(q);
  const labelFor = k => k === 'claim' ? 'Claim' : k === 'evidence' ? 'Evidence' : k === 'reasoning' ? 'Reasoning' : k === 'explanation' ? 'Explanation' : 'Answer';
  const slotLines = slots.map((s, i) => `  ${i}. [${labelFor(s.kind)}] current: ${s.current ? JSON.stringify(s.current) : '(empty)'}`).join('\n');
  const mcqLines = mcq ? 'MULTIPLE-CHOICE OPTIONS:\n' + mcq.options.map((o, i) => `  ${i}. ${stripHtml(o.text || '')}`).join('\n') + '\n' : '';
  return `You are helping a Singapore primary-school science teacher vet a practice question before it goes into the question bank.

QUESTION TITLE: ${q.title || '(untitled)'}
CURRENT TOPIC: ${q.topic || '(none)'}
CURRENT CATEGORY: ${q.category || '(none)'}
QUESTION CONTENT: ${ctx || '(no wording provided)'}
${mcqLines}ANSWER SLOTS (write the ideal model answer for each — improve weak ones, fill empty ones):
${slotLines || '  (none)'}

Return ONLY JSON with this exact shape:
{
  "topic": "<the single closest topic from the list>",
  "category": "<the single closest category from the list>",
  "markingGuide": "<one or two sentences telling the AI marker what a full-mark answer must contain, including accepted alternative wording>",
  "needsIntro": <true ONLY if QUESTION CONTENT above is empty/missing, otherwise false>,
  "introText": "<if needsIntro: a short, clear question prompt a P3-P6 student would read; otherwise an empty string>",
  "answers": [<one model-answer string per slot, in the same order; for a Claim/Evidence/Reasoning slot write only that portion; 1-3 sentences each>],
  "mcqCorrectIndex": <0-based index of the correct option above, or -1 if there is no multiple-choice block>
}
Rules:
- topic MUST be exactly one of: ${autoVetTopics().join('; ')}.
- category MUST be exactly one of: ${AUTOVET_CATEGORIES.join('; ')}.
- "answers" MUST contain exactly ${slots.length} item(s) in order. If there are 0 slots, return [].
- Write the actual answer text itself, not advice or instructions. Plain text only — no markdown, no [[brackets]].`;
}

// Run the AI for one question and apply its result in place. Resolves on success,
// rejects on AI/parse error (the question is then left in the vetting list).
async function _autoVetOne(q) {
  const slots = _vetAnswerSlots(q);
  const mcq = _vetMcqBlock(q);
  const prompt = _vetBuildPrompt(q, slots, mcq);
  const raw = await askGemini(prompt, { maxOutputTokens: 420 + slots.length * 170, temperature: 0.2, json: true });
  const data = _parseAIJson(raw);

  // Topic / category — accept only values from the allowed lists.
  if (data.topic && autoVetTopics().includes(data.topic)) q.topic = data.topic;
  if (data.category && AUTOVET_CATEGORIES.includes(data.category)) q.category = normalizeCategoryValue(data.category);
  applyMcqCategory(q); // keep MCQ questions in the Multiple Choice Question category

  // Fill an empty marking guide (don't clobber one the admin wrote by hand).
  if (!String(q.markingGuide || '').trim() && data.markingGuide && String(data.markingGuide).trim()) {
    q.markingGuide = String(data.markingGuide).trim();
  }

  // Model answers — write each back to its block field (stored as plain text,
  // matching the inline "edit / AI-regenerate" flow).
  if (Array.isArray(data.answers)) {
    slots.forEach((s, i) => {
      const val = (data.answers[i] == null ? '' : String(data.answers[i])).trim();
      if (val) s.block[s.field] = val;
    });
  }

  // Correct MCQ option.
  if (mcq && Number.isInteger(data.mcqCorrectIndex) && data.mcqCorrectIndex >= 0 && mcq.options[data.mcqCorrectIndex]) {
    mcq.correctId = mcq.options[data.mcqCorrectIndex].id;
  }

  // Add a question prompt when the question is answer-only.
  if (data.needsIntro && data.introText && String(data.introText).trim() && !_vetHasPrompt(q)) {
    q.blocks.unshift({ id: generateBlockId(), type: 'text', content: escapeHtml(String(data.introText).trim()) });
  }
  return true;
}

// Runs `worker` over `items`, at most `limit` at a time; reports progress.
async function _autoVetPool(items, limit, worker, onProgress) {
  let idx = 0, done = 0;
  const results = new Array(items.length);
  async function runner() {
    while (idx < items.length) {
      const my = idx++;
      try { await worker(items[my]); results[my] = { ok: true }; }
      catch (e) { results[my] = { ok: false, error: e }; }
      if (onProgress) onProgress(++done, items.length);
    }
  }
  await Promise.all(Array.from({ length: Math.min(limit, items.length) }, runner));
  return results;
}

let _autoVetRunning = false;

function aiAutoVetAll() {
  if (_autoVetRunning) return;
  if (!window.__aiReady || !window.__aiReady()) {
    showToast('AI is not ready yet — try again in a moment', 'error');
    return;
  }
  const queue = vettingList.filter(q => {
    const s = q.status || 'pending';
    return s !== 'approved' && s !== 'rejected';
  });
  if (queue.length === 0) {
    showToast('Nothing to vet — no pending questions in the list', 'info');
    return;
  }
  showConfirm(
    'AI Auto-Vet All',
    `AI will classify the topic & category, write or fix the model answers, add any missing question wording, then approve all ${queue.length} pending question(s) into the bank. Continue?`,
    () => { _runAutoVet(queue); }
  );
}

async function _runAutoVet(queue) {
  _autoVetRunning = true;
  const btn = document.getElementById('aiAutoVetBtn');
  if (btn) btn.disabled = true;
  _openAutoVetModal(queue.length);

  // 1) AI pass — parallel pool; each worker mutates its question in place.
  const results = await _autoVetPool(queue, AUTOVET_CONCURRENCY, _autoVetOne,
    (done, total) => _setAutoVetStatus(`Analysing questions… ${done} / ${total}`, done, total));

  // 2) Approve every question the AI handled, into the bank.
  let approved = 0, failed = 0;
  results.forEach((r, i) => {
    const q = queue[i];
    if (!r || !r.ok) { failed++; if (r) console.error('auto-vet failed for', q && q.id, r.error); return; }
    const idx = vettingList.findIndex(v => v.id === q.id);
    if (idx === -1) return;
    q.status = 'approved';
    questionBank.push(q);
    vettingList.splice(idx, 1);
    // Keep an approved question under its original admin's namespace.
    if (_ownerUidByVettingId[q.id]) _ownerUidByQuestionId[q.id] = _ownerUidByVettingId[q.id];
    saveQuestion(q);        // async, retries internally
    deleteVettingDoc(q.id); // remove from the vetting subcollection
    approved++;
  });

  renderVettingList();
  renderQuestionBank();
  updateCounts();
  _finishAutoVetModal(approved, failed);
  if (approved) showToast(`Auto-vetted ${approved} question${approved === 1 ? '' : 's'} into the bank ✓`, 'success');
  if (failed) showToast(`${failed} question${failed === 1 ? '' : 's'} could not be processed — left in vetting`, 'error');

  if (btn) btn.disabled = false;
  _autoVetRunning = false;
}

function _openAutoVetModal(total) {
  const ov = document.getElementById('autoVetOverlay');
  if (!ov) return;
  document.getElementById('autoVetTitle').textContent = '✨ AI Auto-Vet in progress';
  document.getElementById('autoVetStatus').textContent = `Analysing questions… 0 / ${total}`;
  document.getElementById('autoVetBar').style.width = '0%';
  document.getElementById('autoVetSpinner').style.display = '';
  document.getElementById('autoVetCloseBtn').style.display = 'none';
  ov.classList.add('show');
}

function _setAutoVetStatus(msg, done, total) {
  const s = document.getElementById('autoVetStatus');
  if (s) s.textContent = msg;
  const bar = document.getElementById('autoVetBar');
  if (bar && total) bar.style.width = Math.round((done / total) * 100) + '%';
}

function _finishAutoVetModal(approved, failed) {
  document.getElementById('autoVetTitle').textContent = 'Auto-Vet complete';
  document.getElementById('autoVetSpinner').style.display = 'none';
  document.getElementById('autoVetBar').style.width = '100%';
  document.getElementById('autoVetStatus').innerHTML =
    `Added <strong>${approved}</strong> question${approved === 1 ? '' : 's'} to the bank.` +
    (failed ? ` <span style="color:var(--accent-red);">${failed} left in vetting (AI error).</span>` : '');
  document.getElementById('autoVetCloseBtn').style.display = '';
}

function closeAutoVet() {
  const ov = document.getElementById('autoVetOverlay');
  if (ov) ov.classList.remove('show');
}

