let _qPartScan = null;   // [{ q, hits, note }] awaiting Apply
function qPartScanBank() {
  if (!_canAuthor()) return;
  const out = [], refusedList = [];
  (questionBank || []).forEach(q => {
    const r = qPartScanQuestion(q);
    if (!r) return;
    if (r.refused) refusedList.push(r); else out.push(r);
  });
  _qPartScan = out;
  qPartRenderScan(refusedList);
}

// ---- Automatic conversion on sign-in --------------------------------------
// The Question Doctor panel is the place to REVIEW a conversion, but a bank
// full of questions whose parts are still characters in the text is a bank
// whose answer key is unreadable, and nobody should have to remember to go and
// press a button for that. So the unambiguous ones are converted in the
// background, once per load, the same way untagged questions get auto-tagged.
//
// Only what the scan already approves is touched: two or more markers, each at
// the very start of its own text block, in a question that has open answer
// boxes. Anything it refuses — most importantly a text block holding several
// markers at once — is left for a human and reported.
let _qPartAutoRan = false;
async function qPartAutoConvertInBackground() {
  if (_qPartAutoRan || !_canAuthor()) return;
  _qPartAutoRan = true;
  const targets = [];
  (questionBank || []).forEach(q => {
    const r = qPartScanQuestion(q);
    if (r && !r.refused && r.hits && r.hits.length >= 2) targets.push(r);
  });
  if (!targets.length) return;
  let done = 0, failed = 0;
  for (const r of targets) {
    const live = (questionBank || []).find(x => x && x.id === r.q.id);
    if (!live) continue;
    const next = JSON.parse(JSON.stringify(live));
    let conflict = false;
    for (const h of r.hits) {
      const b = next.blocks && next.blocks[h.i];
      if (!b || b.type !== 'text' || b.content !== h.before) { conflict = true; break; }
      b.content = h.html;
      b.part = h.letter;
    }
    if (conflict) continue;
    let ok = false;
    try { ok = await saveQuestion(next, { quiet: true }); } catch (e) { console.warn('auto part convert', r.q.id, e); }
    if (ok) {
      const i = questionBank.indexOf(live);
      if (i >= 0) questionBank[i] = next; else Object.assign(live, next);
      done++;
    } else failed++;
  }
  if (done) {
    try { renderQuestionBank(); } catch (e) {}
    try {
      showToast('🔡 Sorted ' + done + ' question' + (done === 1 ? '' : 's') + ' into official parts (a) (b) (c) — the answer key now labels each part'
        + (failed ? ' · ' + failed + ' could not be saved' : ''), failed ? 'error' : 'success');
    } catch (e) {}
  }
}
// Kick it off after sign-in has settled, so it never holds up the first paint.
function qPartAutoConvertLater() {
  if (!_canAuthor()) return;
  setTimeout(() => { qPartAutoConvertInBackground().catch(e => console.warn('part auto convert', e)); }, 4000);
}
function qPartRenderScan(refusedList) {
  const host = document.getElementById('qPartScanBody');
  if (!host) return;
  const rows = _qPartScan || [];
  const refused = refusedList || [];
  if (!rows.length && !refused.length) {
    host.innerHTML = `<div class="empty-note">No questions with typed "a)" markers found — either they are already using official parts, or they only have one part each.</div>`;
    return;
  }
  host.innerHTML =
    (rows.length ? `<div class="qpart-scan-head">
        <b>${rows.length}</b> question${rows.length === 1 ? '' : 's'} can be converted.
        The marker is removed from the text and becomes a real part, so the answer key can label each answer.
        <button class="btn btn-primary" type="button" onclick="qPartApplyScan()" style="margin-left:auto;">✓ Convert all ${rows.length}</button>
      </div>` : '')
    + rows.map((r, i) => `
      <div class="qpart-scan-row">
        <label class="qpart-scan-title">
          <input type="checkbox" checked data-qpart-pick="${i}">
          <span><b>${escapeHtml(r.q.title || 'Untitled')}</b>
          <span class="qpart-scan-meta">${escapeHtml(r.q.topic || '')} · ${r.hits.length} parts${r.note ? ' · ⚠️ ' + escapeHtml(r.note) : ''}</span></span>
        </label>
        ${r.hits.map(h => `<div class="qpart-scan-diff">
            <span class="qpart-scan-badge">(${h.letter})</span>
            <span class="qpart-scan-was">${escapeHtml(stripHtml(h.before).slice(0, 90))}</span>
            <span class="qpart-scan-arrow">→</span>
            <span class="qpart-scan-now">${escapeHtml(stripHtml(h.html).slice(0, 90))}</span>
          </div>`).join('')}
      </div>`).join('')
    + (refused.length ? `<div class="qpart-scan-refused"><b>${refused.length} left alone.</b> Each has a text block holding more than one marker, which usually means several parts were typed into one box. Splitting those is a judgement call, so they are yours to do by hand:
        <ul>${refused.map(r => `<li>${escapeHtml(r.q.title || 'Untitled')} — ${escapeHtml(r.refused)}</li>`).join('')}</ul></div>` : '');
}
async function qPartApplyScan() {
  if (!_isAdmin() || !_qPartScan || !_qPartScan.length) return;
  const picked = Array.prototype.slice.call(document.querySelectorAll('[data-qpart-pick]'))
    .filter(c => c.checked).map(c => _qPartScan[Number(c.dataset.qpartPick)]).filter(Boolean);
  if (!picked.length) { showToast('Nothing ticked', 'error'); return; }
  if (!confirm(`Convert ${picked.length} question${picked.length === 1 ? '' : 's'}?\n\nThe typed "a)" markers are removed from the question text and stored as real parts instead. The wording is otherwise untouched. This cannot be undone in one click.`)) return;
  const done = [], failed = [], skipped = [];
  for (const r of picked) {
    const id = r.q && r.q.id;
    // Re-resolve by id rather than trusting the object captured at scan time.
    // The preview survives navigation, so between the scan and this click the
    // admin may have edited the question (saveEditedQuestion REPLACES the bank
    // entry with a fresh object) or deleted it — writing the captured object
    // back would silently undo the edit, or resurrect the deleted document.
    const live = (questionBank || []).find(x => x && x.id === id);
    if (!live) { skipped.push((r.q && r.q.title) || 'Untitled'); continue; }
    // Build the change on a COPY, so a failed write cannot leave the in-memory
    // bank disagreeing with Firestore for the rest of the session.
    const next = JSON.parse(JSON.stringify(live));
    let conflict = false;
    for (const h of r.hits) {
      const b = next.blocks && next.blocks[h.i];
      // The block must still be the one that was scanned. An edit elsewhere
      // (worksheet quick-edit writes the same object in place) or a reordered
      // blocks array would otherwise have another block's text overwritten
      // with this hit's stripped content.
      if (!b || b.type !== 'text' || b.content !== h.before) { conflict = true; break; }
      b.content = h.html;
      b.part = h.letter;
    }
    if (conflict) { skipped.push(live.title || 'Untitled'); continue; }
    let ok = false;
    try { ok = await saveQuestion(next, { quiet: true }); }
    catch (e) { console.warn('part convert', id, e); }
    if (ok) {
      // Commit to the in-memory bank only once Firestore has it.
      const i = questionBank.indexOf(live);
      if (i >= 0) questionBank[i] = next; else Object.assign(live, next);
      done.push(live.title || 'Untitled');
    } else {
      failed.push(live.title || 'Untitled');
    }
  }
  _qPartScan = null;
  qPartScanBank();          // re-scans from the live bank, so a failure is offered again
  renderQuestionBank();
  const bits = [`🔡 Converted ${done.length} question${done.length === 1 ? '' : 's'}`];
  if (failed.length) bits.push(`${failed.length} failed (${failed.slice(0, 3).join(', ')}${failed.length > 3 ? '…' : ''}) — press Find again to retry`);
  if (skipped.length) bits.push(`${skipped.length} skipped, changed since the scan (${skipped.slice(0, 3).join(', ')}${skipped.length > 3 ? '…' : ''})`);
  showToast(bits.join(' · '), (failed.length || skipped.length) ? 'error' : 'success');
}

// Clear every part on this question.
function clearAllParts() {
  if (!Array.isArray(blocks)) return;
  let n = 0;
  blocks.forEach(b => { if (qPartNormalize(b.part)) { b.part = ''; n++; } });
  if (!n) { showToast('This question has no parts to clear', 'error'); return; }
  renderBlocks();
  showToast('Cleared ' + n + ' part label' + (n === 1 ? '' : 's'), 'success');
}

// An annotation pad's own answer — the marked-up screenshot and/or the words —
// pushed onto the printed answer key for the part it belongs to. Annotation
// questions have no answer block, so without this their key page was blank
// however carefully the pad had been keyed.
function _pushAnnotAnswerKey(sections, block, part) {
  if (!block) return;
  const isPad = block.type === 'workingSpace' ? !!block.annotate : (block.type === 'image' && block.annotate !== false);
  if (!isPad) return;
  const words = stripHtml(block.answerKey || '').trim();
  const img = String(block.answerImg || '').trim();
  if (!words && !img) return;
  const name = String(block.dgnLabel || '').trim();
  sections.push({
    label: name ? 'Annotation — ' + name : 'Annotation',
    part: qPartNormalize(part),
    content: (img ? `<div><img src="${escapeHtml(transformImageUrl(img))}" alt="answer key" style="max-width:100%;max-height:150pt;"></div>` : '')
      + (words ? `<div>${escapeHtml(words)}</div>` : '')
  });
}
function _pushAnswerKeySection(sections, label, content, part) {
  const html = sanitizeAnswerKeyHtml(content);
  if (!stripHtml(html)) return;
  sections.push({ label, content: html, part: qPartNormalize(part) });
}
// Render the answer-key body for one question. The part label is printed once,
// when the part CHANGES — so a question with a Claim/Evidence/Reasoning trio
// under part (b) gets one "(b)" heading above the three, not three of them.
// Both print paths call this, which is how they stay in step.
function _akSectionsHtml(sections) {
  let html = '', shown = null;
  (sections || []).forEach(sec => {
    const p = qPartNormalize(sec.part);
    if (p && p !== shown) {
      html += `<div class="ak-part">${escapeHtml(qPartLabel(p))}</div>`;
      shown = p;
    }
    // An unparted section after a parted one (the trailing explanation, say)
    // must not look like it belongs to the last part.
    if (!p) shown = null;
    if (sec.label) html += `<div class="ak-sublabel">${escapeHtml(sec.label)}</div>`;
    html += `<div class="ak-fullcontent${p ? ' ak-parted' : ''}">${sec.content}</div>`;
  });
  return html;
}

// Keep simple formatting (lists, sup/sub, bold, underline) for answer-key rendering
function sanitizeAnswerKeyHtml(content) {
  if (!content) return '';
  return String(content)
    .replace(/<script[\s\S]*?>[\s\S]*?<\/script>/gi, '')
    .replace(/<style[\s\S]*?>[\s\S]*?<\/style>/gi, '')
    .replace(/\son\w+="[^"]*"/gi, '')
    .replace(/\son\w+='[^']*'/gi, '');
}

// How many ruled lines a printed answer box gets.
//
// Sized from the model answer stored in the bank, so the space on the paper
// matches the answer the question actually wants — but scaled for a hand, not
// for typed text, and floored at 2 lines so an ordinary short answer never
// prints a cramped single rule. A one-number or few-word answer ("Population",
// "4.5 N") gets the single line it needs and nothing more.
//
// The old formula was max(3, chars / 70): a 3-line floor on everything, and a
// character budget from typed text, which left long answers short of room and
// one-word answers with three empty rules.
const PRINT_ANSWER_LINES = 2;   // the default — what any ordinary answer gets
const PRINT_LINE_CHARS = 52;    // characters a P5 hand fits on one ruled line
const PRINT_HAND_ALLOWANCE = 1.15;  // a student's wording runs longer than the model's
const PRINT_SHORT_CHARS = 20;   // at or under this, and ≤4 words → one line
const PRINT_LINES_MAX = 12;     // nothing sensible needs more; a cap stops a runaway box
// The ceiling on the author's manual "Printed lines" override. It used to be
// 40: a ruled line is 20pt, so 40 of them plus padding is 287mm — 29mm TALLER
// than a sheet, in a box that refuses to break. The question went down the
// tall/flow path, jumped a sheet whole and still did not fit. 24 lines is
// 169mm, which leaves room for a stem above it and always fits one page.
const PRINT_LINES_MANUAL_MAX = 24;
// Plain text of a model answer, with the [[keyword]] brackets taken out — they
// are markup for the recall game, not something the student writes.
function _printAnswerPlain(text) {
  return stripHtml(String(text || '')).replace(/\[\[|\]\]/g, '').replace(/\s+/g, ' ').trim();
}
// `text` is the model answer this box is for (per field, so a one-line Claim
// does not inherit a five-line Reasoning). The block's "Printed lines" field
// overrides the estimate outright.
function printAnswerLines(block, text) {
  const override = parseInt(block && block.printLines, 10);
  if (isFinite(override) && override > 0) return Math.min(PRINT_LINES_MANUAL_MAX, override);
  const plain = _printAnswerPlain(text);
  if (!plain) return PRINT_ANSWER_LINES;                 // nothing stored — give the default
  const words = plain.split(' ').filter(Boolean).length;
  if (words <= 4 && plain.length <= PRINT_SHORT_CHARS) return 1;
  const need = Math.ceil((plain.length * PRINT_HAND_ALLOWANCE) / PRINT_LINE_CHARS);
  return Math.max(PRINT_ANSWER_LINES, Math.min(PRINT_LINES_MAX, need));
}

// ===== OPEN ENDED MODE =====
function doPrintWorksheetOpen() {
  const selected = questionBank.filter(q => printSelectedIds.has(q.id));
  const output = document.getElementById('printOutput');
  let allHtml = '';
  const answerKeyData = []; // { title, sections: [{ label?, content }] }

  selected.forEach((q, qIndex) => {
    const isMcq = q.blocks.some(b => b.type === 'mcq') && !q.blocks.some(b => b.type === 'answer' || b.type === 'plainanswer');
    const bigImgs = imgQuestionNeedsBig(q);   // the picture IS the options → print it tall
    let qHtml = `<div class="print-question-chunk" data-qid="${escapeHtml(q.id)}"${isMcq ? ' data-mcq="1"' : ''}>`;

    if (qIndex === 0) {
      qHtml += `<div class="print-worksheet-header">
        <img class="print-worksheet-header-logo" src="https://dl.dropboxusercontent.com/scl/fi/h40yjlyg8ldefwfaa3dib/polymath-logo-sticker.png?rlkey=o1ra4taqy79gt9t8u096v82zj" alt="Polymath" onerror="this.onerror=null;this.src='data:image/svg+xml,%3Csvg xmlns=%22http://www.w3.org/2000/svg%22 width=%2252%22 height=%2252%22 viewBox=%220 0 52 52%22%3E%3Crect width=%2252%22 height=%2252%22 rx=%2210%22 fill=%22%234a7c59%22/%3E%3Ctext x=%2226%22 y=%2237%22 font-family=%22DM Sans,sans-serif%22 font-size=%2232%22 font-weight=%22700%22 fill=%22white%22 text-anchor=%22middle%22%3EP%3C/text%3E%3C/svg%3E';">
        <div class="print-worksheet-header-text">
          <h1>CER Worksheet</h1>
          <p>Polymath Learning Centre</p>
        </div>
      </div>
      <div class="print-student-info">
        <span>Name: ___________________________</span>
        <span>Date: _______________</span>
        <span>Class: ___________</span>
      </div>`;
    }

    qHtml += `<div class="print-q-header">
      <h2>${escapeHtml(q.title)}</h2>
      <div class="print-q-meta">${escapeHtml(q.category)} &middot; ${escapeHtml(q.topic)}</div>
    </div>`;

    const qSections = [];
    const qParts = qPartMap(q.blocks);

    q.blocks.forEach(block => {
      const bPart = qPartOf(qParts, block);
      // Annotation pads (an image students draw on, a working area) carry their
      // own answer. Done here rather than per-case because the pad types are
      // spread across `image`, `workingSpace` and the `default` branch; the
      // helper filters to real pads that actually have an answer.
      _pushAnnotAnswerKey(qSections, block, bPart);
      switch (block.type) {
        case 'text': {
          // Text blocks are shown normally (questions / instructions),
          // keeping line breaks so inline option lists stay separated.
          const textHtml = escapeHtmlKeepLines(block.content);
          // A block that OPENS a part prints its label in the margin, so the
          // paper reads "(a) What is X?" exactly as it used to when the marker
          // was typed into the text — only now it is a field, not characters.
          const own = qPartNormalize(block.part);
          if (textHtml || own) {
            qHtml += `<div class="print-text-block${own ? ' print-has-part' : ''}">`
              + (own ? `<span class="print-part-label">${escapeHtml(qPartLabel(own))}</span>` : '')
              + textHtml + `</div>`;
          }
          break;
        }
        case 'image': {
          if (block.url) {
            qHtml += `<div class="print-text-block"><img${imgPrintAttr(block, bigImgs)} src="${escapeHtml(transformImageUrl(block.url))}" alt="Image" style="${imgSizeStyle(block)}"></div>`;
          }
          break;
        }
        case 'answer': {
          // CER answer — labelled blank writing boxes, each sized from ITS OWN
          // model answer (a one-line Claim beside a five-line Reasoning).
          qHtml += `<div class="print-open-cer-section">`;
          qHtml += `<div class="print-open-cer-label">Claim</div><div class="print-open-cer-box">${openEndedLines(printAnswerLines(block, block.claim))}</div>`;
          qHtml += `<div class="print-open-cer-label">Evidence</div><div class="print-open-cer-box">${openEndedLines(printAnswerLines(block, block.evidence))}</div>`;
          qHtml += `<div class="print-open-cer-label">Reasoning</div><div class="print-open-cer-box">${openEndedLines(printAnswerLines(block, block.reasoning))}</div>`;
          qHtml += `</div>`;

          // Collect formatted text for answer key. Empty parts are skipped —
          // pushing blank sections made hasAnySections true for a bank with no
          // model answers, which printed an Answer Key sheet holding nothing
          // but its heading and a row of empty labels.
          _pushAnswerKeySection(qSections, 'Claim', block.claim, bPart);
          _pushAnswerKeySection(qSections, 'Evidence', block.evidence, bPart);
          _pushAnswerKeySection(qSections, 'Reasoning', block.reasoning, bPart);
          break;
        }
        case 'plainanswer': {
          // Plain answer — blank writing box, sized from the model answer
          const paLines = openEndedLines(printAnswerLines(block, block.content));
          qHtml += `<div class="print-open-answer-box"><div class="print-open-lines">${paLines}</div></div>`;
          _pushAnswerKeySection(qSections, null, block.content, bPart);
          break;
        }
        case 'explanation': break;
        case 'video': {
          if (block.url) {
            qHtml += `<div class="print-text-block" style="font-style:italic;color:#666;">Video: ${escapeHtml(block.url)}</div>`;
          }
          break;
        }
        case 'table': {
          qHtml += renderTableReadonly(block, 'print-table');
          break;
        }
        // Explicit, so it does NOT fall through to renderImportedBlockStudent,
        // whose fillblank branch prints the answer inside every blank.
        case 'fillblank': {
          if (_fbHasBlanks(block)) {
            qHtml += _fbPrintHtml(block);
            _pushAnswerKeySection(qSections, 'Fill in the blanks', _fbAnswerKeyText(block), bPart);
          } else {
            qHtml += `<div class="print-text-block">${escapeHtmlKeepLines(block.text || '')}</div>`;
          }
          break;
        }
        default: {
          qHtml += renderImportedBlockStudent(block);
          // The correct option belongs on the key. Without it an MCQ-only
          // question produced NO sections at all, and the
          // `sections.length === 0` guard below dropped it from the key
          // entirely — so a mostly-MCQ paper printed a key that silently
          // skipped most of its questions. Same shape the saved-worksheet
          // builder uses, so the two keys read alike.
          if (block.type === 'mcq') {
            const mo = block.options || [];
            const ci = mo.findIndex(o => o && o.id === block.correctId);
            if (ci >= 0) qSections.push({ label: 'Answer', content: `<b>${ci + 1}.</b> ` + sanitizeAnswerKeyHtml(mo[ci].text || ''), part: qPartNormalize(bPart) });
          }
          break;
        }
      }
    });

    qHtml += `</div>`;
    allHtml += qHtml;
    const _akExtra = _qAnswerKeyExtraSection(q);
    if (_akExtra) qSections.push(_akExtra);
    answerKeyData.push({ title: q.title, sections: qSections });
  });

  // Answer Key Page (open ended — full answer text)
  const hasAnySections = answerKeyData.some(d => d.sections.length > 0);
  if (hasAnySections) {
    allHtml += `<div class="print-question-page print-answer-key-page">`;
    allHtml += `<h2>Answer Key</h2>`;
    answerKeyData.forEach(qData => {
      if (qData.sections.length === 0) return;
      allHtml += `<div class="print-ak-question">`;
      allHtml += `<h4>${escapeHtml(qData.title)}</h4>`;
      allHtml += `<div class="print-ak-fulltext">`;
      allHtml += _akSectionsHtml(qData.sections);
      allHtml += `</div></div>`;
    });
    allHtml += `</div>`;
  }

  output.innerHTML = allHtml;
  autoscaleAndPrint(output);
}

// ===== SHARED: Auto-scale pages and trigger print =====
// ---- Print progress overlay ----
// Building a worksheet (loading every question's images, then measuring each
// one at true print size) can take several seconds, during which the browser
// print dialog hasn't opened yet — so it looks like "nothing happened". This
// lightweight overlay shows live progress so the student knows it's working.
(function injectPrintProgressStyles(){
  const css = `
  #printProgress{ position:fixed; inset:0; z-index:6000; display:none; align-items:center; justify-content:center; background:rgba(20,22,20,0.55); backdrop-filter:blur(2px); }
  #printProgress.show{ display:flex; }
  #printProgress .pp-card{ background:#fff; border-radius:16px; padding:26px 30px; max-width:340px; width:calc(100% - 48px); text-align:center; box-shadow:0 18px 50px rgba(0,0,0,0.28); }
  #printProgress .pp-spin{ width:38px; height:38px; margin:2px auto 14px; border:4px solid var(--primary-light,#e8f3ec); border-top-color:var(--primary,#0b6b4f); border-radius:50%; animation:ppspin 0.8s linear infinite; }
  @keyframes ppspin{ to{ transform:rotate(360deg); } }
  #printProgress .pp-msg{ font-size:0.95rem; font-weight:600; color:var(--text,#1a1a1a); line-height:1.45; }
  #printProgress .pp-sub{ font-size:0.8rem; color:var(--text-muted,#666c71); margin-top:6px; }
  #printProgress .pp-bar{ height:7px; border-radius:6px; background:var(--primary-light,#e8f3ec); margin-top:14px; overflow:hidden; }
  #printProgress .pp-bar-fill{ height:100%; width:0%; background:var(--primary,#0b6b4f); border-radius:6px; transition:width 0.25s ease; }
  @media print{ #printProgress{ display:none !important; } }`;
  const s = document.createElement('style'); s.textContent = css; document.head.appendChild(s);
  const el = document.createElement('div'); el.id = 'printProgress';
  el.innerHTML = `<div class="pp-card"><div class="pp-spin"></div><div class="pp-msg" id="printProgressMsg">Preparing worksheet…</div><div class="pp-sub" id="printProgressSub"></div><div class="pp-bar"><div class="pp-bar-fill" id="printProgressBar"></div></div></div>`;
  (document.body || document.documentElement).appendChild(el);
})();
let _printProgressTimer = null;
function _printProgressShow(msg, sub){
  const o = document.getElementById('printProgress'); if (!o) return;
  const m = document.getElementById('printProgressMsg'); if (m) m.textContent = msg || 'Preparing worksheet…';
  const s = document.getElementById('printProgressSub'); if (s) s.textContent = sub || '';
  const b = document.getElementById('printProgressBar'); if (b) b.style.width = '0%';
  o.classList.add('show');
  // Fail-safe: never leave the overlay stuck if something downstream throws.
  if (_printProgressTimer) clearTimeout(_printProgressTimer);
  _printProgressTimer = setTimeout(() => { o.classList.remove('show'); }, 40000);
}
function _printProgressUpdate(msg, frac, sub){
  const m = document.getElementById('printProgressMsg'); if (m && msg != null) m.textContent = msg;
  const s = document.getElementById('printProgressSub'); if (s && sub != null) s.textContent = sub;
  const b = document.getElementById('printProgressBar'); if (b && frac != null) b.style.width = Math.max(0, Math.min(100, Math.round(frac * 100))) + '%';
}
function _printProgressHide(){ if (_printProgressTimer) { clearTimeout(_printProgressTimer); _printProgressTimer = null; } const o = document.getElementById('printProgress'); if (o) o.classList.remove('show'); }

// Preload every image URL (in the live document, so the browser caches them)
// before we build and measure the worksheet — cached images then report their
// true size immediately, which both speeds up measurement AND stops questions
// being cut across a page break because an unloaded image measured as 0-height.
function _preloadImageUrls(urls, onProgress){
  const uniq = [...new Set((urls || []).filter(Boolean))];
  return new Promise(resolve => {
    if (!uniq.length) { resolve(); return; }
    let done = 0;
    const tick = () => { done++; if (onProgress) onProgress(done, uniq.length); if (done >= uniq.length) resolve(); };
    uniq.forEach(u => {
      const im = new Image();
      let settled = false;
      const one = () => {
        if (im.naturalWidth && im.naturalHeight) _printImgNatural.set(u, [im.naturalWidth, im.naturalHeight]);
        if (settled) return; settled = true; tick();
      };
      im.onload = one; im.onerror = one;
      im.src = u;
      if (im.complete) one();                 // already cached
      setTimeout(one, 12000);                 // per-image safety cap
    });
  });
}

// ---- Reserving a picture's space before it has loaded ----------------------
// An <img> that has not decoded yet occupies about ONE LINE (~22px, its alt
// box), not the ~350px it really prints at. The planner measures in a throwaway
// iframe that RE-FETCHES every picture, so on a slow link its readiness net
// expires with the pictures still in flight and each page is measured as though
// its diagrams were a line of text. Three questions get packed onto one sheet —
// and the main document has those same pictures decoded already, so at print
// time they snap to full height on a page box that is a FIXED height with
// visible overflow. The surplus paints over the next sheet: two questions'
// headings, stems and options superimposed, which is exactly the fault this was
// found from.
//
// So remember every picture's intrinsic size wherever the app has already seen
// it, and stamp width/height onto the copies handed to the planner. Chrome
// derives the aspect ratio from those attributes and reserves the correct box
// BEFORE a single byte arrives, so the measurement stops depending on the
// network. The attributes change nothing once the picture does load — the ratio
// they describe is the picture's own.
const _printImgNatural = new Map();   // src → [naturalWidth, naturalHeight]

function _printLearnImgDims(root) {
  if (!root || !root.querySelectorAll) return;
  Array.from(root.querySelectorAll('img')).forEach(im => {
    const src = im.getAttribute('src');
    if (src && im.naturalWidth && im.naturalHeight) _printImgNatural.set(src, [im.naturalWidth, im.naturalHeight]);
  });
}

// Stamp what we know; return how many pictures are STILL without a reserved box
// and still in flight. A non-zero count means the plan about to be made is
// measuring a diagram as a line of text, and the caller must not trust it.
// A picture that has finished and failed (complete, naturalWidth 0) is NOT
// counted: it renders as the same small broken box in the planner and in the
// printer, so the two agree and nothing can overflow.
function _printStampImgDims(root) {
  let unsized = 0;
  if (!root || !root.querySelectorAll) return 0;
  Array.from(root.querySelectorAll('img')).forEach(im => {
    if (im.getAttribute('width') && im.getAttribute('height')) return;
    const dim = _printImgNatural.get(im.getAttribute('src'));
    if (dim) { im.setAttribute('width', String(dim[0])); im.setAttribute('height', String(dim[1])); return; }
    if (im.naturalWidth && im.naturalHeight) {
      _printImgNatural.set(im.getAttribute('src'), [im.naturalWidth, im.naturalHeight]);
      im.setAttribute('width', String(im.naturalWidth));
      im.setAttribute('height', String(im.naturalHeight));
      return;
    }
    if (!im.complete) unsized++;
  });
  return unsized;
}

function autoscaleAndPrint(output, opts) {
  // Wait for all images to load before printing
  const images = Array.from(output.querySelectorAll('img'));
  const unloaded = images.filter(img => !img.complete);

  if (unloaded.length > 0) {
    _printProgressShow('Preparing worksheet…', 'Loading images 0/' + unloaded.length);
    let remaining = unloaded.length;
    const total = unloaded.length;
    let loaded = 0;
    // Latched: the safety timeout used to fire proceed() and then EVERY late
    // image fired it again (remaining goes negative, so the `<= 0` test keeps
    // passing) — each re-entry rebuilt the DOM and opened another print dialog.
    let started = false;
    const proceed = () => {
      if (started) return;
      started = true;
      _printProgressUpdate('Laying out pages…', 0.9, 'Measuring each question at print size');
      doScaleAndPrint(output, opts);
    };
    const onReady = () => {
      loaded++; remaining--;
      _printProgressUpdate(null, 0.1 + 0.75 * (loaded / total), 'Loading images ' + loaded + '/' + total);
      if (remaining <= 0) proceed();
    };
    unloaded.forEach(img => {
      img.addEventListener('load', onReady, { once: true });
      img.addEventListener('error', onReady, { once: true });
    });
    // Safety timeout — don't wait forever if an image is very slow
    setTimeout(proceed, 12000);
  } else {
    _printProgressShow('Laying out pages…', 'Measuring each question at print size');
    _printProgressUpdate(null, 0.9);
    doScaleAndPrint(output, opts);
  }
}

function _createPrintPageFooter() {
  const footer = document.createElement('div');
  footer.className = 'print-page-footer';
  footer.innerHTML = `<img src="https://dl.dropboxusercontent.com/scl/fi/h40yjlyg8ldefwfaa3dib/polymath-logo-sticker.png?rlkey=o1ra4taqy79gt9t8u096v82zj" alt="Polymath" onerror="this.onerror=null;this.src='data:image/svg+xml,%3Csvg xmlns=%22http://www.w3.org/2000/svg%22 width=%2222%22 height=%2222%22 viewBox=%220 0 22 22%22%3E%3Crect width=%2222%22 height=%2222%22 rx=%224%22 fill=%22%234a7c59%22/%3E%3Ctext x=%2211%22 y=%2216%22 font-family=%22DM Sans,sans-serif%22 font-size=%2214%22 font-weight=%22700%22 fill=%22white%22 text-anchor=%22middle%22%3EP%3C/text%3E%3C/svg%3E';"><span class="print-footer-text">\u00A9 Polymath Learning Centre LLP. No parts of the intellectual property of Polymath Learning Centre can be reproduced in any form without permission from Polymath Learning Centre LLP.</span>`;
  return footer;
}

// ── Page numbers ────────────────────────────────────────────────────────────
// Stamped onto the assembled document, after pagination has settled and before
// it is handed to the printer, because by then every sheet is a real element we
// can count. (CSS @page counters would be the natural tool; Chrome has never
// implemented them, and every export from this app goes through Chrome's print
// dialog.)
//
// The sequence the teacher asked for: the cover carries no number, the blank
// sheet behind it carries none, any other front matter carries none, and the
// first sheet of real content is 1.
//
// A "tall" page is one element that FLOWS across several sheets. Its number
// lands on the last of them, and the counter is advanced by however many sheets
// it really consumed — so a tall question in the middle never leaves the rest of
// the document numbered wrongly.
function _printApplyPageNumbers(output) {
  if (!output) return;
  // The blank verso only makes sense behind an actual cover.
  const cover = output.querySelector('.print-cover-page');
  if (cover) {
    const coverPage = cover.closest('.print-front-page') || cover;
    if (coverPage.parentNode === output && !coverPage.nextElementSibling?.classList.contains('print-blank-sheet')) {
      const blank = document.createElement('div');
      blank.className = 'print-blank-sheet';
      blank.setAttribute('aria-hidden', 'true');
      output.insertBefore(blank, coverPage.nextSibling);
    }
  }
  // One sheet's height in the units this off-screen copy is laid out in.
  const probe = document.createElement('div');
  probe.style.cssText = 'position:absolute;visibility:hidden;height:258mm;width:1px;';
  output.appendChild(probe);
  const sheetH = probe.getBoundingClientRect().height || 975;
  probe.remove();

  let n = 1;
  Array.from(output.children).forEach(page => {
    if (!page.classList) return;
    if (page.classList.contains('print-front-page') || page.classList.contains('print-blank-sheet')) return;
    // Never stamp twice — but still ADVANCE the counter past a page that is
    // already numbered. Returning early left `n` frozen, so every page after an
    // already-stamped one repeated its number.
    const already = page.querySelector(':scope > .print-page-number');
    if (!already) {
      const label = document.createElement('div');
      label.className = 'print-page-number';
      label.textContent = '– ' + n + ' –';
      page.appendChild(label);
    }
    let sheets = 1;
    if (page.classList.contains('print-page-tall')) sheets = _printPadTallPage(page, sheetH);
    n += sheets;
  });
}

// A normal page is a fixed-height flex column, so `margin-top:auto` drops its
// footer and page number onto the foot of the sheet no matter how much question
// sits above them. A TALL page cannot be that — it has to be a plain block so
// its content can fragment across sheets — so it grew to its content and the
// footer and number came to rest wherever the question happened to end: halfway
// up the sheet for a short one, at the foot for a long one. The number moved
// with the question, which is exactly what it must not do.
//
// So pad the page out to a whole number of sheets, with the spacer ABOVE the
// footer: the block now ends on a sheet boundary and the footer and number ride
// down to the bottom edge with it. Returns the sheets the page consumes, which
// is what the caller advances the counter by.
function _printPadTallPage(page, sheetH) {
  const old = page.querySelector(':scope > .print-page-pad');
  if (old) old.remove();
  // The planner measured this page with the print stylesheet live, which the
  // main document does not have — so its number is the one that describes the
  // printed sheet. Fall back to measuring here only when there is no plan (the
  // flow fallback), where an approximate bottom still beats no bottom at all.
  const planned = parseFloat(page.dataset.planH || '');
  const usePlan = isFinite(planned) && planned > 0;
  const z = usePlan ? 1 : (parseFloat(page.style.zoom) || 1);
  const sheet = usePlan ? PRINT_PAGE_PX : sheetH / z;
  const h = usePlan ? planned : page.getBoundingClientRect().height / z;
  // Tolerate sub-pixel overshoot — but in PIXELS. The tolerance used to be 2%
  // of a sheet, which is 19.5px: a page measuring 985px was reported as one
  // sheet and really printed on two, and every page number after it was one too
  // low. 3px is the rounding this is meant to absorb; 19.5px is a whole line.
  const sheets = Math.max(1, Math.ceil((h - 3) / sheet));
  // Only pad a page that fits WITHIN one sheet. That is the case this is for:
  // a question flagged tall but short enough that its footer used to come to
  // rest wherever the question ended, halfway up the paper. A page that really
  // does flow across sheets fragments at boundaries no measurement can predict
  // (a writing box that won't split jumps whole to the next sheet), so padding
  // it by a computed amount is as likely to push the footer onto an extra sheet
  // as to seat it — leave those alone.
  if (sheets > 1 || h > sheet * 0.9) return sheets;
  // Stop 3px short of the boundary: landing exactly on it risks the rounding
  // that makes a break-inside:avoid footer jump to the next sheet on its own.
  const gap = sheets * sheet - h - 3;
  if (gap > 1) {
    const pad = document.createElement('div');
    pad.className = 'print-page-pad';
    pad.setAttribute('aria-hidden', 'true');
    pad.style.height = gap + 'px';
    const anchor = page.querySelector(':scope > .print-page-footer')
      || page.querySelector(':scope > .print-page-number');
    page.insertBefore(pad, anchor);
  }
  return sheets;
}

// Remember what the planner said this page will measure once printed, so the
// bottom-of-sheet padding is computed from print reality rather than from the
// unstyled screen layout the numbering pass runs in. `h` excludes the page
// number, which is stamped on afterwards — add it here.
function _printStampPlanHeight(page, h, numH) {
  if (!isFinite(h) || h <= 0) return;
  page.dataset.planH = String(h + (numH || 0));
}

// Greedily group chunk indices into A4 pages (filling each page as full as it
// fits so questions aren't left alone with big gaps). A new page starts before
// chunk i when forcedFlags[i] is set (manual break) OR it would overflow maxH —
// UNLESS mergeFlags[i] is set, which keeps i on the previous page (the teacher's
// "move to previous page" override), OR the page holds a single compact MCQ and
// chunk i is one too (pairFlags — each fits within half the printable page), in
// which case the two always share the page and the zoom step absorbs the few
// per cent they may nudge over the budget. tallFlags marks chunks taller than
// a whole page: instead of breaking to a fresh sheet (which used to leave the
// previous page mostly blank and still overflow), a tall chunk joins the
// current page to fill its remaining space, flows across sheets from there
// (its page allows inner breaks — see .print-chunk-tall), and closes its page
// so nothing is packed after it. Shared by the printer and the live preview
// so both paginate identically.
function packChunkIndices(heights, forcedFlags, mergeFlags, maxH, separatorH, pairFlags, aloneFlags) {
  const pageGroups = [];
  if (!heights.length) return pageGroups;
  let currentGroup = [];
  let currentHeight = 0;
  const flush = () => { if (currentGroup.length) { pageGroups.push(currentGroup); currentGroup = []; currentHeight = 0; } };
  for (let i = 0; i < heights.length; i++) {
    const forced = !!(forcedFlags && forcedFlags[i]);
    const merge = !!(mergeFlags && mergeFlags[i]);
    const alone = !!(aloneFlags && aloneFlags[i]);
    // A question that needs its own page (shrunk-to-fit, or too big and flows
    // across sheets): close whatever page is open and give it a page by itself,
    // so it is never cut and never leaves a blank sheet.
    if (alone) { flush(); pageGroups.push([i]); continue; }
    const addedHeight = (currentGroup.length > 0 ? separatorH : 0) + heights[i];
    // Two "about half a page or less" questions always share a sheet even if
    // together they nudge just over the budget (the fit-zoom absorbs it).
    const pairUp = !!(pairFlags && pairFlags[i] && currentGroup.length === 1 && pairFlags[currentGroup[0]]);
    const breakHere = currentGroup.length > 0 && (forced || (!merge && !pairUp && currentHeight + addedHeight > maxH));
    if (breakHere) {
      pageGroups.push(currentGroup);
      currentGroup = [i];
      currentHeight = heights[i];
    } else {
      currentGroup.push(i);
      currentHeight += addedHeight;
    }
  }
  flush();
  return pageGroups;
}

// Smallest zoom we shrink a page to before deciding it's too big to fit one
// sheet (then it becomes a one-question page that flows across sheets), and the
// safety gap kept below the sheet edge so a page can never overflow and either
// cut its content or bump itself to a fresh sheet (leaving a blank one).
const PRINT_ZOOM_FLOOR = 0.55;
const PRINT_FIT_SAFETY = 16;
// An over-full page is fixed by moving its last question to the next sheet,
// EXCEPT when a shrink this gentle would fix it instead — an imperceptible few
// per cent is better than leaving a half-empty sheet behind.
const PRINT_GENTLE_ZOOM = 0.9;
// Breathing room kept free below the last block on a page.
const PRINT_PAGE_RESERVE = 10;

// Classify each question chunk for packing:
//  - pair  : ~half a page or less → may share a sheet with another such question
//  - solo  : taller than a page's budget but shrinks onto ONE sheet at ≥ floor
//  - tall  : too big even shrunk → its own sheet(s), flows (never squashed)
// solo + tall both take a page to themselves (aloneFlags).
// `usable` is passed in rather than recomputed: it has to be the SAME ceiling
// _printPlanIn checks assembled pages against (which reserves the page number),
// or a chunk is classified as shrinkable here and then found unfittable there.
function _classifyPrintChunks(heights, footerH, budget, usable) {
  const half = Math.round(PRINT_PAGE_PX / 2);
  const pairFlags = [], soloFlags = [], tallFlags = [], aloneFlags = [];
  heights.forEach((h, i) => {
    // budget already reserves the footer, so a lone chunk fits a normal page
    // when its own height (no footer) is within budget. Its full page height
    // (chunk + footer) is what must be shrunk under the sheet if it doesn't.
    const withFooter = h + footerH;
    pairFlags[i] = h <= half;
    if (h <= budget) { soloFlags[i] = false; tallFlags[i] = false; aloneFlags[i] = false; return; }
    const canShrink = (usable / withFooter) >= PRINT_ZOOM_FLOOR;
    soloFlags[i] = canShrink;
    tallFlags[i] = !canShrink;
    aloneFlags[i] = true;
  });
  return { pairFlags, soloFlags, tallFlags, aloneFlags, half };
}

// ---- Accurate A4 print measurement ----
// The printable content height inside the @page margins (297 − 18 − 20 mm),
// in CSS pixels — the unit every chunk height below is measured in. NOT
// rounded: rounding up invents ~0.1px of space that isn't on the sheet, and
// every fraction we invent is a fraction closer to spilling a blank page.
const A4_CONTENT_PX = (297 - 18 - 20) * 96 / 25.4;             // ≈ 978.9
// Height of one .print-question-page box — must match --print-page-h in the
// print CSS. It sits 1mm inside the printable area so sub-pixel rounding in
// the PDF backend can never push the box onto a second sheet.
const PRINT_PAGE_PX = 258 * 96 / 25.4;                         // ≈ 975.1

// Height of everything that sits at the foot of every sheet — the copyright
// row AND the page number — measured inside a print-CSS context (the image box
// is fixed by CSS at 22pt, so this is stable even before it loads).
//
// The number is stamped on AFTER planning, so its line has to be reserved HERE
// or each page would end up that much taller than the budget said it could be.
// On a page packed right to the limit that is exactly how Chrome is made to
// fragment a sheet and spill a near-blank one — the failure this whole
// measure-first design exists to prevent.
function _printFooterHeightIn(doc, container) {
  const holder = doc.createElement('div');
  holder.innerHTML = _createPrintPageFooter().outerHTML +
    '<div class="print-page-number">– 1 –</div>';
  container.appendChild(holder);
  const h = holder.getBoundingClientRect().height;
  holder.remove();
  return h;
}

// Height the "– 1 –" label really occupies, measured in the same print-CSS
// context. The page heights the planner reports are measured before the number
// is stamped on, so padding a page down to a sheet boundary has to add this
// back. The 1px spacers stop the label's top margin collapsing out.
function _printNumberHeightIn(doc, container) {
  const holder = doc.createElement('div');
  holder.innerHTML = '<div style="height:1px;"></div><div class="print-page-number">– 1 –</div>';
  container.appendChild(holder);
  const h = Math.max(0, holder.getBoundingClientRect().height - 1);
  holder.remove();
  return h;
}

// Height one .print-question-separator really occupies (border + margins),
// measured in the same print-CSS context — replaces a hard-coded guess that
// let page estimates drift near the sheet boundary. The 1px spacer divs stop
// the separator's margins collapsing out of the holder's height.
function _printSeparatorHeightIn(doc, container) {
  const holder = doc.createElement('div');
  holder.innerHTML = '<div style="height:1px;"></div><div class="print-question-separator"></div><div style="height:1px;"></div>';
  container.appendChild(holder);
  const h = Math.max(0, holder.getBoundingClientRect().height - 2);
  holder.remove();
  return h;
}

// Plan the whole document inside a print-CSS context: pack the chunks into
// pages, then ASSEMBLE each page exactly as the printer will see it (chunks +
// separators + footer, inside a real .print-question-page) and measure the
// finished box. Anything still over the sheet is fixed here — by moving its
// last question forward, or by a gentle shrink — so nothing reaches the
// printer that has to be fragmented. Measuring loose chunks and adding up the
// numbers is what used to drift: margins that collapse away in a bare
// container are live on the real page, and those few pixels per chunk are
// what spilled the footer onto a blank sheet.
//
// `root` must itself carry `print-question-page pm-fit`, so descendant print
// rules (image caps, flex layout, margin containment) apply while measuring.
// Returns the plan, or throws — callers treat a throw as "fall back".
// Turn a fit-to-page zoom from an ARITHMETIC GUESS into a measured fact.
//
// zoomFor() assumes every length on the page shrinks in proportion. Most do,
// but not all: a picture already sitting on its max-height cap, a writing box
// that refuses to split, a heading that must stay with what follows — any of
// them can leave the scaled page taller than the ratio predicted. The page box
// is a FIXED height with visible overflow, so when that happened the extra
// content did not clip or reflow: it painted straight over the next sheet, and
// the top of the following question was buried under the bottom of this one.
//
// So try the ratio, measure the page with that zoom really applied, and step
// down until it genuinely fits. Returns { zoom: 0 } when even the floor cannot
// do it — the caller then lets the page flow across sheets, which is ugly but
// never overlaps.
function _printVerifiedZoom(startZoom, measureAt, usable) {
  let z = Math.min(1, startZoom);
  // The step count is DERIVED from the floor, not a hard-coded 14. Fourteen
  // steps of 0.03 from a start of 1.0 stop at 0.58 — above PRINT_ZOOM_FLOOR
  // (0.55) — so a page that would have fitted at 0.56 ran out of attempts and
  // was declared unfittable, sending it down the tall/flow path for nothing.
  const steps = Math.ceil((1 - PRINT_ZOOM_FLOOR) / 0.03) + 2;
  for (let i = 0; i < steps && z >= PRINT_ZOOM_FLOOR; i++) {
    const h = measureAt(z);
    if (h <= usable) return { zoom: z, h };
    z = +(z - 0.03).toFixed(3);
  }
  return { zoom: 0, h: 0 };
}

function _printPlanIn(doc, root, opts) {
  const chunks = Array.from(root.querySelectorAll('.print-question-chunk'));
  const answerKeys = Array.from(root.querySelectorAll('.print-answer-key-page'));
  const fronts = Array.from(root.querySelectorAll('.print-front-page'));

  const stage = doc.createElement('div');
  stage.style.cssText = 'position:absolute;left:0;top:0;width:178mm;visibility:hidden;';
  (root.parentNode || doc.body).appendChild(stage);

  const footerH = _printFooterHeightIn(doc, root);      // footer + page number
  const numH = _printNumberHeightIn(doc, root);
  const footerOnlyH = Math.max(0, footerH - numH);
  const sepH = _printSeparatorHeightIn(doc, root);
  // The ceiling every measured page is checked against. measurePage() assembles
  // content + footer and NOT the page number, because the number is stamped on
  // after planning — so the number's line has to come out of the ceiling here
  // or it is pure overflow. It used to be `PRINT_PAGE_PX - PRINT_FIT_SAFETY`,
  // and PRINT_FIT_SAFETY (16px) is SMALLER than the number's own line
  // (~22.7px): every page packed near the limit printed ~7px past the bottom of
  // a box that is a fixed height with visible overflow, i.e. onto the next
  // sheet. Reserve the number explicitly and let PRINT_FIT_SAFETY be what its
  // name says — the cushion.
  const usable = PRINT_PAGE_PX - numH - PRINT_FIT_SAFETY;
  // Fit-to-page scales the QUESTIONS only — the footer and page number are page
  // chrome and print at full size, on the same baseline as every other sheet.
  // So the ratio is measured against the room left once the chrome is taken
  // out, not against the whole sheet: scaling by usable/h would leave
  // content*z + footer taller than the page and push the footer off the sheet.
  // (`usable` already excludes the number, so only the footer row comes off
  // here — the resulting figure is the same one this always used.)
  const contentSpace = usable - footerOnlyH;
  // What packChunkIndices may fill a page to, derived from the SAME ceiling the
  // assembled page is verified against rather than from PRINT_PAGE_PX directly.
  // It used to be `PRINT_PAGE_PX - footerH - PRINT_PAGE_RESERVE`, which is
  // PRINT_FIT_SAFETY px more generous than the verified ceiling — so an
  // ordinary full page was packed just over the bar and then had to be rescued
  // by the pop-loop or a gratuitous 0.99 zoom on every print.
  const budget = contentSpace - PRINT_PAGE_RESERVE;
  const zoomFor = (h) => contentSpace / Math.max(1, h - footerOnlyH);
  const heights = chunks.map(c => c.getBoundingClientRect().height);

  const forced = (opts && opts.forcedBreakIds) || null;
  const merge = (opts && opts.mergeUpIds) || null;
  const forcedFlags = chunks.map(c => !!(forced && forced.has(c.dataset.qid)));
  const mergeFlags = chunks.map(c => !!(merge && merge.has(c.dataset.qid)));
  const cls = _classifyPrintChunks(heights, footerH, budget, usable);
  chunks.forEach((c, i) => c.classList.toggle('print-chunk-tall', cls.tallFlags[i]));
  const groups = packChunkIndices(heights, forcedFlags, mergeFlags, budget, sepH, cls.pairFlags, cls.aloneFlags);

  const footerNode = () => {
    const holder = doc.createElement('div');
    holder.innerHTML = _createPrintPageFooter().outerHTML;
    return holder.firstElementChild;
  };
  // Build the page for real, read its height, then hand the chunks back so the
  // next candidate layout can be assembled from the same nodes.
  const measurePage = (group, tall, zoom) => {
    const page = doc.createElement('div');
    page.className = 'print-question-page pm-fit' + (tall ? ' print-page-tall' : '');
    // Same shape the printer builds, so the height measured here is the height
    // that page will really have — including the fit-to-page zoom when one is
    // being tried, since that is applied to this same wrapper at print time.
    const content = doc.createElement('div');
    content.className = 'print-page-content';
    if (zoom && zoom < 0.999) content.style.zoom = zoom;
    page.appendChild(content);
    group.forEach((idx, pos) => {
      if (pos > 0) {
        const sep = doc.createElement('div');
        sep.className = 'print-question-separator';
        content.appendChild(sep);
      }
      content.appendChild(chunks[idx]);
    });
    page.appendChild(footerNode());
    stage.appendChild(page);
    const h = page.getBoundingClientRect().height;
    group.forEach(idx => root.appendChild(chunks[idx]));
    page.remove();
    return h;
  };

  const pageHs = [], pageTall = [], pageZoom = [];
  for (let gi = 0; gi < groups.length; gi++) {
    // PER PAGE, not per document. A single shared budget of 500 was spent by a
    // long worksheet somewhere in the middle, after which over-full pages
    // stopped being split and quietly fell to the zoom/tall path instead — the
    // layout changed character halfway through the paper for no visible reason.
    // A page can never need more pops than it has questions on it.
    let guard = 0;
    let tall = groups[gi].some(idx => cls.tallFlags[idx]);
    let h = measurePage(groups[gi], tall);
    // Over the sheet, more than one question on it, and a shrink wouldn't be
    // invisible → push the last question to the next sheet and re-measure.
    while (!tall && h > usable && groups[gi].length > 1 &&
           zoomFor(h) < PRINT_GENTLE_ZOOM && guard++ < groups[gi].length + 2) {
      const last = groups[gi][groups[gi].length - 1];
      if (mergeFlags[last]) break;              // teacher pinned it to this page
      groups[gi].pop();
      const next = groups[gi + 1];
      if (next && !forcedFlags[next[0]] && !cls.aloneFlags[next[0]] && !cls.aloneFlags[last]) next.unshift(last);
      else groups.splice(gi + 1, 0, [last]);
      h = measurePage(groups[gi], tall);
    }
    if (!tall && h > usable) {
      const fit = _printVerifiedZoom(zoomFor(h), z => measurePage(groups[gi], false, z), usable);
      if (fit.zoom) { pageZoom[gi] = fit.zoom; h = fit.h; }
      else {
        // Too big to shrink readably — let it flow across sheets. Marking the
        // PAGE tall is not enough: .print-page-tall only opens the page box up,
        // while every .print-question-chunk still carries `break-inside: avoid`.
        // A chunk that cannot break on a page that is over the sheet does not
        // flow, it overflows — straight over the next sheet. The chunks have to
        // be released too, which is what .print-chunk-tall does, and the flag
        // has to be recorded because that is what doScaleAndPrint reads when it
        // rebuilds the page for the printer.
        tall = true;
        groups[gi].forEach(idx => {
          cls.tallFlags[idx] = true;
          chunks[idx].classList.add('print-chunk-tall');
        });
        h = measurePage(groups[gi], true);
      }
    }
    pageTall[gi] = tall;
    pageHs[gi] = h;
  }

  // Answer-key sheets are pre-built pages; measure them the same way.
  const akPlans = answerKeys.map(ak => {
    const content = _printWrapPageContent(ak, doc);
    const measureAk = (z) => {
      const footer = footerNode();
      ak.classList.add('pm-fit');
      if (z && z < 0.999) content.style.zoom = z; else content.style.zoom = '';
      ak.appendChild(footer);
      stage.appendChild(ak);
      const got = ak.getBoundingClientRect().height;
      footer.remove();
      ak.classList.remove('pm-fit');
      content.style.zoom = '';
      root.appendChild(ak);
      return got;
    };
    const h = measureAk(0);
    if (h <= usable) return { zoom: 0, tall: false, h };
    const fit = _printVerifiedZoom(zoomFor(h), measureAk, usable);
    return fit.zoom ? { zoom: fit.zoom, tall: false, h: fit.h } : { zoom: 0, tall: true, h };
  });

  const frontSpans = fronts.map(f => Math.max(1, Math.ceil((f.getBoundingClientRect().height || 1) / PRINT_PAGE_PX)));
  stage.remove();
  return { groups, pageHs, pageTall, pageZoom, akPlans, frontSpans, tallFlags: cls.tallFlags, heights, footerH, sepH, numH };
}

// The webfont <link>s, rewritten so they actually apply inside a measuring
// iframe. Both font sheets in index.html are declared `media="print"` — one
// flips itself to `all` on load, the other (Crimson Pro, the worksheet cover
// face) never does. A measuring iframe is a SCREEN medium, so copying those
// tags verbatim hands the planner a document that renders in fallback metrics
// while the printer renders in DM Sans. DM Sans is wider, so a stem measured at
// three lines prints at four; ten text blocks a page is over a hundred pixels
// of growth the plan never budgeted, on a page box that is a fixed height with
// visible overflow. Forcing `media="all"` on the COPIES costs the host page
// nothing — it is a string, not the live element.
function _printFontLinksHtml() {
  return Array.from(document.querySelectorAll('link[rel="stylesheet"],link[rel="preconnect"]')).map(l => {
    const c = l.cloneNode(false);
    if (c.rel === 'stylesheet') { c.media = 'all'; c.removeAttribute('onload'); }
    return c.outerHTML;
  }).join('');
}

// Renders the print HTML in a hidden same-origin iframe with the app's
// @media print rules unwrapped (the same technique as the worksheet live
// preview), so every page is planned at the size it will REALLY print at —
// screen styles don't apply to the .print-* classes, so measuring in the main
// document under-counts writing lines, headers and margins.
// Calls cb(plan) or cb(null) if the iframe cannot be used.
function _printPlanPages(html, opts, cb) {
  let fr = null;
  let called = false;
  const finish = (res) => {
    if (called) return;
    called = true;
    try { if (fr) fr.remove(); } catch (_) {}
    cb(res);
  };
  try {
    fr = document.createElement('iframe');
    fr.setAttribute('aria-hidden', 'true');
    // 794px ≈ the A4 page box (210mm), so any width media query resolves here
    // exactly as it will when printing.
    fr.style.cssText = 'position:fixed;left:-9999px;top:0;width:794px;height:640px;visibility:hidden;';
    document.body.appendChild(fr);
    const doc = fr.contentDocument || (fr.contentWindow && fr.contentWindow.document);
    if (!doc) { finish(null); return; }
    const fontLinks = _printFontLinksHtml();
    doc.open();
    doc.write('<!DOCTYPE html><html><head><meta charset="utf-8">' + fontLinks +
      '<style>' + _wsAppCssForPreview() + ' html,body{margin:0;} #pmMeasure{position:absolute;left:0;top:0;width:178mm;}</style></head>' +
      '<body><div id="printOutput"><div id="pmMeasure" class="print-question-page pm-fit">' + html + '</div></div></body></html>');
    doc.close();
    // Give every picture its box before the planner ever looks at the page, so
    // a slow or missing fetch inside this iframe cannot make a diagram measure
    // as one line of text.
    _printStampImgDims(doc);
    _wsPreviewWhenReady(doc, () => {
      // Second pass: some pictures will have decoded during the wait, which
      // teaches us sizes we did not have. Whatever is STILL in flight after it
      // has no reserved space, and a plan measured around it would pack pages
      // that overflow. Refuse to guess — the flow fallback is denser than a
      // planned layout but it can never paint one question over another.
      if (_printStampImgDims(doc) > 0) {
        console.warn('print plan: pictures still loading, using flow fallback');
        finish(null);
        return;
      }
      try { finish(_printPlanIn(doc, doc.getElementById('pmMeasure'), opts)); }
      catch (e) { console.warn('print plan', e); finish(null); }
    });
  } catch (e) { console.warn('print plan', e); finish(null); }
}

// Shrink a page to fit by scaling its CONTENT, never the page box itself.
//
// This used to zoom the whole .print-question-page and divide the declared
// height back out (258/z), which laid out correctly — the box measured exactly
// one sheet — but paginated wrongly: Chrome fragmented the zoomed box as if it
// were the pre-zoom 356mm, so the sheet filled up early and the footer and page
// number were pushed onto the next sheet, or left floating well above the foot
// of the paper. Scaling an inner wrapper instead leaves the page box a plain,
// unzoomed 258mm — exactly like the pages that always printed correctly — so
// `margin-top:auto` drops the footer onto the same baseline every time. It is
// also what the live preview already does (.wspv-content), so the two agree.
function _printApplyZoom(page, z) {
  page.style.zoom = '';
  page.style.height = '';
  const content = page.querySelector(':scope > .print-page-content');
  if (content) content.style.zoom = '';
  if (!z || z >= 0.999 || !content) return;
  content.style.zoom = z;
}

// Move everything that isn't chrome (footer / page number / padding) into the
// wrapper that carries the fit-to-page scaling.
function _printWrapPageContent(page, doc) {
  if (page.querySelector(':scope > .print-page-content')) return page.querySelector(':scope > .print-page-content');
  const content = (doc || document).createElement('div');
  content.className = 'print-page-content';
  Array.from(page.childNodes).forEach(n => {
    if (n.nodeType === 1 && (n.classList.contains('print-page-footer') || n.classList.contains('print-page-number') || n.classList.contains('print-page-pad'))) return;
    content.appendChild(n);
  });
  page.insertBefore(content, page.firstChild);
  return content;
}

// Print, then undo the inline zoom/height once the dialog is done with them.
// `window.print()` blocks on desktop Chrome but NOT in Firefox or several
// mobile WebViews, where an immediate reset would strip the fit-to-page
// scaling before the sheet is ever rasterised.
function _printAndRestore(output) {
  let done = false;
  const restore = () => {
    if (done) return;
    done = true;
    window.removeEventListener('afterprint', restore);
    Array.from(output.querySelectorAll('.print-question-page')).forEach(p => {
      p.style.zoom = '';
      p.style.height = '';
    });
    Array.from(output.querySelectorAll('.print-page-content')).forEach(c => { c.style.zoom = ''; });
  };
  window.addEventListener('afterprint', restore);
  setTimeout(restore, 60000); // in case afterprint never fires
  window.print();
}

// Last resort: we could not measure at print size, so don't guess. Hand the
// whole worksheet to the browser as one flowing document and let it paginate
// at question boundaries (every chunk carries break-inside: avoid). Denser
// than the planned layout and the footer only lands on the final sheet, but
// it can never emit a blank or a clipped page.
function _printFlowFallback(output) {
  const fronts = Array.from(output.querySelectorAll('.print-front-page'));
  const answerKeys = Array.from(output.querySelectorAll('.print-answer-key-page'));
  fronts.forEach(f => f.remove());
  answerKeys.forEach(ak => ak.remove());
  const body = output.innerHTML;
  output.innerHTML = '';
  if (body.trim()) {
    const page = document.createElement('div');
    page.className = 'print-question-page print-page-tall';
    page.innerHTML = body;
    _printWrapPageContent(page);
    page.appendChild(_createPrintPageFooter());
    output.appendChild(page);
  }
  answerKeys.forEach(ak => {
    ak.classList.add('print-page-tall');
    _printWrapPageContent(ak);
    ak.appendChild(_createPrintPageFooter());
    output.appendChild(ak);
  });
  fronts.slice().reverse().forEach(f => output.insertBefore(f, output.firstChild));
  _printApplyPageNumbers(output);   // while it is still laid out and measurable
  output.style.cssText = 'display:none;';
  _printProgressHide();
  _printAndRestore(output);
}

function doScaleAndPrint(output, opts) {
  // Make output visible off-screen so the DOM is laid out.
  output.style.cssText = 'display:block;position:absolute;left:-9999px;top:0;width:178mm;';

  requestAnimationFrame(() => {
    // The pictures here are already decoded (autoscaleAndPrint waited for them),
    // so this is where their intrinsic sizes are cheapest to learn — and
    // stamping them onto the live nodes puts the width/height into the HTML
    // string handed to the planner, which is what stops it measuring a diagram
    // as a line of text inside its own iframe.
    _printLearnImgDims(output);
    _printStampImgDims(output);
    const chunks = Array.from(output.querySelectorAll('.print-question-chunk'));
    const answerKeys = Array.from(output.querySelectorAll('.print-answer-key-page'));
    // Front matter (cover / cheat sheet) — kept aside and re-inserted FIRST,
    // never packed, zoomed or given the standard footer.
    const fronts = Array.from(output.querySelectorAll('.print-front-page'));

    if (chunks.length === 0) { _printFlowFallback(output); return; }

    // Plan and verify every page at true print size, then reproduce that exact
    // layout here. Nothing is re-derived: whatever fitted in the planner is
    // what gets built, so there is no second chance to drift.
    _printPlanPages(output.innerHTML, opts, (plan) => {
      if (!plan) { _printFlowFallback(output); return; }

      chunks.forEach(c => c.remove());
      answerKeys.forEach(ak => ak.remove());
      fronts.forEach(f => f.remove());
      output.innerHTML = '';

      plan.groups.forEach((group, gi) => {
        const page = document.createElement('div');
        page.className = 'print-question-page';
        if (plan.pageTall[gi]) page.classList.add('print-page-tall');
        const content = document.createElement('div');
        content.className = 'print-page-content';
        page.appendChild(content);
        group.forEach((chunkIdx, posInGroup) => {
          if (posInGroup > 0) {
            const sep = document.createElement('div');
            sep.className = 'print-question-separator';
            content.appendChild(sep);
          }
          chunks[chunkIdx].classList.toggle('print-chunk-tall', !!plan.tallFlags[chunkIdx]);
          content.appendChild(chunks[chunkIdx]);
        });
        page.appendChild(_createPrintPageFooter());
        _printApplyZoom(page, plan.pageZoom[gi]);
        _printStampPlanHeight(page, plan.pageHs[gi], plan.numH);
        output.appendChild(page);
      });

      answerKeys.forEach((ak, ai) => {
        const p = plan.akPlans[ai] || {};
        if (p.tall) ak.classList.add('print-page-tall');
        _printWrapPageContent(ak);
        ak.appendChild(_createPrintPageFooter());
        _printApplyZoom(ak, p.zoom);
        _printStampPlanHeight(ak, p.h, plan.numH);
        output.appendChild(ak);
      });

      // Front matter goes back in FIRST (cover, then cheat sheet), before Q1.
      fronts.slice().reverse().forEach(f => output.insertBefore(f, output.firstChild));

      _printApplyPageNumbers(output);   // while it is still laid out and measurable
      output.style.cssText = 'display:none;';
      _printProgressHide();
      _printAndRestore(output);
    });
  });
}

// =====================================================================
// WORK SESSIONS
// An author (employee, or the admin) clocks on, and every question they save
// while the clock runs is logged against that session: how long, how many, and
// which ones.
//
// The clock is a pair of TIMESTAMPS, never a counter something has to keep
// incrementing: elapsed = (endedAt || pausedAt || now) − startedAt − pausedMs.
// A minimised tab, a throttled setInterval, a closed lid or a closed browser
// therefore cost nothing — the 1-second tick only REPAINTS a number derived
// from the wall clock. The running session is mirrored into localStorage on
// every change, so reopening the app picks the same session back up mid-count.
//
// Where a session is filed:
//   workSessions/{uid}_{startedAt}   ← shared; this is the one the admin lists
//   users/{uid}/workSessions/{id}    ← fallback, if the shared collection is
//                                      not open in the Firestore rules yet
// The fallback exists because a denied write must never stop the clock or lose
// the log; the session runs out of localStorage either way, and the admin's
// history read checks both places.
// =====================================================================
const WK_LS_PREFIX = 'sq_work_session:';
const WK_MAX_MS = 12 * 60 * 60 * 1000;  // a session left open longer than this is closed at its last heartbeat
const WK_HEARTBEAT_MS = 60 * 1000;      // how often a running session writes back "the tab was open at…"
const WK_ITEMS_MAX = 500;               // questions listed on one session doc (the count keeps going past it)

let _wkSession = null;        // the running session, or null
let _wkTickTimer = null;      // 1s repaint
let _wkSaveTimer = null;      // debounce for the Firestore write
let _wkSuppress = 0;          // >0 while an AUTOMATIC job saves questions — those are not work done
let _wkPrivateOnly = false;   // the shared collection refused us; using the private copy
let _wkHistory = null;        // past sessions, loaded on demand
let _wkHistoryLoading = false;
let _wkWho = '';              // admin filter: '' = everyone
let _wkOpen = {};             // which past sessions are expanded
let _wkBound = false;

function _wkLsKey() { return WK_LS_PREFIX + ((currentUser && currentUser.uid) || 'anon'); }
function _wkStoreLocal() {
  try {
    if (_wkSession && !_wkSession.endedAt) localStorage.setItem(_wkLsKey(), JSON.stringify(_wkSession));
    else localStorage.removeItem(_wkLsKey());
  } catch (e) { /* private mode — the Firestore copy is still being written */ }
}
function _wkLoadLocal() {
  try {
    const j = JSON.parse(localStorage.getItem(_wkLsKey()) || 'null');
    if (!j || !j.id || !j.startedAt) return null;
    if (!Array.isArray(j.items)) j.items = [];
    return j;
  } catch (e) { return null; }
}

function _wkRunning() { return !!(_wkSession && !_wkSession.endedAt); }
function _wkPaused()  { return !!(_wkRunning() && _wkSession.pausedAt); }
function _wkCount(s)  { return (s && (s.uniq || (s.items || []).length)) || 0; }

// The whole timer, in one line. Nothing here is incremented by a tick, so a
// tab that was never open still returns the right elapsed time.
function _wkElapsed(s) {
  if (!s || !s.startedAt) return 0;
  const end = s.endedAt || s.pausedAt || Date.now();
  return Math.max(0, end - s.startedAt - (s.pausedMs || 0));
}

function _wkHms(ms) {
  const t = Math.max(0, Math.floor(ms / 1000));
  const h = Math.floor(t / 3600), m = Math.floor((t % 3600) / 60), s = t % 60;
  return h + ':' + String(m).padStart(2, '0') + ':' + String(s).padStart(2, '0');
}
function _wkHuman(ms) {
  const mins = Math.max(0, Math.round(ms / 60000));
  if (mins < 60) return mins + ' min';
  const h = Math.floor(mins / 60), m = mins % 60;
  return h + 'h' + (m ? ' ' + m + 'm' : '');
}
function _wkHours(ms) { return (Math.max(0, ms) / 3600000).toFixed(2); }
function _wkFmt(ms, opts) {
  if (!ms) return '';
  try { return new Date(ms).toLocaleString('en-SG', opts); } catch (e) { return new Date(ms).toLocaleString(); }
}
function _wkWhen(ms) { return _wkFmt(ms, { day: 'numeric', month: 'short', hour: '2-digit', minute: '2-digit' }); }
function _wkTime(ms) { return _wkFmt(ms, { hour: '2-digit', minute: '2-digit' }); }
function _wkDay(ms)  { return _wkFmt(ms, { weekday: 'short', day: 'numeric', month: 'short', year: 'numeric' }); }
function _wkPersonName(s)  { return s.name || s.email || 'Unknown'; }

// ---- Persistence ---------------------------------------------------------
// Flattened on the way out: Firestore rejects `undefined`, and the reader (the
// admin's history) wants the totals without walking the items array.
function _wkDoc(s) {
  return {
    id: s.id,
    uid: s.uid || '',
    email: s.email || '',
    name: s.name || '',
    role: s.role || '',
    bankOwner: s.bankOwner || null,
    startedAt: s.startedAt,
    endedAt: s.endedAt || null,
    pausedMs: s.pausedMs || 0,
    pausedAt: s.pausedAt || null,
    lastSeen: s.lastSeen || s.startedAt,
    ms: _wkElapsed(s),
    saves: s.saves || 0,
    questions: _wkCount(s),
    items: (s.items || []).slice(0, WK_ITEMS_MAX),
  };
}

async function _wkPersist(s) {
  if (!s || !currentUser) return;
  const payload = _wkDoc(s);
  if (!_wkPrivateOnly) {
    try { await setDoc(doc(db, 'workSessions', s.id), payload); return; }
    catch (err) {
      // Permission denied is a settled answer, not a blip: stop trying the
      // shared collection for the rest of the session and file it privately.
      const denied = err && (err.code === 'permission-denied' || err.code === 'unauthenticated');
      if (!denied) { console.warn('work session save:', err); return; }
      _wkPrivateOnly = true;
      console.warn('workSessions is not open in the rules — filing this session under the author\'s own account instead');
    }
  }
  try { await setDoc(doc(db, 'users', currentUser.uid, 'workSessions', s.id), payload); }
  catch (err) { console.warn('work session save (own account):', err); }
}

function _wkQueueSave(now) {
  const s = _wkSession;
  if (!s) return;
  clearTimeout(_wkSaveTimer);
  if (now) { _wkPersist(s); return; }
  _wkSaveTimer = setTimeout(() => _wkPersist(s), 1500);
}

// ---- Start / pause / end -------------------------------------------------
function wkStart() {
  if (!_canAuthor()) { showToast('Work sessions are for question authors', 'error'); return; }
  if (_wkRunning()) { showToast('A session is already running', 'info'); return; }
  const now = Date.now();
  _wkSession = {
    id: currentUser.uid + '_' + now,
    uid: currentUser.uid,
    email: currentUser.email || '',
    name: currentUser.name || '',
    role: currentUser.role || '',
    bankOwner: _bankOwnerUid() || null,
    startedAt: now, endedAt: null, pausedMs: 0, pausedAt: null, lastSeen: now,
    saves: 0, uniq: 0, items: [],
  };
  _wkStoreLocal();
  _wkQueueSave(true);
  _wkStartTick();
  wkRenderAll();
  showToast('⏱️ Session started — every question you save from now is logged', 'success');
}

function wkTogglePause() {
  if (!_wkRunning()) return;
  const now = Date.now();
  if (_wkSession.pausedAt) {
    _wkSession.pausedMs = (_wkSession.pausedMs || 0) + Math.max(0, now - _wkSession.pausedAt);
    _wkSession.pausedAt = null;
    showToast('▶ Session resumed', 'info');
  } else {
    _wkSession.pausedAt = now;
    showToast('⏸ Break — the clock is stopped. Questions you save are still logged.', 'info');
  }
  _wkSession.lastSeen = now;
  _wkStoreLocal();
  _wkQueueSave(true);
  wkRenderAll();
}

function wkEnd() {
  if (!_wkRunning()) return;
  const n = _wkCount(_wkSession);
  showConfirm('End work session',
    'Stop the clock and file this session? ' + _wkHuman(_wkElapsed(_wkSession)) + ' · '
      + n + ' question' + (n === 1 ? '' : 's') + '. You can start a new one whenever you like.',
    () => _wkFinish());
}

// atMs — close the session at a moment in the past (a session left running
// overnight is filed at its last heartbeat, not at whenever it was reopened).
function _wkFinish(atMs, quiet) {
  const s = _wkSession;
  if (!s || s.endedAt) return;
  const end = Math.max(s.startedAt, atMs || Date.now());
  if (s.pausedAt) { s.pausedMs = (s.pausedMs || 0) + Math.max(0, end - s.pausedAt); s.pausedAt = null; }
  s.endedAt = end;
  s.lastSeen = end;
  clearTimeout(_wkSaveTimer);
  _wkPersist(s);
  _wkStopTick();
  if (_wkHistory) _wkHistory = [_wkDoc(s)].concat(_wkHistory.filter(x => x.id !== s.id));
  _wkSession = null;
  _wkStoreLocal();          // reads _wkSession — now null, so the key is cleared
  wkRenderAll();
  if (!quiet) showToast('Session filed — ' + _wkHuman(_wkElapsed(s)) + ' · ' + _wkCount(s) + ' questions', 'success');
  return s;
}

// ---- The tick ------------------------------------------------------------
function _wkStartTick() {
  _wkStopTick();
  _wkPaintClock();
  _wkTickTimer = setInterval(_wkTick, 1000);
}
function _wkStopTick() { if (_wkTickTimer) { clearInterval(_wkTickTimer); _wkTickTimer = null; } }

function _wkTick() {
  if (!_wkRunning()) { _wkStopTick(); return; }
  _wkPaintClock();
  const now = Date.now();
  // The heartbeat is the last moment the tab was demonstrably open. It is what
  // an abandoned session gets closed at, so it must keep ticking even when
  // nothing is being saved.
  if (!_wkSession.pausedAt && now - (_wkSession.lastSeen || 0) >= WK_HEARTBEAT_MS) {
    _wkSession.lastSeen = now;
    _wkStoreLocal();
    _wkQueueSave(true);
  }
}

function _wkPaintClock() {
  const txt = _wkHms(_wkElapsed(_wkSession));
  const a = document.getElementById('wkBarClock'); if (a) a.textContent = txt;
  const b = document.getElementById('wkClock');    if (b) b.textContent = txt;
}

function _wkBind() {
  if (_wkBound) return;
  _wkBound = true;
  document.addEventListener('visibilitychange', () => {
    if (!_wkRunning()) return;
    if (document.hidden) { _wkSession.lastSeen = Date.now(); _wkStoreLocal(); _wkQueueSave(true); }
    else { _wkPaintClock(); wkRenderAll(); }
  });
  // localStorage is synchronous, so this copy always lands — a Firestore write
  // started here would be cancelled with the page.
  window.addEventListener('pagehide', () => {
    if (!_wkRunning()) return;
    _wkSession.lastSeen = Date.now();
    _wkStoreLocal();
  });
}

// Called once per sign-in, for anyone who can author.
function wkInit() {
  if (!_canAuthor()) return;
  _wkBind();
  const s = _wkLoadLocal();
  if (s && !s.endedAt) {
    const idle = Date.now() - (s.lastSeen || s.startedAt);
    _wkSession = s;
    if (_wkElapsed(s) > WK_MAX_MS || idle > WK_MAX_MS) {
      // Left running. Hours when nobody was at the keyboard are not hours
      // worked, and a three-day clock helps no one.
      const closed = _wkFinish(s.lastSeen || s.startedAt, true);
      showToast('Your last work session was left running — it has been filed at '
        + _wkWhen(closed.endedAt) + ' (' + _wkHuman(_wkElapsed(closed)) + ')', 'info');
    } else {
      _wkStartTick();
    }
  }
  wkRenderBar();
}

// ---- Logging a question --------------------------------------------------
// Called from saveQuestion / saveVettingQuestion — the two functions EVERY
// committed question goes through, so no authoring path can be forgotten.
function _wkLogQuestion(q, where) {
  if (!_wkRunning() || _wkSuppress > 0) return;
  if (!q || q.id == null) return;
  const s = _wkSession, now = Date.now();
  s.saves = (s.saves || 0) + 1;
  s.lastSeen = now;
  const id = String(q.id);
  const it = (s.items || []).find(x => x.id === id);
  if (it) {
    it.last = now;
    it.n = (it.n || 1) + 1;
    it.act = where;
    if (q.title) it.title = String(q.title).slice(0, 140);
  } else {
    // `uniq` keeps counting past WK_ITEMS_MAX so the headline number never
    // disagrees with the work actually done, even once the list is capped.
    s.uniq = (s.uniq || 0) + 1;
    if ((s.items || []).length < WK_ITEMS_MAX) {
      s.items.push({
        id,
        title: String(q.title || 'Untitled question').slice(0, 140),
        topic: q.topic || '', category: q.category || '',
        at: now, last: now, n: 1, act: where,
      });
    }
  }
  _wkStoreLocal();
  _wkQueueSave();
  wkRenderAll();
}

// ---- History -------------------------------------------------------------
async function wkLoadHistory(force) {
  if (_wkHistoryLoading) return;
  if (_wkHistory && !force) return;
  _wkHistoryLoading = true;
  wkRenderPage();
  const byId = new Map();
  const take = snap => snap.forEach(d => { const v = d.data(); if (v && v.id && v.startedAt) byId.set(v.id, v); });
  try {
    const col = collection(db, 'workSessions');
    // No orderBy alongside the uid filter: that pairing needs a composite
    // index, and these lists are small enough to sort here.
    take(_isAdmin() ? await getDocs(col) : await getDocs(query(col, where('uid', '==', currentUser.uid))));
  } catch (err) { console.warn('work sessions (shared):', err); }
  try { take(await getDocs(collection(db, 'users', currentUser.uid, 'workSessions'))); }
  catch (err) { /* nothing filed privately — fine */ }
  if (_isAdmin()) {
    // Anything an author had to file privately (see _wkPersist) still has to
    // reach the teacher, so read each author's own subtree as well.
    for (const uid of await _wkAuthorUids()) {
      if (uid === currentUser.uid) continue;
      try { take(await getDocs(collection(db, 'users', uid, 'workSessions'))); } catch (err) { /* not readable */ }
    }
  }
  _wkHistory = Array.from(byId.values()).sort((a, b) => (b.startedAt || 0) - (a.startedAt || 0));
  _wkHistoryLoading = false;
  wkRenderPage();
}

async function _wkAuthorUids() {
  const out = [];
  try {
    const snap = await getDocs(collection(db, 'userProfiles'));
    snap.forEach(d => {
      const p = d.data() || {};
      if (p.uid && p.email && (EMPLOYEE_EMAILS.includes(p.email) || p.role === 'employee')) out.push(p.uid);
    });
  } catch (err) { console.warn('author lookup:', err); }
  return out;
}

function _wkFiled() {
  const running = _wkSession && _wkSession.id;
  return (_wkHistory || []).filter(s => s.id !== running);
}
function _wkVisible() {
  return _wkFiled().filter(s => !_wkWho || s.uid === _wkWho);
}

function wkSetWho(uid) { _wkWho = uid || ''; wkRenderPage(); }
function wkToggleSession(id) { _wkOpen[id] = !_wkOpen[id]; wkRenderPage(); }

// ---- Rendering: the floating bar ----------------------------------------
function wkRenderBar() {
  const bar = document.getElementById('wkBar');
  if (!bar) return;
  const on = _wkRunning() && _canAuthor();
  document.body.classList.toggle('wk-clocked-in', on);
  if (!on) { bar.style.display = 'none'; return; }
  bar.style.display = '';
  bar.classList.toggle('wk-bar-paused', _wkPaused());
  const n = _wkCount(_wkSession);
  const dot = document.getElementById('wkBarDot');   if (dot) dot.textContent = _wkPaused() ? '⏸' : '⏱️';
  const cnt = document.getElementById('wkBarCount'); if (cnt) cnt.textContent = n + (n === 1 ? ' question' : ' questions');
  const p   = document.getElementById('wkBarPause'); if (p) p.textContent = _wkPaused() ? 'Resume' : 'Pause';
  _wkPaintClock();
}

function wkRenderAll() {
  wkRenderBar();
  if (document.querySelector('#page-worksession.active')) wkRenderPage();
}

// ---- Rendering: the page -------------------------------------------------
function wkRenderPage() {
  const wrap = document.getElementById('wkPageBody');
  if (!wrap) return;
  if (!_canAuthor()) {
    wrap.innerHTML = '<div class="wk-card"><p class="wk-empty">Work sessions are for question authors.</p></div>';
    return;
  }
  wrap.innerHTML = _wkLiveCardHtml() + _wkItemsCardHtml() + _wkHistoryCardHtml();
  _wkPaintClock();
}

function _wkLiveCardHtml() {
  if (!_wkRunning()) {
    return `<div class="wk-card wk-live">
      <div class="wk-live-head"><span class="wk-live-label wk-idle">No session running</span></div>
      <div class="wk-clock wk-clock-idle">0:00:00</div>
      <p class="wk-hint">Press <b>Start session</b> when you sit down to write questions. The clock runs off the wall clock, so it keeps counting while this tab is minimised, in the background, or closed altogether — and every question you save while it runs is listed here.</p>
      <div class="wk-actions"><button class="btn btn-primary" onclick="wkStart()">▶ Start session</button></div>
    </div>`;
  }
  const s = _wkSession, n = _wkCount(s);
  return `<div class="wk-card wk-live${_wkPaused() ? ' wk-live-paused' : ''}">
    <div class="wk-live-head">
      <span class="wk-live-label">${_wkPaused() ? '⏸ On a break' : '<span class="wk-pulse"></span> Session running'}</span>
      <span class="wk-since">started ${escapeHtml(_wkWhen(s.startedAt))}</span>
    </div>
    <div class="wk-clock" id="wkClock">${_wkHms(_wkElapsed(s))}</div>
    <div class="wk-stats">
      <div class="wk-stat"><b>${n}</b><span>question${n === 1 ? '' : 's'}</span></div>
      <div class="wk-stat"><b>${s.saves || 0}</b><span>save${(s.saves || 0) === 1 ? '' : 's'}</span></div>
      ${s.pausedMs ? `<div class="wk-stat"><b>${escapeHtml(_wkHuman(s.pausedMs))}</b><span>on break</span></div>` : ''}
    </div>
    <div class="wk-actions">
      <button class="btn btn-outline" onclick="wkTogglePause()">${_wkPaused() ? '▶ Resume' : '⏸ Take a break'}</button>
      <button class="btn btn-primary wk-stop" onclick="wkEnd()">■ End session</button>
    </div>
    ${_wkPrivateOnly ? '<p class="wk-warn">⚠ Saving to your own account only — the shared <code>workSessions</code> collection is not open in the database rules yet, so your teacher cannot see this session until it is. Nothing is lost: it is filed and will still be there.</p>' : ''}
  </div>`;
}

function _wkItemsCardHtml() {
  if (!_wkRunning()) return '';
  const s = _wkSession;
  const items = (s.items || []).slice().sort((a, b) => (b.last || b.at || 0) - (a.last || a.at || 0));
  if (!items.length) {
    return `<div class="wk-card">
      <h3 class="wk-h3">Questions this session</h3>
      <p class="wk-empty">Nothing yet. Every question you save — to the question bank or to the vetting list — appears here the moment it is written.</p>
    </div>`;
  }
  const extra = _wkCount(s) - items.length;
  return `<div class="wk-card">
    <h3 class="wk-h3">Questions this session <span class="wk-pill">${items.length}</span></h3>
    <div class="wk-list">${items.map(_wkItemRowHtml).join('')}</div>
    ${extra > 0 ? `<p class="wk-hint">…and ${extra} more — only the first ${WK_ITEMS_MAX} are listed by name, but all of them are counted.</p>` : ''}
  </div>`;
}

function _wkItemRowHtml(it) {
  const meta = [it.topic, it.category].filter(Boolean).map(escapeHtml).join(' · ');
  const vet = it.act === 'vetting';
  return `<div class="wk-row">
    <div class="wk-row-main">
      <div class="wk-row-title">${escapeHtml(it.title || 'Untitled question')}</div>
      ${meta ? `<div class="wk-row-meta">${meta}</div>` : ''}
    </div>
    <span class="wk-tag ${vet ? 'wk-tag-vet' : 'wk-tag-bank'}">${vet ? 'Vetting' : 'Bank'}</span>
    ${(it.n || 1) > 1 ? `<span class="wk-tag wk-tag-n" title="Saved ${it.n} times">×${it.n}</span>` : ''}
    <span class="wk-row-time">${escapeHtml(_wkTime(it.at))}</span>
  </div>`;
}

function _wkHistoryCardHtml() {
  if (_wkHistory === null) {
    return `<div class="wk-card">
      <h3 class="wk-h3">Past sessions</h3>
      ${_wkHistoryLoading
        ? '<p class="wk-empty">Loading…</p>'
        : '<div class="wk-actions"><button class="btn btn-outline" onclick="wkLoadHistory(true)">Load past sessions</button></div>'}
    </div>`;
  }
  const rows = _wkVisible();
  const totalMs = rows.reduce((a, s) => a + (s.ms || 0), 0);
  const totalQ  = rows.reduce((a, s) => a + (s.questions || 0), 0);
  return `<div class="wk-card">
    <div class="wk-hist-head">
      <h3 class="wk-h3">Past sessions <span class="wk-pill">${rows.length}</span></h3>
      <div class="wk-hist-tools">
        ${_isAdmin() ? _wkWhoSelectHtml() : ''}
        <button class="btn btn-outline btn-sm" onclick="wkLoadHistory(true)" title="Fetch the latest sessions">↻ Refresh</button>
        ${rows.length ? '<button class="btn btn-outline btn-sm" onclick="wkExportCsv()" title="Download these sessions as a spreadsheet">⬇ CSV</button>' : ''}
      </div>
    </div>
    ${rows.length ? `<div class="wk-totals">
      <div class="wk-stat"><b>${escapeHtml(_wkHuman(totalMs))}</b><span>logged</span></div>
      <div class="wk-stat"><b>${totalQ}</b><span>questions</span></div>
      <div class="wk-stat"><b>${totalMs ? (totalQ / (totalMs / 3600000)).toFixed(1) : '0.0'}</b><span>questions / hour</span></div>
    </div>` : ''}
    ${rows.length
      ? `<div class="wk-list wk-hist-list">${rows.map(_wkHistRowHtml).join('')}</div>`
      : '<p class="wk-empty">No sessions filed yet.</p>'}
  </div>`;
}

function _wkWhoSelectHtml() {
  const seen = new Map();
  _wkFiled().forEach(s => { if (s.uid && !seen.has(s.uid)) seen.set(s.uid, _wkPersonName(s)); });
  const opts = Array.from(seen.entries()).map(([uid, name]) =>
    `<option value="${escapeHtml(uid)}"${_wkWho === uid ? ' selected' : ''}>${escapeHtml(name)}</option>`).join('');
  return `<select class="wk-select" onchange="wkSetWho(this.value)" title="Whose sessions to show">
    <option value=""${_wkWho ? '' : ' selected'}>Everyone</option>${opts}
  </select>`;
}

function _wkHistRowHtml(s) {
  const open = !!_wkOpen[s.id];
  const items = Array.isArray(s.items) ? s.items.slice().sort((a, b) => (a.at || 0) - (b.at || 0)) : [];
  return `<div class="wk-hist${open ? ' wk-hist-open' : ''}">
    <div class="wk-hist-row" onclick="wkToggleSession('${escapeHtml(s.id)}')" title="Show the questions in this session">
      <span class="wk-caret">${open ? '▾' : '▸'}</span>
      <div class="wk-row-main">
        <div class="wk-row-title">${escapeHtml(_wkDay(s.startedAt))}</div>
        <div class="wk-row-meta">${escapeHtml(_wkTime(s.startedAt))} – ${escapeHtml(s.endedAt ? _wkTime(s.endedAt) : 'still running')}${_isAdmin() ? ' · ' + escapeHtml(_wkPersonName(s)) : ''}${s.pausedMs ? ' · ' + escapeHtml(_wkHuman(s.pausedMs)) + ' on break' : ''}</div>
      </div>
      <span class="wk-tag wk-tag-dur">${escapeHtml(_wkHuman(s.ms || 0))}</span>
      <span class="wk-tag wk-tag-n">${s.questions || 0} q</span>
    </div>
    ${open ? `<div class="wk-hist-body">${items.length
      ? items.map(_wkItemRowHtml).join('')
      : '<p class="wk-empty">No questions were saved in this session.</p>'}</div>` : ''}
  </div>`;
}

// One row per question, so a session's work can be checked line by line.
function wkExportCsv() {
  const rows = _wkVisible();
  if (!rows.length) { showToast('Nothing to export', 'info'); return; }
  const esc = v => '"' + String(v == null ? '' : v).replace(/"/g, '""') + '"';
  const out = [['Person', 'Email', 'Day', 'Start', 'End', 'Hours', 'Break (min)', 'Questions', 'Saves', 'Question', 'Topic', 'Category', 'Saved to', 'Saved at', 'Times saved'].join(',')];
  rows.forEach(s => {
    const head = [_wkPersonName(s), s.email || '', _wkDay(s.startedAt), _wkTime(s.startedAt),
      s.endedAt ? _wkTime(s.endedAt) : '', _wkHours(s.ms || 0), Math.round((s.pausedMs || 0) / 60000),
      s.questions || 0, s.saves || 0];
    const items = Array.isArray(s.items) ? s.items : [];
    if (!items.length) { out.push(head.concat(['', '', '', '', '', '']).map(esc).join(',')); return; }
    items.forEach(it => out.push(head.concat([
      it.title || '', it.topic || '', it.category || '',
      it.act === 'vetting' ? 'Vetting' : 'Bank', _wkTime(it.at), it.n || 1,
    ]).map(esc).join(',')));
  });
  const blob = new Blob(['﻿' + out.join('\r\n')], { type: 'text/csv;charset=utf-8;' });
  const url = URL.createObjectURL(blob);
  const a = document.createElement('a');
  a.href = url;
  a.download = 'work-sessions-' + new Date().toISOString().slice(0, 10) + '.csv';
  document.body.appendChild(a);
  a.click();
  a.remove();
  setTimeout(() => URL.revokeObjectURL(url), 1000);
}

// =====================================================================
// STORAGE — subcollection-per-question architecture
//
//   users/{uid}/questions/{questionId}   ← question bank
//   users/{uid}/vetting/{questionId}     ← vetting list
//
// Each question is its own document: no transactions, no size limits,
// no merging complexity.  A single setDoc/deleteDoc call never fails
// due to contention or document growth.
// =====================================================================

// _bankOwnerUid, not currentUser.uid: an employee authors into the teacher's
// bank, so every read, write and delete has to resolve to the same subtree the
// students are served from.
function _qOwner(id) { return _ownerUidByQuestionId[id] || _bankOwnerUid(); }
function _vOwner(id) { return _ownerUidByVettingId[id]  || _bankOwnerUid(); }
function _qRef(id) { return doc(db, 'users', _qOwner(id), 'questions', id); }
function _vRef(id) { return doc(db, 'users', _vOwner(id), 'vetting',   id); }
function _qCol()   { return collection(db, 'users', _bankOwnerUid(), 'questions'); }
function _vCol()   { return collection(db, 'users', _bankOwnerUid(), 'vetting');   }

let _inflightOps = 0;
let _saveHideTimer = null;

function _setSaveStatus(state) {
  const el = document.getElementById('saveStatusIndicator');
  if (!el) return;
  clearTimeout(_saveHideTimer);
  if (state === 'saving') {
    el.textContent = '● Saving…';
    el.style.cssText = 'display:block;color:rgba(255,255,255,0.5);background:rgba(255,255,255,0.05);';
  } else if (state === 'saved') {
    el.textContent = '✓ Saved';
    el.style.cssText = 'display:block;color:#52c41a;background:rgba(82,196,26,0.1);';
    _saveHideTimer = setTimeout(() => { el.style.display = 'none'; el.textContent = ''; }, 2500);
  } else if (state === 'error') {
    el.textContent = '⚠ Save failed';
    el.style.cssText = 'display:block;color:#ff4d4f;background:rgba(255,77,79,0.1);';
    _saveHideTimer = setTimeout(() => { el.style.display = 'none'; el.textContent = ''; }, 5000);
  }
}

// Write one question doc with auto-retry.
// opts.quiet — background bookkeeping (the usage backfill): no toast, no save
// indicator, no retry. A housekeeping write that fails is the app's problem to
// log, never a popup in the admin's face.
async function saveQuestion(q, opts) {
  if (!currentUser) return false;
  // Ai-nstein caches a searchable string per question (tags, title, topic, body).
  // An edit here — a tag added or removed above all — must not leave him matching
  // against the old one for the rest of the session.
  try { if (q && q.id != null && typeof _ainsteinTextCache !== 'undefined') _ainsteinTextCache.delete(String(q.id)); } catch (_) {}
  const quiet = !!(opts && opts.quiet);
  // Decided HERE, not when the write lands: an automatic job that fires saves
  // off without awaiting them would otherwise have dropped its guard by the
  // time they resolve, and every one of them would be logged as work done.
  const wkLog = !quiet && _wkSuppress === 0;
  const tries = quiet ? 1 : 3;
  if (!quiet) { _inflightOps++; _setSaveStatus('saving'); }
  const done = ok => {
    if (quiet) return ok;
    _inflightOps--;
    if (_inflightOps === 0) _setSaveStatus(ok ? 'saved' : 'error');
    return ok;
  };
  // Firestore rejects nested arrays. A LOADED table block carries data as
  // array-of-arrays and colWidths as an array (normalizeLoadedQuestion restores
  // them for the editor), so a save from a held object — the tag passes, the
  // usage backfill — must convert them back on the way out, exactly as
  // collectQuestionData does for the editor. The in-memory object stays as-is.
  let payload = q;
  if (q && Array.isArray(q.blocks) && q.blocks.some(b => b && b.type === 'table' &&
      (Array.isArray(b.data) || Array.isArray(b.colWidths)))) {
    payload = JSON.parse(JSON.stringify(q));
    payload.blocks.forEach(b => {
      if (!b || b.type !== 'table') return;
      if (Array.isArray(b.data)) b.data = tableDataToFirestore(b.data);
      if (Array.isArray(b.colWidths)) {
        const cw = {};
        b.colWidths.forEach((w, i) => { if (w !== null && w !== undefined) cw[String(i)] = w; });
        b.colWidths = cw;
      }
    });
  }
  let attempts = 0;
  while (attempts < tries) {
    try {
      await setDoc(_qRef(q.id), payload);
      // A running work session logs the question. `quiet` writes are background
      // bookkeeping (the usage backfill, auto-tagging, the part converter) —
      // machine housekeeping is not work the author did.
      if (wkLog) _wkLogQuestion(q, 'bank');
      return done(true);
    } catch (err) {
      attempts++;
      // Permission denied is a settled answer, not a blip — retrying it three
      // times with back-off just delays the same failure and misreports it as a
      // connection problem.
      const fatal = err && (err.code === 'permission-denied' || err.code === 'unauthenticated');
      if (fatal || attempts >= tries) {
        if (!quiet) {
          console.error('saveQuestion failed:', err);
          showToast(fatal ? '⚠ You don\'t have permission to change that question'
                          : '⚠ Could not save question — check your connection', 'error');
        }
        _saveQuestionLastError = (err && err.code) || 'unknown';
        return done(false);
      }
      await new Promise(r => setTimeout(r, 800 * attempts)); // back-off
    }
  }
  return done(false);
}
let _saveQuestionLastError = '';

// Write one vetting doc with auto-retry
async function saveVettingQuestion(q) {
  if (!currentUser) return;
  const wkLog = _wkSuppress === 0;   // see saveQuestion — decided before the await
  _inflightOps++;
  _setSaveStatus('saving');
  let attempts = 0;
  while (attempts < 3) {
    try {
      await setDoc(_vRef(q.id), q);
      if (wkLog) _wkLogQuestion(q, 'vetting');
      _inflightOps--;
      if (_inflightOps === 0) _setSaveStatus('saved');
      return;
    } catch (err) {
      attempts++;
      if (attempts >= 3) {
        _inflightOps--;
        if (_inflightOps === 0) _setSaveStatus('error');
        console.error('saveVettingQuestion failed after 3 attempts:', err);
        showToast('⚠ Could not save question — check your connection', 'error');
        return;
      }
      await new Promise(r => setTimeout(r, 800 * attempts));
    }
  }
}

// Delete one question doc (fire-and-forget; failure is non-critical)
function deleteQuestionDoc(id) {
  if (!currentUser) return;
  deleteDoc(_qRef(id)).catch(err => console.warn('deleteQuestionDoc:', err));
}

// Delete one vetting doc (fire-and-forget)
function deleteVettingDoc(id) {
  if (!currentUser) return;
  deleteDoc(_vRef(id)).catch(err => console.warn('deleteVettingDoc:', err));
}

// no-op kept so any stray internal calls don't throw
function saveToStorage() {}

// Load all questions from subcollections; auto-migrates old single-doc format
async function loadFromStorage() {
  if (!currentUser) return;
  try {
    // ── Migration: old format stored arrays inside users/{uid} ──
    const userRef = doc(db, 'users', currentUser.uid);
    const userSnap = await getDoc(userRef);
    if (userSnap.exists()) {
      const old = userSnap.data();
      if (Array.isArray(old.questionBank) || Array.isArray(old.vettingList)) {
        console.log('Migrating from legacy single-doc format…');
        const writes = [];
        (old.questionBank || []).forEach(q => {
          if (q && q.id) {
            // Re-save through collectQuestionData-style conversion so nested arrays are fixed
            const safe = JSON.parse(JSON.stringify(q));
            if (Array.isArray(safe.blocks)) {
              safe.blocks.forEach(b => {
                if (b.type === 'table' && Array.isArray(b.data)) b.data = tableDataToFirestore(b.data);
              });
            }
            writes.push(setDoc(_qRef(q.id), safe));
          }
        });
        (old.vettingList || []).forEach(q => {
          if (q && q.id) {
            const safe = JSON.parse(JSON.stringify(q));
            if (Array.isArray(safe.blocks)) {
              safe.blocks.forEach(b => {
                if (b.type === 'table' && Array.isArray(b.data)) b.data = tableDataToFirestore(b.data);
              });
            }
            writes.push(setDoc(_vRef(q.id), safe));
          }
        });
        await Promise.all(writes);
        // Overwrite user doc — remove the old arrays so we don't re-migrate
        await setDoc(userRef, { _v: 2, migratedAt: new Date().toISOString() });
        console.log('Migration complete.');
      }
    }

    // ── Load from subcollections ──
    const [qSnap, vSnap] = await Promise.all([
      getDocs(_qCol()),
      getDocs(_vCol())
    ]);
    questionBank = [];
    vettingList  = [];
    // Reset owner maps so stale entries from a previous load don't leak through.
    Object.keys(_ownerUidByQuestionId).forEach(k => delete _ownerUidByQuestionId[k]);
    Object.keys(_ownerUidByVettingId ).forEach(k => delete _ownerUidByVettingId[k]);
    qSnap.forEach(d => {
      const q = d.data();
      if (q && q.id) questionBank.push(normalizeLoadedQuestion(q));
    });
    vSnap.forEach(d => {
      const q = d.data();
      if (q && q.id) vettingList.push(normalizeLoadedQuestion(q));
    });

    // Super admin: also load questions and vetting from every other admin
    // account so they can see and act on Abigail's content too.
    if (currentUser.email === SUPER_ADMIN_EMAIL) {
      try {
        const profilesSnap = await getDocs(collection(db, 'userProfiles'));
        const otherAdminUids = [];
        profilesSnap.forEach(d => {
          const p = d.data();
          if (p && p.uid && p.uid !== currentUser.uid && ADMIN_EMAILS.includes(p.email)) {
            otherAdminUids.push(p.uid);
          }
        });
        const seenQ = new Set(questionBank.map(q => q.id));
        const seenV = new Set(vettingList.map(q => q.id));
        for (const uid of otherAdminUids) {
          const [oQ, oV] = await Promise.all([
            getDocs(collection(db, 'users', uid, 'questions')),
            getDocs(collection(db, 'users', uid, 'vetting'))
          ]);
          oQ.forEach(d => {
            const q = d.data();
            if (q && q.id && !seenQ.has(q.id)) {
              _ownerUidByQuestionId[q.id] = uid;
              questionBank.push(normalizeLoadedQuestion(q));
              seenQ.add(q.id);
            }
          });
          oV.forEach(d => {
            const q = d.data();
            if (q && q.id && !seenV.has(q.id)) {
              _ownerUidByVettingId[q.id] = uid;
              vettingList.push(normalizeLoadedQuestion(q));
              seenV.add(q.id);
            }
          });
        }
      } catch (err) {
        console.warn('Could not load other admins’ questions:', err);
      }
    }

  } catch (err) {
    console.error('loadFromStorage failed:', err);
    showToast('⚠ Could not load questions — working with local data', 'error');
  }
  updateCounts();
  populateTopicFilter();
}

function updateCounts() {
  document.getElementById('bankCount').textContent = questionBank.length;
  document.getElementById('vettingCount').textContent = vettingList.length;
}

// ── Topic filter: a tick list, grouped by the level each topic is taught at ──
// One topic at a time was the wrong shape for the job — "show me Heat AND
// Light" is the normal question, and a <select> cannot answer it. Empty means
// no filter at all, which keeps "All Topics" as the resting state.
let bankTopicSel = new Set();

function populateTopicFilter() {
  const list = document.getElementById('bankTopicList');
  if (!list) { populateSourceFilters(); return; }
  // Only topics that actually have questions behind them — a filter that
  // returns nothing is just a way to waste a click.
  const counts = new Map();
  questionBank.forEach(q => qTopicList(q).forEach(t => {
    const s = String(t || '').trim();
    if (s) counts.set(s, (counts.get(s) || 0) + 1);
  }));
  // A ticked topic whose last question was deleted or retagged stops existing.
  Array.from(bankTopicSel).forEach(t => { if (!counts.has(t)) bankTopicSel.delete(t); });

  const byLevel = { P3: [], P4: [], P5: [], P6: [] };
  Array.from(counts.keys()).sort((a, b) => a.localeCompare(b))
    .forEach(t => { const lv = getTopicLevel(t); (byLevel[lv] || byLevel.P6).push(t); });

  let html = '';
  TOPIC_LEVELS.forEach(lv => {
    const topics = byLevel[lv];
    if (!topics.length) return;
    html += `<div class="ms-level" data-level="${lv}">
      <div class="ms-group" onclick="toggleBankTopicLevel('${lv}', event)">
        <span>Primary ${lv.slice(1)}</span>
        <input type="checkbox" onclick="toggleBankTopicLevel('${lv}', event)" aria-label="All ${lv} topics">
      </div>`;
    topics.forEach(t => {
      html += `<label class="ms-item">
        <span>${escapeHtml(t)} <span class="ms-item-n">${counts.get(t)}</span></span>
        <input type="checkbox" value="${escapeHtml(t)}" onchange="toggleBankTopic(this.value, this.checked)">
      </label>`;
    });
    html += `</div>`;
  });
  // Rebuilding drops the reader's place in a long list, so keep the scroll.
  const scroll = list.scrollTop;
  list.innerHTML = html || '<div class="ms-empty">No topics yet — they appear here as you add questions.</div>';
  list.scrollTop = scroll;
  _syncBankTopicTicks();
  populateSourceFilters();
}

// Ticks follow the state without the list being rebuilt around them — a rebuilt
// list swaps the very checkbox under the cursor for a new node mid-click.
function _syncBankTopicTicks() {
  const list = document.getElementById('bankTopicList');
  if (list) {
    list.querySelectorAll('.ms-item').forEach(item => {
      const cb = item.querySelector('input[type="checkbox"]');
      if (!cb) return;
      const on = bankTopicSel.has(cb.value);
      cb.checked = on;
      item.classList.toggle('on', on);
    });
    list.querySelectorAll('.ms-level').forEach(level => {
      const head = level.querySelector(':scope > .ms-group input[type="checkbox"]');
      if (!head) return;
      const boxes = Array.from(level.querySelectorAll('.ms-item input[type="checkbox"]'));
      const on = boxes.filter(c => c.checked).length;
      head.checked = boxes.length > 0 && on === boxes.length;
      head.indeterminate = on > 0 && on < boxes.length;   // half a year ticked reads as neither
    });
  }
  _syncBankTopicChrome();
}

// The button's own label: what is actually being filtered, at a glance.
function _syncBankTopicChrome() {
  const wrap = document.getElementById('bankTopicFilter');
  const label = document.getElementById('bankTopicLabel');
  const count = document.getElementById('bankTopicCount');
  const n = bankTopicSel.size;
  if (label) label.textContent = n === 0 ? 'All Topics' : n === 1 ? Array.from(bankTopicSel)[0] : n + ' topics';
  if (count) count.textContent = n === 0 ? 'No topics ticked' : n + ' ticked';
  if (wrap) wrap.classList.toggle('has-selection', n > 0);
}

function toggleBankTopic(topic, on) {
  if (on) bankTopicSel.add(topic); else bankTopicSel.delete(topic);
  _syncBankTopicTicks();
  renderQuestionBank();
}

// Tick a whole year at once — off again if it is already fully ticked.
function toggleBankTopicLevel(level, ev) {
  if (ev) { ev.preventDefault(); ev.stopPropagation(); }
  const list = document.getElementById('bankTopicList');
  const wrap = list && list.querySelector(`.ms-level[data-level="${level}"]`);
  const topics = wrap
    ? Array.from(wrap.querySelectorAll('.ms-item input[type="checkbox"]')).map(c => c.value)
    : Array.from(new Set(questionBank.flatMap(q => qTopicList(q)))).filter(t => t && getTopicLevel(t) === level);
  if (!topics.length) return;
  const allOn = topics.every(t => bankTopicSel.has(t));
  topics.forEach(t => { if (allOn) bankTopicSel.delete(t); else bankTopicSel.add(t); });
  _syncBankTopicTicks();
  renderQuestionBank();
}

function clearBankTopics() {
  if (!bankTopicSel.size) return;
  bankTopicSel.clear();
  _syncBankTopicTicks();
  renderQuestionBank();
}

function toggleBankTopicMenu(ev) {
  if (ev) ev.stopPropagation();
  const wrap = document.getElementById('bankTopicFilter');
  if (!wrap) return;
  const opening = !wrap.classList.contains('open');
  wrap.classList.toggle('open', opening);
  if (opening) populateTopicFilter();
}

// Click anywhere else, or press Escape, and the tick list puts itself away.
document.addEventListener('pointerdown', (e) => {
  const wrap = document.getElementById('bankTopicFilter');
  if (wrap && wrap.classList.contains('open') && !wrap.contains(e.target)) wrap.classList.remove('open');
});
document.addEventListener('keydown', (e) => {
  if (e.key !== 'Escape') return;
  const wrap = document.getElementById('bankTopicFilter');
  if (wrap) wrap.classList.remove('open');
});

// The worksheet a question was imported from (preferred), or its citation.
function questionSource(q) {
  return ((q && (q.sourceWorksheet || q.source)) || '').trim();
}

function populateSourceFilters() {
  const sources = [...new Set(questionBank.map(questionSource).filter(Boolean))].sort();
  ['bankFilterSource', 'wsFilterSource'].forEach(id => {
    const sel = document.getElementById(id);
    if (!sel) return;
    const prev = sel.value;
    sel.innerHTML = '<option value="">All Sources</option>';
    sources.forEach(s => {
      const opt = document.createElement('option');
      opt.value = s;
      opt.textContent = s;
      sel.appendChild(opt);
    });
    if (prev && sources.includes(prev)) sel.value = prev;
  });
}

// =====================================================================
// UTILITIES
// =====================================================================
function escapeHtml(str) {
  if (!str) return '';
  const div = document.createElement('div');
  div.appendChild(document.createTextNode(str));
  return div.innerHTML;
}

// Escape a text block's HTML for print while KEEPING its line breaks (so
// inline option lists like "A: …<br>B: …" don't collapse onto one line).
// <br> and block-level closings become newlines; other tags are stripped.
function escapeHtmlKeepLines(content) {
  if (!content) return '';
  const withBreaks = String(content)
    .replace(/<\s*br\s*\/?>/gi, '\n')
    .replace(/<\/(p|div|li|tr|h[1-6])\s*>/gi, '\n');
  const lines = withBreaks
    .replace(/<[^>]*>/g, '')
    .replace(/&nbsp;/g, ' ')
    .split('\n')
    .map(l => l.replace(/[ \t]+/g, ' ').trim())
    .filter(l => l.length);
  return lines.map(escapeHtml).join('<br>');
}

// A repeated message stacks a counter instead of a new toast, and the container
// is capped. Whatever goes wrong in a loop, the screen never fills with a wall
// of identical popups the user has to sit and watch scroll past.
const TOAST_MAX = 4;
function showToast(message, type = 'info') {
  const container = document.getElementById('toastContainer');
  if (!container) return;
  const same = Array.from(container.children).find(el => el.dataset && el.dataset.msg === message && el.dataset.type === type);
  if (same) {
    same.dataset.n = String((parseInt(same.dataset.n, 10) || 1) + 1);
    let tag = same.querySelector('.toast-count');
    if (!tag) { tag = document.createElement('b'); tag.className = 'toast-count'; same.appendChild(tag); }
    tag.textContent = ' ×' + same.dataset.n;
    clearTimeout(same._hide);
    same._hide = setTimeout(() => _toastFade(same), 3000);
    return;
  }
  while (container.children.length >= TOAST_MAX) container.removeChild(container.firstElementChild);
  const toast = document.createElement('div');
  toast.className = 'toast ' + type;
  toast.dataset.msg = message;
  toast.dataset.type = type;
  toast.dataset.n = '1';

  let icon = '';
  switch (type) {
    case 'success': icon = '<svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5"><polyline points="20 6 9 17 4 12"/></svg>'; break;
    case 'error': icon = '<svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5"><circle cx="12" cy="12" r="10"/><line x1="15" y1="9" x2="9" y2="15"/><line x1="9" y1="9" x2="15" y2="15"/></svg>'; break;
    default: icon = '<svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5"><circle cx="12" cy="12" r="10"/><line x1="12" y1="16" x2="12" y2="12"/><line x1="12" y1="8" x2="12.01" y2="8"/></svg>';
  }
  
  toast.innerHTML = icon + message;
  container.appendChild(toast);
  toast._hide = setTimeout(() => _toastFade(toast), 3000);
}
function _toastFade(toast) {
  if (!toast) return;
  toast.style.opacity = '0';
  toast.style.transform = 'translateX(30px)';
  toast.style.transition = '0.3s ease';
  setTimeout(() => toast.remove(), 300);
}

function showConfirm(title, message, onConfirm) {
  document.getElementById('confirmTitle').textContent = title;
  document.getElementById('confirmMessage').textContent = message;
  document.getElementById('confirmOverlay').classList.add('active');
  
  const btn = document.getElementById('confirmAction');
  btn.onclick = () => {
    closeConfirm();
    onConfirm();
  };
}

function closeConfirm() {
  document.getElementById('confirmOverlay').classList.remove('active');
}

// =====================================================================
// STUDENT MANAGEMENT
// =====================================================================
let students = []; // [{ name: 'John', level: 'P4' }]
let studentSetupSeen = false; // once true, don't auto-prompt again
let activeStudentIndex = -1;

const topicLevelMap = {
  'Living and non-living things': 'P3', 'Materials': 'P3', 'Life Cycles': 'P3', 'Magnets': 'P3',
  'Plant Systems': 'P4', 'Human Body Systems': 'P4', 'Matter and its 3 States': 'P4', 'Light': 'P4', 'Heat': 'P4',
  'Water and its 3 States': 'P5', 'Plant Reproduction': 'P5', 'Human Reproduction': 'P5',
  'Human and Plant Respiration': 'P5', 'Human and Plant Transport': 'P5', 'Electrical Systems': 'P5',
  'Forces': 'P6', 'Energy in Food': 'P6', 'Energy Conversion': 'P6',
  'Living Together': 'P6', 'Food Chains and Webs': 'P6', 'Humans and the Environment': 'P6'
};

// ── Custom topic management — the authoring dropdown is the defaults above plus
// the admin's custom topics, minus any they removed; persisted per user. ──────
const TOPIC_LEVELS = ['P3', 'P4', 'P5', 'P6'];
let customTopics = {};   // { 'Topic name': 'P3'|'P4'|'P5'|'P6' }
let removedTopics = [];  // default topic names hidden from the dropdown
function _topicsStoreKey() { return 'cerTopics:' + (currentUser ? currentUser.uid : 'anon'); }
function loadCustomTopics() {
  try {
    const raw = JSON.parse(localStorage.getItem(_topicsStoreKey()) || '{}');
    customTopics = (raw && typeof raw.custom === 'object' && raw.custom) ? raw.custom : {};
    removedTopics = Array.isArray(raw && raw.removed) ? raw.removed : [];
  } catch (_) { customTopics = {}; removedTopics = []; }
}
function saveCustomTopics() {
  try { localStorage.setItem(_topicsStoreKey(), JSON.stringify({ custom: customTopics, removed: removedTopics })); } catch (_) {}
  publishTopicsForStudents();
}
// Admin only: mirror the topic→level map to Firestore so students resolve
// custom topics to their REAL level (otherwise unknown topics default to P6
// and would be hidden from every student below P6 by the level cap).
function publishTopicsForStudents() {
  if (!currentUser || currentUser.role !== 'admin' || !db) return;
  setDoc(doc(db, 'users', currentUser.uid, 'settings', 'topics'),
    { custom: customTopics, removed: removedTopics }, { merge: false })
    .catch(e => console.warn('topics publish', e));
}
function currentTopicsByLevel() {
  const byLevel = { P3: [], P4: [], P5: [], P6: [] };
  Object.keys(topicLevelMap).forEach(t => { if (!removedTopics.includes(t)) byLevel[topicLevelMap[t]].push(t); });
  Object.keys(customTopics).forEach(t => { const lv = customTopics[t]; if (byLevel[lv] && !byLevel[lv].includes(t)) byLevel[lv].push(t); });
  return byLevel;
}
function currentTopics() {
  const byLevel = currentTopicsByLevel();
  return TOPIC_LEVELS.reduce((a, lv) => a.concat(byLevel[lv]), []);
}
function getTopicLevel(topic) {
  return customTopics[topic] || topicLevelMap[topic] || 'P6'; // default to P6 for unknown/custom topics
}
function rebuildTopicSelect() {
  const sel = document.getElementById('topicSelect');
  if (!sel) return;
  const cur = (sel.value && sel.value !== '__custom__') ? sel.value : '';
  const byLevel = currentTopicsByLevel();
  let html = '';
  TOPIC_LEVELS.forEach(lv => {
    html += `<optgroup label="── ${lv} ──">`;
    byLevel[lv].forEach(t => { html += `<option value="${escapeHtml(t)}">${escapeHtml(t)}</option>`; });
    html += `</optgroup>`;
  });
  html += `<optgroup label="── Manage ──"><option value="__custom__">⚙ Add / remove topics…</option></optgroup>`;
  sel.innerHTML = html;
  if (cur && Array.from(sel.options).some(o => o.value === cur && o.value !== '__custom__')) sel.value = cur;
  else { const all = currentTopics(); sel.value = all.includes('Heat') ? 'Heat' : (all[0] || ''); }
  // Optional 2nd-topic select: same options, a "None" placeholder, no Manage entry.
  const sel2 = document.getElementById('topicSelect2');
  if (sel2) {
    const cur2 = sel2.value || '';
    let html2 = '<option value="">+ Add 2nd topic (optional)</option>';
    TOPIC_LEVELS.forEach(lv => {
      html2 += `<optgroup label="── ${lv} ──">`;
      byLevel[lv].forEach(t => { html2 += `<option value="${escapeHtml(t)}">${escapeHtml(t)}</option>`; });
      html2 += `</optgroup>`;
    });
    sel2.innerHTML = html2;
    sel2.value = (cur2 && Array.from(sel2.options).some(o => o.value === cur2)) ? cur2 : '';
  }
}
function openManageTopics() {
  renderManageTopicsList();
  const nm = document.getElementById('newTopicName'); if (nm) nm.value = '';
  const lv = document.getElementById('newTopicLevel'); if (lv) lv.value = 'P5';
  const ov = document.getElementById('manageTopicsOverlay'); if (ov) ov.classList.add('active');
}
function closeManageTopics() {
  const ov = document.getElementById('manageTopicsOverlay'); if (ov) ov.classList.remove('active');
}
function renderManageTopicsList() {
  const wrap = document.getElementById('manageTopicsList');
  if (!wrap) return;
  const byLevel = currentTopicsByLevel();
  wrap.innerHTML = TOPIC_LEVELS.map(lv => {
    const rows = byLevel[lv].map(t => {
      const isCustom = !!customTopics[t];
      const safe = escapeHtml(t).replace(/'/g, "\\'");
      return `<div style="display:flex;align-items:center;gap:8px;padding:5px 8px;border:1px solid var(--border);border-radius:8px;margin-bottom:5px;">
        <span style="flex:1;font-size:0.88rem;">${escapeHtml(t)}${isCustom ? ' <span style="font-size:0.7rem;color:var(--primary);">(custom)</span>' : ''}</span>
        <button class="btn btn-outline" style="padding:2px 9px;font-size:0.78rem;color:var(--accent-red);border-color:#f0b9b9;" onclick="removeTopic('${safe}')">✕ Remove</button>
      </div>`;
    }).join('') || `<div style="font-size:0.8rem;color:var(--text-muted);padding:4px 0;">No topics</div>`;
    return `<div style="margin-bottom:10px;"><div style="font-size:0.72rem;font-weight:700;letter-spacing:0.05em;color:var(--text-muted);text-transform:uppercase;margin-bottom:5px;">${lv}</div>${rows}</div>`;
  }).join('');
}
function addCustomTopic() {
  const nameEl = document.getElementById('newTopicName');
  const lvlEl = document.getElementById('newTopicLevel');
  const name = (nameEl ? nameEl.value : '').trim();
  const lvl = lvlEl ? lvlEl.value : 'P5';
  if (!name) { showToast('Type a topic name first', 'error'); return; }
  if (!TOPIC_LEVELS.includes(lvl)) return;
  if (currentTopics().includes(name)) { showToast('That topic already exists', 'info'); return; }
  customTopics[name] = lvl;
  removedTopics = removedTopics.filter(t => t !== name); // un-hide if it was a removed default
  saveCustomTopics();
  rebuildTopicSelect();
  renderManageTopicsList();
  if (nameEl) nameEl.value = '';
  showToast(`Added “${name}” under ${lvl} ✓`, 'success');
}
function removeTopic(topic) {
  if (!topic) return;
  showConfirm('Remove topic', `Remove “${topic}” from the topic list? Questions already saved with this topic keep it — this only hides it from the dropdown.`, () => {
    if (customTopics[topic]) delete customTopics[topic];
    else if (topicLevelMap[topic] && !removedTopics.includes(topic)) removedTopics.push(topic);
    saveCustomTopics();
    rebuildTopicSelect();
    renderManageTopicsList();
    showToast(`Removed “${topic}”`, 'info');
  });
}

// ── Custom question categories — e.g. "PSLE 2025 - MCQ" ─────────────────────
// Admin-defined categories offered alongside the built-in ones when authoring
// and in every category filter. Stored permanently: Firestore (survives new
// devices) with a localStorage copy for instant startup.
const DEFAULT_CATEGORY_GROUPS = [
  { label: 'Skills', items: ['CER', 'Single Relationship', 'Double Relationship', 'Reliability', 'Fairness', 'Accuracy', 'Constant Variable', 'Hypothesis', 'Aim', 'Conclusion', 'Definition', 'Explanation', 'Stating'] },
  { label: 'Key Concepts', items: ['Key Concepts'] },
  { label: 'Question Type', items: ['Multiple Choice Question'] },
  { label: 'PSLE', items: ['PSLE - MCQ', 'PSLE - OEQ'] }
];
let customCategories = [];
function _categoriesStoreKey() { return 'cerCategories:' + (currentUser ? currentUser.uid : 'anon'); }
function allCategories() {
  const defaults = DEFAULT_CATEGORY_GROUPS.reduce((a, g) => a.concat(g.items), []);
  return defaults.concat(customCategories.filter(c => !defaults.includes(c)));
}
function isCustomCategory(c) { return customCategories.includes(c); }
async function loadCustomCategories() {
  try {
    const raw = JSON.parse(localStorage.getItem(_categoriesStoreKey()) || '[]');
    customCategories = Array.isArray(raw) ? raw.filter(c => typeof c === 'string' && c.trim()) : [];
  } catch (_) { customCategories = []; }
  // Firestore copy is authoritative. Students read the ADMIN's list so custom
  // categories show up in their worksheet filters too.
  try {
    const uid = (currentUser && currentUser.role === 'student') ? adminUid : (currentUser && currentUser.uid);
    if (uid && db) {
      const s = await getDoc(doc(db, 'users', uid, 'settings', 'categories'));
      if (s.exists() && Array.isArray(s.data().custom)) {
        customCategories = s.data().custom.filter(c => typeof c === 'string' && c.trim());
      }
    }
  } catch (e) { console.warn('categories load', e); }
  rebuildCategorySelects();
}
function saveCustomCategories() {
  try { localStorage.setItem(_categoriesStoreKey(), JSON.stringify(customCategories)); } catch (_) {}
  if (currentUser && currentUser.role === 'admin' && db) {
    setDoc(doc(db, 'users', currentUser.uid, 'settings', 'categories'), { custom: customCategories })
      .catch(e => console.warn('categories save', e));
  }
}
// Rebuild every select that offers categories: the authoring dropdown (which
// also carries the Manage entry) and the bank / worksheet / quest-picker
// filters (which keep their "All …" placeholder). Selection is preserved.
function rebuildCategorySelects() {
  let groupsHtml = '';
  DEFAULT_CATEGORY_GROUPS.forEach(g => {
    groupsHtml += `<optgroup label="── ${g.label} ──">`;
    g.items.forEach(c => { groupsHtml += `<option value="${escapeHtml(c)}">${escapeHtml(c)}</option>`; });
    groupsHtml += '</optgroup>';
  });
  if (customCategories.length) {
    groupsHtml += '<optgroup label="── Custom ──">';
    customCategories.forEach(c => { groupsHtml += `<option value="${escapeHtml(c)}">${escapeHtml(c)}</option>`; });
    groupsHtml += '</optgroup>';
  }
  const authoring = document.getElementById('categorySelect');
  if (authoring) {
    const cur = (authoring.value && authoring.value !== '__custom__') ? authoring.value : 'CER';
    authoring.innerHTML = groupsHtml + '<optgroup label="── Manage ──"><option value="__custom__">⚙ Add / remove categories…</option></optgroup>';
    authoring.value = allCategories().includes(cur) ? cur : 'CER';
  }
  // Optional 2nd-category select: same options, a "None" placeholder, no Manage entry.
  const authoring2 = document.getElementById('categorySelect2');
  if (authoring2) {
    const cur2 = authoring2.value || '';
    authoring2.innerHTML = '<option value="">+ Add 2nd category (optional)</option>' + groupsHtml;
    authoring2.value = (cur2 && allCategories().includes(cur2)) ? cur2 : '';
  }
  ['bankFilterCategory', 'wsFilterCategory', 'cqFilterCategory'].forEach(id => {
    const sel = document.getElementById(id);
    if (!sel) return;
    const cur = sel.value;
    const placeholder = (sel.options[0] && sel.options[0].value === '') ? sel.options[0].textContent : 'All Categories';
    sel.innerHTML = `<option value="">${escapeHtml(placeholder)}</option>` + groupsHtml;
    sel.value = (cur && allCategories().includes(cur)) ? cur : '';
  });
}
function openManageCategories() {
  renderManageCategoriesList();
  const nm = document.getElementById('newCategoryName'); if (nm) nm.value = '';
  const ov = document.getElementById('manageCategoriesOverlay'); if (ov) ov.classList.add('active');
}
function closeManageCategories() {
  const ov = document.getElementById('manageCategoriesOverlay'); if (ov) ov.classList.remove('active');
}
function renderManageCategoriesList() {
  const wrap = document.getElementById('manageCategoriesList');
  if (!wrap) return;
  wrap.innerHTML = customCategories.map(c => {
    const safe = escapeHtml(c).replace(/'/g, "\\'");
    return `<div style="display:flex;align-items:center;gap:8px;padding:5px 8px;border:1px solid var(--border);border-radius:8px;margin-bottom:5px;">
      <span style="flex:1;font-size:0.88rem;">${escapeHtml(c)} <span style="font-size:0.7rem;color:var(--primary);">(custom)</span></span>
      <button class="btn btn-outline" style="padding:2px 9px;font-size:0.78rem;color:var(--accent-red);border-color:#f0b9b9;" onclick="removeCustomCategory('${safe}')">✕ Remove</button>
    </div>`;
  }).join('') || `<div style="font-size:0.8rem;color:var(--text-muted);padding:4px 0;">No custom categories yet — add one above, e.g. &ldquo;PSLE 2025 - MCQ&rdquo;.</div>`;
}
function addCustomCategory() {
  const nameEl = document.getElementById('newCategoryName');
  const name = (nameEl ? nameEl.value : '').trim();
  if (!name) { showToast('Type a category name first', 'error'); return; }
  if (name === '__custom__') return;
  if (allCategories().includes(name)) { showToast('That category already exists', 'info'); return; }
  customCategories.push(name);
  customCategories.sort((a, b) => a.localeCompare(b));
  saveCustomCategories();
  rebuildCategorySelects();
  renderManageCategoriesList();
  // Select it right away — the admin is usually mid-authoring when adding one.
  const sel = document.getElementById('categorySelect');
  if (sel) { sel.value = name; _lastCategoryValue = name; }
  if (nameEl) nameEl.value = '';
  showToast(`Added “${name}” ✓ — selected for this question`, 'success');
}
function removeCustomCategory(name) {
  if (!isCustomCategory(name)) return;
  showConfirm('Remove category', `Remove “${name}” from the category list? Questions already saved with it keep it — this only removes it from the dropdowns.`, () => {
    customCategories = customCategories.filter(c => c !== name);
    saveCustomCategories();
    rebuildCategorySelects();
    renderManageCategoriesList();
    showToast(`Removed “${name}”`, 'info');
  });
}

function getLevelNumber(level) {
  return parseInt(level.replace('P', '')) || 3;
}

function openStudentSetup() {
  const overlay = document.getElementById('studentSetupOverlay');
  const list = document.getElementById('studentSetupList');
  list.innerHTML = '';
  if (students.length === 0) {
    addStudentRow();
  } else {
    students.forEach((s, i) => addStudentRow(s.name, s.level));
  }
  overlay.classList.add('active');
}

function addStudentRow(name, level) {
  const list = document.getElementById('studentSetupList');
  const row = document.createElement('div');
  row.className = 'student-setup-row';
  row.innerHTML = `
    <input type="text" placeholder="Student name" value="${escapeHtml(name || '')}" class="student-name-input">
    <select class="student-level-select">
      <option value="P3"${level === 'P3' ? ' selected' : ''}>P3</option>
      <option value="P4"${level === 'P4' ? ' selected' : ''}>P4</option>
      <option value="P5"${level === 'P5' ? ' selected' : ''}>P5</option>
      <option value="P6"${level === 'P6' ? ' selected' : ''}>P6</option>
    </select>
    <button class="remove-student-btn" onclick="this.parentElement.remove()" title="Remove">
      <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" style="width:14px;height:14px;"><line x1="18" y1="6" x2="6" y2="18"/><line x1="6" y1="6" x2="18" y2="18"/></svg>
    </button>
  `;
  list.appendChild(row);
}

function saveStudentSetup() {
  const rows = document.querySelectorAll('#studentSetupList .student-setup-row');
  const newStudents = [];
  rows.forEach(row => {
    const name = row.querySelector('.student-name-input').value.trim();
    const level = row.querySelector('.student-level-select').value;
    if (name) {
      newStudents.push({ name, level });
    }
  });
  if (newStudents.length === 0) {
    showToast('Please enter at least one student name', 'error');
    return;
  }
  students = newStudents;
  studentSetupSeen = true;
  saveStudentsToStorage();
  document.getElementById('studentSetupOverlay').classList.remove('active');
  populatePracticeStudentSelect();
  showToast('Students saved!', 'success');
}

function skipStudentSetup() {
  studentSetupSeen = true;
  saveStudentsToStorage();
  document.getElementById('studentSetupOverlay').classList.remove('active');
}

function saveStudentsToStorage() {
  if (!currentUser) return;
  const ref = doc(db, 'users', currentUser.uid);
  setDoc(ref, { students, studentSetupSeen }, { merge: true }).catch(err => {
    console.error('Failed to save students:', err);
  });
}

async function loadStudentsFromStorage() {
  if (!currentUser) return;
  try {
    const ref = doc(db, 'users', currentUser.uid);
    const snap = await getDoc(ref);
    if (snap.exists()) {
      const data = snap.data();
      students = data.students || [];
      // Backward compatibility: users with existing students should not be prompted again
      studentSetupSeen = !!data.studentSetupSeen || students.length > 0;
    } else {
      students = [];
      studentSetupSeen = false;
    }
  } catch (err) {
    console.error('Failed to load students:', err);
    // On load failure, avoid trapping user in repeated prompts this session
    studentSetupSeen = true;
  }
}

function populatePracticeStudentSelect() {
  const sel = document.getElementById('practiceStudentSelect');
  if (!sel) return;
  sel.innerHTML = '<option value="">Select student...</option>';
  students.forEach((s, i) => {
    const opt = document.createElement('option');
    opt.value = i;
    opt.textContent = `${s.name} (${s.level})`;
    sel.appendChild(opt);
  });
}

function onPracticeStudentChange() {
  const sel = document.getElementById('practiceStudentSelect');
  activeStudentIndex = sel.value !== '' ? parseInt(sel.value) : -1;
  practiceSessionResults = [];   // a new student starts a fresh session
  _practiceServed = _practiceServedLoad(students[activeStudentIndex]);
  if (activeStudentIndex >= 0) {
    renderPracticeReady();
  } else {
    document.getElementById('practiceContainer').innerHTML = `
      <div class="empty-state">
        <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5"><path d="M2 3h6a4 4 0 0 1 4 4v14a3 3 0 0 0-3-3H2z"/><path d="M22 3h-6a4 4 0 0 0-4 4v14a3 3 0 0 1 3-3h7z"/></svg>
        <h3>Select a Student</h3>
        <p>Choose a student from the dropdown above, then click "Next Question" to start practising.</p>
      </div>`;
  }
}

function renderPracticeReady() {
  const student = students[activeStudentIndex];
  if (!student) return;

  document.getElementById('practiceContainer').innerHTML = `
    <div class="practice-student-info">
      <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" style="width:16px;height:16px;"><path d="M20 21v-2a4 4 0 0 0-4-4H8a4 4 0 0 0-4 4v2"/><circle cx="12" cy="7" r="4"/></svg>
      ${escapeHtml(student.name)} &mdash; Level ${escapeHtml(student.level)}
    </div>
    <div style="text-align:center;padding:30px 0;">
      <button class="btn btn-primary btn-lg" onclick="loadRandomPracticeQuestion()">
        <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" style="width:18px;height:18px;"><polyline points="1 4 1 10 7 10"/><path d="M3.51 15a9 9 0 1 0 2.13-9.36L1 10"/></svg>
        Start Practice
      </button>
    </div>`;
}

// Out-of-syllabus questions are kept in the bank and shown on the Past Papers
// page, but never served in any general practice mode.
function qInSyllabus(q) {
  if (!q) return true;
  if (q.notInSyllabus) return false;
  // Retired topics (Cell Systems) are past-paper-completion ONLY — never
  // served in any practice or game mode, even if the admin missed ticking
  // the "Not in syllabus" flag on an individual question.
  if (/cell\s*system/i.test(q.topic || '')) return false;
  return true;
}

function getQuestionsForLevel(level) {
  const maxLevel = getLevelNumber(level);
  return questionBank.filter(q => {
    if (!qInSyllabus(q)) return false;             // not in syllabus → practice-excluded
    // Only include questions with something the AI can mark
    if (!questionHasMarkableAnswer(q)) return false;
    const qLevel = getLevelNumber(getTopicLevel(q.topic));
    return qLevel <= maxLevel;
  });
}

let practiceSessionResults = []; // per-question results for the end-of-session report
// qid -> times served to this student profile (rotation for count ties).
// Persisted per (admin uid + profile name) so switching students or reloading
// the page no longer restarts the rotation from scratch — attempts on this
// page aren't written to the shared log, so this map is its only memory.
let _practiceServed = {};
function _practiceServedKey(stu) { return 'practiceServed_' + ((currentUser && currentUser.uid) || 'anon') + '_' + ((stu && stu.name) || ''); }
function _practiceServedLoad(stu) { if (!stu) return {}; try { return JSON.parse(localStorage.getItem(_practiceServedKey(stu))) || {}; } catch (_) { return {}; } }
function _practiceServedSave(stu) { if (!stu) return; try { localStorage.setItem(_practiceServedKey(stu), JSON.stringify(_practiceServed)); } catch (_) {} }

async function loadRandomPracticeQuestion() {
  rpgQuestionChanged();
  const student = students[activeStudentIndex];
  if (!student) return;

  const available = getQuestionsForLevel(student.level);
  if (available.length === 0) {
    document.getElementById('practiceContainer').innerHTML = `
      <div class="practice-student-info">
        <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" style="width:16px;height:16px;"><path d="M20 21v-2a4 4 0 0 0-4-4H8a4 4 0 0 0-4 4v2"/><circle cx="12" cy="7" r="4"/></svg>
        ${escapeHtml(student.name)} &mdash; Level ${escapeHtml(student.level)}
      </div>
      <div class="empty-state">
        <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5"><circle cx="12" cy="12" r="10"/><line x1="12" y1="16" x2="12" y2="12"/><line x1="12" y1="8" x2="12.01" y2="8"/></svg>
        <h3>No Questions Available</h3>
        <p>There are no questions for ${escapeHtml(student.level)} level or below yet. Add questions to the Question Bank first.</p>
      </div>`;
    return;
  }

  // Serve the LEAST-DONE question first: never-attempted (0×) is top priority,
  // then ascending attempt count (orderByAttemptPriority). A session-served
  // counter breaks ties so one sitting still rotates through everything before
  // any repeats.
  try { await loadAttemptStats(); } catch (_) {}
  const ordered = orderByAttemptPriority(available);
  ordered.sort((a, b) => (_practiceServed[a.id] || 0) - (_practiceServed[b.id] || 0)); // stable: keeps count-priority within equal serves
  const q = ordered[0];
  _practiceServed[q.id] = (_practiceServed[q.id] || 0) + 1;
  _practiceServedSave(student);
  renderPracticeQuestion(q, student);
}

let currentPracticeQ = null;
let _openItemsStore = {};        // containerSel -> [{ label, model }] for open-ended marking
let _openMcqStore = {};          // containerSel -> [{ blockId, options:[{letter,text,id,correct}] }] — "letter" is the option NUMBER ("1".."8")
let _openQStore = {};            // containerSel -> the question being answered (context for per-part AI calls)
let _openSurfaceCfg = {};        // containerSel -> { scoreElId, scorePrefix, mode, onAllMarked }
let _openPartResults = {};       // containerSel -> { 'open:<oidx>'|'mcq:<blockId>': { verdict, pts, expected, student } }
let _openFinalized = {};         // containerSel -> true once the attempt has been recorded

// Hint + Check answer buttons for ONE part of a question (an answer box or an MCQ),
// plus the box the hint is written into.
function _partActionsHtml(containerSel, kind, pid) {
  return `<div class="part-actions" style="display:flex;gap:6px;margin-top:6px;flex-wrap:wrap;">
      <button type="button" class="btn btn-outline part-ai-btn" style="padding:5px 12px;font-size:0.8rem;" data-part-hint="${containerSel}" data-kind="${kind}" data-pid="${pid}" title="Get a hint for this part — it won't give away the answer">💡 Hint</button>
      <button type="button" class="btn btn-check part-ai-btn" style="padding:5px 12px;font-size:0.8rem;" data-part-mark="${containerSel}" data-kind="${kind}" data-pid="${pid}" title="Check this part — the AI marks it and tells you how you did">✓ Check answer</button>
    </div>
    <div class="part-hint-box" data-hint-for="${kind}:${pid}" style="display:none;margin-top:6px;padding:8px 12px;border:1px solid var(--accent-orange);background:var(--accent-orange-light,#fff3e0);border-radius:8px;font-size:0.85rem;line-height:1.55;"></div>`;
}

// One line of question text, with its part marker in front of it when the block
// opens a part. Flex row rather than a prepended span, because block.content is
// authored HTML that usually starts with a <p> or <div> — an inline marker
// inside it would be pushed onto its own line anyway.
function _qpTextHtml(part, content) {
  const lab = qPartLabel(part) || (part ? String(part) : '');
  const text = `<div class="qp-qtext">${content || ''}</div>`;
  if (!lab) return text;
  return `<div class="qp-part-row"><span class="qp-part-tag">${escapeHtml(lab)}</span>${text}</div>`;
}
// `part` is the question part this box belongs to ('(a)'). It is deliberately
// NOT shown above the box — the part is already printed beside the question, and
// repeating it over every answer area is noise that pushes the page down. It
// still travels into items[].label, which is the name the AI marker uses to tell
// one answer from another ("Part: [(a) Claim]").
function _openSection(items, label, modelAnswer, bg, fg, containerSel, source, part) {
  const oidx = items.length;
  // `block`/`field` let admins edit this part's model answer in place and write
  // it straight back to the question (see _adminAnsSave).
  const p = part ? String(part).trim() : '';
  const itemLabel = [p, label || (p ? 'Answer' : '')].filter(Boolean).join(' ') || 'Answer';
  items.push({ label: itemLabel, model: modelAnswer || '', block: source && source.block, field: (source && source.field) || 'content' });
  // Escaped: every caller used to pass a hard-coded literal, but the label now
  // carries the question's own part marker, so it is author-influenced text.
  const labelHtml = label ? `<div class="cer-student-label" style="background:${bg};color:${fg};margin-bottom:6px;">${escapeHtml(label)}</div>` : '';
  return `<div class="open-answer-section" data-mic-wrap style="margin-bottom:14px;">
      ${labelHtml}
      <div style="display:flex;gap:6px;align-items:flex-start;">
        <textarea class="open-answer" data-oidx="${oidx}" rows="3" placeholder="Type or speak your answer..."
          style="flex:1;min-width:0;padding:10px;border:1px solid var(--border);border-radius:8px;font-family:inherit;font-size:0.95rem;line-height:1.5;resize:vertical;background:#fff;color:var(--on-surface,#14161a);"></textarea>
        ${micButtonHtml('', 'Speak your answer')}
      </div>
      ${_partActionsHtml(containerSel, 'open', oidx)}
      ${_adminAnswerToolHtml(containerSel, oidx, modelAnswer || '')}
      <div class="open-feedback" style="margin-top:4px;"></div>
    </div>`;
}

// =====================================================================
// ADMIN: fix a part's model answer inline while practising. Admins can edit the
// answer by hand or regenerate it with AI, review the draft, then save it back
// to the question bank so every student is marked against the corrected answer.
// =====================================================================
function _isAdmin() { return !!(currentUser && currentUser.role === 'admin'); }
function _isEmployee() { return !!(currentUser && currentUser.role === 'employee'); }
// Everything an employee is hired to do — authoring questions and building
// worksheets — is gated on this rather than on _isAdmin. _isAdmin keeps its
// old meaning everywhere else, so nothing an employee should not touch opens
// up by accident: adding the role is default-deny.
function _canAuthor() { return _isAdmin() || _isEmployee(); }
// configureSidebarForRole('employee') hides every nav item and shows back only
// EMPLOYEE_PAGES — but several subsystems switch their OWN nav item back on
// LATER, once an async load resolves (rpgApplyVisibility for the game items,
// and through it the Realm of Embers and Science Strike navs). Every one of
// those late shows must ask this first, or the lockdown lasts only until the
// hero doc arrives and the whole game menu reappears.
function _navAllowed(page) {
  return !_isEmployee() || EMPLOYEE_PAGES.indexOf(page) >= 0;
}
// Whose question bank this account reads and writes. An employee has none of
// their own — they author directly into the teacher's, which is the bank
// students are actually served from.
function _bankOwnerUid() {
  if (_isEmployee() && adminUid) return adminUid;
  return currentUser ? currentUser.uid : null;
}

function _adminAnswerToolHtml(containerSel, oidx, model) {
  if (!_isAdmin()) return '';
  const has = (model || '').trim();
  return `<div class="admin-ans-tool" data-aatool="${containerSel}" data-aoidx="${oidx}" style="margin-top:6px;padding:8px 10px;border:1px dashed var(--accent-blue,#2d6ca8);border-radius:8px;background:rgba(37,99,235,0.05);font-size:0.82rem;">
      <div class="admin-ans-view" style="display:flex;gap:8px;align-items:flex-start;flex-wrap:wrap;">
        <span style="color:var(--accent-blue,#2d6ca8);font-weight:600;white-space:nowrap;">🛠️ Model answer</span>
        <span class="admin-ans-current" style="flex:1;min-width:140px;color:var(--text-muted);line-height:1.5;">${has ? escapeHtml(model) : '<em>— none set —</em>'}</span>
        <span style="display:flex;gap:6px;flex-wrap:wrap;">
          <button type="button" class="btn btn-outline" style="padding:3px 9px;font-size:0.78rem;" data-aedit>✎ Edit</button>
          <button type="button" class="btn btn-outline" style="padding:3px 9px;font-size:0.78rem;" data-aregen>🤖 Regenerate</button>
        </span>
      </div>
      <div class="admin-ans-edit" style="display:none;margin-top:6px;">
        <textarea class="admin-ans-input" rows="3" placeholder="Type the correct model answer for this part..." style="width:100%;box-sizing:border-box;padding:8px;border:1px solid var(--border);border-radius:6px;font-family:inherit;font-size:0.85rem;line-height:1.5;resize:vertical;background:#fff;color:var(--on-surface,#14161a);"></textarea>
        <div style="display:flex;gap:6px;margin-top:6px;align-items:center;">
          <span class="admin-ans-status" style="margin-right:auto;color:var(--text-muted);font-size:0.78rem;"></span>
          <button type="button" class="btn btn-outline" style="padding:3px 10px;font-size:0.78rem;" data-acancel>Cancel</button>
          <button type="button" class="btn btn-primary" style="padding:3px 12px;font-size:0.78rem;" data-asave>Save answer</button>
        </div>
      </div>
    </div>`;
}

// The specific sub-question text a part answers: the nearest text block above it.
// Gives the AI the right context for ONE part of a multi-part question.
// The sub-question an answer box belongs to. When the question uses official
// parts this selects by PART — the text that opened this block's part — rather
// than by "nearest text block above", which picked up a shared preamble or an
// unrelated aside. Falls back to proximity for questions with no parts.
function _partPromptText(q, block) {
  const blocks = (q && q.blocks) || [];
  const idx = block ? blocks.indexOf(block) : -1;
  if (idx < 0) return '';
  const pMap = qHasParts(blocks) ? qPartMap(blocks) : null;
  const mine = pMap ? qPartOf(pMap, block) : '';
  if (mine) {
    const own = [];
    blocks.forEach(b => {
      if ((b.type === 'text' || b.type === 'part') && qPartOf(pMap, b) === mine) {
        own.push(((b.type === 'part' && b.label) ? b.label + ' ' : '') + stripHtml(b.content || ''));
      }
    });
    const joined = own.join(' ').replace(/\s+/g, ' ').trim();
    // The marker itself is a field now, so put it back in front — the model is
    // being asked about part (b) and should be told so.
    if (joined) return qPartLabel(mine) + ' ' + joined;
  }
  for (let i = idx - 1; i >= 0; i--) {
    if (blocks[i].type === 'text') return stripHtml(blocks[i].content || '');
  }
  return '';
}

function _adminAnsItem(toolEl) {
  const cs = toolEl.getAttribute('data-aatool');
  const oidx = parseInt(toolEl.getAttribute('data-aoidx'), 10);
  const items = _openItemsStore[cs] || [];
  return { cs, oidx, it: items[oidx], q: _openQStore[cs] };
}

function _adminAnsOpenEditor(toolEl, draft) {
  const editBox = toolEl.querySelector('.admin-ans-edit');
  const input = toolEl.querySelector('.admin-ans-input');
  const { it } = _adminAnsItem(toolEl);
  if (input) input.value = typeof draft === 'string' ? draft : (it ? it.model || '' : '');
  if (editBox) editBox.style.display = '';
  if (input) input.focus();
}

async function _adminAnsRegen(toolEl, btn) {
  if (!window.__aiReady || !window.__aiReady()) { showToast("AI isn't set up yet — add your reCAPTCHA site key in the code", 'info'); return; }
  const { it, q } = _adminAnsItem(toolEl);
  if (!it || !q) return;
  _adminAnsOpenEditor(toolEl, ''); // surface the editor so the draft is reviewable
  const statusEl = toolEl.querySelector('.admin-ans-status');
  const orig = btn ? btn.innerHTML : '';
  if (btn) { btn.disabled = true; btn.innerHTML = '…'; }
  if (statusEl) statusEl.textContent = 'Generating…';
  try {
    const ctx = _questionContext(q);
    const partText = _partPromptText(q, it.block);
    const cer = it.label && it.label !== 'Answer' ? `This is the "${it.label}" portion of a Claim–Evidence–Reasoning answer; write only that portion. ` : '';
    const prompt =
      `You are a science teacher writing the ideal model answer for ONE part of an exam question. ` +
      `Question: "${q.title || ''}" (topic: ${q.topic || 'Science'}). Full context: "${ctx}". ` +
      `The specific part to answer is: "${partText || it.label || 'the question'}". ` + cer +
      `Write the concise, scientifically correct answer a student should give for THIS part only — the actual answer itself, not advice or instructions. Keep it to 1–3 sentences. Return ONLY the answer text.`;
    const out = (await askGemini(prompt, { maxOutputTokens: 320, temperature: 0.2 })).trim();
    const input = toolEl.querySelector('.admin-ans-input');
    if (input) input.value = out;
    if (statusEl) statusEl.textContent = 'Draft ready — review and Save.';
  } catch (e) {
    console.error('regen answer', e);
    showToast('AI error: ' + (e && e.message ? e.message : e), 'error');
    if (statusEl) statusEl.textContent = '';
  }
  if (btn) { btn.disabled = false; btn.innerHTML = orig; }
}

async function _adminAnsSave(toolEl, btn) {
  const { it, q } = _adminAnsItem(toolEl);
  if (!it || !q) return;
  const input = toolEl.querySelector('.admin-ans-input');
  const val = input ? input.value.trim() : '';
  // Update the live question block + the in-memory marking store so this session
  // marks against it immediately, then persist to the bank for everyone.
  if (it.block && it.field) it.block[it.field] = val;
  it.model = val;
  const orig = btn ? btn.innerHTML : '';
  if (btn) { btn.disabled = true; btn.innerHTML = 'Saving…'; }
  const ok = await saveQuestion(q);
  if (btn) { btn.disabled = false; btn.innerHTML = orig; }
  if (ok) {
    showToast('Model answer saved — students are now marked against it ✓', 'success');
    const cur = toolEl.querySelector('.admin-ans-current');
    if (cur) cur.innerHTML = val ? escapeHtml(val) : '<em>— none set —</em>';
    const editBox = toolEl.querySelector('.admin-ans-edit');
    if (editBox) editBox.style.display = 'none';
  }
}

// Delegated clicks for the admin answer tools (admin-only UI; no-op otherwise).
document.addEventListener('click', function (e) {
  const tool = e.target.closest && e.target.closest('.admin-ans-tool');
  if (!tool) return;
  if (e.target.closest('[data-aedit]'))   { e.preventDefault(); _adminAnsOpenEditor(tool); return; }
  if (e.target.closest('[data-aregen]'))  { e.preventDefault(); _adminAnsRegen(tool, e.target.closest('[data-aregen]')); return; }
  if (e.target.closest('[data-acancel]')) { e.preventDefault(); const b = tool.querySelector('.admin-ans-edit'); if (b) b.style.display = 'none'; return; }
  if (e.target.closest('[data-asave]'))   { e.preventDefault(); _adminAnsSave(tool, e.target.closest('[data-asave]')); return; }
});

// Generic open-ended body for ANY practice surface (Practice / Quick / Topical).
// Records each textarea's expected (model) answer in _openItemsStore[containerSel].
// markCfg ({ scoreElId, scorePrefix, mode, onAllMarked }) tells the per-part
// Check answer buttons where to show the running score and what to do once every
// part of the question has been marked.
function buildOpenBody(q, containerSel, markCfg) {
  const items = [];
  const mcqItems = [];
  const fbBlocks = [];
  const isAnnot = !!(q && q.annotation);
  let annotCount = 0;
  // Blocks are grouped into visual PARTS: a run of question content (text,
  // pictures, tables) followed by its answer area(s). A new part starts at the
  // first text block AFTER an answer area, so a multi-part question reads as
  // clean separated cards instead of a wall of "QUESTION / YOUR ANSWER" chips.
  const sections = [];
  let cur = null;
  const sec = () => { if (!cur) { cur = { html: '', hasAnswer: false }; sections.push(cur); } return cur; };
  const add = h => { sec().html += h; };
  const addAnswer = h => { const s = sec(); s.html += h; s.hasAnswer = true; };
  // Official part labels, when the question has them. `pLab` is the label to
  // hang on this block's answer boxes — it travels into `items[].label`, which
  // is what the AI marking prompt names each answer by ("Part: [(b) Claim]"),
  // so labelling here is what stops the marker matching an answer to the wrong
  // sub-question.
  const partsOn = qHasParts(q.blocks);
  const pMap = partsOn ? qPartMap(q.blocks) : null;
  const pOf = b => (partsOn && qPartOf(pMap, b)) ? qPartLabel(qPartOf(pMap, b)) : '';
  q.blocks.forEach(block => {
    const pLab = pOf(block);
    switch (block.type) {
      case 'mcq':
        addAnswer(
          renderImportedBlockStudent(block, q) +
          _partActionsHtml(containerSel, 'mcq', block.id) +
          `<div class="mcq-feedback" data-mcq-fb="${block.id}" style="margin:2px 0 4px;"></div>`
        );
        mcqItems.push({
          blockId: block.id,
          options: (block.options || []).map((o, idx) => ({ letter: String(idx + 1), text: stripHtml(o.text || ''), id: o.id, correct: block.correctId === o.id }))
        });
        break;
      case 'text':
        // An official part label starts a new card outright; otherwise fall
        // back to the old heuristic (a text block after an answer area).
        if (cur && (cur.hasAnswer || qBlockOpensPart(block))) cur = null;
        // The part sits BESIDE the question, not above it: a label on its own
        // line costs a whole row of vertical space on every part of every
        // question, and the marker belongs in front of the words it labels.
        add(_qpTextHtml(qBlockOpensPart(block), block.content));
        break;
      case 'part':
        // The legacy part BLOCK. It used to fall through to `default:`, which
        // never reset the card, so a question authored with real part blocks
        // rendered as one undivided wall. It opens a part like any other
        // opener now, and its own label is not repeated under the tag.
        if (cur) cur = null;
        add(_qpTextHtml(qBlockOpensPart(block) || String(block.label || ''), block.content));
        break;
      case 'image':
        if (block.url) {
          // Only images the admin marked as annotatable get the pen & label
          // pad — reference pictures render plain even on annotation questions.
          if (isAnnot && block.annotate !== false) { add(annotationPadHtml(block, q, containerSel)); annotCount++; }
          else add(`<div style="margin:12px 0;"><img src="${escapeHtml(transformImageUrl(block.url))}" onerror="handleImgError(this)" loading="eager" decoding="async" fetchpriority="high" style="${imgSizeStyle(block)};border-radius:8px;border:1px solid var(--border);"></div>`);
        }
        break;
      case 'answer':
        addAnswer(
          _openSection(items, 'Claim', stripHtml(block.claim || ''), 'var(--accent-blue-light)', 'var(--accent-blue)', containerSel, { block, field: 'claim' }, pLab) +
          _openSection(items, 'Evidence', stripHtml(block.evidence || ''), 'var(--accent-orange-light)', 'var(--accent-orange)', containerSel, { block, field: 'evidence' }, pLab) +
          _openSection(items, 'Reasoning', stripHtml(block.reasoning || ''), 'var(--primary-light)', 'var(--primary)', containerSel, { block, field: 'reasoning' }, pLab)
        );
        break;
      case 'plainanswer':
        addAnswer(_openSection(items, '', stripHtml(block.content || ''), '', '', containerSel, { block, field: 'content' }, pLab));
        break;
      case 'openLines':
      case 'workingSpace':
        // Annotation working area: a blank pen-and-label pad for annotating the
        // question above, AI-marked against the block's answer key.
        if (block.type === 'workingSpace' && block.annotate) {
          addAnswer(annotationPadHtml(block, q, containerSel));
          annotCount++;
          break;
        }
        // Open-ended mode: just a writing box (no lines). Reads any stored model
        // answer so an admin-set answer persists across renders.
        addAnswer(_openSection(items, '', stripHtml(block.content || ''), '', '', containerSel, { block, field: 'content' }, pLab));
        break;
      case 'fillblank': {
        const parts = _fbParse(block.text || '');
        const hasBlank = parts.some(p => p.type === 'blank');
        if (!hasBlank) { add(`<div class="fb-sentence" style="line-height:2;margin:8px 0;">${parts.map(p => escapeHtml(p.text)).join('')}</div>`); break; }
        const oidxs = [], answers = [];
        let sentence = '';
        parts.forEach(p => {
          if (p.type === 'text') { sentence += escapeHtml(p.text); return; }
          const oidx = items.length;
          items.push({ label: [pOf(block), 'Blank ' + (oidxs.length + 1)].filter(Boolean).join(' '), model: p.answer, block, field: 'text' });
          oidxs.push(oidx); answers.push(p.answer);
          const w = Math.max(6, Math.min(22, (p.answer || '').length + 3));
          sentence += `<input class="fb-input" data-oidx="${oidx}" type="text" autocomplete="off" spellcheck="false" aria-label="blank" style="width:${w}ch;">`;
        });
        fbBlocks.push({ blockId: block.id, oidxs, answers });
        addAnswer(
          `<div class="fb-sentence" style="line-height:2.4;margin-bottom:10px;">${sentence}</div>` +
          `<div class="fb-actions" style="display:flex;gap:8px;flex-wrap:wrap;align-items:center;margin-bottom:4px;">
            <button type="button" class="btn btn-check" data-fb-check="${containerSel}" data-fb-block="${block.id}" style="padding:6px 14px;font-size:0.82rem;">✓ Check answers</button>
          </div>
          <div class="fb-feedback" data-fb-fb="${block.id}" style="margin:2px 0 4px;"></div>`
        );
        break;
      }
      case 'explanation':
      case 'widget':
        break; // hidden until the student has answered (see showExplanation)
      case 'video':
        if (block.url) {
          const embedUrl = getYouTubeEmbedUrl(block.url);
          if (embedUrl) add(`<div class="video-embed"><iframe src="${embedUrl}" allowfullscreen></iframe></div>`);
        }
        break;
      case 'table':
        add(renderTableReadonly(block, ''));
        break;
      default:
        add(renderImportedBlockStudent(block, q));
        break;
    }
  });
  // Single-part questions render plain (no extra frame); multi-part questions
  // get one softly-bordered card per part so the structure is obvious.
  const solo = sections.length <= 1;
  let html = sections.map(s => `<div class="qp-part${solo ? ' solo' : ''}">${s.html}</div>`).join('');
  const fbItemCount = fbBlocks.reduce((s, b) => s + b.oidxs.length, 0);
  if (annotCount) {
    // Each annotation pad carries its own Check / AI Check bar; just add the
    // how-to hint once at the end instead of the photo bar / "nothing" note.
    html += `<div class="dgn-hint">✍️ Annotate each diagram / working area — use <strong>✏️ Pen</strong> to draw ticks, crosses, lines or circles and <strong>🔤 Label</strong> to type labels — then use the check buttons under it.</div>`;
  } else if (items.length === 0 && mcqItems.length === 0) {
    html += `<div style="padding:12px;color:var(--text-muted);font-size:0.9rem;">This question has no answer section for the AI to mark.</div>`;
  } else if (items.length - fbItemCount === 0 && mcqItems.length === 0) {
    // Fill-in-the-blank only — each block carries its own Check button, so the
    // "photo of your written work" bar would just be noise here.
  } else {
    html += openPhotoBarHtml(containerSel);
  }
  _openItemsStore[containerSel] = items;
  _openMcqStore[containerSel] = mcqItems;
  _fbStore[containerSel] = fbBlocks;
  _openQStore[containerSel] = q;
  _openSurfaceCfg[containerSel] = markCfg || {};
  _openPartResults[containerSel] = {};
  _annotPadScores[containerSel] = {};
  _openFinalized[containerSel] = false;
  _openPhoto[containerSel] = null; // fresh render — drop any previous photo
  if (annotCount) _scheduleAnnotInit(containerSel);
  return html;
}

// =====================================================================
// DIAGRAM ANNOTATION — tick & label questions. The student draws on the
// diagram (pen), drops text-box labels, then Check (reveal answer) or AI
// Check (flatten the annotated image and send it to Gemini for marking).
// Strokes are stored in NORMALISED [0..1] coords so they survive resize;
// text boxes are positioned in % so they scale with the image.
// =====================================================================
const _annotPads = {}; // padId -> live pad state

function _annotPadId(containerSel, blockId) {
  return 'ap_' + _openPhotoKey(containerSel) + '_' + String(blockId).replace(/[^a-z0-9]/gi, '');
}

// Blank white "canvas" for annotation working areas — served as an inline SVG
// image so the whole pad machinery (sizing, strokes, flatten-to-JPEG export
// for the AI) works unchanged, exactly as if it were a diagram picture.
function _workingPadSvgUrl(lines) {
  const h = Math.max(3, Math.min(40, Number(lines) || 6)) * 40; // on a 1000-wide canvas
  return 'data:image/svg+xml;charset=utf-8,' + encodeURIComponent(
    `<svg xmlns="http://www.w3.org/2000/svg" width="1000" height="${h}"><rect width="1000" height="${h}" fill="#ffffff"/></svg>`);
}

// The image (or blank working area) + drawing/text overlay + its toolbar.
function annotationPadHtml(block, q, containerSel) {
  const pid = _annotPadId(containerSel, block.id);
  const isWorking = block.type === 'workingSpace';
  const src = isWorking ? _workingPadSvgUrl(block.lines) : escapeHtml(transformImageUrl(block.url));
  const label = String(block.dgnLabel || '').trim() || (isWorking ? 'Working area' : '');
  const swatch = (color, name) => `<button type="button" class="dgn-swatch${color === '#e11d48' ? ' active' : ''}" data-dgn-color="${pid}" data-color="${color}" style="background:${color};" title="${name}"></button>`;
  return `<div class="dgn-wrap">
      <div class="dgn-toolbar" data-dgn-tb="${pid}">
        ${label ? `<span class="dgn-badge">📍 ${escapeHtml(label)}</span>` : ''}
        <button type="button" class="dgn-tool active" data-dgn-tool="${pid}" data-tool="pen" title="Draw / tick with a pen">✏️ Pen</button>
        <button type="button" class="dgn-tool" data-dgn-tool="${pid}" data-tool="text" title="Add a text label — then click on the diagram">🔤 Label</button>
        <button type="button" class="dgn-tool" data-dgn-tool="${pid}" data-tool="erase" title="Erase pen strokes">🩹 Erase</button>
        <span class="dgn-divider"></span>
        ${swatch('#e11d48', 'Red')}${swatch('#2d6ca8', 'Blue')}${swatch('#16a34a', 'Green')}${swatch('#111827', 'Black')}
        <span class="dgn-divider"></span>
        <button type="button" class="dgn-tool" data-dgn-undo="${pid}" title="Undo the last mark">↶ Undo</button>
        <button type="button" class="dgn-tool" data-dgn-clear="${pid}" title="Clear all annotations">🗑 Clear</button>
      </div>
      <div class="dgn-pad" data-annot="${pid}" data-dgn-block="${escapeHtml(String(block.id))}" id="${pid}"${label ? ` data-dgn-name="${escapeHtml(label)}"` : ''}>
        <img id="${pid}_img" src="${src}" onerror="handleImgError(this)" alt="${isWorking ? 'working area to annotate' : 'diagram to annotate'}">
        <canvas id="${pid}_cv"></canvas>
        <div class="dgn-textlayer" id="${pid}_tl"></div>
      </div>
      <div class="dgn-actions" style="margin-top:10px;">
        <button type="button" class="btn btn-check" data-dgn-aicheck="${containerSel}" data-dgn-pid="${pid}" style="padding:7px 14px;font-size:0.83rem;" title="Check your annotations on this diagram — the AI marks them and tells you how you did">✓ Check answer${label ? ' — ' + escapeHtml(label) : ''}</button>
        <button type="button" class="btn btn-outline" data-dgn-check="${containerSel}" data-dgn-pid="${pid}" style="padding:7px 14px;font-size:0.83rem;" title="Show the model answer without marking your work">👁 Show model answer</button>
      </div>
      <div class="dgn-feedback" data-dgn-fb-pad="${pid}" style="margin-top:6px;"></div>
    </div>`;
}

// buildOpenBody returns a string that the caller injects with innerHTML, so we
// initialise the live pads on the next frame once that DOM exists.
function _scheduleAnnotInit(containerSel) {
  const run = () => { try { initAnnotationPadsIn(containerSel); } catch (e) { console.warn('annot init', e); } };
  if (typeof requestAnimationFrame === 'function') requestAnimationFrame(run);
  setTimeout(run, 80);
}
function initAnnotationPadsIn(containerSel) {
  const c = document.querySelector(containerSel);
  if (!c) return;
  c.querySelectorAll('.dgn-pad[data-annot]').forEach(el => _initAnnotPad(el.getAttribute('data-annot')));
  _annotLinkifyDiagramRefs(c, containerSel);
}

function _initAnnotPad(pid) {
  const pad = document.getElementById(pid);
  if (!pad || pad._annotReady) return;
  const canvas = document.getElementById(pid + '_cv');
  const img = document.getElementById(pid + '_img');
  const tl = document.getElementById(pid + '_tl');
  if (!canvas || !img || !tl) return;
  const st = _annotPads[pid] = _annotPads[pid] || { id: pid, tool: 'pen', color: '#e11d48', size: 3, strokes: [] };
  st.canvas = canvas; st.ctx = canvas.getContext('2d'); st.img = img; st.tl = tl; st.pad = pad;
  st.blockUrl = img.currentSrc || img.src;
  pad._annotReady = true;

  const resize = () => _annotResize(pid);
  if (img.complete && img.naturalWidth) resize();
  img.addEventListener('load', resize);
  if (window.ResizeObserver) { try { st.ro = new ResizeObserver(resize); st.ro.observe(pad); } catch (_) {} }
  else window.addEventListener('resize', resize);

  canvas.addEventListener('pointerdown', e => _annotPointerDown(pid, e));
  canvas.addEventListener('pointermove', e => _annotPointerMove(pid, e));
  canvas.addEventListener('pointerup', e => _annotPointerUp(pid, e));
  canvas.addEventListener('pointercancel', e => _annotPointerUp(pid, e));
  canvas.addEventListener('pointerleave', e => { const s = _annotPads[pid]; if (s && s.erasing) s.erasing = false; });
  // Click on empty text layer (Label tool active) drops a new text box.
  tl.addEventListener('pointerdown', e => { const s = _annotPads[pid]; if (s && s.tool === 'text' && e.target === tl) _annotAddText(pid, e); });

  _annotSyncPointerEvents(pid);
}

function _annotResize(pid) {
  const st = _annotPads[pid];
  if (!st || !st.pad) return;
  const rect = st.pad.getBoundingClientRect();
  const w = Math.max(1, Math.round(rect.width)), h = Math.max(1, Math.round(rect.height));
  const dpr = Math.min(window.devicePixelRatio || 1, 2);
  st.canvas.width = Math.round(w * dpr);
  st.canvas.height = Math.round(h * dpr);
  st.canvas.style.width = w + 'px';
  st.canvas.style.height = h + 'px';
  st.ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
  st.cssW = w; st.cssH = h;
  _annotRedraw(pid);
}

function _annotDrawStroke(ctx, s, w, h) {
  if (!s || !s.pts || !s.pts.length) return;
  ctx.strokeStyle = s.color || '#e11d48';
  ctx.lineWidth = s.size || 3;
  ctx.beginPath();
  s.pts.forEach((p, i) => { const x = p.x * w, y = p.y * h; if (i === 0) ctx.moveTo(x, y); else ctx.lineTo(x, y); });
  if (s.pts.length === 1) { const p = s.pts[0]; ctx.lineTo(p.x * w + 0.1, p.y * h + 0.1); }
  ctx.stroke();
}
function _annotRedraw(pid) {
  const st = _annotPads[pid];
  if (!st || !st.ctx) return;
  const w = st.cssW || 0, h = st.cssH || 0;
  st.ctx.clearRect(0, 0, w, h);
  st.ctx.lineJoin = 'round'; st.ctx.lineCap = 'round';
  st.strokes.forEach(s => _annotDrawStroke(st.ctx, s, w, h));
  if (st.cur) _annotDrawStroke(st.ctx, st.cur, w, h);
}

function _annotNormPt(st, e) {
  const r = st.canvas.getBoundingClientRect();
  return { x: (e.clientX - r.left) / (r.width || 1), y: (e.clientY - r.top) / (r.height || 1) };
}
function _annotPointerDown(pid, e) {
  const st = _annotPads[pid];
  if (!st || st.tool === 'text') return;
  e.preventDefault();
  try { st.canvas.setPointerCapture(e.pointerId); } catch (_) {}
  if (st.tool === 'erase') { st.erasing = true; _annotEraseAt(pid, _annotNormPt(st, e)); return; }
  st.drawing = true;
  st.cur = { color: st.color, size: st.size, pts: [_annotNormPt(st, e)] };
}
function _annotPointerMove(pid, e) {
  const st = _annotPads[pid];
  if (!st) return;
  if (st.tool === 'erase' && st.erasing) { _annotEraseAt(pid, _annotNormPt(st, e)); return; }
  if (!st.drawing || !st.cur) return;
  st.cur.pts.push(_annotNormPt(st, e));
  _annotRedraw(pid);
}
function _annotPointerUp(pid, e) {
  const st = _annotPads[pid];
  if (!st) return;
  if (st.erasing) { st.erasing = false; return; }
  if (st.drawing && st.cur) {
    if (st.cur.pts && st.cur.pts.length) st.strokes.push(st.cur);
    st.cur = null; st.drawing = false;
    _annotRedraw(pid);
  }
}
function _annotEraseAt(pid, p) {
  const st = _annotPads[pid];
  if (!st) return;
  const th = 0.035;
  const before = st.strokes.length;
  st.strokes = st.strokes.filter(s => !s.pts.some(q => Math.hypot(q.x - p.x, q.y - p.y) < th));
  if (st.strokes.length !== before) _annotRedraw(pid);
}

function _annotAddText(pid, e) {
  const st = _annotPads[pid];
  if (!st) return;
  const r = st.tl.getBoundingClientRect();
  const x = ((e.clientX - r.left) / (r.width || 1)) * 100;
  const y = ((e.clientY - r.top) / (r.height || 1)) * 100;
  // The box itself is NOT contenteditable — an editable box whose only
  // children are the non-editable ✥/× handles gets no caret in Chrome/Safari,
  // so typing goes nowhere. The text lives in an inner editable span instead.
  const box = document.createElement('div');
  box.className = 'dgn-text';
  box.setAttribute('data-dgn-textbox', '1');
  box.style.left = Math.max(0, Math.min(92, x)) + '%';
  box.style.top = Math.max(0, Math.min(94, y)) + '%';
  box.style.color = st.color;
  const drag = document.createElement('div');
  drag.className = 'dgn-drag'; drag.textContent = '✥';
  const del = document.createElement('div');
  del.className = 'dgn-del'; del.textContent = '×';
  del.addEventListener('pointerdown', ev => { ev.stopPropagation(); ev.preventDefault(); box.remove(); });
  _annotBindDrag(pid, box, drag);
  const edit = document.createElement('span');
  edit.className = 'dgn-edit';
  edit.setAttribute('contenteditable', 'true');
  // An abandoned empty label is just clutter — remove it when focus leaves.
  edit.addEventListener('blur', () => setTimeout(() => {
    if (box.isConnected && !_annotTextValue(box)) box.remove();
  }, 150));
  box.appendChild(drag);
  box.appendChild(del);
  box.appendChild(edit);
  // Clicking anywhere on the box puts the caret in the text.
  box.addEventListener('pointerdown', ev => {
    if (ev.target === drag || ev.target === del) return;
    setTimeout(() => { try { edit.focus(); } catch (_) {} }, 0);
  });
  st.tl.appendChild(box);
  setTimeout(() => { try { edit.focus(); } catch (_) {} }, 0);
}
function _annotBindDrag(pid, box, handle) {
  handle.addEventListener('pointerdown', e => {
    e.preventDefault(); e.stopPropagation();
    const st = _annotPads[pid];
    if (!st) return;
    const r = st.tl.getBoundingClientRect();
    const move = ev => {
      const x = ((ev.clientX - r.left) / (r.width || 1)) * 100;
      const y = ((ev.clientY - r.top) / (r.height || 1)) * 100;
      box.style.left = Math.max(0, Math.min(96, x)) + '%';
      box.style.top = Math.max(0, Math.min(96, y)) + '%';
    };
    const up = () => { document.removeEventListener('pointermove', move); document.removeEventListener('pointerup', up); };
    document.addEventListener('pointermove', move);
    document.addEventListener('pointerup', up);
  });
}
function _annotTextValue(box) {
  const clone = box.cloneNode(true);
  clone.querySelectorAll('.dgn-drag, .dgn-del').forEach(n => n.remove());
  return (clone.textContent || '').replace(/ /g, ' ').trim();
}

function _annotSyncPointerEvents(pid) {
  const st = _annotPads[pid];
  if (!st) return;
  const drawMode = st.tool === 'pen' || st.tool === 'erase';
  st.canvas.style.pointerEvents = drawMode ? 'auto' : 'none';
  st.tl.style.pointerEvents = st.tool === 'text' ? 'auto' : 'none';
  st.canvas.style.cursor = st.tool === 'erase' ? 'cell' : (drawMode ? 'crosshair' : 'default');
  st.tl.style.cursor = st.tool === 'text' ? 'crosshair' : 'default';
}
function _dgnSetTool(pid, tool, btn) {
  const st = _annotPads[pid];
  if (!st) return;
  st.tool = tool;
  if (btn && btn.parentElement) btn.parentElement.querySelectorAll('[data-dgn-tool]').forEach(b => b.classList.toggle('active', b === btn));
  _annotSyncPointerEvents(pid);
}
function _annotSetColor(pid, color, btn) {
  const st = _annotPads[pid];
  if (!st) return;
  st.color = color;
  if (btn && btn.parentElement) btn.parentElement.querySelectorAll('[data-dgn-color]').forEach(b => b.classList.toggle('active', b === btn));
}
function _annotUndo(pid) {
  const st = _annotPads[pid];
  if (!st) return;
  if (st.strokes.length) { st.strokes.pop(); _annotRedraw(pid); return; }
  const boxes = st.tl.querySelectorAll('.dgn-text');
  if (boxes.length) boxes[boxes.length - 1].remove();
}
function _annotClear(pid) {
  const st = _annotPads[pid];
  if (!st) return;
  st.strokes = [];
  st.cur = null;
  _annotRedraw(pid);
  st.tl.querySelectorAll('.dgn-text').forEach(b => b.remove());
}

// Flatten diagram + pen strokes + text labels into a base64 JPEG for the AI.
async function _annotExportBase64(pid) {
  const st = _annotPads[pid];
  if (!st) return null;
  // Prefer a CORS-clean copy so the export canvas isn't tainted; fall back to
  // the on-screen <img> (fine for data: URLs and same-origin images).
  let source = st.img;
  try {
    const durl = await _urlToDataUrlRobust(st.blockUrl);
    source = await new Promise((res, rej) => { const im = new Image(); im.onload = () => res(im); im.onerror = () => rej(new Error('img load')); im.src = durl; });
  } catch (_) { source = st.img; }
  const nw = source.naturalWidth || source.width || st.cssW || 800;
  const nh = source.naturalHeight || source.height || st.cssH || 600;
  const maxDim = 1400;
  const scale = Math.min(1, maxDim / Math.max(nw, nh));
  const W = Math.max(1, Math.round(nw * scale)), H = Math.max(1, Math.round(nh * scale));
  const off = document.createElement('canvas');
  off.width = W; off.height = H;
  const cx = off.getContext('2d');
  cx.fillStyle = '#fff'; cx.fillRect(0, 0, W, H);
  try { cx.drawImage(source, 0, 0, W, H); } catch (_) {}
  // Pen strokes.
  cx.lineJoin = 'round'; cx.lineCap = 'round';
  const swScale = W / (st.cssW || W);
  st.strokes.forEach(s => {
    if (!s.pts || !s.pts.length) return;
    cx.strokeStyle = s.color || '#e11d48';
    cx.lineWidth = Math.max(1.5, (s.size || 3) * swScale);
    cx.beginPath();
    s.pts.forEach((p, i) => { const x = p.x * W, y = p.y * H; if (i === 0) cx.moveTo(x, y); else cx.lineTo(x, y); });
    if (s.pts.length === 1) { const p = s.pts[0]; cx.lineTo(p.x * W + 0.1, p.y * H + 0.1); }
    cx.stroke();
  });
  // Text labels.
  const padRect = st.pad.getBoundingClientRect();
  const fs = Math.max(13, Math.round(0.028 * H));
  cx.textBaseline = 'top';
  st.tl.querySelectorAll('.dgn-text').forEach(box => {
    const txt = _annotTextValue(box);
    if (!txt) return;
    const br = box.getBoundingClientRect();
    const x = ((br.left - padRect.left) / (padRect.width || 1)) * W;
    const y = ((br.top - padRect.top) / (padRect.height || 1)) * H;
    const color = box.style.color || '#111827';
    cx.font = `600 ${fs}px 'DM Sans', sans-serif`;
    txt.split(/\n/).forEach((ln, i) => {
      const ty = y + i * (fs * 1.28) + 3;
      const w = cx.measureText(ln).width;
      cx.fillStyle = 'rgba(255,255,255,0.82)';
      cx.fillRect(x, ty - 1, w + 8, fs * 1.2);
      cx.fillStyle = color;
      cx.fillText(ln, x + 4, ty);
    });
  });
  try { return off.toDataURL('image/jpeg', 0.9).split(',')[1] || null; }
  catch (e) { console.warn('annot export tainted', e); return null; }
}

// Make "Diagram 2" (etc.) mentions in the question text clickable — they
// scroll to (and flash) the matching annotation pad, so students can see
// which diagram each part refers to. Matching: the pad whose admin-set
// "Diagram label" equals the clicked text; else the only pad; else the Nth.
function _annotLinkifyDiagramRefs(c, containerSel) {
  if (c._dgnLinked) return;
  c._dgnLinked = true;
  const re = /\bDiagrams?\s*\d+[a-z]?\b/gi;
  c.querySelectorAll('.qp-qtext').forEach(el => {
    const walker = document.createTreeWalker(el, NodeFilter.SHOW_TEXT);
    const nodes = [];
    while (walker.nextNode()) {
      const n = walker.currentNode;
      re.lastIndex = 0;
      if (re.test(n.nodeValue)) nodes.push(n);
    }
    nodes.forEach(n => {
      const s = n.nodeValue;
      const frag = document.createDocumentFragment();
      let last = 0, m;
      re.lastIndex = 0;
      while ((m = re.exec(s))) {
        frag.appendChild(document.createTextNode(s.slice(last, m.index)));
        const a = document.createElement('span');
        a.className = 'dgn-link';
        a.setAttribute('data-dgn-jump', containerSel);
        a.title = 'Show this diagram';
        a.textContent = m[0];
        frag.appendChild(a);
        last = m.index + m[0].length;
      }
      frag.appendChild(document.createTextNode(s.slice(last)));
      n.parentNode.replaceChild(frag, n);
    });
  });
}
function _annotJumpToDiagram(containerSel, name) {
  const c = document.querySelector(containerSel);
  if (!c) return;
  const pads = Array.from(c.querySelectorAll('.dgn-pad[data-annot]'));
  if (!pads.length) return;
  const norm = s => String(s || '').toLowerCase().replace(/\s+/g, ' ').trim();
  let target = pads.find(p => norm(p.getAttribute('data-dgn-name')) === norm(name));
  if (!target && pads.length === 1) target = pads[0];
  if (!target) {
    const num = parseInt((String(name).match(/\d+/) || [])[0], 10);
    if (num && num <= pads.length) target = pads[num - 1];
  }
  if (!target) target = pads[0];
  const wrap = target.closest('.dgn-wrap') || target;
  wrap.scrollIntoView({ behavior: 'smooth', block: 'center' });
  wrap.classList.remove('dgn-flash');
  void wrap.offsetWidth;
  wrap.classList.add('dgn-flash');
  setTimeout(() => wrap.classList.remove('dgn-flash'), 2400);
}

// "Check answer" — reveal the authored model answer / marking guide (self-mark).
function annotShowAnswer(containerSel, pid) {
  const q = _openQStore[containerSel];
  const cfg = _openSurfaceCfg[containerSel] || {};
  if (!q) return;
  // A pad that has its own answer — the marked-up screenshot, or the words —
  // shows THAT, right under the pad it belongs to. Falling back to the whole
  // question's model answer told a student about parts they hadn't reached.
  const padEl = pid ? document.getElementById(pid) : null;
  const padBlockId = padEl && padEl.getAttribute('data-dgn-block');
  const padBlock = padBlockId ? ((q.blocks || []).find(b => b && String(b.id) === padBlockId)) : null;
  if (padBlock && (String(padBlock.answerImg || '').trim() || stripHtml(padBlock.answerKey || '').trim())) {
    const fbPad = document.querySelector(containerSel + ' [data-dgn-fb-pad="' + pid + '"]');
    if (fbPad) {
      const words = stripHtml(padBlock.answerKey || '').trim();
      fbPad.innerHTML = `<div class="dgn-model">`
        + `<div class="dgn-model-h">✅ Model answer${padEl && padEl.getAttribute('data-dgn-name') ? ' — ' + escapeHtml(padEl.getAttribute('data-dgn-name')) : ''}</div>`
        + (padBlock.answerImg ? `<img src="${escapeHtml(transformImageUrl(padBlock.answerImg))}" onerror="handleImgError(this)" alt="model answer">` : '')
        + (words ? `<div class="dgn-model-t">${escapeHtml(words)}</div>` : '')
        + `</div>`;
      return;
    }
  }
  const model = (q.markingGuide || '').trim() || _deriveModelAnswer(q);
  const hasExp = ((q.blocks) || []).some(b => b.type === 'explanation' && stripHtml(b.content || '').trim());
  showExplanation(containerSel, q, '', cfg.scoreElId, model);
  if (!model && !hasExp) {
    const fb = document.querySelector(containerSel + ' .dgn-feedback');
    if (fb) fb.innerHTML = '<span style="color:var(--text-muted);font-size:0.85rem;">No model answer was set for this question — use 🤖 AI Check for feedback.</span>';
  }
}

// "AI Check" — flatten ONE annotated diagram and have Gemini mark it. Every
// pad has its own button + feedback; the question finalises (attempt record,
// score, Next button) once every pad in it has been checked at least once.
const _annotPadScores = {}; // containerSel -> { pid: { score, total } }
async function annotAiCheck(containerSel, pid, btn) {
  const q = _openQStore[containerSel];
  const cfg = _openSurfaceCfg[containerSel] || {};
  const c = document.querySelector(containerSel);
  if (!c || !q) return;
  if (!window.__aiReady || !window.__aiReady()) {
    showToast("AI checking isn't set up yet — add your reCAPTCHA site key in the code", 'info');
    return;
  }
  const allPids = Array.from(c.querySelectorAll('.dgn-pad[data-annot]')).map(el => el.getAttribute('data-annot'));
  if (!allPids.length) { showToast('Nothing to check on this question', 'info'); return; }
  if (!pid || !allPids.includes(pid)) pid = allPids[0];
  const st = _annotPads[pid];
  const hasMarks = st && ((st.strokes && st.strokes.length) ||
    Array.from(st.tl.querySelectorAll('.dgn-text')).some(b => _annotTextValue(b)));
  if (!hasMarks) { showToast('Annotate this first, then AI Check', 'info'); return; }
  const padEl = document.getElementById(pid);
  const padName = (padEl && padEl.getAttribute('data-dgn-name')) || '';
  // Working-area pads carry their own answer key on the block; mark against it.
  const padBlockId = padEl && padEl.getAttribute('data-dgn-block');
  const padBlock = padBlockId ? ((q.blocks || []).find(b => b && String(b.id) === padBlockId)) : null;
  const isWorkingPad = !!(padBlock && padBlock.type === 'workingSpace');
  // Both pad kinds can now carry their own answer key — the words and, more
  // usefully for a drawing, a SCREENSHOT of the correctly annotated diagram.
  const padKey = padBlock ? stripHtml(padBlock.answerKey || '').replace(/\s+/g, ' ').trim() : '';
  const padAnsImg = padBlock ? String(padBlock.answerImg || '').trim() : '';
  const fb = c.querySelector('[data-dgn-fb-pad="' + pid + '"]') || c.querySelector('.dgn-feedback');
  const scoreEl = cfg.scoreElId ? document.getElementById(cfg.scoreElId) : null;
  const orig = btn ? btn.innerHTML : '';
  if (btn) { btn.disabled = true; btn.innerHTML = 'Checking…'; }
  if (fb) fb.innerHTML = '<span style="color:var(--text-muted);font-size:0.85rem;">🤖 Reading your annotations…</span>';
  try {
    const d = await _annotExportBase64(pid);
    if (!d) throw new Error('could not read the annotated diagram (the image may block copying)');
    const media = [{ mimeType: 'image/jpeg', data: d }];
    // The marked-up answer screenshot goes in as a SECOND picture. Comparing
    // two diagrams is a far more reliable way to mark a drawing than comparing
    // a drawing against a sentence describing one.
    let hasAnsImg = false;
    if (padAnsImg) {
      const am = await _annotImgToMedia(padAnsImg);
      if (am) { media.push(am); hasAnsImg = true; }
    }
    const ctx = _questionContext(q);
    const guide = (q.markingGuide || '').trim();
    const model = _deriveModelAnswer(q);
    const multi = allPids.length > 1;
    const intro = isWorkingPad
      ? `You are a science teacher marking the WORKING AREA a student filled in for the question above it. ` +
        `The student was given a BLANK working/annotation space under the question and drew or wrote on it directly — pen strokes (ticks, crosses, arrows, sketches, diagrams, written working) and/or typed text labels. ` +
        `The attached image is that working area with everything the student drew and typed. Read it carefully and decide whether the working/annotations are correct and complete. `
      : `You are a science teacher marking a "ticking and labelling" annotation question. ` +
        `The student was shown a diagram and annotated it DIRECTLY — drawing ticks, crosses, circles or lines with a pen and/or typing text labels onto it. ` +
        `The attached image is the diagram WITH the student's annotations drawn on top. Look carefully at where the ticks/circles/lines point and read any typed labels, then decide whether each is in the right place / correct. `;
    const expected = padKey
      ? `ANSWER KEY for this ${isWorkingPad ? 'working area' : 'diagram'} — mark the student's work against it: "${padKey.slice(0, 700)}". `
      : (model ? `Expected correct answer: "${model.replace(/\s+/g, ' ').slice(0, 700)}". ` : '');
    const twoPics = hasAnsImg
      ? `TWO pictures are attached. The FIRST is the student's work. The SECOND is the CORRECT answer — the same ${isWorkingPad ? 'area' : 'diagram'} with the correct annotations already on it. Compare the first against the second and mark what the student drew and labelled. `
      : '';
    const prompt =
      intro +
      twoPics +
      (multi ? `This question has ${allPids.length} annotated areas and you are marking ONLY the ${hasAnsImg ? 'FIRST attached' : 'attached'} one${padName ? ` (called "${padName}")` : ''} — award marks only for what THIS one asks for. ` : '') +
      `${_markingPreamble(guide, q && q.topic)}\n` +
      `Question context: "${ctx}". ` +
      expected +
      `Work out how many marks the student earned out of the total available for this ${isWorkingPad ? 'working area' : 'diagram'}. ` +
      `Return ONLY JSON: {"score":<number>,"total":<number>,"verdict":"correct|partial|incorrect","feedback":"<1-2 sentences to the student: what they got right and what was wrong or missing>","modelAnswer":"<what a fully correct ${isWorkingPad ? 'working area' : 'annotated diagram'} should show>","explanation":"<2-4 sentences addressed to \\"you\\" that refer to what the student actually annotated and explain the marks>"}. ` +
      `If there are no visible annotations, return score 0 and say they haven't annotated yet.`;
    const raw = await askGeminiVision(prompt, media, { maxOutputTokens: 900, json: true });
    const parsed = _parseAIJson(raw) || {};
    let total = Number(parsed.total);
    if (!(total > 0)) total = 1;
    let score = Number(parsed.score);
    const vfromtext = String(parsed.verdict || '').toLowerCase();
    if (!isFinite(score)) score = vfromtext === 'correct' ? total : vfromtext === 'partial' ? total / 2 : 0;
    score = Math.max(0, Math.min(total, score));
    const verdict = (vfromtext || (score >= total ? 'correct' : score > 0 ? 'partial' : 'incorrect'));
    const color = verdict === 'correct' ? 'var(--primary)' : verdict === 'partial' ? 'var(--accent-orange)' : 'var(--accent-red)';
    const icon = verdict === 'correct' ? '✓' : verdict === 'partial' ? '≈' : '✗';
    if (fb) fb.innerHTML = `<div style="padding:6px 0;"><span style="color:${color};font-weight:700;text-transform:capitalize;">${icon} ${escapeHtml(verdict)}</span><span style="color:var(--text-muted);"> — ${escapeHtml(parsed.feedback || '')}</span></div>`;
    // Aggregate this pad's result with the question's other pads AND any typed
    // parts, so mixed questions (answer boxes + pads) score and finalise once.
    const store = _annotPadScores[containerSel] = _annotPadScores[containerSel] || {};
    store[pid] = { score, total };
    const agg = allPids.reduce((a, p) => store[p] ? { s: a.s + store[p].score, t: a.t + store[p].total, n: a.n + 1 } : a, { s: 0, t: 0, n: 0 });
    const typedTotal = (_openItemsStore[containerSel] || []).length + (_openMcqStore[containerSel] || []).length;
    const typedResults = _openPartResults[containerSel] || {};
    const typedMarked = Math.min(Object.keys(typedResults).length, typedTotal);
    let typedScore = 0;
    Object.values(typedResults).forEach(r => { typedScore += (r && r.pts) || 0; });
    const allChecked = agg.n >= allPids.length && typedMarked >= typedTotal;
    if (scoreEl) {
      const cs = agg.s + typedScore, ct = agg.t + typedTotal;
      const pct = Math.round((cs / (ct || 1)) * 100);
      const left = [];
      if (agg.n < allPids.length) left.push(`${agg.n}/${allPids.length} pads checked`);
      if (typedMarked < typedTotal) left.push(`${typedMarked}/${typedTotal} parts marked`);
      scoreEl.textContent = `${cfg.scorePrefix || 'AI Score'}: ${cs}/${ct} (${pct}%)` + (left.length ? ` — ${left.join(', ')}` : '');
      scoreEl.style.color = cs === ct ? 'var(--primary)' : 'var(--accent-orange)';
    }
    if (allChecked && !_openFinalized[containerSel]) {
      _openFinalized[containerSel] = true;
      const finalScore = agg.s + typedScore, finalTotal = agg.t + typedTotal;
      if (currentUser && currentUser.role === 'student') {
        addDoc(collection(db, 'questionAttempts'), {
          uid: currentUser.uid,
          email: currentUser.email,
          displayName: currentUser.name,
          questionId: q.id || '',
          questionTitle: q.title || '',
          score: finalScore,
          totalBlanks: finalTotal,
          answerHash: rpgAnswerFingerprint('annot:' + (q.id || '')),
          timestamp: Timestamp.now(),
          mode: cfg.mode || 'practice-open'
        }).catch(err => console.warn('Could not record attempt:', err));
        noteAttemptLocally(q.id, finalScore, finalTotal);
      }
      recordCerPerformance(q, finalScore, finalTotal, cfg.mode || 'practice-open', 'annotation');
      // Reveal the surface's "Next" button (Quick / Topical gate it behind this).
      if (typeof cfg.onAllMarked === 'function') cfg.onAllMarked({ score: finalScore, total: finalTotal, mistakes: [] });
    }
    if (allChecked) {
      showExplanation(containerSel, q, String(parsed.explanation || ''), cfg.scoreElId, String(parsed.modelAnswer || '') || model || guide);
    }
  } catch (err) {
    console.error('annotation AI check error:', err);
    if (fb) fb.innerHTML = '<span style="color:var(--accent-red);font-size:0.85rem;">AI check failed: ' + escapeHtml(err && err.message ? err.message : String(err)) + '</span>';
    showToast('AI check error: ' + (err && err.message ? err.message : err), 'error');
  } finally {
    if (btn) { btn.disabled = false; btn.innerHTML = orig; }
  }
}

// Delegated handlers for the annotation toolbar + Check / AI Check buttons.
document.addEventListener('click', function (e) {
  const tool = e.target.closest && e.target.closest('[data-dgn-tool]');
  if (tool) { e.preventDefault(); _dgnSetTool(tool.getAttribute('data-dgn-tool'), tool.getAttribute('data-tool'), tool); return; }
  const col = e.target.closest && e.target.closest('[data-dgn-color]');
  if (col) { e.preventDefault(); _annotSetColor(col.getAttribute('data-dgn-color'), col.getAttribute('data-color'), col); return; }
  const un = e.target.closest && e.target.closest('[data-dgn-undo]');
  if (un) { e.preventDefault(); _annotUndo(un.getAttribute('data-dgn-undo')); return; }
  const cl = e.target.closest && e.target.closest('[data-dgn-clear]');
  if (cl) { e.preventDefault(); _annotClear(cl.getAttribute('data-dgn-clear')); return; }
  const chk = e.target.closest && e.target.closest('[data-dgn-check]');
  if (chk) { e.preventDefault(); annotShowAnswer(chk.getAttribute('data-dgn-check'), chk.getAttribute('data-dgn-pid')); return; }
  const aichk = e.target.closest && e.target.closest('[data-dgn-aicheck]');
  if (aichk) { e.preventDefault(); annotAiCheck(aichk.getAttribute('data-dgn-aicheck'), aichk.getAttribute('data-dgn-pid'), aichk); return; }
  const jump = e.target.closest && e.target.closest('[data-dgn-jump]');
  if (jump) { e.preventDefault(); _annotJumpToDiagram(jump.getAttribute('data-dgn-jump'), jump.textContent); return; }
});

// =====================================================================
// FILL IN THE BLANKS — a paragraph with selected words blanked out as
// [[answer]]. Students type the missing words inline; a Check button grades
// them (exact match instantly, then the AI accepts sensible variations).
// =====================================================================
const _fbStore = {}; // containerSel -> [{ blockId, oidxs:[], answers:[] }]

// Split text into tokens, keeping [[...]] groups (even multi-word) intact.
function _fbSplitTokens(text) { const toks = []; const re = /\[\[[\s\S]+?\]\]|\S+/g; let m; while ((m = re.exec(String(text || '')))) toks.push(m[0]); return toks; }
// Parse into ordered segments of plain text and blanks (with the answer).
function _fbParse(text) {
  const parts = []; const re = /\[\[([\s\S]+?)\]\]/g; let last = 0, m; text = String(text || '');
  while ((m = re.exec(text))) { if (m.index > last) parts.push({ type: 'text', text: text.slice(last, m.index) }); parts.push({ type: 'blank', answer: (m[1] || '').trim() }); last = m.index + m[0].length; }
  if (last < text.length) parts.push({ type: 'text', text: text.slice(last) });
  return parts;
}
function _fbHasBlanks(block) { return !!(block && block.type === 'fillblank' && /\[\[[\s\S]+?\]\]/.test(block.text || '')); }

// ---- fill-in-the-blank on PAPER --------------------------------------------
// The print builders used to fall through to renderImportedBlockStudent, whose
// `fillblank` case is _fbReadonlyHtml — a REVIEW rendering that prints each
// answer inside its slot. So every fill-in-the-blank question came off the
// printer with the answers already filled in, which makes the worksheet
// useless. On paper a blank has to be blank; the answers belong on the key.
function _fbPrintHtml(block) {
  const parts = _fbParse(block.text || '');
  if (!parts.length) return '';
  // The rule width follows the answer's length, so a one-word blank does not
  // get the same run of paper as a six-word one.
  const body = parts.map(p => p.type === 'blank'
    ? `<span class="print-blank" style="min-width:${Math.max(70, Math.min(240, (p.answer || '').length * 7 + 40))}pt;">&nbsp;</span>`
    : escapeHtml(p.text)).join('');
  return `<div class="print-text-block" style="line-height:2.4;">${body}</div>`;
}
function _fbAnswerKeyText(block) {
  const answers = _fbParse(block.text || '').filter(p => p.type === 'blank').map(p => p.answer || '');
  if (!answers.length) return '';
  return answers.map((a, i) => `${i + 1}. ${a}`).join('   ');
}

// ---- editor: clickable word chips + live student preview ----
function _fbChipsHtml(id, text) {
  const toks = _fbSplitTokens(text);
  if (!toks.length) return '<span style="font-size:0.8rem;color:var(--text-muted);">Type a sentence above, then click words here to blank them.</span>';
  return toks.map((t, i) => {
    const bm = t.match(/^\W*\[\[([\s\S]+?)\]\]\W*$/);
    const label = bm ? bm[1] : t;
    return `<span class="fb-chip${bm ? ' on' : ''}" onclick="fbToggleToken('${id}',${i})" title="${bm ? 'Click to un-blank' : 'Click to make this a blank'}">${escapeHtml(label)}</span>`;
  }).join(' ');
}
function _fbPreviewHtml(text) {
  const parts = _fbParse(text);
  if (!parts.length) return '<span style="color:var(--text-muted);font-size:0.82rem;">—</span>';
  return parts.map(p => p.type === 'blank'
    ? `<span class="fb-blank-slot" title="${escapeHtml(p.answer)}">${'&nbsp;'.repeat(Math.max(6, (p.answer || '').length + 2))}</span>`
    : escapeHtml(p.text)).join('');
}
function fbSyncChips(id) {
  const b = blocks.find(x => x.id === id); if (!b) return;
  const c = document.getElementById('fbChips_' + id); if (c) c.innerHTML = _fbChipsHtml(id, b.text || '');
  const p = document.getElementById('fbPrev_' + id); if (p) p.innerHTML = _fbPreviewHtml(b.text || '');
}
function fbToggleToken(id, idx) {
  const b = blocks.find(x => x.id === id); if (!b) return;
  const toks = _fbSplitTokens(b.text || '');
  let t = toks[idx]; if (t == null) return;
  const bm = t.match(/^(\W*)\[\[([\s\S]+?)\]\](\W*)$/);
  if (bm) t = bm[1] + bm[2] + bm[3];                                  // un-blank
  else { const wm = t.match(/^(\W*)([\s\S]*?)(\W*)$/); t = wm[1] + '[[' + wm[2] + ']]' + wm[3]; } // blank the core word
  toks[idx] = t;
  b.text = toks.join(' ');
  const ta = document.getElementById('fbText_' + id); if (ta) ta.value = b.text;
  fbSyncChips(id);
}

// ---- read-only render (previews, student view, print) ----
function _fbReadonlyHtml(block) {
  const parts = _fbParse(block.text || '');
  if (!parts.length) return '';
  const body = parts.map(p => p.type === 'blank'
    ? `<span class="fb-blank-slot" style="color:var(--primary);border-bottom:1.5px solid var(--primary);">${escapeHtml(p.answer)}</span>`
    : escapeHtml(p.text)).join('');
  return `<div class="fb-sentence" style="line-height:2;">${body}</div>`;
}

// ---- marking: exact match first, then the AI accepts variations ----
async function fbCheck(containerSel, blockId, btn) {
  const c = document.querySelector(containerSel); if (!c) return;
  const store = (_fbStore[containerSel] || []).find(x => x.blockId === blockId); if (!store) return;
  const q = _openQStore[containerSel];
  const fb = c.querySelector('[data-fb-fb="' + blockId + '"]');
  const rows = store.oidxs.map((oidx, i) => {
    const el = c.querySelector('.fb-input[data-oidx="' + oidx + '"]');
    return { oidx, i, el, model: store.answers[i] || '', student: el ? el.value.trim() : '' };
  });
  if (rows.every(r => !r.student)) { showToast('Fill in the blanks first', 'info'); return; }
  const norm = s => String(s || '').toLowerCase().replace(/[^a-z0-9\s]/g, '').replace(/\s+/g, ' ').trim();
  const pending = [];
  rows.forEach(r => { if (r.student && norm(r.student) === norm(r.model)) r.verdict = 'correct'; else if (r.student) pending.push(r); else r.verdict = 'incorrect'; });
  // Variations → AI (only the ones that don't match exactly and aren't blank).
  if (pending.length && window.__aiReady && window.__aiReady()) {
    const orig = btn ? btn.innerHTML : '';
    if (btn) { btn.disabled = true; btn.innerHTML = 'Checking…'; }
    if (fb) fb.innerHTML = '<span style="color:var(--text-muted);font-size:0.85rem;">🤖 Checking your answers…</span>';
    try {
      const ctx = q ? _questionContext(q) : '';
      const list = pending.map((r, k) => `${k}. expected="${r.model}" student="${r.student}"`).join('\n');
      const prompt =
        `You are marking fill-in-the-blank answers for a primary-school science quiz. ${_markingPreamble(q && q.markingGuide, q && q.topic)}\n` +
        `Question context: "${ctx}".\n` +
        `For EACH blank, decide whether the student's word means the same as the expected answer. ACCEPT synonyms, plurals, minor spelling slips and scientifically equivalent terms; only mark "incorrect" when the meaning is wrong. ` +
        `Return ONLY a JSON array like [{"i":0,"verdict":"correct"}]:\n${list}`;
      const raw = await askGemini(prompt, { maxOutputTokens: 300 + pending.length * 40, temperature: 0.1, json: true });
      const parsed = _parseAIJson(raw);
      const arr = Array.isArray(parsed) ? parsed : ((parsed && parsed.items) || []);
      arr.forEach(v => { if (v && typeof v.i === 'number' && pending[v.i]) pending[v.i].verdict = String(v.verdict || '').toLowerCase() === 'correct' ? 'correct' : 'incorrect'; });
    } catch (e) { console.warn('fill-blank AI mark', e); }
    if (btn) { btn.disabled = false; btn.innerHTML = orig; }
  }
  let correct = 0;
  rows.forEach(r => {
    if (!r.verdict) r.verdict = 'incorrect';
    const ok = r.verdict === 'correct'; if (ok) correct++;
    if (r.el) { r.el.style.borderColor = ok ? 'var(--primary)' : 'var(--accent-red)'; r.el.style.background = ok ? '#f0fdf4' : '#fef2f2'; }
    _setPartResult(containerSel, 'open:' + r.oidx, r.verdict, ok ? 1 : 0, r.model, r.student);
  });
  if (fb) {
    const wrong = rows.filter(r => r.verdict !== 'correct');
    fb.innerHTML = `<span style="font-weight:700;color:${correct === rows.length ? 'var(--primary)' : 'var(--accent-orange)'};">${correct} / ${rows.length} correct</span>` +
      (wrong.length ? `<span style="color:var(--text-muted);font-size:0.85rem;"> — correct answer${wrong.length === 1 ? '' : 's'}: ${wrong.map(r => escapeHtml(r.model)).join(', ')}</span>` : ' 🎉');
  }
  _checkAllPartsMarked(containerSel);
}

// Delegated Check handler for fill-in-the-blank blocks.
document.addEventListener('click', function (e) {
  const chk = e.target.closest && e.target.closest('[data-fb-check]');
  if (chk) { e.preventDefault(); fbCheck(chk.getAttribute('data-fb-check'), chk.getAttribute('data-fb-block'), chk); }
});

// =====================================================================
// PHOTO ANSWER — one photo of the whole page of written answers, sent to the
// AI so it can read the handwriting and mark each open-ended section.
// =====================================================================
const _openPhoto = {}; // containerSel -> { dataUrl, mimeType, data, name }
// Keep underscores: the file-input "change" handler rebuilds the container
// selector as '#' + key, so the key must round-trip for ids like wsPreview_q_….
function _openPhotoKey(containerSel) { return String(containerSel || '').replace(/[^a-z0-9_]/gi, ''); }
function openPhotoBarHtml(containerSel) {
  const key = _openPhotoKey(containerSel);
  return `<div class="open-photo-bar" style="margin:6px 0 14px;padding:10px 12px;border:1px dashed var(--border);border-radius:10px;background:var(--surface-alt,#fafbfa);">
      <div style="display:flex;gap:8px;flex-wrap:wrap;align-items:center;">
        <span style="font-size:0.85rem;color:var(--text-muted);">📸 Prefer writing on paper? Submit one photo of your whole page of answers and the AI will read and mark every part at once:</span>
        <button type="button" class="btn btn-outline" style="padding:6px 12px;font-size:0.82rem;" data-openphoto-take="${containerSel}">📷 Take photo</button>
        <button type="button" class="btn btn-outline" style="padding:6px 12px;font-size:0.82rem;" data-openphoto-upload="${containerSel}">🖼️ Upload photo</button>
        <input type="file" accept="image/*" capture="environment" hidden id="openPhotoCam_${key}">
        <input type="file" accept="image/*" hidden id="openPhotoFile_${key}">
      </div>
      <div class="open-photo-preview" id="openPhotoPrev_${key}" style="margin-top:10px;"></div>
    </div>`;
}
function renderOpenPhotoPreview(containerSel) {
  const key = _openPhotoKey(containerSel);
  const el = document.getElementById('openPhotoPrev_' + key);
  if (!el) return;
  const p = _openPhoto[containerSel];
  if (!p) { el.innerHTML = ''; return; }
  el.innerHTML = `<div style="display:flex;gap:10px;align-items:center;flex-wrap:wrap;">
      <img src="${p.dataUrl}" style="width:96px;height:96px;object-fit:cover;border-radius:8px;border:1px solid var(--border);">
      <span style="font-size:0.82rem;color:var(--primary);">Photo attached — the AI can read it for a single part (✓ Check answer) or check the whole page:</span>
      <button type="button" class="btn btn-check part-ai-btn" id="openPhotoMarkBtn_${key}" data-openphoto-markall="${containerSel}" style="padding:6px 14px;font-size:0.82rem;">✓ Check all parts from photo</button>
      <button type="button" class="btn btn-outline" style="padding:4px 10px;font-size:0.8rem;" data-openphoto-remove="${containerSel}">Remove</button>
    </div>`;
}
async function attachOpenPhoto(containerSel, file) {
  if (!file) return;
  if (!file.type || !file.type.startsWith('image/')) { showToast('Please choose an image', 'error'); return; }
  if (file.size > 18 * 1024 * 1024) { showToast('Image too large (max 18 MB)', 'error'); return; }
  try {
    const dataUrl = await new Promise((res, rej) => { const r = new FileReader(); r.onload = () => res(String(r.result || '')); r.onerror = () => rej(new Error('could not read the image')); r.readAsDataURL(file); });
    const m = /^data:([^;,]+)[^,]*,(.*)$/.exec(dataUrl);
    _openPhoto[containerSel] = { dataUrl, mimeType: (m && m[1]) || file.type || 'image/jpeg', data: (m && m[2]) || '', name: file.name || 'answer photo' };
    renderOpenPhotoPreview(containerSel);
    showToast('Answer photo attached ✓', 'success');
  } catch (e) { showToast('Could not attach photo: ' + (e && e.message ? e.message : e), 'error'); }
}
document.addEventListener('click', function (e) {
  const take = e.target.closest && e.target.closest('[data-openphoto-take]');
  if (take) { e.preventDefault(); const i = document.getElementById('openPhotoCam_' + _openPhotoKey(take.getAttribute('data-openphoto-take'))); if (i) i.click(); return; }
  const up = e.target.closest && e.target.closest('[data-openphoto-upload]');
  if (up) { e.preventDefault(); const i = document.getElementById('openPhotoFile_' + _openPhotoKey(up.getAttribute('data-openphoto-upload'))); if (i) i.click(); return; }
  const rm = e.target.closest && e.target.closest('[data-openphoto-remove]');
  if (rm) { e.preventDefault(); const cs = rm.getAttribute('data-openphoto-remove'); _openPhoto[cs] = null; renderOpenPhotoPreview(cs); return; }
  const pm = e.target.closest && e.target.closest('[data-openphoto-markall]');
  if (pm) { e.preventDefault(); markAllPartsFromPhoto(pm.getAttribute('data-openphoto-markall')); return; }
  const mk = e.target.closest && e.target.closest('[data-part-mark]');
  if (mk) { e.preventDefault(); markQuestionPart(mk.getAttribute('data-part-mark'), mk.getAttribute('data-kind'), mk.getAttribute('data-pid'), mk); return; }
  const ht = e.target.closest && e.target.closest('[data-part-hint]');
  if (ht) { e.preventDefault(); hintQuestionPart(ht.getAttribute('data-part-hint'), ht.getAttribute('data-kind'), ht.getAttribute('data-pid'), ht); }
});
document.addEventListener('change', function (e) {
  const t = e.target;
  if (!t || t.tagName !== 'INPUT' || t.type !== 'file' || !/^openPhoto(Cam|File)_/.test(t.id || '')) return;
  const containerSel = '#' + t.id.replace(/^openPhoto(Cam|File)_/, '');
  const file = t.files && t.files[0];
  if (file) attachOpenPhoto(containerSel, file);
  t.value = '';
});

function renderOpenPracticeBody(q) {
  return buildOpenBody(q, '#practiceContainer', {
    scoreElId: 'practiceScoreDisplay', scorePrefix: 'AI Score', mode: 'practice-open',
    // Every fully-marked question is banked into the session so "Finish &
    // report" can summarise the whole sitting.
    onAllMarked: res => {
      practiceSessionResults.push({ title: q.title || '', topic: q.topic || '', correct: res.score, total: res.total, mistakes: res.mistakes || [] });
      const btn = document.getElementById('practiceFinishBtn');
      if (btn) btn.innerHTML = `🏁 Finish &amp; report (${practiceSessionResults.length})`;
    }
  });
}

// End the Practice Mode sitting: show the shared end-of-practice report (score
// ring, per-question breakdown, AI strengths / areas to improve).
function finishPracticeSession() {
  if (!practiceSessionResults.length) { showToast('Mark at least one question first — then finish to see the report', 'info'); return; }
  renderPracticeReport('#practiceContainer', practiceSessionResults.slice(), `
    <button class="btn btn-primary" onclick="startNewPracticeSession()">
      <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" style="width:16px;height:16px;"><polyline points="1 4 1 10 7 10"/><path d="M3.51 15a9 9 0 1 0 2.13-9.36L1 10"/></svg>
      Practice Again
    </button>`);
  practiceSessionResults = [];
}
function startNewPracticeSession() {
  practiceSessionResults = [];
  loadRandomPracticeQuestion();
}

function renderPracticeQuestion(q, student) {
  currentPracticeQ = q;

  let html = `
    <div class="practice-student-info">
      <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" style="width:16px;height:16px;"><path d="M20 21v-2a4 4 0 0 0-4-4H8a4 4 0 0 0-4 4v2"/><circle cx="12" cy="7" r="4"/></svg>
      ${escapeHtml(student.name)} &mdash; Level ${escapeHtml(student.level)}
      <span style="margin-left:auto;font-size:0.78rem;color:var(--text-muted);">Topic: ${escapeHtml(q.topic)}</span>
    </div>
    <div class="practice-card">
      <div class="practice-card-header">
        <h3>${escapeHtml(q.title)}</h3>
        <div style="display:flex;gap:6px;align-items:center;">
          <span class="qb-tag category">${escapeHtml(q.category)}</span>
          <span class="qb-tag topic">${escapeHtml(q.topic)}</span>
        </div>
      </div>
      <div class="practice-card-body">`;

  html += renderOpenPracticeBody(q);

  html += `</div>
      <div class="practice-actions">
        <div class="practice-score" id="practiceScoreDisplay"></div>
        <div style="display:flex;gap:8px;flex-wrap:wrap;justify-content:flex-end;">
          <button class="btn btn-outline" onclick="resetOpenAnswers()">
            <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" style="width:14px;height:14px;"><polyline points="1 4 1 10 7 10"/><path d="M3.51 15a9 9 0 1 0 2.13-9.36L1 10"/></svg>
            Reset
          </button>
          <button class="btn btn-outline" id="practiceFinishBtn" onclick="finishPracticeSession()" title="End this sitting and see a summary of the learning — score, question breakdown and AI strengths / areas to improve">🏁 Finish &amp; report${practiceSessionResults.length ? ' (' + practiceSessionResults.length + ')' : ''}</button>
          <button class="btn btn-primary" onclick="loadRandomPracticeQuestion()">
            Next Question &rarr;
          </button>
        </div>
      </div>
    </div>`;

  document.getElementById('practiceContainer').innerHTML = html;
}

function resetOpenAnswersIn(containerSel, scoreElId) {
  document.querySelectorAll(containerSel + ' .open-answer').forEach(a => {
    a.value = '';
    a.disabled = false;
    a.style.borderColor = 'var(--border)';
  });
  document.querySelectorAll(containerSel + ' .fb-input').forEach(a => { a.value = ''; a.disabled = false; a.style.borderColor = 'var(--border)'; a.style.background = '#fff'; });
  document.querySelectorAll(containerSel + ' .open-feedback, ' + containerSel + ' .mcq-feedback, ' + containerSel + ' .fb-feedback').forEach(fb => { fb.innerHTML = ''; });
  document.querySelectorAll(containerSel + ' .part-hint-box').forEach(h => { h.style.display = 'none'; h.innerHTML = ''; });
  document.querySelectorAll(containerSel + ' .part-ai-btn').forEach(b => { b.disabled = false; });
  document.querySelectorAll(containerSel + ' .mcq-block label').forEach(l => { l.style.background = ''; l.style.borderColor = 'var(--border)'; });
  document.querySelectorAll(containerSel + ' .mcq-block input[type="radio"]').forEach(r => { r.checked = false; });
  const c = document.querySelector(containerSel);
  if (c) c.querySelectorAll('.post-explanation').forEach(el => el.remove());
  // Wipe any diagram annotations (strokes + text labels + feedback) too.
  if (c) c.querySelectorAll('.dgn-pad[data-annot]').forEach(el => _annotClear(el.getAttribute('data-annot')));
  if (c) c.querySelectorAll('.dgn-feedback').forEach(el => { el.innerHTML = ''; });
  _openPartResults[containerSel] = {};
  _annotPadScores[containerSel] = {};
  _openFinalized[containerSel] = false;
  const scoreEl = scoreElId ? document.getElementById(scoreElId) : null;
  if (scoreEl) scoreEl.textContent = '';
}
function resetOpenAnswers() { resetOpenAnswersIn('#practiceContainer', 'practiceScoreDisplay'); }

function _questionContext(q) {
  const parts = [q.title || ''];
  // Part markers used to be characters inside the text and reached the model
  // for free. They are a field now, so they are put back — every marking, hint
  // and explanation call reads this, and "(b)" is often what makes the
  // sub-question intelligible on its own.
  const blocks = (q && q.blocks) || [];
  blocks.forEach(b => {
    if (b.type !== 'text') return;
    const opens = qBlockOpensPart(b);
    parts.push((opens ? qPartLabel(opens) + ' ' : '') + stripHtml(b.content || ''));
  });
  return parts.join(' ').replace(/\s+/g, ' ').trim().slice(0, 800);
}

// Last-resort explanation built locally, used when the AI returns nothing so
// the A.I. Explanation box is never left empty. References the verdict and the
// model answer so it still speaks to the answer the student gave.
function _fallbackExplanation(entries) {
  const verb = { correct: 'was marked correct', partial: 'was marked partially correct', incorrect: 'was marked incorrect' };
  const parts = (entries || []).map(e => {
    const v = e.verdict || 'incorrect';
    if (e.kind === 'open') {
      const tail = e.model ? ` A full-mark answer needs: ${e.model}.` : '';
      return `Your "${e.label || 'answer'}" ${verb[v] || verb.incorrect}.${v === 'correct' ? '' : tail}`;
    }
    const correct = e.mcq.options.find(o => o.correct);
    const tail = correct ? ` The correct option is ${correct.letter}) ${correct.text}.` : '';
    return `Your multiple-choice answer ${verb[v] || verb.incorrect}.${v === 'correct' ? '' : tail}`;
  }).filter(Boolean);
  if (!parts.length) return 'Compare your response with the model answers shown above to see where the key marks are.';
  return parts.join(' ');
}

// Generic AI marking for open-ended written answers (correct / partial / incorrect).
// Returns { score, total, mistakes } on success, or null if nothing was marked.
async function markOpenAnswersIn(containerSel, q, opts = {}) {
  const { btnId, scoreElId, scorePrefix = 'AI Score', mode = 'practice-open' } = opts;
  const areas = Array.from(document.querySelectorAll(containerSel + ' .open-answer'));
  const mcqList = _openMcqStore[containerSel] || [];
  if (!areas.length && !mcqList.length) { showToast('Nothing to mark in this question', 'info'); return null; }

  const items = _openItemsStore[containerSel] || [];
  const scoreEl = scoreElId ? document.getElementById(scoreElId) : null;
  const btn = btnId ? document.getElementById(btnId) : null;
  const ctx = q ? _questionContext(q) : '';
  const photo = _openPhoto[containerSel];

  // Reset visuals
  areas.forEach(a => {
    a.style.borderColor = 'var(--border)';
    const sec = a.closest('.open-answer-section');
    const fb = sec && sec.querySelector('.open-feedback');
    if (fb) fb.innerHTML = '';
  });
  mcqList.forEach(m => { const fb = document.querySelector(containerSel + ' [data-mcq-fb="' + m.blockId + '"]'); if (fb) fb.innerHTML = ''; });

  // Unified list of markable entries: open-text answers + multiple-choice.
  const entries = [];
  areas.forEach(a => {
    const it = items[parseInt(a.dataset.oidx)] || { label: 'Answer', model: '' };
    entries.push({ kind: 'open', label: it.label, model: it.model, student: a.value.trim(), areaEl: a });
  });
  mcqList.forEach(m => {
    const checked = document.querySelector(containerSel + ' input[name="mcq_' + m.blockId + '"]:checked');
    let studentLetter = '';
    if (checked) { const o = m.options.find(x => x.id === checked.value); if (o) studentLetter = o.letter; }
    entries.push({ kind: 'mcq', mcq: m, studentLetter });
  });

  // MCQs are marked LOCALLY — the correct option is already in the bank, so they
  // never need an AI call. Only OPEN answers go to the AI (plus an MCQ whose
  // choice must be read from a photo, i.e. handwritten with nothing picked on
  // screen). A pure multiple-choice question shows the bank's stored explanation.
  const hasOpen = entries.some(e => e.kind === 'open');
  const aiEntries = [];
  entries.forEach((e, i) => {
    if (e.kind === 'open') aiEntries.push({ e, i });
    else if (e.kind === 'mcq' && photo && !e.studentLetter) aiEntries.push({ e, i });
  });
  const needAi = aiEntries.length > 0;
  if (needAi && (!window.__aiReady || !window.__aiReady())) {
    showToast("AI marking isn't set up yet — add your reCAPTCHA site key in the code", 'info');
    return null;
  }

  const byI = {};
  // Deterministic marking for on-screen multiple-choice (no AI needed).
  entries.forEach((e, i) => {
    if (e.kind === 'mcq' && !(photo && !e.studentLetter)) {
      const correctOpt = e.mcq.options.find(o => o.correct);
      const ok = !!(e.studentLetter && correctOpt && e.studentLetter === correctOpt.letter);
      byI[i] = { i: i, verdict: ok ? 'correct' : 'incorrect', chosen: e.studentLetter };
    }
  });

  let aiExplanation = '';
  let aiModelAnswer = '';
  if (needAi) {
    const orig = btn ? btn.innerHTML : '';
    if (btn) { btn.disabled = true; btn.innerHTML = 'Checking…'; }
    if (scoreEl) scoreEl.textContent = 'Marking with AI…';
    try {
      const list = aiEntries.map(({ e, i }) => {
        if (e.kind === 'open') {
          return `${i}. [${e.label}] type=open expected="${e.model}" student="${e.student || (photo ? '(see attached photo)' : '(blank)')}"`;
        }
        const opts = e.mcq.options.map(o => `${o.letter}) ${o.text}`).join(' | ');
        const correct = e.mcq.options.find(o => o.correct);
        return `${i}. [Multiple choice] type=mcq options=[${opts}] correct=${correct ? correct.letter : '?'} studentSelected="${e.studentLetter || (photo ? '(read from photo)' : '(blank)')}"`;
      }).join('\n');
      const prompt =
        `You are a science teacher marking a student's answers. ` +
        `${_markingPreamble(q && q.markingGuide, q && q.topic)}\n` +
        `Question context: "${ctx}".\n` +
        (photo
          ? `The student wrote their answers on paper and attached ONE photo of the whole page. Read the photo carefully and find the student's answer for EACH item below, matching by its label and order. For a multiple-choice item, work out which option number the student chose (a circled option, a written number or letter, or a tick) from the photo when they have not selected one on screen. Ignore handwriting quality.\n`
          : ``) +
        `For each OPEN item, compare the student's answer to the expected model answer by meaning (ignore wording, grammar and spelling — focus on the science); verdict "correct", "partial" or "incorrect". ` +
        `For each MULTIPLE-CHOICE item, decide which option the student chose and mark "correct" only if it matches the correct option number, otherwise "incorrect"; also include "chosen":"<the option number the student picked, or empty>". ` +
        `Give ONE short feedback sentence (max 22 words) addressed to the student for each item. ` +
        `Provide the full correct MODEL ANSWER for the whole question as "modelAnswer" — the ideal answer a student should give (use the expected answers if provided, otherwise generate the correct answer yourself; for multiple choice state the correct option and what it says). ` +
        `Also write a clear overall EXPLANATION (2-4 sentences) addressed to "you" that is SPECIFIC to the answer the student actually gave: explain WHY their answer was marked correct, partial or incorrect — quote or refer to what they wrote, say what they got right, what was missing or wrong, and what a full-mark answer needs. Do NOT just restate the model answer or describe the question in the abstract. ` +
        `Return ONLY JSON: {"items":[{"i":0,"verdict":"correct","feedback":"...","chosen":"B"}],"modelAnswer":"...","explanation":"..."}.\n${list}`;
      let raw;
      if (photo && photo.data) {
        raw = await askGeminiVision(prompt, [{ mimeType: photo.mimeType, data: photo.data }], { maxOutputTokens: 1100 + aiEntries.length * 220, json: true });
      } else {
        raw = await askGemini(prompt, { maxOutputTokens: 1100 + aiEntries.length * 220, temperature: 0.2, json: true });
      }
      const parsed = _parseAIJson(raw);
      (Array.isArray(parsed) ? parsed : ((parsed && parsed.items) || [])).forEach(v => { if (v && typeof v.i === 'number') byI[v.i] = v; });
      aiExplanation = (parsed && !Array.isArray(parsed) && parsed.explanation) ? String(parsed.explanation) : '';
      aiModelAnswer = (parsed && !Array.isArray(parsed) && parsed.modelAnswer) ? String(parsed.modelAnswer) : '';
    } catch (e) {
      console.error('Open marking error:', e);
      showToast('AI mark error: ' + (e && e.message ? e.message : e), 'error');
      if (btn) { btn.disabled = false; btn.innerHTML = orig; }
      if (scoreEl) scoreEl.textContent = '';
      return null;
    }
    if (btn) { btn.disabled = false; btn.innerHTML = orig; }
  }

  let score = 0;
  const mistakes = [];
  entries.forEach((e, i) => {
    const v = byI[i];
    const verdict = v ? String(v.verdict || '').toLowerCase() : 'incorrect';
    e.verdict = verdict;
    const pts = verdict === 'correct' ? 1 : verdict === 'partial' ? 0.5 : 0;
    score += pts;
    const color = verdict === 'correct' ? 'var(--primary)' : verdict === 'partial' ? 'var(--accent-orange)' : 'var(--accent-red)';
    const icon = verdict === 'correct' ? '✓' : verdict === 'partial' ? '≈' : '✗';
    const fbHead = `<span style="color:${color};font-weight:600;font-size:0.85rem;text-transform:capitalize;">${icon} ${escapeHtml(verdict)}</span>` +
      `<span style="color:var(--text-muted);font-size:0.85rem;"> — ${escapeHtml(v && v.feedback ? v.feedback : '')}</span>`;
    if (e.kind === 'open') {
      if (verdict !== 'correct') mistakes.push({ expected: e.model, student: e.student });
      e.areaEl.style.borderColor = color;
      const sec = e.areaEl.closest('.open-answer-section');
      const fb = sec && sec.querySelector('.open-feedback');
      if (fb) {
        let inner = fbHead;
        if (verdict !== 'correct' && e.model) inner += `<div style="margin-top:4px;font-size:0.82rem;color:var(--primary);"><strong>Model answer:</strong> ${escapeHtml(e.model)}</div>`;
        fb.innerHTML = inner;
      }
      _setPartResult(containerSel, 'open:' + (e.areaEl.dataset.oidx || ''), verdict, pts, e.model, e.student);
    } else {
      const m = e.mcq;
      const correctOpt = m.options.find(o => o.correct);
      const chosenLetter = (v && v.chosen) ? _normMcqChoice(v.chosen) : e.studentLetter;
      e.chosenLetter = chosenLetter;
      if (verdict !== 'correct') mistakes.push({ expected: correctOpt ? (correctOpt.letter + ') ' + correctOpt.text) : '', student: chosenLetter });
      const wrap = document.querySelector(containerSel + ' .mcq-block[data-block="' + m.blockId + '"]');
      if (wrap) {
        wrap.querySelectorAll('label').forEach((lab, idx) => {
          const o = m.options[idx]; if (!o) return;
          lab.style.background = ''; lab.style.borderColor = 'var(--border)';
          if (o.correct) { lab.style.background = '#dcfce7'; lab.style.borderColor = '#16a34a'; }
          if (chosenLetter && o.letter === chosenLetter && !o.correct) { lab.style.background = '#fee2e2'; lab.style.borderColor = '#dc2626'; }
        });
      }
      const fb = document.querySelector(containerSel + ' [data-mcq-fb="' + m.blockId + '"]');
      if (fb) {
        let inner = fbHead + (chosenLetter ? `<span style="color:var(--text-muted);font-size:0.85rem;"> (you chose ${escapeHtml(chosenLetter)})</span>` : '');
        if (verdict !== 'correct' && correctOpt) inner += `<div style="margin-top:4px;font-size:0.82rem;color:var(--primary);"><strong>Correct answer:</strong> ${escapeHtml(correctOpt.letter)}) ${escapeHtml(correctOpt.text)}</div>`;
        fb.innerHTML = inner;
      }
      _setPartResult(containerSel, 'mcq:' + m.blockId, verdict, pts, correctOpt ? (correctOpt.letter + ') ' + correctOpt.text) : '', chosenLetter);
    }
  });

  const total = entries.length;
  if (scoreEl) {
    const pct = total ? Math.round((score / total) * 100) : 0;
    scoreEl.textContent = `${scorePrefix}: ${score}/${total} (${pct}%)`;
    scoreEl.style.color = score === total ? 'var(--primary)' : 'var(--accent-orange)';
  }

  // The student's written (open) answers — used to fingerprint the attempt and
  // to enforce "unique answers" for the monthly questions-done leaderboard.
  const answerText = entries.filter(e => e.kind === 'open').map(e => e.student || '').join(' ¶ ');
  if (currentUser && currentUser.role === 'student' && q) {
    addDoc(collection(db, 'questionAttempts'), {
      uid: currentUser.uid,
      email: currentUser.email,
      displayName: currentUser.name,
      questionId: q.id || '',
      questionTitle: q.title || '',
      score: score,
      totalBlanks: total,
      answerHash: rpgAnswerFingerprint(answerText),
      timestamp: Timestamp.now(),
      mode
    }).catch(err => console.warn('Could not record attempt:', err));
    noteAttemptLocally(q.id, score, total);
  }
  recordCerPerformance(q, score, total, mode, answerText);
  _openFinalized[containerSel] = true; // attempt recorded — per-part marking must not record it again

  // Force an A.I. explanation to always exist, by hook or by crook. The model
  // sometimes returns the marking items without a usable "explanation" field
  // (e.g. it replies with a bare array, or drops it when the token budget is
  // tight). When that happens, retry with a small follow-up call dedicated to
  // the explanation; if every attempt still comes back empty, fall back to an
  // explanation built locally from the model answers — so the A.I. Explanation
  // box is never empty. (MCQ-only questions skip this entirely and instead show
  // the bank's stored explanation block — see showExplanation.)
  if (hasOpen && !aiExplanation) {
    const answerLines = entries.map((e, i) => {
      const verdict = e.verdict || 'incorrect';
      if (e.kind === 'open') {
        return `${i + 1}. ${e.label || 'Answer'} — marked ${verdict}. Model answer: ${e.model || '(not provided)'}. The student wrote: "${e.student || '(blank)'}"`;
      }
      const correct = e.mcq.options.find(o => o.correct);
      return `${i + 1}. Multiple choice — marked ${verdict}. Correct answer: ${correct ? correct.letter + ') ' + correct.text : '(unknown)'}. The student chose: ${e.chosenLetter || '(blank)'}`;
    }).join('\n');
    const expPrompt =
      `You are a science teacher giving feedback to a student on the answer they just gave. ` +
      `Write a clear EXPLANATION (2-4 sentences) addressed to "you" that is SPECIFIC to the student's actual answer: ` +
      `explain WHY each answer was marked correct, partial or incorrect — refer to what they actually wrote, say what they got right, what was missing or wrong, and what a full-mark answer needs. ` +
      `Do NOT just restate the model answer or describe the question in the abstract.\n` +
      `Question context: "${ctx}".\n` +
      `Items (with the verdict, the model answer and what the student wrote):\n${answerLines}\n` +
      `Return ONLY the explanation text — no JSON, no preamble, no headings.`;
    for (let attempt = 0; attempt < 2 && !aiExplanation; attempt++) {
      try {
        const expRaw = await askGemini(expPrompt, { maxOutputTokens: 300, temperature: attempt === 0 ? 0.3 : 0.6 });
        aiExplanation = (expRaw || '').trim();
      } catch (e) {
        console.warn('Explanation follow-up failed (attempt ' + (attempt + 1) + '):', e);
      }
    }
    if (!aiExplanation) aiExplanation = _fallbackExplanation(entries);
  }

  showExplanation(containerSel, q, aiExplanation, scoreElId, aiModelAnswer);
  return { score, total, mistakes };
}

// =====================================================================
// PER-PART AI MARKING + HINTS — every answer box / MCQ gets its own
// "✓ Check answer" and "💡 Hint" buttons instead of one big per-question button.
// =====================================================================
function _setPartResult(containerSel, key, verdict, pts, expected, student) {
  (_openPartResults[containerSel] = _openPartResults[containerSel] || {})[key] = { verdict, pts, expected, student };
}

// Once a part is marked, refresh the running score; when EVERY part of the
// question has a verdict, record the attempt and hand over to the surface
// (Quick/Topical practice use this to reveal their Next button).
function _checkAllPartsMarked(containerSel) {
  const totalParts = (_openItemsStore[containerSel] || []).length + (_openMcqStore[containerSel] || []).length;
  if (!totalParts) return;
  const results = _openPartResults[containerSel] || {};
  const marked = Object.keys(results).length;
  const cfg = _openSurfaceCfg[containerSel] || {};
  const scoreEl = cfg.scoreElId ? document.getElementById(cfg.scoreElId) : null;
  let score = 0;
  const mistakes = [];
  Object.values(results).forEach(r => {
    score += r.pts || 0;
    if (r.verdict !== 'correct') mistakes.push({ expected: r.expected, student: r.student });
  });
  // Annotation pads (diagram or working-area) count as parts of this question:
  // the score combines them and the question only finalises once every pad has
  // been AI-checked too (annotAiCheck does the same from the other side).
  const cEl = document.querySelector(containerSel);
  const padPids = cEl ? Array.from(cEl.querySelectorAll('.dgn-pad[data-annot]')).map(el => el.getAttribute('data-annot')) : [];
  const padStore = _annotPadScores[containerSel] || {};
  const padAgg = padPids.reduce((a, p) => padStore[p] ? { s: a.s + padStore[p].score, t: a.t + padStore[p].total, n: a.n + 1 } : a, { s: 0, t: 0, n: 0 });
  if (marked < totalParts || padAgg.n < padPids.length) {
    if (scoreEl) {
      scoreEl.textContent = `${marked + padAgg.n} / ${totalParts + padPids.length} parts marked`;
      scoreEl.style.color = 'var(--text-muted)';
    }
    return;
  }
  const finalScore = score + padAgg.s, finalTotal = totalParts + padAgg.t;
  if (scoreEl) {
    const pct = Math.round((finalScore / (finalTotal || 1)) * 100);
    scoreEl.textContent = `${cfg.scorePrefix || 'AI Score'}: ${finalScore}/${finalTotal} (${pct}%)`;
    scoreEl.style.color = finalScore === finalTotal ? 'var(--primary)' : 'var(--accent-orange)';
  }
  if (_openFinalized[containerSel]) return;
  _openFinalized[containerSel] = true;
  const q = _openQStore[containerSel];
  const answerText = Object.values(results || {}).map(r => (r && r.student) || '').join(' ¶ ');
  if (currentUser && currentUser.role === 'student' && q) {
    addDoc(collection(db, 'questionAttempts'), {
      uid: currentUser.uid,
      email: currentUser.email,
      displayName: currentUser.name,
      questionId: q.id || '',
      questionTitle: q.title || '',
      score: finalScore,
      totalBlanks: finalTotal,
      answerHash: rpgAnswerFingerprint(answerText),
      timestamp: Timestamp.now(),
      mode: cfg.mode || 'practice-open'
    }).catch(err => console.warn('Could not record attempt:', err));
    noteAttemptLocally(q.id, finalScore, finalTotal);
    // Keep the REASONS, not just the score — this is what revision flashcards are
    // built from. Taken from `results` rather than the flattened `mistakes` above,
    // because the key is the only thing that says whether a part was an MCQ.
    fcNoteMistakes(q, Object.entries(results)
      .filter(([, r]) => r && r.verdict !== 'correct')
      .map(([key, r]) => ({ kind: String(key).startsWith('mcq:') ? 'mcq' : 'open',
                            verdict: r.verdict, expected: r.expected, student: r.student })),
      cfg.mode || 'practice-open');
  }
  recordCerPerformance(q, finalScore, finalTotal, cfg.mode || 'practice-open', answerText);
  if (typeof cfg.onAllMarked === 'function') cfg.onAllMarked({ score: finalScore, total: finalTotal, mistakes });
  // Show the "why": an A.I. explanation of the answers. The photo/bulk path makes
  // its own; the click-to-mark path (including MCQ) didn't — so generate one here.
  _genAndShowExplanation(containerSel, q, results, cfg.scoreElId);
}

// Build an answer-specific explanation from the marked parts and show it (falls
// back to the question's authored explanation block if the AI is unavailable).
async function _genAndShowExplanation(containerSel, q, results, scoreElId) {
  const entries = Object.entries(results || {});
  if (!entries.length || !q) return;
  // MCQ-only questions show the bank's stored explanation (no AI). Only generate
  // an answer-specific AI explanation when there's at least one open answer.
  const hasOpen = entries.some(([key]) => key.indexOf('open') === 0);
  let aiText = '';
  try {
    if (hasOpen && window.__aiReady && window.__aiReady()) {
      const ctx = _questionContext(q);
      const lines = entries.map(([key, r], i) => {
        const kind = key.indexOf('mcq') === 0 ? 'Multiple choice' : 'Open answer';
        return `${i + 1}. ${kind} — marked ${r.verdict}. Correct/model answer: ${r.expected || '(none)'}. The student gave: ${r.student || '(blank)'}`;
      }).join('\n');
      const prompt =
        `You are a science teacher giving feedback to a Singapore primary-school student on the question they just answered. ` +
        `Write a clear EXPLANATION (2-4 sentences) addressed to "you" that says WHY the correct answer is correct and, where the student was wrong, names the likely misconception and what to remember. Be specific to this question; do not merely restate the model answer.\n` +
        `Question: "${ctx}".\nItems:\n${lines}\n` +
        `Return ONLY the explanation text — no JSON, no preamble, no headings.`;
      aiText = (await askGemini(prompt, { maxOutputTokens: 320, temperature: 0.3 }) || '').trim();
    }
  } catch (e) { console.warn('explanation gen failed', e); }
  try { showExplanation(containerSel, q, aiText, scoreElId, ''); } catch (e) { console.warn('showExplanation', e); }
}

// Mark ONE part of the question (an open answer box or one MCQ) with the AI.
async function markQuestionPart(containerSel, kind, pid, btn) {
  const q = _openQStore[containerSel];
  const ctx = q ? _questionContext(q) : '';
  const photo = _openPhoto[containerSel];

  let areaEl = null, fbEl = null, mcq = null, correctOpt = null;
  let label = 'Answer', model = '', student = '', studentLetter = '';
  if (kind === 'open') {
    areaEl = document.querySelector(containerSel + ' .open-answer[data-oidx="' + pid + '"]');
    if (!areaEl) return;
    const it = (_openItemsStore[containerSel] || [])[parseInt(pid, 10)] || {};
    label = it.label || 'Answer';
    model = it.model || '';
    student = areaEl.value.trim();
    if (!student && !photo) { showToast('Type an answer for this part first — or attach a photo of your written work', 'info'); return; }
    const sec = areaEl.closest('.open-answer-section');
    fbEl = sec && sec.querySelector('.open-feedback');
  } else {
    mcq = (_openMcqStore[containerSel] || []).find(m => m.blockId === pid);
    if (!mcq) return;
    correctOpt = mcq.options.find(o => o.correct);
    const checked = document.querySelector(containerSel + ' input[name="mcq_' + pid + '"]:checked');
    if (checked) { const o = mcq.options.find(x => x.id === checked.value); if (o) studentLetter = o.letter; }
    if (!studentLetter && !photo) { showToast('Choose an option first — or attach a photo of your written work', 'info'); return; }
    fbEl = document.querySelector(containerSel + ' [data-mcq-fb="' + pid + '"]');
  }

  // Multiple-choice is deterministic — mark it locally (no AI) unless the choice
  // has to be read from a photo.
  if (kind === 'mcq' && !photo) {
    const verdict = (studentLetter && correctOpt && studentLetter === correctOpt.letter) ? 'correct' : 'incorrect';
    const pts = verdict === 'correct' ? 1 : 0;
    const color = verdict === 'correct' ? 'var(--primary)' : 'var(--accent-red)';
    const icon = verdict === 'correct' ? '✓' : '✗';
    const wrap = document.querySelector(containerSel + ' .mcq-block[data-block="' + pid + '"]');
    if (wrap) wrap.querySelectorAll('label').forEach((lab, idx) => {
      const o = mcq.options[idx]; if (!o) return;
      lab.style.background = ''; lab.style.borderColor = 'var(--border)';
      if (o.correct) { lab.style.background = '#dcfce7'; lab.style.borderColor = '#16a34a'; }
      if (studentLetter && o.letter === studentLetter && !o.correct) { lab.style.background = '#fee2e2'; lab.style.borderColor = '#dc2626'; }
    });
    if (fbEl) {
      let inner = `<span style="color:${color};font-weight:600;font-size:0.85rem;text-transform:capitalize;">${icon} ${escapeHtml(verdict)}</span>` +
        (studentLetter ? `<span style="color:var(--text-muted);font-size:0.85rem;"> (you chose ${escapeHtml(studentLetter)})</span>` : '');
      if (correctOpt) inner += `<div style="margin-top:4px;font-size:0.82rem;color:var(--primary);"><strong>Correct answer:</strong> ${escapeHtml(correctOpt.letter)}) ${escapeHtml(correctOpt.text)}</div>`;
      fbEl.innerHTML = inner;
    }
    _setPartResult(containerSel, 'mcq:' + pid, verdict, pts, correctOpt ? (correctOpt.letter + ') ' + correctOpt.text) : '', studentLetter);
    _checkAllPartsMarked(containerSel);
    return;
  }
  if (!window.__aiReady || !window.__aiReady()) {
    showToast("AI marking isn't set up yet — add your reCAPTCHA site key in the code", 'info');
    return;
  }

  const orig = btn ? btn.innerHTML : '';
  if (btn) { btn.disabled = true; btn.innerHTML = 'Checking…'; }
  if (fbEl) fbEl.innerHTML = '';

  let parsed = null;
  try {
    let item;
    if (kind === 'open') {
      item = `Part: [${label}] type=open expected="${model || '(none provided — work out the correct answer from the question context)'}" student="${student || '(see attached photo)'}"`;
    } else {
      const optsTxt = mcq.options.map(o => `${o.letter}) ${o.text}`).join(' | ');
      item = `Part: [Multiple choice] type=mcq options=[${optsTxt}] correct=${correctOpt ? correctOpt.letter : '?'} studentSelected="${studentLetter || '(read from photo)'}"`;
    }
    const prompt =
      `You are a science teacher marking ONE part of a student's answer to a question. ` +
      `${_markingPreamble(q && q.markingGuide, q && q.topic)}\n` +
      `Question context: "${ctx}".\n` +
      (photo
        ? `The student wrote their answers on paper and attached ONE photo of the whole page. Find the student's answer for THIS part in the photo, matching by its label and order${kind === 'mcq' ? ' (a circled option, a written number or letter, or a tick)' : ''}. Ignore handwriting quality.\n`
        : ``) +
      (kind === 'open'
        ? `Compare the student's answer to the expected model answer by meaning (ignore wording, grammar and spelling — focus on the science); verdict "correct", "partial" or "incorrect". `
        : `Decide which option the student chose and mark "correct" only if it matches the correct option number, otherwise "incorrect"; also include "chosen":"<the option number the student picked, or empty>". `) +
      `Give ONE short feedback sentence (max 22 words) addressed to the student. ` +
      `Provide the full correct answer for THIS part as "modelAnswer"${kind === 'mcq' ? ' (state the correct option number and what it says)' : ' (use the expected answer if provided, otherwise generate the correct answer yourself)'}. ` +
      `Return ONLY JSON: {"verdict":"correct","feedback":"...","modelAnswer":"..."${kind === 'mcq' ? ',"chosen":"2"' : ''}}.\n${item}`;
    let raw;
    if (photo && photo.data) {
      raw = await askGeminiVision(prompt, [{ mimeType: photo.mimeType, data: photo.data }], { maxOutputTokens: 500, json: true });
    } else {
      raw = await askGemini(prompt, { maxOutputTokens: 500, temperature: 0.2, json: true });
    }
    parsed = _parseAIJson(raw);
    if (Array.isArray(parsed)) parsed = parsed[0];
  } catch (e) {
    console.error('Part marking error:', e);
    showToast('AI mark error: ' + (e && e.message ? e.message : e), 'error');
  }
  if (btn) { btn.disabled = false; btn.innerHTML = orig; }
  if (!parsed || typeof parsed !== 'object') return;

  const v = String(parsed.verdict || '').toLowerCase();
  const verdict = v === 'correct' ? 'correct' : v === 'partial' ? 'partial' : 'incorrect';
  const pts = verdict === 'correct' ? 1 : verdict === 'partial' ? 0.5 : 0;
  const color = verdict === 'correct' ? 'var(--primary)' : verdict === 'partial' ? 'var(--accent-orange)' : 'var(--accent-red)';
  const icon = verdict === 'correct' ? '✓' : verdict === 'partial' ? '≈' : '✗';
  const fbHead = `<span style="color:${color};font-weight:600;font-size:0.85rem;text-transform:capitalize;">${icon} ${escapeHtml(verdict)}</span>` +
    `<span style="color:var(--text-muted);font-size:0.85rem;"> — ${escapeHtml(parsed.feedback || '')}</span>`;

  if (kind === 'open') {
    areaEl.style.borderColor = color;
    const modelShown = model || String(parsed.modelAnswer || '').trim();
    if (fbEl) {
      let inner = fbHead;
      if (modelShown) inner += `<div style="margin-top:4px;font-size:0.82rem;color:var(--primary);"><strong>Model answer:</strong> ${escapeHtml(modelShown)}</div>`;
      fbEl.innerHTML = inner;
    }
    _setPartResult(containerSel, 'open:' + pid, verdict, pts, model, student);
  } else {
    const chosenLetter = parsed.chosen ? _normMcqChoice(parsed.chosen) : studentLetter;
    const wrap = document.querySelector(containerSel + ' .mcq-block[data-block="' + pid + '"]');
    if (wrap) {
      wrap.querySelectorAll('label').forEach((lab, idx) => {
        const o = mcq.options[idx]; if (!o) return;
        lab.style.background = ''; lab.style.borderColor = 'var(--border)';
        if (o.correct) { lab.style.background = '#dcfce7'; lab.style.borderColor = '#16a34a'; }
        if (chosenLetter && o.letter === chosenLetter && !o.correct) { lab.style.background = '#fee2e2'; lab.style.borderColor = '#dc2626'; }
      });
    }
    if (fbEl) {
      let inner = fbHead + (chosenLetter ? `<span style="color:var(--text-muted);font-size:0.85rem;"> (you chose ${escapeHtml(chosenLetter)})</span>` : '');
      if (correctOpt) inner += `<div style="margin-top:4px;font-size:0.82rem;color:var(--primary);"><strong>Correct answer:</strong> ${escapeHtml(correctOpt.letter)}) ${escapeHtml(correctOpt.text)}</div>`;
      fbEl.innerHTML = inner;
    }
    _setPartResult(containerSel, 'mcq:' + pid, verdict, pts, correctOpt ? (correctOpt.letter + ') ' + correctOpt.text) : '', chosenLetter);
  }
  _checkAllPartsMarked(containerSel);
}

// Give the student a nudge on ONE part without revealing the answer.
async function hintQuestionPart(containerSel, kind, pid, btn) {
  if (!window.__aiReady || !window.__aiReady()) {
    showToast("AI hints aren't set up yet — add your reCAPTCHA site key in the code", 'info');
    return;
  }
  const q = _openQStore[containerSel];
  const ctx = q ? _questionContext(q) : '';
  const box = document.querySelector(containerSel + ' .part-hint-box[data-hint-for="' + kind + ':' + pid + '"]');

  let partDesc;
  if (kind === 'open') {
    const it = (_openItemsStore[containerSel] || [])[parseInt(pid, 10)] || {};
    partDesc = `The part the student is stuck on: "${it.label || 'Answer'}". The model answer (do NOT reveal it): "${it.model || '(none provided — infer the correct answer from the question context)'}".`;
  } else {
    const mcq = (_openMcqStore[containerSel] || []).find(m => m.blockId === pid);
    if (!mcq) return;
    const correct = mcq.options.find(o => o.correct);
    partDesc = `The part is a multiple-choice question with options: ${mcq.options.map(o => `${o.letter}) ${o.text}`).join(' | ')}. The correct option (do NOT reveal it or its number): ${correct ? correct.letter : '?'}.`;
  }

  const orig = btn ? btn.innerHTML : '';
  if (btn) { btn.disabled = true; btn.innerHTML = 'Thinking…'; }
  try {
    const prompt =
      `You are a science teacher. A student is stuck on ONE part of a question and asked for a hint.\n` +
      `Question context: "${ctx}".\n${partDesc}\n` +
      `Give ONE short hint (1-2 sentences, max 35 words) addressed to "you" that nudges the student toward the answer — point at the science concept to think about or where in the question to look. ` +
      `Do NOT state the answer, the model answer's wording, or the correct option number. Return ONLY the hint text — no preamble.`;
    const raw = await askGemini(prompt, { maxOutputTokens: 200, temperature: 0.5 });
    const hint = (raw || '').trim();
    if (box) {
      box.style.display = '';
      box.innerHTML = `<strong style="color:var(--accent-orange);">💡 Hint:</strong> ${escapeHtml(hint || 'Re-read the question and think about which science idea it is testing.')}`;
    }
    rpgNoteHintUsed(); // hint used → reduced battle damage this question
  } catch (e) {
    console.error('Hint error:', e);
    showToast('Could not get a hint: ' + (e && e.message ? e.message : e), 'error');
  }
  if (btn) { btn.disabled = false; btn.innerHTML = orig; }
}

// Whole-page marking for the photo flow: one photo covers every part, so it is
// still marked in a single AI call, then handed to the surface's completion hook.
async function markAllPartsFromPhoto(containerSel) {
  if (!_openPhoto[containerSel]) { showToast('Attach a photo of your answers first', 'info'); return; }
  const cfg = _openSurfaceCfg[containerSel] || {};
  const alreadyFinalized = !!_openFinalized[containerSel];
  const res = await markOpenAnswersIn(containerSel, _openQStore[containerSel], {
    btnId: 'openPhotoMarkBtn_' + _openPhotoKey(containerSel),
    scoreElId: cfg.scoreElId, scorePrefix: cfg.scorePrefix || 'AI Score', mode: cfg.mode || 'practice-open'
  });
  if (!res) return null;
  if (!alreadyFinalized && typeof cfg.onAllMarked === 'function') cfg.onAllMarked(res);
  return res;
}

// =====================================================================
// SNAP & MARK (student): photograph a question + handwritten answer, find the
// matching bank question, then mark the answer from the SAME photo. Reuses the
// open-question marking engine (buildOpenBody + _openPhoto + markAllPartsFromPhoto),
// so per-part feedback, the score, the A.I. explanation and progress recording
// all come for free.
// =====================================================================
let _snapPhotos = [];  // [{ dataUrl, mimeType, data, name }] — photos and/or PDF pages, marked one by one
const SNAP_MAX_PHOTOS = 20;
// The current marking run. Marking carries on in the BACKGROUND if the student
// leaves the page (the page is only hidden, the async loop keeps going); when
// every photo is done an overview + AI report is built from these items.
// items[i] = { name, status: 'marked'|'unmatched'|'error', title, topic, score, total, mistakes }
let _snapRun = null;

const _SNAP_STOP = new Set('the a an of to in on for and or is are was were be been which what why how does do did with as at by from this that these those it its their his her them they you your we our not can will would should could than then so if'.split(' '));
function _snapTokens(s) {
  return new Set(String(s || '').toLowerCase().replace(/[^a-z0-9\s]/g, ' ').split(/\s+/).filter(w => w.length > 2 && !_SNAP_STOP.has(w)));
}
// Compact "what is being asked" text for a question — question / part / MCQ-option
// text only (NOT the model answer), used for AI matching and the fallback ranking.
function _snapCandidateText(q) {
  const bits = [];
  (q.blocks || []).forEach(b => {
    if (!b || !b.type) return;
    if (b.type === 'text') bits.push(stripHtmlToText(b.content));
    else if (b.type === 'part') { bits.push(b.label || ''); bits.push(stripHtmlToText(b.content)); }
    else if (b.type === 'mcq') (b.options || []).forEach(o => bits.push(stripHtmlToText(o.text)));
    else if (b.type === 'image' && b.caption) bits.push(stripHtmlToText(b.caption));
  });
  return bits.join(' ').replace(/\s+/g, ' ').trim();
}
function _snapSim(aSet, q) {
  const b = _snapTokens(_snapCandidateText(q) + ' ' + (q.title || ''));
  if (!aSet.size || !b.size) return 0;
  let inter = 0; aSet.forEach(t => { if (b.has(t)) inter++; });
  return inter / Math.min(aSet.size, b.size); // overlap coefficient
}

function setSnapStatus(msg, busy) {
  const el = document.getElementById('snapStatus');
  if (!el) return;
  el.innerHTML = msg ? (busy ? '⏳ ' : '') + escapeHtml(msg) : '';
}
function renderSnapPreview() {
  const el = document.getElementById('snapPreview');
  if (!el) return;
  if (!_snapPhotos.length) { el.innerHTML = ''; return; }
  const thumbs = _snapPhotos.map((p, i) => `
      <div style="position:relative;display:inline-block;">
        <img src="${p.dataUrl}" title="${escapeHtml(p.name || '')}" style="width:110px;height:110px;object-fit:cover;border-radius:10px;border:1px solid var(--border);display:block;">
        <button type="button" onclick="snapRemovePhoto(${i})" title="Remove this photo" style="position:absolute;top:-7px;right:-7px;width:22px;height:22px;border-radius:50%;border:none;background:var(--accent-red,#c0392b);color:#fff;font-size:12px;line-height:1;cursor:pointer;box-shadow:0 1px 4px rgba(0,0,0,0.25);">✕</button>
        <div style="position:absolute;left:4px;bottom:4px;background:rgba(0,0,0,0.55);color:#fff;font-size:0.68rem;font-weight:700;border-radius:6px;padding:1px 7px;">${i + 1}</div>
      </div>`).join('');
  const n = _snapPhotos.length;
  el.innerHTML = `<div style="display:flex;flex-direction:column;gap:14px;align-items:center;">
      <div style="display:flex;gap:12px;flex-wrap:wrap;justify-content:center;">${thumbs}</div>
      <div style="display:flex;gap:8px;flex-wrap:wrap;justify-content:center;">
        <button class="btn btn-primary" onclick="snapFindAndMark()">🔎 Find &amp; mark ${n === 1 ? 'this' : 'all ' + n}</button>
        <button class="btn btn-outline" onclick="document.getElementById('snapCam').click()">📸 Snap another</button>
        <button class="btn btn-outline" onclick="document.getElementById('snapFile').click()">🖼️ Upload</button>
        <button class="btn btn-outline" onclick="snapClearPhoto()">Remove all</button>
      </div>
    </div>`;
}
function _snapPushPhoto(p) {
  if (_snapPhotos.length >= SNAP_MAX_PHOTOS) return false;
  _snapPhotos.push(p);
  return true;
}
// Accept any mix of images and PDFs; every PDF page becomes one photo entry.
async function snapHandleFiles(files) {
  const list = Array.from(files || []);
  if (!list.length) return;
  let overflow = false;
  try {
    for (const file of list) {
      const isPdf = (file.type === 'application/pdf') || /\.pdf$/i.test(file.name || '');
      if (isPdf) {
        if (file.size > 40 * 1024 * 1024) { showToast('PDF too large (max 40 MB)', 'error'); continue; }
        setSnapStatus('Reading ' + (file.name || 'your PDF') + '…', true);
        const pages = await _pdfToPageImages(file, (p, total) => setSnapStatus('Reading ' + (file.name || 'PDF') + ' — page ' + p + ' of ' + total + '…', true));
        for (let i = 0; i < pages.length; i++) {
          const pg = pages[i];
          if (!_snapPushPhoto({ dataUrl: 'data:' + pg.mimeType + ';base64,' + pg.data, mimeType: pg.mimeType, data: pg.data, name: (file.name || 'PDF') + ' — page ' + (i + 1) })) { overflow = true; break; }
        }
      } else {
        if (!file.type || !file.type.startsWith('image/')) { showToast('"' + (file.name || 'file') + '" is not an image or PDF', 'error'); continue; }
        if (file.size > 18 * 1024 * 1024) { showToast('"' + (file.name || 'image') + '" is too large (max 18 MB)', 'error'); continue; }
        const dataUrl = await new Promise((res, rej) => { const r = new FileReader(); r.onload = () => res(String(r.result || '')); r.onerror = () => rej(new Error('could not read the image')); r.readAsDataURL(file); });
        const m = /^data:([^;,]+)[^,]*,(.*)$/.exec(dataUrl);
        if (!_snapPushPhoto({ dataUrl, mimeType: (m && m[1]) || file.type || 'image/jpeg', data: (m && m[2]) || '', name: file.name || 'photo' })) overflow = true;
      }
      if (overflow) break;
    }
    if (overflow) showToast('Keeping the first ' + SNAP_MAX_PHOTOS + ' photos/pages — mark these first, then add the rest', 'info');
    const r = document.getElementById('snapResult'); if (r) r.innerHTML = '';
    setSnapStatus('', false);
    renderSnapPreview();
  } catch (e) {
    setSnapStatus('', false);
    showToast('Could not read the file: ' + (e && e.message ? e.message : e), 'error');
  } finally {
    // allow re-picking the same file(s)
    const c = document.getElementById('snapCam'), f = document.getElementById('snapFile');
    if (c) c.value = ''; if (f) f.value = '';
  }
}
function snapRemovePhoto(i) {
  _snapPhotos.splice(i, 1);
  renderSnapPreview();
}
function snapClearPhoto() {
  _snapPhotos = []; renderSnapPreview(); setSnapStatus('', false);
  const c = document.getElementById('snapCam'), f = document.getElementById('snapFile');
  if (c) c.value = ''; if (f) f.value = '';
}
function snapReset() {
  const r = document.getElementById('snapResult'); if (r) r.innerHTML = '';
  const rep = document.getElementById('snapReport'); if (rep) rep.innerHTML = '';
  _snapRun = null;
  // Drop the per-section photo attachments from the previous run.
  Object.keys(_openPhoto).forEach(k => { if (k.startsWith('#snapItem_')) delete _openPhoto[k]; });
  snapClearPhoto();
}
function snapInit() {
  // A run in progress — or finished results and their report — survives leaving
  // the page: never wipe them on re-entry. "Mark another set" / "Remove all"
  // are how the student starts fresh.
  if (_snapRun && (_snapRun.active || _snapRun.items.some(Boolean))) return;
  if (_snapPhotos.length) return; // photos staged but not yet marked
  snapReset();
}

async function snapFindAndMark() {
  if (!_snapPhotos.length) { showToast('Take or upload a photo first', 'info'); return; }
  if (_snapRun && _snapRun.active) { showToast('Already marking — hang on, your report is on its way', 'info'); return; }
  if (!window.__aiReady || !window.__aiReady()) { showToast("AI isn't ready yet — try again in a moment", 'info'); return; }
  if (!questionBank.length) { showToast('No practice questions are loaded yet', 'info'); return; }

  const host = document.getElementById('snapResult');
  if (host) host.innerHTML = '';
  const rep = document.getElementById('snapReport');
  if (rep) rep.innerHTML = '';
  _snapRun = { active: true, total: _snapPhotos.length, items: [] };
  const cand = questionBank.map((q, i) =>
    `${i}\t${(q.title || '').slice(0, 70)} | ${q.topic || ''} | ${_snapCandidateText(q).slice(0, 200)}`
  ).join('\n');
  const prompt =
    `You match a photographed exam/worksheet question to one in a question bank.\n` +
    `The photo may also contain the student's handwritten answer — IGNORE the answer; match ONLY on the question being asked (its wording, numbers, multiple-choice options, diagram).\n` +
    `Numbered question bank (index<TAB>title | topic | text):\n${cand}\n\n` +
    `Which bank question is the SAME question shown in the photo?\n` +
    `Return ONLY JSON: {"match": <index, or -1 if none clearly match>, "confidence": "high|medium|low", "questionText": "<transcribe the question from the photo as plain text>"}`;

  // Mark the photos ONE BY ONE, each into its own result section, so a long
  // stack of photos (or a whole PDF) is checked in a single go.
  const total = _snapPhotos.length;
  for (let i = 0; i < total; i++) {
    const item = document.createElement('div');
    item.id = 'snapItem_' + i;
    if (host) host.appendChild(item);
    const label = total > 1 ? (`Photo ${i + 1} of ${total}` + (_snapPhotos[i].name ? ` (${_snapPhotos[i].name})` : '')) : 'your photo';
    setSnapStatus(`Reading ${label} and finding the matching question…`, true);
    let data;
    try {
      const raw = await askGeminiVision(prompt, [{ mimeType: _snapPhotos[i].mimeType, data: _snapPhotos[i].data }], { maxOutputTokens: 800, json: true });
      data = _parseAIJson(raw);
    } catch (e) {
      item.innerHTML = `<div class="practice-card"><div class="practice-card-body">${total > 1 ? `<p style="margin:0 0 6px;font-weight:700;">📷 Photo ${i + 1}</p>` : ''}
          <p style="color:var(--accent-red,#c0392b);font-size:0.9rem;margin:0;">Could not read this photo — try a clearer picture. (${escapeHtml((e && e.message ? e.message : String(e)).slice(0, 200))})</p>
        </div></div>`;
      _snapRecordItem(i, { status: 'error' });
      continue;
    }
    const idx = Number.isInteger(data && data.match) ? data.match : -1;
    const conf = String((data && data.confidence) || '').toLowerCase();
    if (idx >= 0 && idx < questionBank.length && conf !== 'low') {
      if (total > 1) setSnapStatus(`Marking ${label}…`, true);
      await snapMarkQuestion(questionBank[idx], i);
    } else {
      snapShowSuggestions(String((data && data.questionText) || ''), i);
    }
  }
  if (_snapRun) _snapRun.active = false;
  setSnapStatus(total > 1 ? `Done — checked all ${total} photos. Review your report and each result below.` : '', false);
  snapRenderReport();
  // The student may have gone off to another page while we marked — tell them.
  const smPage = document.getElementById('page-snapmark');
  if (smPage && !smPage.classList.contains('active')) {
    showToast(`📸 Snap & Mark is done — all ${total} photo${total === 1 ? '' : 's'} marked. Open Snap & Mark for your report.`, 'success');
  }
}

// Record the outcome for photo i in the current run; if the run has already
// finished (e.g. the student picked a suggested match afterwards), refresh the
// report so it always reflects what's on screen.
function _snapRecordItem(i, entry) {
  if (!_snapRun) return;
  _snapRun.items[i] = Object.assign({ name: (_snapPhotos[i] && _snapPhotos[i].name) || ('Photo ' + (i + 1)) }, entry);
  if (!_snapRun.active) snapRenderReport();
}

// Overview of the whole run + a short AI-written report. The overview renders
// instantly from the recorded scores; the AI summary streams in after.
function snapRenderReport() {
  const host = document.getElementById('snapReport');
  if (!host || !_snapRun) return;
  const items = _snapRun.items;
  const present = items.filter(Boolean);
  if (present.length < 2) { host.innerHTML = ''; return; }
  const marked = present.filter(x => x.status === 'marked' && x.total);
  const sum = marked.reduce((a, x) => ({ s: a.s + (x.score || 0), t: a.t + (x.total || 0) }), { s: 0, t: 0 });
  const pct = sum.t ? Math.round((sum.s / sum.t) * 100) : 0;
  const rows = items.map((x, i) => {
    if (!x) return '';
    let right, main;
    if (x.status === 'marked' && x.total) {
      const p = Math.round(((x.score || 0) / x.total) * 100);
      const bg = p >= 80 ? '#e7f3ec' : p >= 50 ? '#fff3e0' : '#fdecec';
      const fg = p >= 80 ? '#1c8a4a' : p >= 50 ? '#b8741a' : '#c0392b';
      right = `<span style="flex-shrink:0;font-weight:700;font-size:0.8rem;background:${bg};color:${fg};border-radius:999px;padding:3px 11px;white-space:nowrap;">${x.score}/${x.total} · ${p}%</span>`;
      main = `<strong>${escapeHtml(x.title || 'Question')}</strong>${x.topic ? `<span style="color:var(--text-muted);"> — ${escapeHtml(x.topic)}</span>` : ''}`;
    } else if (x.status === 'unmatched') {
      right = `<span style="flex-shrink:0;font-size:0.8rem;color:var(--text-muted);">not matched</span>`;
      main = `<span style="color:var(--text-muted);">No matching question found — pick one of the suggestions below</span>`;
    } else {
      right = `<span style="flex-shrink:0;font-size:0.8rem;color:var(--accent-red,#c0392b);">unreadable</span>`;
      main = `<span style="color:var(--text-muted);">Could not read this photo</span>`;
    }
    return `<div style="display:flex;align-items:center;gap:12px;padding:10px 0;border-top:1px solid var(--border);font-size:0.88rem;line-height:1.5;">
        <span style="flex-shrink:0;width:26px;height:26px;border-radius:8px;background:var(--surface-alt,#f4f2ee);display:flex;align-items:center;justify-content:center;font-weight:700;font-size:0.76rem;">${i + 1}</span>
        <div style="flex:1;min-width:0;">${main}</div>${right}
      </div>`;
  }).join('');
  host.innerHTML = `<div class="practice-card" style="max-width:680px;margin:0 auto;">
      <div class="practice-card-body" style="padding:22px 24px;">
        <h3 style="margin:0 0 6px;">📋 Overall report</h3>
        <p style="color:var(--text-muted);font-size:0.86rem;margin:0 0 14px;line-height:1.6;">${present.length} photo${present.length === 1 ? '' : 's'} checked · ${marked.length} question${marked.length === 1 ? '' : 's'} marked${sum.t ? ` · combined score <strong style="color:${pct >= 80 ? 'var(--primary)' : 'var(--accent-orange)'};">${sum.s}/${sum.t} (${pct}%)</strong>` : ''}</p>
        <div id="snapReportSummary" style="padding:14px 16px;border-radius:10px;background:var(--surface-alt,#fafbfa);border:1px solid var(--border);font-size:0.9rem;line-height:1.65;margin-bottom:6px;">${marked.length ? '⏳ Writing your summary…' : 'No questions could be marked this run — try clearer photos of the full question and your answer.'}</div>
        <div style="margin-top:12px;">${rows}</div>
      </div>
    </div>`;
  if (marked.length) _snapWriteSummary(items);
}

let _snapSummarySeq = 0;
async function _snapWriteSummary(items) {
  const seq = ++_snapSummarySeq;
  const lines = items.map((x, i) => {
    if (!x) return '';
    if (x.status !== 'marked' || !x.total) return `${i + 1}. ${x.name} — ${x.status === 'unmatched' ? 'no matching question found' : 'photo could not be read'}`;
    const miss = (x.mistakes || []).map(m => `expected "${String(m.expected || '').slice(0, 90)}" but the student wrote "${String(m.student || '').slice(0, 90)}"`).join('; ');
    return `${i + 1}. ${x.title} (topic: ${x.topic || 'unknown'}) — scored ${x.score}/${x.total}${miss ? `. Mistakes: ${miss}` : '. All parts correct'}`;
  }).filter(Boolean).join('\n');
  const prompt =
    `You are a science teacher writing a short end-of-session report for a primary school student who just photographed and had ${items.filter(Boolean).length} questions marked.\n` +
    `Per-question results:\n${lines}\n\n` +
    `Write 3-6 sentences addressed to "you": overall how they did, what they clearly understand (name the topics), the common weaknesses or misconceptions you can see in their mistakes, and ONE concrete thing to revise or practise next. ` +
    `Be encouraging but honest and specific — refer to the actual topics and mistakes above. Return ONLY the report text, no headings, no JSON.`;
  let txt = '';
  try {
    txt = String(await askGemini(prompt, { maxOutputTokens: 420, temperature: 0.3 }) || '').trim();
  } catch (e) { console.warn('Snap report summary failed:', e); }
  if (seq !== _snapSummarySeq) return; // a newer report superseded this one
  const el = document.getElementById('snapReportSummary');
  if (el) el.innerHTML = txt ? `<strong>🧑‍🏫 Teacher's summary:</strong> ${escapeHtml(txt)}` : 'Summary unavailable — review the per-question feedback below.';
}

function snapShowSuggestions(questionText, photoIdx) {
  const i = Number.isInteger(photoIdx) ? photoIdx : 0;
  _snapRecordItem(i, { status: 'unmatched' });
  const host = document.getElementById('snapItem_' + i) || document.getElementById('snapResult');
  if (!host) return;
  if (_snapPhotos.length <= 1) setSnapStatus('', false);
  const label = _snapPhotos.length > 1 ? `<p style="margin:0 0 6px;font-weight:700;">📷 Photo ${i + 1}${_snapPhotos[i] && _snapPhotos[i].name ? ' — ' + escapeHtml(_snapPhotos[i].name) : ''}</p>` : '';
  const aSet = _snapTokens(questionText);
  const ranked = questionBank.map(q => ({ q, s: _snapSim(aSet, q) }))
    .sort((a, b) => b.s - a.s).filter(x => x.s > 0.12).slice(0, 3);
  if (!ranked.length) {
    host.innerHTML = `<div class="practice-card"><div class="practice-card-body">${label}
        <p style="margin:0 0 6px;font-weight:600;">No matching question found</p>
        <p style="color:var(--text-muted);font-size:0.9rem;margin:0;">We couldn't match this photo to a question in your practice bank. Try a clearer photo of the full question, or use Quick Practice.</p>
        ${questionText ? `<div style="margin-top:10px;font-size:0.85rem;color:var(--text-muted);"><strong>What we read:</strong> ${escapeHtml(questionText.slice(0, 300))}</div>` : ''}
      </div></div>`;
    return;
  }
  host.innerHTML = `<div class="practice-card"><div class="practice-card-body">${label}
      <p style="margin:0 0 10px;font-weight:600;">We weren't completely sure — did you mean one of these?</p>
      ${ranked.map(x => `<button class="btn btn-outline" style="display:block;width:100%;text-align:left;margin-bottom:8px;" onclick="snapMarkById('${x.q.id}', ${i})">
          <strong>${escapeHtml(x.q.title || 'Question')}</strong><span style="color:var(--text-muted);font-size:0.82rem;"> — ${escapeHtml(x.q.topic || '')}</span>
        </button>`).join('')}
      <button class="btn btn-outline" style="margin-top:2px;font-size:0.82rem;" onclick="snapReset()">None of these — start over</button>
    </div></div>`;
}
function snapMarkById(id, photoIdx) {
  const q = questionBank.find(x => x.id === id);
  if (q) snapMarkQuestion(q, photoIdx);
}

async function snapMarkQuestion(q, photoIdx) {
  const i = Number.isInteger(photoIdx) ? photoIdx : 0;
  // Each photo marks into its own section so many photos / PDF pages can all
  // be checked in one go without overwriting each other.
  let host = document.getElementById('snapItem_' + i);
  if (!host) {
    const res = document.getElementById('snapResult');
    if (!res) return;
    host = document.createElement('div');
    host.id = 'snapItem_' + i;
    res.appendChild(host);
  }
  const sel = '#snapItem_' + i;
  const photo = _snapPhotos[i];
  if (!photo) { showToast('Take or upload a photo first', 'info'); return; }
  const many = _snapPhotos.length > 1;
  const qLevel = getTopicLevel(q.topic || '');
  let html = `<div class="practice-card"${many ? ' style="margin-bottom:18px;"' : ''}>
      <div class="practice-card-header">
        <h3>${many ? '📷 ' + (i + 1) + ' · ' : ''}${escapeHtml(q.title || 'Question')}</h3>
        <div style="display:flex;gap:6px;align-items:center;flex-wrap:wrap;">
          <span class="qp-level-badge">${escapeHtml(qLevel)}</span>
          <span class="qb-tag category">${escapeHtml(normalizeCategoryValue(q.category))}</span>
          <span class="qb-tag topic">${escapeHtml(q.topic || '')}</span>
          ${qSecondaryTagsHtml(q)}
        </div>
      </div>
      <div class="practice-card-body">
        <div id="snapMatchNote_${i}" style="margin-bottom:12px;padding:8px 12px;border-radius:8px;background:var(--primary-light);color:var(--primary);font-size:0.88rem;">✓ Matched from your photo — reading your answer and marking…</div>`;
  html += buildOpenBody(q, sel, { scoreElId: 'snapScore_' + i, scorePrefix: 'Score', mode: 'snapmark-open' });
  html += `</div>
      <div class="practice-actions">
        <div class="practice-score" id="snapScore_${i}"></div>
        <div style="display:flex;gap:8px;flex-wrap:wrap;justify-content:flex-end;">
          <button class="flag-question-btn" onclick="openFlagDialog('${q.id}','${escapeHtml(q.title || '').replace(/'/g, "\\'")}')">
            <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" style="width:12px;height:12px;"><path d="M4 15s1-1 4-1 5 2 8 2 4-1 4-1V3s-1 1-4 1-5-2-8-2-4 1-4 1z"/><line x1="4" y1="22" x2="4" y2="15"/></svg>
            Flag
          </button>
          <button class="btn btn-outline" onclick="snapReset()">📸 Mark another set</button>
        </div>
      </div>
    </div>`;
  host.innerHTML = html;
  if (!many) setSnapStatus('', false);
  if (i === 0) { try { host.scrollIntoView({ behavior: 'smooth', block: 'start' }); } catch (e) {} }
  // Attach THIS photo to this result section, then auto-mark every part.
  _openPhoto[sel] = Object.assign({}, photo);
  renderOpenPhotoPreview(sel);
  const res = await markAllPartsFromPhoto(sel);
  _snapRecordItem(i, {
    status: 'marked', title: q.title || 'Question', topic: q.topic || '',
    score: res ? res.score : 0, total: res ? res.total : 0,
    mistakes: res && Array.isArray(res.mistakes) ? res.mistakes.slice(0, 4) : []
  });
  // Work marked from a photo is still work they got wrong — it feeds the same
  // revision deck. markOpenAnswersIn's mistakes carry no part kind, so they are
  // logged as written answers, which is what a photographed worksheet is.
  if (res && Array.isArray(res.mistakes)) {
    fcNoteMistakes(q, res.mistakes.map(m => ({ kind: 'open', verdict: 'incorrect', expected: m.expected, student: m.student })), 'snapmark-open');
  }
  const note = document.getElementById('snapMatchNote_' + i);
  if (note) note.innerHTML = "✓ Matched from your photo. Here's your feedback — review each part below.";
}

// =====================================================================
// STUDENT WORKSHEET CREATOR
// =====================================================================
let wsSelectedIds = new Set();
let wsManualBreaks = new Set(); // question ids forced to start a new page (preview + print)
let wsMergeUp = new Set();       // question ids forced to stay on the previous page
let savedWorksheets = [];

function populateWsTopicFilter() {
  const sel = document.getElementById('wsFilterTopic');
  if (!sel) return;
  const topics = [...new Set(questionBank.flatMap(q => qTopicList(q)))].sort();
  sel.innerHTML = '<option value="">All Topics</option>';
  topics.forEach(t => {
    const opt = document.createElement('option');
    opt.value = t;
    opt.textContent = t;
    sel.appendChild(opt);
  });
  populateSourceFilters();
  populateWsConceptFilter();
}

// Every label a question can be filtered by here: its tags, plus the legacy
// `concepts` array. This dropdown and the quest picker's twin were both wired to
// `concepts` alone — a field nothing in the app ever wrote, so both had sat empty
// since the day they were added. Tags are the field that now carries this, so
// they feed it; `concepts` stays in the union in case anything ever set it.
function qConceptLabels(q) {
  const out = [], seen = new Set();
  qTagList(q).concat(Array.isArray(q && q.concepts) ? q.concepts : []).forEach(c => {
    const s = String(c == null ? '' : c).replace(/\s+/g, ' ').trim();
    if (!s) return;
    const k = s.toLowerCase();
    if (seen.has(k)) return;
    seen.add(k);
    out.push(s);
  });
  return out;
}
function qMatchesConceptLabel(q, lower) {
  return !lower ? true : qConceptLabels(q).some(c => c.toLowerCase() === lower);
}
// Fill the worksheet "Concept" filter from the tags on questions.
function populateWsConceptFilter() {
  const sel = document.getElementById('wsFilterConcept');
  if (!sel) return;
  const counts = new Map();
  questionBank.forEach(q => qConceptLabels(q).forEach(c => {
    const k = c.toLowerCase();
    const rec = counts.get(k) || { label: c, n: 0 };
    rec.n++; counts.set(k, rec);
  }));
  const concepts = [...counts.values()].sort((a, b) => a.label.localeCompare(b.label));
  const cur = sel.value;
  sel.innerHTML = '<option value="">All Concepts</option>';
  concepts.forEach(c => {
    const o = document.createElement('option');
    o.value = c.label; o.textContent = '🏷 ' + c.label + ' (' + c.n + ')';
    sel.appendChild(o);
  });
  if (cur && concepts.some(c => c.label === cur)) sel.value = cur;
}

function renderWsQuestions() {
  const grid = document.getElementById('wsQuestionGrid');
  if (!grid) return;
  const levelFilter = document.getElementById('wsFilterLevel')?.value || '';
  const topicFilter = document.getElementById('wsFilterTopic')?.value || '';
  const catFilter = document.getElementById('wsFilterCategory')?.value || '';
  const sourceFilter = document.getElementById('wsFilterSource')?.value || '';
  const formatFilter = document.getElementById('wsFilterFormat')?.value || '';
  const conceptFilter = (document.getElementById('wsFilterConcept')?.value || '').toLowerCase();
  const searchRaw = (document.getElementById('wsSearch')?.value || '').trim().toLowerCase();

  let filtered = questionBank.filter(q => {
    if (topicFilter && !qMatchesTopic(q, topicFilter)) return false;
    if (catFilter && !qMatchesCategory(q, catFilter)) return false;
    if (sourceFilter && questionSource(q) !== sourceFilter) return false;
    if (formatFilter === 'mcq' && !qpHasMcq(q)) return false;
    if (formatFilter === 'written' && !qpHasWritten(q)) return false;
    if (!qMatchesConceptLabel(q, conceptFilter)) return false;
    const qLevel = getTopicLevel(q.topic || '');
    if (levelFilter && qLevel !== levelFilter) return false;
    if (searchRaw) {
      const haystack = extractQuestionSearchText(q);
      if (!haystack.includes(searchRaw)) return false;
    }
    return true;
  });

  if (filtered.length === 0) {
    grid.innerHTML = `<div class="empty-state">
      <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" style="width:48px;height:48px;opacity:0.4;margin-bottom:12px;"><path d="M4 19.5A2.5 2.5 0 0 1 6.5 17H20"/><path d="M6.5 2H20v20H6.5A2.5 2.5 0 0 1 4 19.5v-15A2.5 2.5 0 0 1 6.5 2z"/></svg>
      <h3>No questions found</h3>
      <p>Try adjusting your filters</p>
    </div>`;
    return;
  }

  grid.innerHTML = filtered.map(q => {
    const checked = wsSelectedIds.has(q.id);
    const qLevel = getTopicLevel(q.topic || '');
    const qCategory = normalizeCategoryValue(q.category);
    const previewText = getQuestionPreview(q);
    const qSource = questionSource(q);
    return `<div class="ws-q-card${checked ? ' selected' : ''}" data-qid="${q.id}" onclick="onWsCardClick('${q.id}', event)" style="cursor:pointer;">
      <div class="ws-q-top">
        <input type="checkbox" ${checked ? 'checked' : ''} onchange="toggleWsQuestion('${q.id}', this.checked)">
        <div class="ws-q-info">
          <div class="ws-q-title">${escapeHtml(q.title)}</div>
          <div class="ws-q-meta">
            <span class="qb-tag category">${escapeHtml(qCategory)}</span>
            <span class="qb-tag topic">${escapeHtml(q.topic)}</span>
            ${qSecondaryTagsHtml(q)}
            <span class="qb-tag">${escapeHtml(qLevel)}</span>
            ${qSource ? `<span class="qb-tag source" title="${escapeHtml(qSource)}">${escapeHtml(qSource)}</span>` : ''}
          </div>
        </div>
        <button class="ws-q-expand-btn" onclick="event.stopPropagation();toggleWsPreview('${q.id}', this)" title="Preview question">
          <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><polyline points="6 9 12 15 18 9"/></svg>
        </button>
      </div>
      <div class="ws-q-preview" id="wsPreview_${q.id}"></div>
    </div>`;
  }).join('');
  updateWsCount();
}

function toggleWsPreview(qId, btn) {
  const previewEl = document.getElementById('wsPreview_' + qId);
  if (!previewEl) return;
  const isOpen = previewEl.classList.contains('open');
  if (isOpen) {
    previewEl.classList.remove('open');
    btn.classList.remove('expanded');
  } else {
    // Render preview content on first open
    if (!previewEl.dataset.rendered) {
      previewEl.innerHTML = renderQuestionPreviewHtml(qId);
      previewEl.dataset.rendered = '1';
    }
    previewEl.classList.add('open');
    btn.classList.add('expanded');
  }
}

function renderQuestionPreviewHtml(qId) {
  const q = questionBank.find(qb => qb.id === qId);
  if (!q) return '<p>Question not found</p>';
  let html = '';
  q.blocks.forEach(block => {
    switch (block.type) {
      case 'text':
        if (block.content) html += `<div style="margin:6px 0;">${block.content}</div>`;
        break;
      case 'image':
        // Preview images (Doctor cards, past-paper hover, worksheet preview) load
        // eagerly at high priority so the diagram is visible right away.
        if (block.url) html += `<div style="margin:8px 0;"><img src="${escapeHtml(transformImageUrl(block.url))}" onerror="handleImgError(this)" loading="eager" decoding="async" fetchpriority="high" style="${imgSizeStyle(block)};border-radius:6px;"></div>`;
        break;
      case 'answer':
        html += `<div style="margin:8px 0;padding:8px 12px;background:var(--accent-blue-light);border-radius:6px;"><strong style="color:var(--accent-blue);font-size:0.78rem;">Claim:</strong> ${block.claim || '<em>empty</em>'}</div>`;
        html += `<div style="margin:8px 0;padding:8px 12px;background:var(--accent-orange-light);border-radius:6px;"><strong style="color:var(--accent-orange);font-size:0.78rem;">Evidence:</strong> ${block.evidence || '<em>empty</em>'}</div>`;
        html += `<div style="margin:8px 0;padding:8px 12px;background:var(--primary-light);border-radius:6px;"><strong style="color:var(--primary);font-size:0.78rem;">Reasoning:</strong> ${block.reasoning || '<em>empty</em>'}</div>`;
        break;
      case 'plainanswer':
        if (block.content) html += `<div style="margin:6px 0;padding:8px 12px;background:var(--surface-alt);border:1px solid var(--border);border-radius:6px;">${block.content}</div>`;
        break;
      case 'table':
        html += renderTableReadonly(block, '');
        break;
      case 'video':
        if (block.url) html += `<div style="margin:6px 0;font-style:italic;color:var(--text-muted);font-size:0.82rem;">Video: ${escapeHtml(block.url)}</div>`;
        break;
      case 'openLines':
      case 'workingSpace':
        if (block.type === 'workingSpace' && block.annotate) {
          html += `<div style="margin:8px 0;padding:8px 12px;border:1px dashed var(--border);border-radius:8px;background:var(--surface-alt,#fafbfa);font-size:0.82rem;color:var(--text-muted);">✍️ Annotation working area — students draw &amp; label here; the AI marks it${stripHtml(block.answerKey || '').trim() ? ' against the attached answer key' : ''}</div>`;
          break;
        }
        html += `<div style="margin:8px 0;padding:8px 12px;border:1px dashed var(--border);border-radius:8px;background:var(--surface-alt,#fafbfa);font-size:0.82rem;color:var(--text-muted);">✍️ Open-ended answer space (${Number(block.lines) || (block.type === 'openLines' ? 4 : 6)} lines)</div>`;
        break;
      case 'explanation':
        break;
      default:
        html += renderImportedBlockStudent(block);
        break;
    }
  });
  if (!html) return '<p style="color:var(--text-muted);font-style:italic;">No content</p>';
  if (questionHasMarkableAnswer(q)) {
    html += `<div style="margin-top:12px;padding-top:10px;border-top:1px dashed var(--border);">
      <button class="btn btn-outline" style="padding:6px 14px;font-size:0.84rem;" onclick="wsPreviewTryIt('${qId}')">✍️ Answer it yourself — AI marks it</button>
    </div>`;
  }
  return html;
}

function questionHasMarkableAnswer(q) {
  // Annotation (tick & label) questions are markable via AI Check as long as
  // they carry a diagram to annotate.
  if (q && q.annotation && ((q.blocks) || []).some(b => b && b.type === 'image' && b.url)) return true;
  // A fill-in-the-blank block counts only once it actually has blanks marked.
  if (((q && q.blocks) || []).some(b => _fbHasBlanks(b))) return true;
  return ((q && q.blocks) || []).some(b => b && ['answer', 'plainanswer', 'openLines', 'workingSpace', 'mcq'].includes(b.type));
}

// Switch a worksheet-builder preview card into "try it" mode: the same
// open-ended answer boxes students get in practice, plus AI marking.
function wsPreviewTryIt(qId) {
  const q = questionBank.find(qb => qb.id === qId);
  const el = document.getElementById('wsPreview_' + qId);
  if (!q || !el) return;
  el.innerHTML =
    `<div style="margin-bottom:8px;font-size:0.8rem;color:var(--text-muted);">✍️ Type your answers below — each part has its own 💡 Hint and ✓ Check answer buttons, exactly like practice mode.</div>` +
    buildOpenBody(q, '#wsPreview_' + qId, {
      scoreElId: 'wsPrevScore_' + qId, scorePrefix: 'AI Score', mode: 'preview'
    }) +
    `<div style="display:flex;gap:10px;align-items:center;flex-wrap:wrap;margin-top:8px;">
      <span id="wsPrevScore_${qId}" style="font-weight:600;font-size:0.9rem;"></span>
      <button class="btn btn-outline" style="padding:7px 12px;font-size:0.82rem;margin-left:auto;" onclick="wsPreviewBack('${qId}')">↩ Back to preview</button>
    </div>`;
}

function wsPreviewBack(qId) {
  const el = document.getElementById('wsPreview_' + qId);
  if (el) el.innerHTML = renderQuestionPreviewHtml(qId);
}

function toggleWsQuestion(id, checked) {
  if (checked) wsSelectedIds.add(id);
  else wsSelectedIds.delete(id);
  const card = document.querySelector(`.ws-q-card[data-qid="${id}"]`);
  if (card) card.classList.toggle('selected', checked);
  const selectAll = document.getElementById('wsSelectAll');
  if (selectAll) selectAll.checked = wsSelectedIds.size === questionBank.length && questionBank.length > 0;
  updateWsCount();
}

function onWsCardClick(id, event) {
  // Don't toggle if clicking expand button, checkbox, or preview area
  if (event.target.closest('.ws-q-expand-btn') || event.target.closest('.ws-q-preview') || event.target.tagName === 'INPUT') return;
  const card = document.querySelector(`.ws-q-card[data-qid="${id}"]`);
  if (!card) return;
  const cb = card.querySelector('input[type="checkbox"]');
  if (cb) {
    cb.checked = !cb.checked;
    toggleWsQuestion(id, cb.checked);
  }
}

function toggleWsSelectAll(checked) {
  // Select/deselect only currently visible (filtered) questions
  const visibleCards = document.querySelectorAll('.ws-q-card');
  visibleCards.forEach(card => {
    const qid = card.dataset.qid;
    if (checked) wsSelectedIds.add(qid);
    else wsSelectedIds.delete(qid);
    card.classList.toggle('selected', checked);
    const cb = card.querySelector('input[type="checkbox"]');
    if (cb) cb.checked = checked;
  });
  updateWsCount();
}

function updateWsCount() {
  const countEl = document.getElementById('wsSelectedCount');
  if (countEl) countEl.textContent = wsSelectedIds.size + ' selected';
}

// ---- Save worksheets to Firestore ----
function _wsCol() { return collection(db, 'users', currentUser.uid, 'worksheets'); }
function _wsRef(id) { return doc(db, 'users', currentUser.uid, 'worksheets', id); }

function saveWorksheet() {
  if (wsSelectedIds.size === 0) {
    showToast('Select at least one question', 'error');
    return;
  }
  // Pre-fill from current state
  const nameInput = document.getElementById('saveWsName');
  nameInput.value = (document.getElementById('wsTitle')?.value || '').trim();
  document.getElementById('saveWsOverlay').classList.add('active');
  nameInput.focus();
}

function closeSaveWsDialog() {
  document.getElementById('saveWsOverlay').classList.remove('active');
}

async function confirmSaveWorksheet() {
  const title = (document.getElementById('saveWsName')?.value || '').trim();
  if (!title) {
    showToast('Please enter a worksheet name', 'error');
    document.getElementById('saveWsName').focus();
    return;
  }
  const ws = {
    id: 'ws_' + Date.now() + '_' + Math.random().toString(36).substr(2, 6),
    title: title,
    questionIds: Array.from(wsSelectedIds),
    format: 'open',
    createdAt: new Date().toISOString()
  };
  savedWorksheets.unshift(ws);   // newest first, the order the list is sorted in
  // Close, confirm and PERSIST before drawing anything. Redrawing a list is the
  // least important thing happening here, and it must never be able to swallow
  // the save — that is exactly how the button came to look like it did nothing.
  closeSaveWsDialog();
  if (currentUser) {
    setDoc(_wsRef(ws.id), ws).catch(err => console.error('Failed to save worksheet:', err));
  }
  showToast('Worksheet saved — find it under Saved Worksheets', 'success');
  try { renderSavedWorksheets(); } catch (e) { console.warn('saved worksheets render', e); }
}

// One stored worksheet, made safe to render. A doc written by an older build —
// or one whose write dropped a field — used to reach the renderer with no
// questionIds at all, and `ws.questionIds.length` then threw. That single bad
// row took out the WHOLE page (the grid was left untouched, so it looked empty)
// and, because the save flow re-renders before it closes the dialog, it also
// made the Save button look completely dead. Normalising here means nothing
// downstream ever has to wonder.
function _wsNormalise(ws, id) {
  if (!ws || typeof ws !== 'object') return null;
  const wsId = ws.id || id;
  if (!wsId) return null;
  return Object.assign({}, ws, {
    id: String(wsId),
    title: typeof ws.title === 'string' && ws.title.trim() ? ws.title : 'Untitled worksheet',
    questionIds: Array.isArray(ws.questionIds) ? ws.questionIds.filter(x => x != null).map(String) : [],
    createdAt: typeof ws.createdAt === 'string' ? ws.createdAt : '',
  });
}

async function loadSavedWorksheets() {
  if (!currentUser) return;
  try {
    const snap = await getDocs(_wsCol());
    savedWorksheets = [];
    snap.forEach(d => {
      const ws = _wsNormalise(d.data(), d.id);
      if (ws) savedWorksheets.push(ws);
    });
    savedWorksheets.sort((a, b) => (b.createdAt || '').localeCompare(a.createdAt || ''));
  } catch (err) {
    console.error('Failed to load worksheets:', err);
  }
}

function renderSavedWorksheets() {
  const grid = document.getElementById('savedWsGrid');
  if (!grid) return;
  if (savedWorksheets.length === 0) {
    grid.innerHTML = `<div class="empty-state">
      <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" style="width:48px;height:48px;opacity:0.4;margin-bottom:12px;"><path d="M19 21H5a2 2 0 0 1-2-2V5a2 2 0 0 1 2-2h11l5 5v11a2 2 0 0 1-2 2z"/><polyline points="17 21 17 13 7 13 7 21"/><polyline points="7 3 7 8 15 8"/></svg>
      <h3>No saved worksheets</h3>
      <p>Create a worksheet to see it here</p>
    </div>`;
    return;
  }
  grid.innerHTML = savedWorksheets.map(ws => {
    // Belt and braces on top of _wsNormalise: a row that somehow still cannot be
    // drawn is skipped, never allowed to blank the whole page.
    if (!ws || !ws.id) return '';
    const ids = Array.isArray(ws.questionIds) ? ws.questionIds : [];
    const date = ws.createdAt ? new Date(ws.createdAt).toLocaleDateString() : '';
    return `<div class="ws-saved-card">
      <div class="ws-saved-info">
        <h4>${escapeHtml(ws.title || 'Untitled worksheet')}</h4>
        <p>${ids.length} question${ids.length !== 1 ? 's' : ''}${date ? ' &middot; ' + date : ''}</p>
      </div>
      <div class="ws-saved-actions">
        <button class="btn btn-outline" onclick="previewSavedWorksheet('${ws.id}')" title="Preview the printed pages — and edit any question from there">
          <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" style="width:16px;height:16px;"><path d="M1 12s4-8 11-8 11 8 11 8-4 8-11 8-11-8-11-8z"/><circle cx="12" cy="12" r="3"/></svg>
          Preview
        </button>
        <button class="btn btn-outline" onclick="reprintWorksheet('${ws.id}')" title="Print">
          <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" style="width:16px;height:16px;"><polyline points="6 9 6 2 18 2 18 9"/><path d="M6 18H4a2 2 0 0 1-2-2v-5a2 2 0 0 1 2-2h16a2 2 0 0 1 2 2v5a2 2 0 0 1-2 2h-2"/><rect x="6" y="14" width="12" height="8"/></svg>
          Print
        </button>
        <button class="btn btn-outline" onclick="practiceSavedWorksheet('${ws.id}')" title="Practice" style="color:var(--accent-blue);border-color:var(--accent-blue);">
          <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" style="width:16px;height:16px;"><path d="M2 3h6a4 4 0 0 1 4 4v14a3 3 0 0 0-3-3H2z"/><path d="M22 3h-6a4 4 0 0 0-4 4v14a3 3 0 0 1 3-3h7z"/></svg>
          Practice
        </button>
        <button class="qb-action-btn delete-qb" onclick="deleteWorksheet('${ws.id}')" title="Delete">
          <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><polyline points="3 6 5 6 21 6"/><path d="M19 6v14a2 2 0 0 1-2 2H7a2 2 0 0 1-2-2V6m3 0V4a2 2 0 0 1 2-2h4a2 2 0 0 1 2 2v2"/></svg>
        </button>
      </div>
    </div>`;
  }).join('');
}

function deleteWorksheet(id) {
  showConfirm('Delete Worksheet', 'Are you sure you want to delete this worksheet?', () => {
    savedWorksheets = savedWorksheets.filter(ws => ws.id !== id);
    renderSavedWorksheets();
    showToast('Worksheet deleted', 'info');
    if (currentUser) {
      deleteDoc(_wsRef(id)).catch(err => console.warn('deleteWorksheet:', err));
    }
  });
}

function reprintWorksheet(id) {
  const ws = savedWorksheets.find(w => w.id === id);
  if (!ws) return;
  const selected = _wsSavedQuestions(ws);
  if (selected.length === 0) {
    showToast('Questions no longer available', 'error');
    return;
  }
  const noFields = !_wsStudentFieldsOn('saved');
  const wantCover = !!document.getElementById('mwIncludeCover')?.checked;
  doPrintStudentWorksheet(selected, ws.title, wantCover ? _wsCoverHtml(ws.title, undefined, undefined, noFields) : '', noFields);
}

// The questions of a saved worksheet, in the order they were chosen — the ids
// are stored in that order, so "Question 1" is the same question every reprint.
// (questionBank.filter() would have returned them in bank order instead.)
// Shared by reprint, preview and practice so all three show the same sheet.
function _wsSavedQuestions(ws) {
  const byId = new Map(questionBank.map(q => [String(q.id), q]));
  return (ws && Array.isArray(ws.questionIds) ? ws.questionIds : [])
    .map(qid => byId.get(String(qid))).filter(Boolean);
}

// ---- Practice worksheet questions ----
function practiceCurrentWorksheet() {
  if (wsSelectedIds.size === 0) {
    showToast('Select at least one question', 'error');
    return;
  }
  const selected = questionBank.filter(q => wsSelectedIds.has(q.id));
  if (selected.length === 0) {
    showToast('No questions available to practice', 'error');
    return;
  }
  launchWorksheetPractice(selected);
}

function practiceSavedWorksheet(id) {
  const ws = savedWorksheets.find(w => w.id === id);
  if (!ws) return;
  const ids = Array.isArray(ws.questionIds) ? ws.questionIds.map(String) : [];
  const selected = questionBank.filter(q => ids.includes(String(q.id)));
  if (selected.length === 0) {
    showToast('Questions no longer available', 'error');
    return;
  }
  launchWorksheetPractice(selected);
}

function launchWorksheetPractice(questions) {
  // Shuffle the questions
  const shuffled = [...questions];
  for (let i = shuffled.length - 1; i > 0; i--) {
    const j = Math.floor(Math.random() * (i + 1));
    [shuffled[i], shuffled[j]] = [shuffled[j], shuffled[i]];
  }
  // Reuse the Quick Practice infrastructure
  qpQueue = shuffled;
  qpIndex = -1;
  qpAnswered = 0;
  qpSessionResults = [];
  // Navigate to the Quick Practice page
  navigateTo('quickpractice');
  // Start practicing with these questions
  loadNextQpQuestion();
}

// ---- Print student worksheet with logo ----
