// Flat list of learning objectives in syllabus order, each carrying its parent
// topic/level/theme and the app topic names it maps to (for the fallback).
function _flatSyllabusLOs() {
  const out = [];
  SYLLABUS_LO_TOPICS.forEach(t => (t.los || []).forEach(lo => out.push(
    Object.assign({}, lo, { topic: t.topic, level: t.level, theme: t.theme, appTopics: t.topics || [] })
  )));
  return out;
}

// The intro banner printed above each learning objective's questions.
function _loBannerHtml(lo, count) {
  return `<div class="print-lo-banner">
    <div class="print-lo-meta">${escapeHtml(lo.level)} &middot; ${escapeHtml(lo.theme)} &middot; ${escapeHtml(lo.topic)}</div>
    <h2 class="print-lo-title">${escapeHtml(lo.title)}</h2>
    <p class="print-lo-intro">${escapeHtml(lo.intro)}</p>
    <div class="print-lo-count">${count} question${count === 1 ? '' : 's'} in this learning objective</div>
  </div>`;
}

// Fallback classifier — keyword hits (weighted) plus a small bonus when the
// question's app topic matches the objective's topic. Returns a loId or null.
function _classifyLOByKeyword(q) {
  const text = extractQuestionSearchText(q); // already lowercased
  const qTopic = (q.topic || '').toLowerCase();
  let best = null, bestScore = 0;
  _flatSyllabusLOs().forEach(lo => {
    let score = 0;
    (lo.kw || []).forEach(k => { const kk = String(k || '').toLowerCase(); if (kk && text.includes(kk)) score += 2; });
    if ((lo.appTopics || []).some(t => String(t).toLowerCase() === qTopic)) score += 1;
    if (score > bestScore) { bestScore = score; best = lo.id; }
  });
  return bestScore > 0 ? best : null;
}

// AI classifier — one batched call mapping each question index → loId.
async function _classifyLOsWithAI(selected) {
  const los = _flatSyllabusLOs();
  const objList = los.map(lo => `${lo.id} | ${lo.level} ${lo.topic} — ${lo.title}: ${lo.obj}`).join('\n');
  const qList = selected.map((q, i) => {
    const txt = extractQuestionSearchText(q).slice(0, 320);
    return `${i + 1}. [topic: ${q.topic || '?'}] ${stripHtmlToText(q.title || '')} :: ${txt}`;
  }).join('\n');
  const prompt =
    `You are sorting Singapore MOE Primary Science questions into the syllabus Learning Objectives listed below. ` +
    `For EACH question pick the SINGLE best-fitting objective id — the objective whose science content the question actually tests, not just a loosely related topic.\n\n` +
    `LEARNING OBJECTIVES (id | level topic — title: outcome):\n${objList}\n\n` +
    `QUESTIONS:\n${qList}\n\n` +
    `Return ONLY a JSON array with one entry per question, e.g. [{"n":1,"id":"heat-effects"},{"n":2,"id":"wat-states"}]. ` +
    `"id" must be exactly one of the ids above, or "other" if truly none fit.`;
  const raw = await askGemini(prompt, { maxOutputTokens: Math.min(6000, 300 + selected.length * 45), temperature: 0, json: true });
  const arr = _parseAIJson(raw);
  const valid = new Set(los.map(l => l.id));
  const map = {};
  (Array.isArray(arr) ? arr : []).forEach(e => {
    const n = parseInt(e && e.n, 10);
    const id = e && String(e.id || '');
    if (n >= 1 && n <= selected.length && valid.has(id)) map[n - 1] = id;
  });
  return map;
}

// Build & print a worksheet whose questions are grouped under syllabus learning
// objectives, each introduced by a short banner. AI classifies; a keyword/topic
// pass fills anything the AI missed; leftovers go into a final "Other" section.
async function generateSyllabusPdf() {
  if (wsSelectedIds.size === 0) { showToast('Select at least one question', 'error'); return; }
  const selected = questionBank.filter(q => wsSelectedIds.has(q.id));
  const title = (document.getElementById('wsTitle')?.value || '').trim() || 'Science Worksheet';

  _printProgressShow('Sorting by syllabus…', 'Matching your questions to learning objectives');
  let aiMap = {};
  try { aiMap = await _classifyLOsWithAI(selected); }
  catch (e) { console.warn('AI learning-objective classify failed; using keyword fallback', e); }

  const loById = {};
  _flatSyllabusLOs().forEach(lo => { loById[lo.id] = lo; });

  // Every question gets a loId: AI → keyword/topic → 'other'.
  const assign = selected.map((q, i) => aiMap[i] || _classifyLOByKeyword(q) || 'other');

  // Group, keeping syllabus order; the 'other' bucket always comes last.
  const groups = new Map();
  selected.forEach((q, i) => { const id = assign[i]; if (!groups.has(id)) groups.set(id, []); groups.get(id).push(q); });
  const order = _flatSyllabusLOs().map(l => l.id).concat(['other']);

  const orderedQs = [];
  const sectionHtmlById = {};
  const forced = new Set();
  let firstGroup = true;
  order.forEach(id => {
    const qs = groups.get(id);
    if (!qs || !qs.length) return;
    const lo = loById[id] || { level: '', theme: 'Other', topic: 'Other', title: 'Other questions',
      intro: 'Questions that did not fall neatly under a single syllabus learning objective.' };
    sectionHtmlById[qs[0].id] = _loBannerHtml(lo, qs.length);
    if (!firstGroup) forced.add('__lo__' + qs[0].id); // each objective starts a fresh page
    firstGroup = false;
    qs.forEach(q => orderedQs.push(q));
  });

  _printProgressUpdate('Laying out pages…', 0.85, 'Building your syllabus worksheet');
  const frontHtml = await _wsFrontHtml(selected, title);
  const output = document.getElementById('printOutput');
  output.innerHTML = buildWorksheetHtml(orderedQs, title, { frontHtml, sectionHtmlById, plainNumbers: true });
  autoscaleAndPrint(output, { forcedBreakIds: forced });
}

// =====================================================================
// WORKSHEET LIVE PREVIEW — renders the exact print layout in an isolated
// iframe (the @media print rules, unwrapped, apply on screen there), lets the
// teacher force a page break before any question, updates live, and prints the
// identical layout. WYSIWYG because preview + print share buildWorksheetHtml +
// packChunkIndices + the same wsManualBreaks.
// =====================================================================
(function injectWsPreviewStyles() {
  const css = `
  .wspv-overlay{ display:none; position:fixed; inset:0; z-index:400; background:#525659; flex-direction:column; }
  .wspv-overlay.show{ display:flex; }
  .wspv-bar{ display:flex; align-items:center; gap:14px; padding:10px 16px; background:var(--surface,#fff); border-bottom:1px solid var(--border,#e3e6e4); flex-wrap:wrap; }
  .wspv-bar .wspv-title{ font-weight:700; }
  .wspv-bar .wspv-count{ font-weight:500; color:var(--text-muted,#666c71); font-size:0.85rem; }
  .wspv-bar .wspv-hint{ flex:1; min-width:120px; font-size:0.8rem; color:var(--text-muted,#666c71); }
  .wspv-stage{ flex:1; overflow:hidden; }
  #wsPreviewFrame{ width:100%; height:100%; border:0; display:block; background:#525659; }
  @media print { .wspv-overlay{ display:none !important; } }`;
  const s = document.createElement('style'); s.textContent = css; document.head.appendChild(s);
})();

// Styles written INTO the preview iframe (on top of the app's print CSS).
const WS_PREVIEW_CSS = `
  html,body{ margin:0; background:#525659; }
  #wsMeasure{ position:absolute; left:-9999px; top:0; width:178mm; }
  #wsPages{ padding:22px 0; }
  .wspv-sheet{ position:relative; width:210mm; min-height:297mm; box-sizing:border-box; padding:18mm 16mm 20mm; background:#fff; margin:0 auto 20px; box-shadow:0 3px 16px rgba(0,0,0,.45); }
  .wspv-content{ position:relative; }
  .wspv-pageno{ position:absolute; left:0; right:0; bottom:7mm; text-align:center; font-size:8pt; color:#b3b3b3; }
  .print-question-chunk{ position:relative; }
  .wspv-tools{ position:absolute; top:5px; right:6px; z-index:9; display:flex; gap:6px; }
  .wspv-brk{ font:600 11px 'DM Sans',sans-serif; border:1px solid #cfcfcf; background:#fff; color:#555; border-radius:6px; padding:2px 9px; cursor:pointer; box-shadow:0 1px 3px rgba(0,0,0,.2); }
  .wspv-brk.on{ background:#0b6b4f; color:#fff; border-color:#0b6b4f; }
  .wspv-brk.up{ color:#2d6ca8; border-color:#9bb8f0; }
  .wspv-brk.up:hover{ background:#2d6ca8; color:#fff; }
  .wspv-brk.edit{ color:#8a5a00; border-color:#e6c489; }
  .wspv-brk.edit:hover{ background:#8a5a00; color:#fff; }`;

// Copy the app stylesheet but unwrap the `@media print { … }` block (balanced
// braces) so its rules apply on the iframe's screen — single source of truth,
// no duplication, and the host page's real print is untouched.
function _wsAppCssForPreview() {
  // EVERY stylesheet, not the first one. The first <style> in the document is
  // the prebuilt Tailwind reset; the app's own rules — including the whole
  // @media print block that gives a printed page its type sizes, writing-box
  // heights and page geometry — live in a later one. Taking only the first
  // meant the planner measured pages that had none of the print styling on
  // them, so every height it reported was wrong: pages were shrunk by the wrong
  // factor and footers and page numbers came to rest well short of the foot of
  // the sheet, or were pushed onto the next one.
  let css = Array.from(document.querySelectorAll('style')).map(s => s.textContent || '').join('\n');
  // Unwrap every `@media print { … }` (balanced braces) so its rules apply on
  // the iframe's screen — single source of truth, and the host page's own print
  // is untouched.
  for (let guard = 0; guard < 50; guard++) {
    const i = css.indexOf('@media print');
    if (i < 0) break;
    const open = css.indexOf('{', i);
    if (open < 0) break;
    let depth = 0, j = open;
    for (; j < css.length; j++) { const ch = css[j]; if (ch === '{') depth++; else if (ch === '}') { depth--; if (depth === 0) break; } }
    if (depth !== 0) break;
    css = css.slice(0, i) + css.slice(open + 1, j) + css.slice(j + 1);
  }
  return css;
}

// The preview normally shows what the worksheet BUILDER has selected. A saved
// worksheet reprint has no builder selection behind it, so it sets this instead
// and every read below goes through _wsPreviewCtx() — one renderer, two sources.
let _wsPreviewSaved = null;   // { id, title } of the saved worksheet on show

function _wsPreviewCtx() {
  if (_wsPreviewSaved) {
    const ws = savedWorksheets.find(w => w.id === _wsPreviewSaved.id);
    return {
      saved: true,
      selected: ws ? _wsSavedQuestions(ws) : [],
      title: (ws && ws.title) || _wsPreviewSaved.title || 'CER Worksheet',
      cover: !!document.getElementById('mwIncludeCover')?.checked,
      noFields: !_wsStudentFieldsOn('saved')
    };
  }
  return {
    saved: false,
    selected: questionBank.filter(q => wsSelectedIds.has(q.id)),
    title: (document.getElementById('wsTitle')?.value || '').trim() || 'CER Worksheet',
    cover: !!document.getElementById('wsIncludeCover')?.checked,
    noFields: !_wsStudentFieldsOn('builder')
  };
}

function openWorksheetPreview() {
  if (!wsSelectedIds.size) { showToast('Select at least one question first', 'error'); return; }
  _wsPreviewSaved = null;
  _wsShowPreviewOverlay();
}

// Preview a SAVED worksheet — the same A4 preview the builder uses, opened from
// the My Worksheets card, so a sheet can be checked (and its questions fixed)
// before it goes to the printer.
function previewSavedWorksheet(id) {
  const ws = savedWorksheets.find(w => w.id === id);
  if (!ws) return;
  if (_wsSavedQuestions(ws).length === 0) {
    showToast('Questions no longer available', 'error');
    return;
  }
  _wsPreviewSaved = { id: ws.id, title: ws.title };
  _wsShowPreviewOverlay();
}

function _wsShowPreviewOverlay() {
  const ov = document.getElementById('wsPreviewOverlay');
  if (ov) ov.classList.add('show');
  renderWsPreview();
}

function closeWorksheetPreview() {
  const ov = document.getElementById('wsPreviewOverlay');
  if (ov) ov.classList.remove('show');
  closeWsQuickEdit();
  _wsPreviewSaved = null;
}
function wsBreakBefore(qid) { // push this question onto a new page
  if (!qid) return;
  wsMergeUp.delete(qid);
  wsManualBreaks.add(qid);
  renderWsPreview();
}
function wsPullUp(qid) { // pull this question onto the previous page
  if (!qid) return;
  wsManualBreaks.delete(qid);
  wsMergeUp.add(qid);
  renderWsPreview();
}
function printFromPreview() {
  if (_wsPreviewSaved) { reprintWorksheet(_wsPreviewSaved.id); return; }
  printStudentWorksheet();
}

async function renderWsPreview() {
  const frame = document.getElementById('wsPreviewFrame');
  if (!frame) return;
  const ctx = _wsPreviewCtx();
  const selected = ctx.selected;
  const title = ctx.title;
  const frontHtml = ctx.cover ? _wsCoverHtml(title, undefined, undefined, ctx.noFields) : '';
  const html = buildWorksheetHtml(selected, title, { frontHtml, plainNumbers: true, noStudentFields: ctx.noFields });   // exactly what will print
  const fontLinks = _printFontLinksHtml();
  const doc = frame.contentDocument || (frame.contentWindow && frame.contentWindow.document);
  if (!doc) return;
  doc.open();
  doc.write('<!DOCTYPE html><html><head><meta charset="utf-8">' + fontLinks +
    '<style>' + _wsAppCssForPreview() + WS_PREVIEW_CSS + '</style></head><body>' +
    '<div id="printOutput"><div id="wsMeasure" class="print-question-page pm-fit">' + html + '</div><div id="wsPages"></div></div></body></html>');
  doc.close();
  // Same picture-space reservation the printer uses. The preview runs the SAME
  // planner, so without it the teacher is shown a pagination that the printed
  // sheet will not reproduce — and the whole point of the preview is that the
  // two agree.
  _printStampImgDims(doc);
  _wsPreviewWhenReady(doc, () => { _printStampImgDims(doc); _wsPreviewPack(doc); });
}

function _wsPreviewWhenReady(doc, cb) {
  let done = false;
  const view = doc.defaultView || window;
  // Two frames, not one: the first lets the newly-applied font faces take
  // effect, the second measures the reflowed result.
  const go = () => { if (done) return; done = true; view.requestAnimationFrame(() => view.requestAnimationFrame(cb)); };
  try {
    // `doc.fonts.ready` only promises the faces this document KNOWS about, so
    // waiting on it before the Google Fonts stylesheet has arrived resolves
    // instantly against an empty font set — and every text block then gets
    // measured in fallback metrics it will not print with.
    const sheets = Array.from(doc.querySelectorAll('link[rel="stylesheet"]'));
    const sheetsP = Promise.all(sheets.map(l => (l.sheet ? Promise.resolve() : new Promise(res => {
      l.addEventListener('load', res, { once: true });
      l.addEventListener('error', res, { once: true });
      setTimeout(res, 3000);
    }))));
    const fontsP = sheetsP.then(() => (doc.fonts && doc.fonts.ready) ? doc.fonts.ready : Promise.resolve());
    const pending = Array.from(doc.images || []).filter(im => !im.complete);
    if (!pending.length) { fontsP.then(go); }
    else { let rem = pending.length; const one = () => { if (--rem <= 0) fontsP.then(go); }; pending.forEach(im => { im.addEventListener('load', one, { once: true }); im.addEventListener('error', one, { once: true }); }); }
    setTimeout(go, 8000); // safety net
  } catch (e) { setTimeout(go, 300); }
}

function _wsPreviewPack(doc) {
  const measure = doc.getElementById('wsMeasure');
  const pagesEl = doc.getElementById('wsPages');
  if (!measure || !pagesEl) return;
  const chunks = Array.from(measure.querySelectorAll('.print-question-chunk'));
  const answerKeys = Array.from(measure.querySelectorAll('.print-answer-key-page'));
  const fronts = Array.from(measure.querySelectorAll('.print-front-page'));
  pagesEl.innerHTML = '';
  if (!chunks.length) { measure.style.display = 'none'; return; }
  // The preview runs the SAME planner the printer runs, on the same assembled
  // pages, so what the teacher sees here is what comes out of the PDF —
  // including the re-flow that moves an over-full page's last question on.
  let plan;
  try {
    plan = _printPlanIn(doc, measure, { forcedBreakIds: wsManualBreaks, mergeUpIds: wsMergeUp });
  } catch (e) { console.warn('preview plan', e); measure.style.display = 'none'; return; }
  const heights = plan.heights;
  const footerH = plan.footerH;
  const separatorH = plan.sepH;
  const tallFlags = plan.tallFlags;
  const pageGroups = plan.groups;
  const frontSpans = plan.frontSpans;
  chunks.forEach((c, i) => c.classList.toggle('print-chunk-tall', tallFlags[i]));
  measure.style.display = 'none';
  // How many printed sheets each group really spans — a tall question flows
  // over several sheets when printed (never shrunk below readable), and the
  // answer key does the same once fit-to-page would drop below the zoom floor.
  const spanOf = h => Math.max(1, Math.ceil(h / PRINT_PAGE_PX));
  const groupSpans = pageGroups.map((g, gi) => plan.pageTall[gi] ? spanOf(plan.pageHs[gi]) : 1);
  const akSpans = answerKeys.map((ak, ai) => {
    const p = plan.akPlans[ai] || {};
    return p.tall ? spanOf(p.h || 1) : 1;
  });
  const totalPages = frontSpans.reduce((a, b) => a + b, 0) + groupSpans.reduce((a, b) => a + b, 0) + akSpans.reduce((a, b) => a + b, 0);
  let pageNo = 0;
  const addSheet = (span, build, zoom) => {
    const from = pageNo + 1;
    pageNo += span;
    const sheet = doc.createElement('div'); sheet.className = 'wspv-sheet';
    const content = doc.createElement('div'); content.className = 'wspv-content';
    build(content);
    sheet.appendChild(content);
    const pno = doc.createElement('div'); pno.className = 'wspv-pageno';
    pno.textContent = (span > 1 ? 'Pages ' + from + '–' + pageNo : 'Page ' + pageNo) + ' of ' + totalPages;
    sheet.appendChild(pno);
    pagesEl.appendChild(sheet);
    content.style.zoom = '';
    if (span > 1) return;  // flows across sheets when printed — shown full-length here, never shrunk
    if (zoom) content.style.zoom = zoom;  // exactly what the printer will apply
  };
  fronts.forEach((f, fi) => addSheet(frontSpans[fi], content => content.appendChild(f), 0));
  pageGroups.forEach((group, gi) => addSheet(groupSpans[gi], content => {
    group.forEach((idx, pos) => {
      if (pos > 0) { const sep = doc.createElement('div'); sep.className = 'print-question-separator'; content.appendChild(sep); }
      const chunk = chunks[idx];
      const qid = chunk.dataset.qid;
      const tools = doc.createElement('div');
      tools.className = 'wspv-tools';
      if (idx !== 0) { // nothing precedes the very first question
        const btn = doc.createElement('button');
        btn.type = 'button';
        if (pos === 0) { // this question starts a page — offer to pull it onto the previous one
          btn.className = 'wspv-brk up';
          btn.textContent = '⬆ move to previous page';
          btn.title = 'Pull this question onto the previous page (fit more per page)';
          btn.setAttribute('onclick', "parent.wsPullUp('" + qid + "')");
        } else { // mid-page — offer to push it onto a new page
          btn.className = 'wspv-brk';
          btn.textContent = '⤓ break before';
          btn.title = 'Push this question onto a new page';
          btn.setAttribute('onclick', "parent.wsBreakBefore('" + qid + "')");
        }
        tools.appendChild(btn);
      }
      // Edit the question where it is — the whole point of previewing a sheet is
      // spotting the diagram that printed too small, and the fix used to mean
      // leaving the page for the bank and finding your way back. Admins only:
      // this writes to the shared question bank.
      if (qid && qid.indexOf('__lo__') !== 0 && _canAuthor()) {
        const eb = doc.createElement('button');
        eb.type = 'button';
        eb.className = 'wspv-brk edit';
        eb.textContent = '✏️ edit question';
        eb.title = 'Edit this question — text and diagram size — without leaving the preview';
        eb.setAttribute('onclick', "parent.wsQuickEdit('" + qid + "')");
        tools.appendChild(eb);
      }
      if (tools.children.length) chunk.appendChild(tools);
      content.appendChild(chunk);
    });
  }, plan.pageZoom[gi]));
  answerKeys.forEach((ak, ai) => addSheet(akSpans[ai], content => content.appendChild(ak), (plan.akPlans[ai] || {}).zoom));
  const cnt = document.getElementById('wsPreviewPageCount');
  if (cnt) cnt.textContent = '· ' + totalPages + ' page' + (totalPages === 1 ? '' : 's');
}

// =====================================================================
// WORKSHEET QUICK EDIT — edit a question at its SOURCE from the preview.
// Writes to the question bank (the same doc the full editor writes), so the
// change sticks for every worksheet, quest and game that uses the question.
// Covers the two things a printed sheet makes you want to change — the wording
// and how big a diagram comes out — and hands anything structural to the full
// editor, which now returns you to where you started.
// =====================================================================
let _wsQeQid = null;      // id of the question in the drawer
let _wsQeDraft = null;    // working copy; discarded unless Save is pressed
let _wsQeReturn = null;   // preview to reopen after a trip to the full editor

function wsQuickEdit(qid) {
  if (!_canAuthor()) return;
  const q = questionBank.find(x => String(x.id) === String(qid));
  if (!q) { showToast('That question is no longer in the bank', 'error'); return; }
  _wsQeQid = String(q.id);
  _wsQeDraft = JSON.parse(JSON.stringify({ title: q.title || '', blocks: q.blocks || [] }));
  const sub = document.getElementById('wsQuickEditSub');
  if (sub) sub.textContent = [q.category, q.topic].filter(Boolean).join(' · ');
  _wsQeRender();
  const ov = document.getElementById('wsQuickEditOverlay');
  if (ov) ov.classList.add('show');
}

function closeWsQuickEdit() {
  const ov = document.getElementById('wsQuickEditOverlay');
  if (ov) ov.classList.remove('show');
  _wsQeQid = null;
  _wsQeDraft = null;
}

// A short, honest label for a block we cannot edit here.
function _wsQeBlockSummary(b) {
  switch (b.type) {
    case 'mcq': return (b.options || []).length + ' answer option' + ((b.options || []).length === 1 ? '' : 's');
    case 'table': return 'Table';
    case 'answer': return 'Claim / Evidence / Reasoning · '
      + [b.claim, b.evidence, b.reasoning].map(t => printAnswerLines(b, t)).join(' / ') + ' printed lines';
    case 'plainanswer': return printAnswerLines(b, b.content) + ' printed answer line'
      + (printAnswerLines(b, b.content) === 1 ? '' : 's');
    case 'openLines': return (Number(b.lines) || 4) + ' blank lines';
    case 'workingSpace': return 'Working space';
    case 'answerLine': return 'Answer line';
    case 'fillblank': return 'Fill in the blanks';
    case 'explanation': return 'Explanation (answer key)';
    case 'widget': return 'Interactive widget (screen-only, not printed)';
    case 'answerKey': return 'Answer key';
    case 'commonMistake': return 'Common mistake note';
    case 'studentAnswer': return "Student's answer";
    case 'part': return 'Question part';
    case 'pageBreak': return 'Page break';
    default: return b.type;
  }
}

function _wsQeRender() {
  const body = document.getElementById('wsQuickEditBody');
  if (!body || !_wsQeDraft) return;
  const rows = (_wsQeDraft.blocks || []).map(b => {
    const bid = escapeHtml(String(b.id || ''));
    if (b.type === 'image') {
      return `<div class="wsqe-block">
        <div class="wsqe-block-label">🖼 Diagram</div>
        ${b.url
          ? `<div class="wsqe-shot" id="wsqeShot_${bid}"><img id="wsqeImg_${bid}" src="${escapeHtml(transformImageUrl(b.url))}" alt="" style="${imgSizeStyle(b)}"></div>`
          : `<div class="wsqe-shot wsqe-shot-empty">No image on this block yet</div>`}
        <div class="wsqe-size">
          <button type="button" class="wsqe-step" onclick="wsQeImgSize('${bid}',-1)" title="Smaller — ${IMG_SCALE_STEP}% at a time, down to ${IMG_SCALE_MIN}%">−</button>
          <span class="wsqe-size-val" id="wsqeSize_${bid}">${imgSizeLabelText(b)}</span>
          <button type="button" class="wsqe-step" onclick="wsQeImgSize('${bid}',1)" title="Larger — ${IMG_SCALE_STEP}% at a time, up to the full page width">+</button>
          <button type="button" class="wsqe-step wsqe-step-auto" onclick="wsQeImgSize('${bid}',0)" title="Auto: fill the page width without stretching the picture past its own resolution">Auto</button>
          <span class="wsqe-hint">of the page width — ${IMG_SCALE_MAX}% fills the column</span>
        </div>
        <div class="wsqe-size">
          <span class="wsqe-hint" style="margin-left:0;">🖨️ Print height</span>
          <select class="wsqe-input" style="max-width:160px;padding:5px 8px;" onchange="wsQePrintImg('${bid}', this.value)">
            ${PRINT_IMG_CHOICES.map(([v, label, tip]) =>
              `<option value="${v}" title="${escapeHtml(tip)}"${(String(b.printImg || 'auto') === v) ? ' selected' : ''}>${escapeHtml(label)}</option>`).join('')}
          </select>
          <span class="wsqe-hint">Large for a graph, a table or a figure holding the options</span>
        </div>
        <label class="wsqe-label" for="wsqeUrl_${bid}">Image link</label>
        <input class="wsqe-input" id="wsqeUrl_${bid}" type="text" value="${escapeHtml(b.url || '')}"
               placeholder="https://…" oninput="wsQeImgUrl('${bid}', this.value)">
      </div>`;
    }
    if (b.type === 'text') {
      return `<div class="wsqe-block">
        <div class="wsqe-block-label">✍️ Text</div>
        <div class="wsqe-rich" contenteditable="true" data-wsqe-rich="${bid}">${b.content || ''}</div>
      </div>`;
    }
    return `<div class="wsqe-block wsqe-block-locked">
      <div class="wsqe-block-label">${escapeHtml(_wsQeBlockSummary(b))}</div>
      <div class="wsqe-hint">Change this one in the full editor.</div>
    </div>`;
  }).join('');
  body.innerHTML = `<label class="wsqe-label" for="wsqeTitle">Question title</label>
    <input class="wsqe-input" id="wsqeTitle" type="text" value="${escapeHtml(_wsQeDraft.title || '')}">
    ${rows || '<div class="wsqe-hint">This question has no blocks.</div>'}`;
}

function _wsQeBlock(bid) {
  return (_wsQeDraft && _wsQeDraft.blocks || []).find(b => String(b.id) === String(bid));
}

// Same range and steps as the editor's own control. dir 0 means "back to Auto".
// Print height for a picture, edited straight from the worksheet preview —
// the place where you actually notice a diagram came out too big or too small.
function wsQePrintImg(bid, val) {
  const b = _wsQeBlock(bid);
  if (!b) return;
  if (!val || val === 'auto') delete b.printImg; else b.printImg = val;
}
function wsQeImgSize(bid, dir) {
  const b = _wsQeBlock(bid);
  if (!b) return;
  if (!dir) delete b.scale;
  else {
    const base = imgHasScale(b) ? Math.round(imgScale(b) * 100)
                                : _imgRenderedPct('wsqeShot_' + bid, IMG_SCALE_MAX);
    b.scale = Math.max(IMG_SCALE_MIN, Math.min(IMG_SCALE_MAX, base + dir * IMG_SCALE_STEP)) / 100;
  }
  const lbl = document.getElementById('wsqeSize_' + bid);
  if (lbl) lbl.textContent = imgSizeLabelText(b);
  const img = document.getElementById('wsqeImg_' + bid);
  if (img) img.setAttribute('style', imgSizeStyle(b));
}

function wsQeImgUrl(bid, url) {
  const b = _wsQeBlock(bid);
  if (!b) return;
  b.url = (url || '').trim();
  const img = document.getElementById('wsqeImg_' + bid);
  if (img && b.url) img.src = transformImageUrl(b.url);
}

async function saveWsQuickEdit() {
  if (!_wsQeDraft) return;
  const q = questionBank.find(x => String(x.id) === String(_wsQeQid));
  if (!q) { showToast('That question is no longer in the bank', 'error'); closeWsQuickEdit(); return; }
  // Rich text lives in the DOM until now — read it back before saving.
  document.querySelectorAll('#wsQuickEditBody [data-wsqe-rich]').forEach(el => {
    const b = _wsQeBlock(el.dataset.wsqeRich);
    if (b) b.content = el.innerHTML;
  });
  const titleEl = document.getElementById('wsqeTitle');
  const title = titleEl ? titleEl.value.trim() : '';
  q.title = title || q.title;
  q.blocks = JSON.parse(JSON.stringify(_wsQeDraft.blocks || []));
  closeWsQuickEdit();
  renderWsPreview();                       // the sheet redraws with the change
  try { renderQuestionBank(); } catch (e) { /* bank not on screen — fine */ }
  const ok = await saveQuestion(q);
  if (ok) showToast('Question updated ✓', 'success');
}

// Escape hatch for anything the drawer cannot change. Remembers the preview so
// the full editor drops you back here — sheet open, same place — when it closes.
function wsQuickEditOpenFull() {
  const qid = _wsQeQid;
  if (!qid) return;
  const back = _wsPreviewSaved ? Object.assign({}, _wsPreviewSaved) : null;
  closeWsQuickEdit();
  closeWorksheetPreview();
  editQuestion(qid);
  // editQuestion() resets the return page, so set ours after it and refresh the
  // "← Back" affordance — otherwise it keeps whatever the last edit left there.
  _editReturnPage = back ? 'myworksheets' : 'worksheet';
  _wsQeReturn = back;
  _syncBackToPapersBtn();
}

// Called after the full editor closes (save or cancel) — reopens the preview
// the edit was launched from.
function _wsQeReopenPreview() {
  const back = _wsQeReturn;
  _wsQeReturn = null;
  if (!back) return;
  setTimeout(() => { if (savedWorksheets.some(w => w.id === back.id)) previewSavedWorksheet(back.id); }, 60);
}

// =====================================================================
// QUICK PRACTICE MODE — level-ordered practice for students
// =====================================================================
let qpQueue = [];       // ordered array of question objects
let qpIndex = -1;       // current position in queue
let qpLevel = 'P6';     // selected student level
let qpAnswered = 0;     // questions answered so far
let qpSessionResults = []; // per-question results for the end-of-session AI feedback

// Cross-session "recently served" memory so students aren't shown the same
// questions first every time they start a new Quick Practice session. The queue
// already covers the whole filtered pool without repeats WITHIN a session, but a
// fresh session used to reshuffle from scratch — so a student who only answers a
// few each visit kept seeing the same opening questions. We remember served IDs
// per student and front-load the ones they haven't seen recently.
const QP_SEEN_CAP = 600; // rolling window of remembered question IDs
function qpSeenKey() { return 'sciQuestQpSeen:' + (currentUser ? currentUser.uid : 'anon'); }
function qpLoadSeen() { try { const a = JSON.parse(localStorage.getItem(qpSeenKey()) || '[]'); return Array.isArray(a) ? a.map(String) : []; } catch (_) { return []; } }
function qpSaveSeen(arr) { try { localStorage.setItem(qpSeenKey(), JSON.stringify(arr.slice(-QP_SEEN_CAP))); } catch (_) {} }
function qpMarkServed(qid) {
  qid = String(qid || ''); if (!qid) return;
  const a = qpLoadSeen().filter(x => x !== qid); // move to most-recent
  a.push(qid);
  qpSaveSeen(a);
}

// ── Student level cap ─────────────────────────────────────────────────────────
// Each student account can be assigned a P3–P6 level by the admin (Usage page).
// Students are NEVER served questions whose topic sits above their level, in
// any mode: quick practice, topical practice, quests and the mini-games.
// Unassigned students default to P6 (no restriction) so nothing breaks until
// the admin sets levels.
function studentCapLevel() {
  if (currentUser && currentUser.role === 'student' && /^P[3-6]$/.test(currentUser.level || '')) return currentUser.level;
  return 'P6';
}
function studentCapNum() { return getLevelNumber(studentCapLevel()); }
function qWithinStudentLevel(q) {
  return getLevelNumber(getTopicLevel((q && q.topic) || '')) <= studentCapNum();
}
// Clamp a P-level string to the student's cap (admins pass through unchanged).
function clampToStudentLevel(level) {
  const n = Math.min(getLevelNumber(level), studentCapNum());
  return 'P' + Math.max(3, n);
}
// Rebuild the student-facing level dropdowns up to the student's cap so they
// can't select a level above their own, and preselect their level. Rebuilt
// (not just trimmed) because the cap can RISE when a family account switches
// to an older sibling.
function applyStudentLevelCaps() {
  if (!currentUser || currentUser.role !== 'student') return;
  const capNum = studentCapNum();
  ['qpLevelSelect', 'tpLevelSelect'].forEach(id => {
    const sel = document.getElementById(id);
    if (!sel) return;
    const cur = sel.value;
    sel.innerHTML = '';
    for (let n = 3; n <= capNum; n++) {
      const o = document.createElement('option');
      o.value = 'P' + n; o.textContent = 'P' + n;
      sel.appendChild(o);
    }
    sel.value = (/^P[3-6]$/.test(cur) && getLevelNumber(cur) <= capNum) ? cur : studentCapLevel();
  });
}
// Load the signed-in student's assigned level. Primary source: their own
// userProfiles doc (set by the admin). Fallback: the admin's shared
// settings/studentLevels map — covers rule setups where students can't read
// userProfiles. Both failing leaves the P6 default (no restriction).
async function loadStudentLevel() {
  if (!currentUser || currentUser.role !== 'student') return;
  let lvl = '', served = '';
  try {
    const s = await getDoc(doc(db, 'userProfiles', currentUser.uid));
    if (s.exists()) {
      const d = s.data();
      if (/^P[3-6]$/.test(d.level || '')) lvl = d.level;
      // What we served last time. Used only as a stand-in until the family
      // profile loads a few lines later and recomputes it properly — but that
      // gap is exactly where an uncapped P6 used to slip through.
      if (/^P[3-6]$/.test(d.servingLevel || '')) served = d.servingLevel;
    }
  } catch (e) { console.warn('own profile level read', e); }
  if (!lvl && adminUid) {
    try {
      const s = await getDoc(doc(db, 'users', adminUid, 'settings', 'studentLevels'));
      const map = s.exists() ? (s.data().levels || {}) : {};
      if (/^P[3-6]$/.test(map[currentUser.uid] || '')) lvl = map[currentUser.uid];
    } catch (e) { console.warn('shared level map read', e); }
  }
  currentUser.adminLevel = lvl || ''; // the teacher's assigned cap for this account
  currentUser.level = lvl || served || '';
  applyStudentLevelCaps();
}

// ── Family profile: the students on this login, their levels, home address ──
// Every student login gets a popup: the first time it asks for each child's
// name and level (parents tap "+ Add student" for more); afterwards it asks
// who's practising today. Details are editable under ⚙ Settings, but at most
// FAM_EDIT_LIMIT times per student — the teacher can always change them.
const FAM_EDIT_LIMIT = 2;
let familyProfile = { students: [], address: '', activeStudent: 0 };
let _famAddFrom = 'login'; // where the "+ Add student" flow was opened from

function famStudents() { return Array.isArray(familyProfile.students) ? familyProfile.students : []; }
function famActive() { return famStudents()[familyProfile.activeStudent] || famStudents()[0] || null; }

async function famLoadProfile() {
  familyProfile = { students: [], address: '', activeStudent: 0 };
  try {
    const s = await getDoc(doc(db, 'userProfiles', currentUser.uid));
    if (s.exists()) {
      const d = s.data();
      familyProfile.students = Array.isArray(d.students)
        ? d.students.filter(x => x && typeof x.name === 'string' && x.name.trim()).map(x => ({
            name: x.name.trim(),
            level: /^P[3-6]$/.test(x.level || '') ? x.level : 'P6',
            edits: Math.max(0, Number(x.edits) || 0)
          }))
        : [];
      familyProfile.address = typeof d.address === 'string' ? d.address : '';
      familyProfile.activeStudent = Math.min(Math.max(0, Number(d.activeStudent) || 0), Math.max(0, familyProfile.students.length - 1));
    }
  } catch (e) { console.warn('family profile load', e); }
}
function famSaveProfile() {
  if (!currentUser || !db) return Promise.resolve();
  return setDoc(doc(db, 'userProfiles', currentUser.uid), {
    students: famStudents().map(s => ({ name: s.name, level: s.level, edits: s.edits || 0 })),
    address: familyProfile.address || '',
    activeStudent: familyProfile.activeStudent || 0
  }, { merge: true }).catch(e => console.warn('family profile save', e));
}
// The level the app is ACTUALLY serving at, stored where everything else can
// see it: the Usage dashboard, the next session, and fps.html — which runs as
// its own page and cannot see this one's memory. Kept in its own field so the
// teacher's assigned level (userProfiles.level) stays the teacher's, and the
// "lower of the two wins" rule below still has two separate numbers to compare.
function _famPersistServingLevel() {
  if (!currentUser || !db || currentUser.role !== 'student') return;
  const lvl = /^P[3-6]$/.test(currentUser.level || '') ? currentUser.level : '';
  const name = currentUser.name || '';
  if (_famServingWritten === lvl + '|' + name) return;    // nothing changed
  _famServingWritten = lvl + '|' + name;
  setDoc(doc(db, 'userProfiles', currentUser.uid),
    { servingLevel: lvl, servingName: name, servingLevelAt: new Date().toISOString() }, { merge: true })
    .catch(e => console.warn('serving level save', e));
}
let _famServingWritten = '';

// The serving cap honours BOTH sides: the teacher's assigned level (Usage
// dashboard) and the active student's own declared level — the LOWER of the
// two wins, so neither a typo nor an eager student can raise it.
function famApplyActiveStudent() {
  const s = famActive();
  const kid = (s && /^P[3-6]$/.test(s.level || '')) ? s.level : '';
  const admin = /^P[3-6]$/.test(currentUser.adminLevel || '') ? currentUser.adminLevel : '';
  currentUser.level = (kid && admin)
    ? (getLevelNumber(kid) < getLevelNumber(admin) ? kid : admin)
    : (kid || admin || '');
  // Write the level that will actually be served back to the profile. Without
  // this it lived only in memory for the rest of the session: the teacher's
  // Usage dashboard showed "—" for a child who had plainly declared P4, and any
  // session or page that resolved the level before the family profile loaded
  // fell through to the P6 default — which is no cap at all.
  _famPersistServingLevel();
  if (s && s.name) {
    // Attempts, the leaderboard and the sidebar show the child who's
    // practising, not the parent's Google account name.
    currentUser.name = s.name;
    const nameEl = document.querySelector('.sidebar-footer div div:first-child');
    if (nameEl) nameEl.textContent = s.name;
    const av = document.querySelector('.avatar');
    if (av) av.textContent = s.name[0].toUpperCase();
  }
  applyStudentLevelCaps();
}

function famHintHtml() {
  return `<p style="font-size:0.8rem;color:var(--text-muted);line-height:1.5;margin-top:16px;">💡 You can update student names, levels and your address anytime under <strong>⚙ Settings</strong> in the menu. Each student's details can only be edited ${FAM_EDIT_LIMIT} times, so type carefully — your teacher can always fix them for you.</p>`;
}
// =====================================================================
// 📜 TERMS OF ACCESS
// Every student agrees before they can use the portal. Bump
// AGREEMENT_VERSION to put the dialog back in front of EVERYONE — the
// stored acceptance is compared against it, so a new version re-prompts
// the whole roster on their next visit.
//
// The acceptance is written to the student's own userProfiles doc (the
// same doc famSaveProfile already writes), so the Usage dashboard can
// show who agreed, when, and which of the two routes they chose — the
// "not enrolled" route is a billing commitment and the teacher has to be
// able to see it.
// =====================================================================
const AGREEMENT_VERSION = '2026-08-v1';
const AGREEMENT_FEE = '$150 per month';
let _agreementResolve = null;
// Resolves once the student has agreed. Declining signs them out, so the
// promise deliberately never resolves down that path.
function agreementRequire() {
  // Admins are not students, and an admin previewing AS a student must not be
  // asked to accept terms on that student's behalf.
  if (!currentUser || currentUser.role !== 'student' || _practiceAs) return Promise.resolve();
  return new Promise(resolve => {
    (async () => {
      let ok = false;
      try {
        const s = await getDoc(doc(db, 'userProfiles', currentUser.uid));
        const a = s.exists() && s.data().agreement;
        ok = !!(a && a.version === AGREEMENT_VERSION);
      } catch (e) {
        // Can't read the profile (offline, rules). Ask again rather than let
        // someone through on a failed check.
        console.warn('agreement read', e);
      }
      if (ok) { resolve(); return; }
      _agreementResolve = resolve;
      agreementShow();
    })();
  });
}
function agreementShow() {
  const ov = document.getElementById('agreementOverlay');
  if (!ov) { if (_agreementResolve) { _agreementResolve(); _agreementResolve = null; } return; }
  const accept = document.getElementById('agreementAcceptBtn');
  const decline = document.getElementById('agreementDeclineBtn');
  const check = document.getElementById('agreeTerms');
  const radios = Array.prototype.slice.call(ov.querySelectorAll('input[name="agreementWho"]'));
  const sync = () => {
    const who = radios.find(r => r.checked);
    const ready = !!who && !!(check && check.checked);
    if (accept) accept.disabled = !ready;
    const foot = document.getElementById('agreementFoot');
    if (foot) {
      foot.textContent = ready
        ? (who.value === 'paying'
            ? 'By continuing, your parent or guardian agrees to pay ' + AGREEMENT_FEE + ' for access.'
            : 'Thank you — you can continue.')
        : 'Choose an option above and tick the box to continue.';
    }
  };
  radios.forEach(r => { r.checked = false; r.onchange = sync; });
  if (check) { check.checked = false; check.onchange = sync; }
  if (accept) accept.onclick = () => {
    const who = radios.find(r => r.checked);
    if (!who || !check || !check.checked) return;
    agreementAccept(who.value);
  };
  if (decline) decline.onclick = agreementDecline;
  sync();
  ov.classList.add('active');
}
async function agreementAccept(choice) {
  const ov = document.getElementById('agreementOverlay');
  const accept = document.getElementById('agreementAcceptBtn');
  if (accept) { accept.disabled = true; accept.textContent = 'Saving…'; }
  const record = {
    version: AGREEMENT_VERSION,
    choice: choice === 'paying' ? 'paying' : 'enrolled',
    fee: choice === 'paying' ? AGREEMENT_FEE : '',
    at: new Date().toISOString(),
    name: (currentUser && currentUser.name) || '',
    email: (currentUser && currentUser.email) || ''
  };
  try {
    await setDoc(doc(db, 'userProfiles', currentUser.uid), { agreement: record }, { merge: true });
  } catch (e) {
    // Don't trap a student behind a failed write — they agreed, and the
    // dialog comes back next time because nothing was stored.
    console.warn('agreement save', e);
    showToast("Couldn't save your agreement — you can continue, and we'll ask again next time", 'error');
  }
  if (accept) accept.textContent = 'Agree and continue';
  if (ov) ov.classList.remove('active');
  if (_agreementResolve) { _agreementResolve(); _agreementResolve = null; }
}
async function agreementDecline() {
  if (!confirm('Decline the terms and sign out?\n\nYou need to accept them to use the Science Learning Portal. You can sign back in and accept at any time.')) return;
  const ov = document.getElementById('agreementOverlay');
  if (ov) ov.classList.remove('active');
  _agreementResolve = null;
  try { await signOut(auth); } catch (e) { console.warn('agreement sign-out', e); }
  showToast('Signed out — accept the terms to use the portal', '');
}

function famShowLoginPopup() {
  if (!currentUser || currentUser.role !== 'student') return;
  renderFamLoginBody();
  const ov = document.getElementById('famLoginOverlay');
  if (ov) ov.classList.add('active');
}
function renderFamLoginBody() {
  const body = document.getElementById('famLoginBody');
  if (!body) return;
  const studs = famStudents();
  if (!studs.length) {
    body.innerHTML = `
      <h3 style="margin-bottom:6px;">👋 Welcome! Who's practising?</h3>
      <p style="font-size:0.88rem;color:var(--text-muted);line-height:1.5;margin-bottom:16px;">Enter the student's name and school level. More than one child using this account? Click <strong>+ Add student</strong>.</p>
      <div id="famSetupRows"></div>
      <button class="btn btn-outline" style="margin-top:4px;" onclick="famAddSetupRow()">+ Add student</button>
      <div class="btn-group" style="justify-content:flex-end;margin-top:18px;">
        <button class="btn btn-primary" onclick="famSaveSetup()">Save &amp; start</button>
      </div>
      ${famHintHtml()}`;
    famAddSetupRow();
  } else {
    body.innerHTML = `
      <h3 style="margin-bottom:6px;">👋 Who's practising today?</h3>
      <p style="font-size:0.88rem;color:var(--text-muted);margin-bottom:16px;">Tap your name to start.</p>
      <div style="display:flex;flex-direction:column;gap:8px;">
        ${studs.map((s, i) => `
          <button class="btn btn-outline" style="display:flex;width:100%;justify-content:space-between;align-items:center;padding:12px 16px;font-size:0.95rem;" onclick="famPickStudent(${i})">
            <span>${escapeHtml(s.name)}</span><span style="color:var(--text-muted);font-size:0.8rem;">${escapeHtml(s.level)}</span>
          </button>`).join('')}
      </div>
      <button class="btn btn-outline" style="margin-top:14px;" onclick="famStartAdd('login')">+ Add student</button>
      ${famHintHtml()}`;
  }
}
function famAddSetupRow(name, level) {
  const wrap = document.getElementById('famSetupRows');
  if (!wrap) return;
  const row = document.createElement('div');
  row.className = 'fam-setup-row';
  row.style.cssText = 'display:flex;gap:8px;align-items:center;margin-bottom:8px;';
  row.innerHTML = `
    <input type="text" class="form-input fam-name" placeholder="Student name" value="${escapeHtml(name || '')}" style="flex:1;">
    <select class="form-select fam-level" style="max-width:90px;">
      ${['P3', 'P4', 'P5', 'P6'].map(lv => `<option value="${lv}"${lv === (level || 'P4') ? ' selected' : ''}>${lv}</option>`).join('')}
    </select>
    <button class="block-action-btn delete" title="Remove" onclick="this.parentElement.remove()">✕</button>`;
  wrap.appendChild(row);
}
function _famCollectRows() {
  return Array.from(document.querySelectorAll('#famSetupRows .fam-setup-row')).map(r => ({
    name: (r.querySelector('.fam-name').value || '').trim(),
    level: r.querySelector('.fam-level').value,
    edits: 0
  })).filter(s => s.name);
}
async function famSaveSetup() {
  const studs = _famCollectRows();
  if (!studs.length) { showToast("Enter the student's name first", 'error'); return; }
  familyProfile.students = studs;
  familyProfile.activeStudent = 0;
  await famSaveProfile();
  if (studs.length > 1) renderFamLoginBody(); // several children — ask who's practising now
  else famPickStudent(0);
}
function famStartAdd(from) {
  _famAddFrom = from || 'login';
  const body = document.getElementById('famLoginBody');
  if (!body) return;
  body.innerHTML = `
    <h3 style="margin-bottom:12px;">Add a student</h3>
    <div id="famSetupRows"></div>
    <div class="btn-group" style="justify-content:flex-end;margin-top:18px;">
      <button class="btn btn-outline" onclick="famCancelAdd()">Back</button>
      <button class="btn btn-primary" onclick="famSaveAdd()">Add &amp; save</button>
    </div>
    ${famHintHtml()}`;
  famAddSetupRow();
  const ov = document.getElementById('famLoginOverlay');
  if (ov) ov.classList.add('active');
}
function famCancelAdd() {
  if (_famAddFrom === 'settings') {
    const ov = document.getElementById('famLoginOverlay');
    if (ov) ov.classList.remove('active');
  } else {
    renderFamLoginBody();
  }
}
async function famSaveAdd() {
  const studs = _famCollectRows();
  if (!studs.length) { showToast("Enter the student's name first", 'error'); return; }
  familyProfile.students = famStudents().concat(studs);
  await famSaveProfile();
  showToast('Student added ✓', 'success');
  if (_famAddFrom === 'settings') {
    const ov = document.getElementById('famLoginOverlay');
    if (ov) ov.classList.remove('active');
    famRenderSettings();
  } else {
    renderFamLoginBody();
  }
}
function famPickStudent(i) {
  familyProfile.activeStudent = Math.max(0, Math.min(i, famStudents().length - 1));
  famSaveProfile();
  famApplyActiveStudent();
  const ov = document.getElementById('famLoginOverlay');
  if (ov) ov.classList.remove('active');
  const s = famActive();
  if (s) showToast(`Hi ${s.name}! Questions up to ${currentUser.level || 'P6'} today`, 'success');
}

// ⚙ Settings page (student side): address, student names/levels (2 edits per
// student), add students, and switch who's practising.
function famRenderSettings() {
  const wrap = document.getElementById('famSettingsContainer');
  if (!wrap) return;
  const studs = famStudents();
  const rows = studs.map((s, i) => {
    const left = Math.max(0, FAM_EDIT_LIMIT - (s.edits || 0));
    const locked = left <= 0;
    return `
    <div style="border:1px solid var(--border);border-radius:12px;padding:16px;margin-bottom:12px;">
      <label style="display:flex;align-items:center;gap:6px;font-size:0.8rem;color:var(--text-muted);margin-bottom:10px;cursor:pointer;">
        <input type="radio" name="famActivePick" ${i === familyProfile.activeStudent ? 'checked' : ''} onchange="famPickStudent(${i});famRenderSettings();"> Practising now
      </label>
      <div style="display:flex;gap:8px;align-items:center;flex-wrap:wrap;">
        <input type="text" id="famSetName${i}" class="form-input" value="${escapeHtml(s.name)}" style="flex:1;min-width:150px;" ${locked ? 'disabled' : ''}>
        <select id="famSetLevel${i}" class="form-select" style="max-width:90px;" ${locked ? 'disabled' : ''}>
          ${['P3', 'P4', 'P5', 'P6'].map(lv => `<option value="${lv}"${lv === s.level ? ' selected' : ''}>${lv}</option>`).join('')}
        </select>
        <button class="btn btn-primary" onclick="famSaveStudentEdit(${i})" ${locked ? 'disabled' : ''}>Save</button>
      </div>
      <div style="font-size:0.76rem;color:${locked ? 'var(--accent-red, #c62828)' : 'var(--text-muted)'};margin-top:8px;">
        ${locked ? 'No edits left — ask your teacher to change these details.' : `${left} of ${FAM_EDIT_LIMIT} edits left for this student.`}
      </div>
    </div>`;
  }).join('') || '<p style="color:var(--text-muted);">No students yet — add one below.</p>';
  wrap.innerHTML = `
    <h3 style="margin-bottom:12px;">Students</h3>
    ${rows}
    <button class="btn btn-outline" onclick="famStartAdd('settings')">+ Add student</button>
    <h3 style="margin:28px 0 12px;">Home address</h3>
    <textarea id="famAddressInput" class="form-input" rows="2" placeholder="Your address (used for prize deliveries)" style="resize:vertical;">${escapeHtml(familyProfile.address || '')}</textarea>
    <div class="btn-group" style="margin-top:10px;">
      <button class="btn btn-primary" onclick="famSaveAddress()">Save address</button>
    </div>
    <p style="font-size:0.78rem;color:var(--text-muted);line-height:1.5;margin-top:20px;">Each student's name and level can be edited ${FAM_EDIT_LIMIT} times in total. Your teacher can always update them for you.</p>`;
}
async function famSaveStudentEdit(i) {
  const s = famStudents()[i];
  if (!s) return;
  const nameEl = document.getElementById('famSetName' + i);
  const lvlEl = document.getElementById('famSetLevel' + i);
  const name = (nameEl ? nameEl.value : '').trim();
  const level = lvlEl ? lvlEl.value : s.level;
  if (!name) { showToast('Name cannot be empty', 'error'); return; }
  if (name === s.name && level === s.level) { showToast('Nothing changed', 'info'); return; }
  if ((s.edits || 0) >= FAM_EDIT_LIMIT) { showToast('No edits left for this student — ask your teacher.', 'error'); return; }
  s.name = name;
  s.level = /^P[3-6]$/.test(level) ? level : s.level;
  s.edits = (s.edits || 0) + 1;
  await famSaveProfile();
  if (i === familyProfile.activeStudent) famApplyActiveStudent();
  famRenderSettings();
  showToast(`Saved ✓ — ${Math.max(0, FAM_EDIT_LIMIT - s.edits)} edit${FAM_EDIT_LIMIT - s.edits === 1 ? '' : 's'} left for this student`, 'success');
}
async function famSaveAddress() {
  const el = document.getElementById('famAddressInput');
  familyProfile.address = el ? el.value.trim() : '';
  await famSaveProfile();
  showToast('Address saved ✓', 'success');
}

// ── Cross-mode attempt stats ──────────────────────────────────────────────────
// One shared per-question record of everything this student has ever attempted
// — practice, topical, quests AND the mini-games — read once from the
// questionAttempts log and kept fresh in-session. Feeds the serving order
// everywhere: questions never attempted first, then lowest best-percentage.
let _qAttemptStats = null;   // { '<questionId>': { n, correct, best } }
let _qAttemptStatsAt = 0;
let _qAttemptStatsUid = '';  // who the cache belongs to — never reuse across accounts
async function loadAttemptStats(force) {
  if (!currentUser || !currentUser.uid || !db) { _qAttemptStats = _qAttemptStats || {}; return _qAttemptStats; }
  if (_qAttemptStatsUid !== currentUser.uid) { _qAttemptStats = null; _qAttemptStatsAt = 0; }
  if (_qAttemptStats && !force && (Date.now() - _qAttemptStatsAt) < 5 * 60 * 1000) return _qAttemptStats;
  try {
    const snap = await getDocs(query(collection(db, 'questionAttempts'), where('uid', '==', currentUser.uid)));
    const stats = {};
    snap.forEach(d => {
      const a = d.data();
      if (!a || a.questionId == null) return;
      const id = String(a.questionId);
      const frac = a.totalBlanks ? Math.max(0, Math.min(1, (Number(a.score) || 0) / a.totalBlanks)) : 0;
      const ts = (a.timestamp && typeof a.timestamp.toMillis === 'function') ? a.timestamp.toMillis() : 0;
      const r = stats[id] || (stats[id] = { n: 0, correct: 0, best: 0, last: 0 });
      r.n++; if (frac >= 1) r.correct++; if (frac > r.best) r.best = frac; if (ts > r.last) r.last = ts;
    });
    _qAttemptStats = stats;
    _qAttemptStatsAt = Date.now();
    _qAttemptStatsUid = currentUser.uid;
  } catch (e) { console.warn('attempt stats load', e); _qAttemptStats = _qAttemptStats || {}; }
  return _qAttemptStats;
}
// Keep the in-memory stats current as the student answers, so a rebuilt queue
// mid-session already treats just-answered questions as attempted.
function noteAttemptLocally(qid, score, total) {
  if (!_qAttemptStats) return;
  const id = String(qid || ''); if (!id) return;
  const frac = total ? Math.max(0, Math.min(1, (Number(score) || 0) / total)) : 0;
  const r = _qAttemptStats[id] || (_qAttemptStats[id] = { n: 0, correct: 0, best: 0, last: 0 });
  r.n++; if (frac >= 1) r.correct++; if (frac > r.best) r.best = frac; r.last = Date.now();
}
// Order a pool by how many times the student has DONE each question (the
// per-question attempt counter): never-attempted first (0× = top priority),
// then ascending attempt count so the least-practised questions always surface
// first. Within the same count, the weakest best score comes back soonest.
// Ties shuffle so back-to-back sessions stay fresh.
function orderByAttemptPriority(pool) {
  const stats = _qAttemptStats || {};
  const jitter = new Map();
  pool.forEach(q => jitter.set(q, Math.random()));
  const rec = q => stats[String(q.id)] || null;
  const count = q => { const r = rec(q); return r ? (r.n || 0) : 0; };
  const best = q => { const r = rec(q); return r ? (r.best || 0) : 0; };
  return pool.slice().sort((a, b) => (count(a) - count(b)) || (best(a) - best(b)) || (jitter.get(a) - jitter.get(b)));
}

// Reset the practice session and show the "ready" state. Reused whenever the
// level, type or topic filter changes.
function resetQpSession() {
  qpLevel = document.getElementById('qpLevelSelect').value;
  qpQueue = [];
  qpIndex = -1;
  qpAnswered = 0;
  qpSessionResults = [];
  const banner = document.getElementById('qpRecommendBanner');
  if (banner) { banner.style.display = 'none'; banner.innerHTML = ''; }
  updateQpProgress();
  const f = qpFilters();
  const typeLabel = f.type === 'mcq' ? 'MCQ' : f.type === 'written' ? 'written (CER)' : 'all';
  const scope = `${escapeHtml(qpLevel)} · ${typeLabel} questions${f.topic ? ' · ' + escapeHtml(f.topic) : ''}`;
  const container = document.getElementById('qpContainer');
  if (container) container.innerHTML = `
    <div class="empty-state">
      <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" style="width:48px;height:48px;opacity:0.4;margin-bottom:12px;"><path d="M2 3h6a4 4 0 0 1 4 4v14a3 3 0 0 0-3-3H2z"/><path d="M22 3h-6a4 4 0 0 0-4 4v14a3 3 0 0 1 3-3h7z"/></svg>
      <h3>Ready to Practice</h3>
      <p>${scope}. Press Start to begin.</p>
      <button class="btn btn-primary btn-lg" onclick="startQuickPractice()" style="margin-top:16px;">
        <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" style="width:18px;height:18px;"><polygon points="5 3 19 12 5 21 5 3"/></svg>
        Start Practice
      </button>
    </div>`;
}

function onQpLevelChange() {
  populateQpControls();
  resetQpSession();
}

// Type or topic filter changed — refresh the topic list (the available topics
// depend on the chosen type) and reset the session.
function onQpFilterChange() {
  populateQpControls();
  resetQpSession();
}

// Let the AI pick the student's weakest topic and a suitable difficulty (level)
// from their performance history, then set the filters and start practising.
async function qpAiRecommend() {
  const btn = document.getElementById('qpAiRecommendBtn');
  const banner = document.getElementById('qpRecommendBanner');
  const orig = btn ? btn.innerHTML : '';
  if (btn) { btn.disabled = true; btn.innerHTML = 'Thinking…'; }
  try {
    if (!cerPerf) await loadCerPerf();
    const p = cerPerf || _emptyPerf();
    const f = qpFilters();
    const counts = qpAvailableTopics(f.type);
    const available = Object.keys(counts);
    if (!available.length) {
      showToast('No questions available to recommend from yet.', 'info');
      return;
    }

    // Per-topic accuracy from the student's record, limited to topics we can serve.
    const accByTopic = {};
    _topicAccuracy(p).forEach(x => { accByTopic[x.topic] = x; });

    let pick = null;       // { topic, level, reason }
    const aiReady = window.__aiReady && window.__aiReady();
    if (aiReady && p.attempts) {
      const lines = available.map(t => {
        const a = accByTopic[t];
        const lvl = getTopicLevel(t);
        return `- "${t}" (${lvl}, ${counts[t]} questions): ${a ? a.acc + '% over ' + a.n + ' attempts' : 'not attempted yet'}`;
      }).join('\n');
      // The rest of the student's weakness profile: skill category + question type.
      const catAcc = Object.entries(p.categories || {}).map(([c, d]) => ({ name: c, acc: d.possible ? Math.round(100 * d.score / d.possible) : 0, n: d.attempts || 0 })).filter(x => x.n > 0).sort((a, b) => a.acc - b.acc);
      const typeAcc = Object.entries(p.types || {}).map(([t, d]) => ({ name: t, acc: d.possible ? Math.round(100 * d.score / d.possible) : 0, n: d.attempts || 0 })).filter(x => x.n > 0);
      const prompt =
        `You are an adaptive primary-school science tutor choosing what a student should practise next.\n` +
        `Their overall mastery score is ${p.score100 || 0}/100 over ${p.attempts} attempts.\n` +
        `Available topics with the student's accuracy and the topic's syllabus level (P3 easiest … P6 hardest):\n${lines}\n` +
        `Accuracy by skill category (weakest first): ${catAcc.length ? catAcc.map(c => c.name + ' ' + c.acc + '%').join(', ') : 'none yet'}.\n` +
        `Accuracy by question type: ${typeAcc.length ? typeAcc.map(t => (t.name === 'open' ? 'open-ended' : 'MCQ') + ' ' + t.acc + '%').join(', ') : 'none yet'}.\n\n` +
        `Pick the ONE topic the student should practise next — prefer a weak topic (low accuracy) or an important untried one, keeping their weak skill categories in mind. ` +
        `Choose a difficulty level P3–${studentCapLevel()} (never above ${studentCapLevel()}, the student's own level): easier when struggling, harder when doing well. ` +
        `Also choose a question "type": "mcq", "written" (open-ended) or "all" — target the student's weaker type when there is a clear gap, otherwise "all". ` +
        `Return ONLY JSON: {"topic":"<exact topic from the list>","level":"P3|P4|P5|P6","type":"mcq|written|all","reason":"one short sentence to the student starting with 'Let's'"}`;
      try {
        const raw = await askGemini(prompt, { maxOutputTokens: 220, temperature: 0.3, json: true });
        const parsed = _parseAIJson(raw);
        if (parsed && parsed.topic && counts[parsed.topic]) {
          const lvl = clampToStudentLevel(/^P[3-6]$/.test(parsed.level) ? parsed.level : getTopicLevel(parsed.topic));
          const ty = /^(mcq|written|all)$/.test(parsed.type) ? parsed.type : 'all';
          pick = { topic: parsed.topic, level: lvl, type: ty, reason: parsed.reason || '' };
        }
      } catch (e) { console.warn('AI recommend failed, using local fallback', e); }
    }

    // Fallback: lowest-accuracy available topic (or one not yet attempted).
    if (!pick) {
      const scored = available.map(t => ({
        topic: t,
        acc: accByTopic[t] ? accByTopic[t].acc : -1,  // untried sorts first
        n: accByTopic[t] ? accByTopic[t].n : 0
      })).sort((a, b) => a.acc - b.acc);
      const top = scored[0];
      const lvl = clampToStudentLevel(getTopicLevel(top.topic));
      // Ease off by one level if they have been scoring low on it.
      const easedNum = top.acc >= 0 && top.acc < 50 ? Math.max(3, getLevelNumber(lvl) - 1) : getLevelNumber(lvl);
      pick = {
        topic: top.topic,
        level: 'P' + easedNum,
        type: 'all',
        reason: top.acc < 0
          ? `Let's try ${top.topic} — you haven't practised it yet!`
          : `Let's strengthen ${top.topic}, where you're scoring around ${top.acc}%.`
      };
    }

    // Apply the recommendation to the controls.
    const levelEl = document.getElementById('qpLevelSelect');
    const topicEl = document.getElementById('qpTopicSelect');
    const typeEl = document.getElementById('qpTypeSelect');
    if (levelEl) levelEl.value = pick.level;
    if (typeEl && pick.type) typeEl.value = pick.type;
    // If the chosen type can't serve this topic, fall back to "all" so we still practise it.
    if (typeEl && pick.topic && !qpAvailableTopics(typeEl.value)[pick.topic]) typeEl.value = 'all';
    populateQpControls(); // topic options depend on the type filter
    if (topicEl && qpAvailableTopics((typeEl && typeEl.value) || 'all')[pick.topic]) topicEl.value = pick.topic;

    if (banner) {
      banner.style.display = '';
      banner.innerHTML = `
        <div style="display:flex;gap:10px;align-items:center;padding:12px 14px;border:1.5px solid var(--primary);background:var(--primary-light,#e8f5e9);border-radius:var(--radius-md);">
          <span style="font-size:1.2rem;">✨</span>
          <div style="flex:1;min-width:0;font-size:0.88rem;color:var(--on-surface,#14161a);">
            <strong>AI suggestion:</strong> ${escapeHtml(pick.reason)}
            <span style="color:var(--text-muted);"> (${escapeHtml(pick.topic)} · ${escapeHtml(pick.level)})</span>
          </div>
        </div>`;
    }
    // Start practising the recommendation straight away.
    await startQuickPractice();
  } catch (e) {
    console.error('qpAiRecommend error', e);
    showToast('Could not generate a recommendation right now.', 'error');
  } finally {
    if (btn) { btn.disabled = false; btn.innerHTML = orig; }
  }
}

// ── Question-type helpers (shared by Quick Practice filters) ──────────
function qpHasWritten(q) {
  return !!(q && Array.isArray(q.blocks) && q.blocks.some(b => b && ['answer', 'plainanswer', 'openLines', 'workingSpace'].includes(b.type)));
}
function qpHasMcq(q) {
  return !!(q && Array.isArray(q.blocks) && q.blocks.some(b => b.type === 'mcq'));
}
// Does a question match the chosen practice type? ('all' | 'mcq' | 'written')
function qpMatchesType(q, typeFilter) {
  if (typeFilter === 'mcq') return qpHasMcq(q);
  if (typeFilter === 'written') return qpHasWritten(q);
  return qpHasMcq(q) || qpHasWritten(q); // 'all' — anything practiceable
}

// Read the current Quick Practice filter selections.
function qpFilters() {
  const typeEl = document.getElementById('qpTypeSelect');
  const topicEl = document.getElementById('qpTopicSelect');
  return {
    type: (typeEl && typeEl.value) || 'all',
    topic: (topicEl && topicEl.value) || ''
  };
}

// Topics that currently have practiceable questions for the chosen type,
// with a question count for each. Used to populate the topic dropdown.
function qpAvailableTopics(typeFilter) {
  const counts = {};
  questionBank.forEach(q => {
    if (!qInSyllabus(q)) return;          // not in syllabus → never offered in practice
    if (!qpMatchesType(q, typeFilter)) return;
    if (!qWithinStudentLevel(q)) return; // topics above the student's level never show
    const ts = qTopicList(q);
    (ts.length ? ts : ['General']).forEach(t => { counts[t] = (counts[t] || 0) + 1; });
  });
  return counts;
}

// Fill the topic dropdown based on the chosen type, preserving the selection
// when still valid.
function populateQpControls() {
  const sel = document.getElementById('qpTopicSelect');
  if (!sel) return;
  const prev = sel.value;
  const counts = qpAvailableTopics(qpFilters().type);
  const topics = Object.keys(counts).sort();
  let html = '<option value="">All topics</option>';
  topics.forEach(t => {
    html += `<option value="${escapeHtml(t)}">${escapeHtml(t)} (${counts[t]})</option>`;
  });
  sel.innerHTML = html;
  sel.value = (prev && counts[prev]) ? prev : '';
}

function buildQpQueue(level) {
  // Hard cap: never serve a question above the selected level, and never above
  // the student's assigned level regardless of what the dropdown says.
  const levelNum = Math.min(getLevelNumber(level), studentCapNum());
  const { type, topic } = qpFilters();
  const pool = questionBank.filter(q => {
    if (!qInSyllabus(q)) return false;             // not in syllabus → practice-excluded
    if (!qpMatchesType(q, type)) return false;
    if (topic) { const ts = qTopicList(q); if (!(ts.length ? ts.includes(topic) : topic === 'General')) return false; }
    return getLevelNumber(getTopicLevel(q.topic || '')) <= levelNum;
  });

  // Serving order: questions this student has NEVER attempted (in any mode, on
  // any device) come first, then previously attempted ones with the lowest
  // best score. Within the unattempted group, ones not served recently in
  // quick practice float to the front so back-to-back sessions stay fresh.
  const stats = _qAttemptStats || {};
  const ordered = orderByAttemptPriority(pool);
  const served = new Set(qpLoadSeen());
  const unattempted = ordered.filter(q => !stats[String(q.id)]);
  const attempted = ordered.filter(q => !!stats[String(q.id)]);
  // Recently-served demotion applies to BOTH groups: a question opened and
  // abandoned last session keeps its attempt-priority rank, so without this it
  // would lead the queue again every single sitting.
  return unattempted.filter(q => !served.has(String(q.id)))
    .concat(unattempted.filter(q => served.has(String(q.id))))
    .concat(attempted.filter(q => !served.has(String(q.id))))
    .concat(attempted.filter(q => served.has(String(q.id))));
}

// Student shortcut: jump straight into MCQ-only Quick Practice.
function startMcqPractice() {
  navigateTo('quickpractice');
  const typeEl = document.getElementById('qpTypeSelect');
  if (typeEl) typeEl.value = 'mcq';
  if (typeof onQpFilterChange === 'function') onQpFilterChange();
  startQuickPractice();
}
async function startQuickPractice() {
  _questRun = null;   // a normal practice run is not part of any encounter quest
  qpLevel = document.getElementById('qpLevelSelect').value;
  await loadAttemptStats(); // unattempted-first ordering needs the attempt log
  qpQueue = buildQpQueue(qpLevel);
  qpIndex = -1;
  qpAnswered = 0;
  qpSessionResults = [];
  if (qpQueue.length === 0) {
    document.getElementById('qpContainer').innerHTML = `
      <div class="empty-state">
        <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" style="width:48px;height:48px;opacity:0.4;margin-bottom:12px;"><circle cx="12" cy="12" r="10"/><line x1="12" y1="16" x2="12" y2="12"/><line x1="12" y1="8" x2="12.01" y2="8"/></svg>
        <h3>No Questions Available</h3>
        <p>No questions match your current filters. Try a different type, topic or level.</p>
      </div>`;
    updateQpProgress();
    return;
  }
  // Preload images before starting
  await preloadQueueImages(qpQueue);
  loadNextQpQuestion();
}

function loadNextQpQuestion() {
  rpgQuestionChanged();
  qpIndex++;
  if (qpIndex >= qpQueue.length) {
    renderQpSummary();
    updateQpProgress();
    return;
  }
  const q = qpQueue[qpIndex];
  if (q && q.id) qpMarkServed(q.id); // remember it so next session shows fresh ones first
  renderQpQuestion(q);
  updateQpProgress();
}

function _recordQpResult(correct, total, mistakes) {
  const q = qpQueue[qpIndex] || {};
  qpSessionResults.push({
    title: q.title || '',
    topic: q.topic || '',
    correct, total,
    mistakes: mistakes || []
  });
  // Performance + the battle round are already recorded by the marking flow
  // (markOpenAnswersIn / _checkAllPartsMarked). Recording again here ran the
  // battle TWICE per question — double XP/gold and an extra enemy hit.
}

// Shared, styled end-of-practice report (used by Quick/Worksheet and Topical).
function _reportColor(pct) {
  return pct >= 80 ? 'var(--primary)' : pct >= 50 ? 'var(--accent-orange)' : 'var(--accent-red)';
}
function _fmtScore(n) { return Number.isInteger(n) ? String(n) : n.toFixed(1); }

function renderPracticeReport(containerSel, results, actionsHtml) {
  const host = document.querySelector(containerSel);
  if (!host) return;
  const totalCorrect = results.reduce((s, r) => s + r.correct, 0);
  const totalBlanks = results.reduce((s, r) => s + r.total, 0);
  const pct = totalBlanks ? Math.round((totalCorrect / totalBlanks) * 100) : 0;
  const color = _reportColor(pct);

  const R = 52, C = 2 * Math.PI * R, dash = C * (pct / 100);
  const ring = `
    <svg viewBox="0 0 120 120" style="width:130px;height:130px;transform:rotate(-90deg);">
      <circle cx="60" cy="60" r="${R}" fill="none" stroke="var(--surface-container-high,#f2f4f3)" stroke-width="11"/>
      <circle cx="60" cy="60" r="${R}" fill="none" stroke="${color}" stroke-width="11" stroke-linecap="round"
              stroke-dasharray="${dash.toFixed(1)} ${(C - dash).toFixed(1)}" style="transition:stroke-dasharray .6s ease;"/>
    </svg>`;

  const breakdown = results.map((r, i) => {
    const full = r.total && r.correct === r.total;
    const part = r.correct > 0 && !full;
    const badge = full ? '✓' : part ? '◑' : '✗';
    const bcol = full ? 'var(--primary)' : part ? 'var(--accent-orange)' : 'var(--accent-red)';
    return `<div style="display:flex;align-items:center;gap:10px;padding:9px 12px;border-radius:10px;background:var(--surface-container-low,#f7f9f8);margin-bottom:6px;">
        <span style="flex-shrink:0;width:22px;height:22px;border-radius:50%;background:${bcol};color:#fff;display:inline-flex;align-items:center;justify-content:center;font-size:0.72rem;font-weight:700;">${badge}</span>
        <span style="flex:1;font-size:0.86rem;color:var(--on-surface,#14161a);min-width:0;">${i + 1}. ${escapeHtml(r.title || r.topic || 'Question')}</span>
        <span style="font-weight:700;font-size:0.86rem;color:${bcol};white-space:nowrap;">${_fmtScore(r.correct)}/${r.total}</span>
      </div>`;
  }).join('');

  host.innerHTML = `
    <div class="practice-card" style="max-width:840px;margin:0 auto;padding:0;overflow:hidden;">
      <div style="text-align:center;padding:28px 20px 20px;background:linear-gradient(180deg,var(--primary-light,#e8f5e9),transparent);">
        <div style="position:relative;display:inline-block;">
          ${ring}
          <div style="position:absolute;inset:0;display:flex;flex-direction:column;align-items:center;justify-content:center;">
            <div style="font-size:1.8rem;font-weight:800;color:${color};line-height:1;">${pct}%</div>
            <div style="font-size:0.8rem;color:var(--text-muted);margin-top:2px;">${_fmtScore(totalCorrect)} / ${totalBlanks}</div>
          </div>
        </div>
        <h3 style="margin:14px 0 2px;font-size:1.3rem;">Practice Complete! 🎉</h3>
        <div style="font-size:0.85rem;color:var(--text-muted);">across ${results.length} question${results.length !== 1 ? 's' : ''}</div>
      </div>
      <div style="padding:4px 20px 0;">
        <div style="font-weight:700;font-size:0.78rem;text-transform:uppercase;letter-spacing:0.05em;color:var(--text-muted);margin:8px 0 10px;">Question breakdown</div>
        ${breakdown}
      </div>
      <div id="practiceReportFeedback" style="padding:8px 20px 0;"></div>
      <div style="display:flex;gap:10px;justify-content:center;flex-wrap:wrap;padding:20px;">
        ${actionsHtml}
      </div>
    </div>`;

  generatePracticeFeedback('practiceReportFeedback', results, totalCorrect, totalBlanks, pct);
}

async function generatePracticeFeedback(boxId, results, totalCorrect, totalBlanks, pct) {
  const box = document.getElementById(boxId);
  if (!box || !results.length) return;
  if (!window.__aiReady || !window.__aiReady()) {
    box.innerHTML = `<div style="font-size:0.85rem;color:var(--text-muted);text-align:center;padding:8px;">AI feedback isn't set up yet.</div>`;
    return;
  }
  box.innerHTML = `<div style="display:flex;align-items:center;justify-content:center;gap:8px;color:var(--text-muted);font-size:0.88rem;padding:14px;">
      <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" style="width:16px;height:16px;animation:spin 1s linear infinite;"><path d="M21 12a9 9 0 1 1-6.219-8.56"/></svg>
      Generating your personalised feedback…
    </div>`;

  const lines = results.map((r, i) => {
    const m = r.mistakes && r.mistakes.length
      ? r.mistakes.map(x => `${x.expected}→${x.student || '(blank)'}`).join('; ')
      : 'none';
    return `${i + 1}. Topic "${r.topic}" — score ${_fmtScore(r.correct)}/${r.total}; mistakes: ${m}`;
  }).join('\n');

  const prompt =
    `You are an encouraging primary-school science tutor giving end-of-practice feedback to a student.\n` +
    `Overall score: ${_fmtScore(totalCorrect)}/${totalBlanks} (${pct}%).\n` +
    `Per-question results (expected→student shows their mistakes):\n${lines}\n\n` +
    `Write feedback addressed directly to the student ("you"). Be specific to the topics and mistakes above, warm and constructive.\n` +
    `Give EXACTLY 5 strengths and EXACTLY 5 weaknesses (areas to improve), each a short specific phrase.\n` +
    `Return ONLY JSON: {"summary":"2-3 encouraging sentences","strengths":["..."],"weaknesses":["..."]}`;

  let fb;
  try {
    const raw = await askGemini(prompt, { maxOutputTokens: 900, temperature: 0.5, json: true });
    fb = _parseAIJson(raw);
  } catch (e) {
    console.error('Practice feedback error:', e);
    box.innerHTML = `<div style="font-size:0.85rem;color:var(--accent-red);text-align:center;padding:8px;">Couldn't generate feedback: ${escapeHtml(e && e.message ? e.message : String(e))}</div>`;
    return;
  }

  const items = (arr, color, icon) => (Array.isArray(arr) ? arr : []).slice(0, 5).map(t =>
    `<li style="display:flex;gap:8px;align-items:flex-start;margin-bottom:8px;font-size:0.85rem;line-height:1.45;">
       <span style="flex-shrink:0;color:${color};font-weight:800;">${icon}</span><span>${escapeHtml(String(t))}</span>
     </li>`).join('');

  box.innerHTML = `
    <div style="background:var(--surface-container-low,#f7f9f8);border-radius:14px;padding:16px 18px;">
      ${fb.summary ? `<p style="font-size:0.92rem;line-height:1.55;margin:0 0 14px;color:var(--on-surface,#14161a);">${escapeHtml(fb.summary)}</p>` : ''}
      <div style="display:grid;grid-template-columns:repeat(auto-fit,minmax(240px,1fr));gap:14px;">
        <div style="background:var(--primary-light,#e8f5e9);border:1px solid var(--primary);border-radius:12px;padding:13px 15px;">
          <div style="font-weight:800;font-size:0.82rem;color:var(--primary);margin-bottom:9px;">💪 Strengths</div>
          <ul style="list-style:none;padding:0;margin:0;color:var(--on-surface,#14161a);">${items(fb.strengths, 'var(--primary)', '✓')}</ul>
        </div>
        <div style="background:var(--accent-orange-light,#fff3e0);border:1px solid var(--accent-orange);border-radius:12px;padding:13px 15px;">
          <div style="font-weight:800;font-size:0.82rem;color:var(--accent-orange);margin-bottom:9px;">🎯 Areas to improve</div>
          <ul style="list-style:none;padding:0;margin:0;color:var(--on-surface,#14161a);">${items(fb.weaknesses, 'var(--accent-orange)', '→')}</ul>
        </div>
      </div>
    </div>`;
}

