// =====================================================================
// PERFORMANCE TRACKING + AI REPORT (students) + explanation reveal
// =====================================================================
let cerPerf = null; // in-memory performance profile for the signed-in student
function _emptyPerf() { return { attempts: 0, totalScore: 0, totalPossible: 0, topics: {}, categories: {}, recent: [], score100: 0 }; }
function _computeScore100(p) {
  const rec = (p.recent || []).slice(-30);
  if (rec.length) return Math.round(rec.reduce((s, r) => s + (r.pct || 0), 0) / rec.length);
  return p.totalPossible ? Math.round(100 * p.totalScore / p.totalPossible) : 0;
}
async function loadCerPerf() {
  if (!currentUser) { cerPerf = _emptyPerf(); return; }
  try {
    const s = await getDoc(doc(db, 'users', currentUser.uid, 'stats', 'performance'));
    cerPerf = s.exists() ? Object.assign(_emptyPerf(), s.data()) : _emptyPerf();
  } catch (e) { console.warn('perf load', e); cerPerf = _emptyPerf(); }
}
// Called after EVERY marking so the report always reflects the latest work.
function recordCerPerformance(q, score, total, mode, answerText) {
  try { rpgOnMarked(q, score, total, { mode, answerText }); } catch (e) { console.warn('rpg reward', e); }
  if (!currentUser || currentUser.role !== 'student' || !q || !total) return;
  if (!cerPerf) cerPerf = _emptyPerf();
  const p = cerPerf;
  const topic = q.topic || 'General';
  const category = normalizeCategoryValue(q.category) || 'CER';
  const pct = Math.max(0, Math.min(100, Math.round((score / total) * 100)));
  p.attempts = (p.attempts || 0) + 1;
  p.totalScore = (p.totalScore || 0) + score;
  p.totalPossible = (p.totalPossible || 0) + total;
  p.topics = p.topics || {}; p.categories = p.categories || {};
  (p.topics[topic] = p.topics[topic] || { score: 0, possible: 0, attempts: 0 });
  p.topics[topic].score += score; p.topics[topic].possible += total; p.topics[topic].attempts++;
  (p.categories[category] = p.categories[category] || { score: 0, possible: 0, attempts: 0 });
  p.categories[category].score += score; p.categories[category].possible += total; p.categories[category].attempts++;
  // Track strength by question type too (mcq vs open) — part of the weakness profile.
  const qType = qpHasMcq(q) ? 'mcq' : 'open';
  p.types = p.types || {};
  (p.types[qType] = p.types[qType] || { score: 0, possible: 0, attempts: 0 });
  p.types[qType].score += score; p.types[qType].possible += total; p.types[qType].attempts++;
  p.recent = p.recent || [];
  p.recent.push({ pct, topic, category, type: qType, title: q.title || '', mode: mode || '', at: new Date().toISOString() });
  if (p.recent.length > 50) p.recent = p.recent.slice(-50);
  p.score100 = _computeScore100(p);
  p.updatedAt = new Date().toISOString();
  setDoc(doc(db, 'users', currentUser.uid, 'stats', 'performance'), p, { merge: true }).catch(e => console.warn('perf save', e));
  setDoc(doc(db, 'cerLeaderboard', currentUser.uid), {
    name: currentUser.name || '', email: currentUser.email || '',
    score100: p.score100, attempts: p.attempts, updatedAt: p.updatedAt
  }, { merge: true }).catch(e => console.warn('leaderboard save', e));
}
function _scoreColor(s) { return s >= 80 ? 'var(--primary)' : s >= 55 ? 'var(--accent-orange)' : 'var(--accent-red)'; }
function _topicAccuracy(p) {
  return Object.entries(p.topics || {})
    .map(([t, d]) => ({ topic: t, acc: d.possible ? Math.round(100 * d.score / d.possible) : 0, n: d.attempts || 0 }))
    .filter(x => x.n > 0);
}
// =====================================================================
// STUDENT HOME — one simple screen: continue today's practice, questions
// due for review, weakest topic, recent progress, and one Games button.
// =====================================================================
let _homeWeakestTopic = '';

// Questions this student has attempted but never fully cracked (best < 100%),
// weakest and least-recently-tried first. In-syllabus, within level, markable.
function _homeReviewPool() {
  const stats = _qAttemptStats || {};
  const pool = (questionBank || []).filter(q => {
    if (!q || q.id == null) return false;
    if (!questionHasMarkableAnswer(q) || !qInSyllabus(q) || !qWithinStudentLevel(q)) return false;
    const r = stats[String(q.id)];
    return !!(r && r.n > 0 && (r.best || 0) < 1);
  });
  const best = q => (stats[String(q.id)] && stats[String(q.id)].best) || 0;
  const last = q => (stats[String(q.id)] && stats[String(q.id)].last) || 0;
  return pool.sort((a, b) => (best(a) - best(b)) || (last(a) - last(b)));
}

async function renderHomePage() {
  const c = document.getElementById('homeContainer');
  if (!c) return;
  const first = ((currentUser && currentUser.name) || '').trim().split(/\s+/)[0] || '';
  const g = document.getElementById('homeGreeting');
  if (g) g.textContent = first ? `👋 Hi, ${first}!` : '🏠 Home';
  c.innerHTML = '<div style="padding:40px;text-align:center;color:var(--text-muted);">Loading your day…</div>';
  try { await loadAttemptStats(); } catch (_) {}
  try { if (!cerPerf) await loadCerPerf(); } catch (_) {}
  const p = cerPerf || _emptyPerf();

  // Today's practice (the 10-a-day goal that also feeds the voucher streak).
  const s = (rpgState && rpgState.streak) || {};
  const todayQ = (s.dayKey === advToday()) ? (s.dayMarks || 0) : 0;
  const goal = 10;
  const streakDays = s.count || 0;

  // Due for review + weakest topic (needs 2+ attempts to be meaningful).
  const review = _homeReviewPool();
  const topics = _topicAccuracy(p).sort((a, b) => (a.acc - b.acc) || (b.n - a.n));
  const weakest = topics.find(t => t.n >= 2) || topics[0] || null;
  _homeWeakestTopic = weakest ? weakest.topic : '';

  // Recent progress: last five marked questions, newest first.
  const recent = (p.recent || []).slice(-5).reverse();
  const recentRows = recent.map(r => {
    const col = r.pct >= 80 ? 'var(--primary)' : r.pct >= 50 ? 'var(--accent-orange)' : 'var(--accent-red)';
    return `<div class="home-recent-row">
      <span style="flex:1;min-width:0;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;">${escapeHtml(r.title || r.topic || 'Question')}</span>
      <span style="color:var(--text-muted);font-size:0.76rem;flex:0 0 auto;">${escapeHtml(r.topic || '')}</span>
      <b style="color:${col};flex:0 0 auto;">${Number(r.pct) || 0}%</b>
    </div>`;
  }).join('');

  const pctToday = Math.min(100, Math.round((todayQ / goal) * 100));
  // Revision cards, but only when there is something to do with them — a card
  // that always says "nothing waiting" is a card nobody reads.
  let fcDue = 0, fcTopGap = null;
  try { fcDue = fcDecks.reduce((s, d) => s + fcDueCards(d).length, 0); } catch (_) {}
  try { if (!fcDue) fcTopGap = fcGaps(1)[0] || null; } catch (_) {}
  const fcCardHtml = (fcDue || fcTopGap) ? `
      <div class="home-card">
        <h3>🃏 Revision cards</h3>
        ${fcDue ? `
        <div class="home-big">${fcDue}<span style="font-size:1.05rem;color:var(--text-muted);font-weight:600;"> card${fcDue === 1 ? '' : 's'} due</span></div>
        <div class="home-sub">Written from your own mistakes. Five minutes here beats half an hour of reading.</div>
        <button class="btn btn-blue" onclick="navigateTo('flashcards')">Revise now</button>` : `
        <div class="home-big" style="font-size:1.35rem;">${escapeHtml(fcTopGap.label)}</div>
        <div class="home-sub">This is what's costing you the most marks. I can turn it into flashcards in one tap.</div>
        <button class="btn btn-blue" onclick="navigateTo('flashcards')">Make my cards</button>`}
      </div>` : '';
  c.innerHTML = `
    <div class="home-grid">
      <div class="home-card wide">
        <h3>📘 Today's practice</h3>
        <div class="home-big">${Math.min(todayQ, goal)}<span style="font-size:1.05rem;color:var(--text-muted);font-weight:600;"> / ${goal} questions</span></div>
        <div class="home-bar"><div class="home-bar-fill" style="width:${pctToday}%;"></div></div>
        <div class="home-sub">${todayQ >= goal ? '🎉 Daily goal done — anything more is bonus!' : streakDays ? `🔥 ${streakDays}-day streak — answer ${goal - todayQ} more to keep today counting.` : 'Answer questions every day to build a practice streak.'}</div>
        <button class="btn btn-primary btn-lg" onclick="homeContinuePractice()">
          <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" style="width:16px;height:16px;"><polygon points="5 3 19 12 5 21 5 3"/></svg>
          ${todayQ > 0 ? "Continue today's practice" : "Start today's practice"}
        </button>
      </div>
      <div class="home-card">
        <h3>🔁 Due for review</h3>
        <div class="home-big">${review.length}<span style="font-size:1.05rem;color:var(--text-muted);font-weight:600;"> question${review.length === 1 ? '' : 's'}</span></div>
        <div class="home-sub">${review.length ? "Ones you haven't fully cracked yet — beat your best score." : "Nothing waiting — everything you've tried is mastered!"}</div>
        ${review.length ? `<button class="btn btn-blue" onclick="homeStartReview()">Review ${Math.min(review.length, 10)} now</button>` : ''}
      </div>
      <div class="home-card">
        <h3>🎯 Weakest topic</h3>
        ${weakest ? `
        <div class="home-big" style="font-size:1.35rem;">${escapeHtml(weakest.topic)}</div>
        <div class="home-sub">${weakest.acc}% correct over ${weakest.n} attempt${weakest.n === 1 ? '' : 's'} — a little focus goes a long way.</div>
        <button class="btn btn-blue" onclick="homePractiseWeakest()">Practise this topic</button>` : `
        <div class="home-sub">Answer a few questions and your weakest topic will show up here with a one-tap practice button.</div>`}
      </div>
      ${fcCardHtml}
      <div class="home-card wide">
        <h3>🧭 Not sure what to do?</h3>
        <div class="home-sub">The menu is long and you only need a few of it. Ask Ai-nstein and he'll lay out the next step as buttons — nothing to hunt for, and these three cost you nothing.</div>
        <div class="home-guide-row">
          <button class="btn btn-outline" onclick="ainsteinGuideLocal('tour')">🧭 How do I use this?</button>
          <button class="btn btn-outline" onclick="ainsteinGuideLocal('lost')">🤷 I'm lost — what now?</button>
          <button class="btn btn-outline" onclick="ainsteinGuideLocal('psle')">📄 Suggest a PSLE paper</button>
        </div>
      </div>
      <div class="home-card wide">
        <h3>📈 Recent progress</h3>
        ${recent.length ? `
        <div class="home-sub">Performance score <b style="color:${_scoreColor(p.score100 || 0)};">${p.score100 || 0}/100</b> · ${p.attempts || 0} question${(p.attempts || 0) === 1 ? '' : 's'} marked so far.</div>
        <div>${recentRows}</div>
        <button class="btn btn-outline" onclick="navigateTo('myreport')">View full report</button>` : `
        <div class="home-sub">Your last few marked questions will appear here once you start practising.</div>`}
      </div>
      <div class="home-card wide" style="align-items:center;text-align:center;">
        <div style="font-size:2.4rem;line-height:1;">🕹️</div>
        <h3 style="justify-content:center;">Games</h3>
        <div class="home-sub" style="max-width:420px;">All five science games live in the Arcade. Every play costs 1 game credit — practice earns you more.</div>
        <button class="btn btn-primary btn-lg" onclick="navigateTo('arcade')" style="align-self:center;">Open the Arcade</button>
      </div>
    </div>`;
}

// Home actions — each hands over to an existing practice surface.
function homeContinuePractice() {
  navigateTo('quickpractice');
  startQuickPractice();
}
function homeStartReview() {
  const pool = _homeReviewPool();
  if (!pool.length) { showToast('Nothing to review — great work!', 'success'); return; }
  _questRun = null;
  qpQueue = pool.slice(0, 10);
  qpIndex = -1;
  qpAnswered = 0;
  qpSessionResults = [];
  navigateTo('quickpractice');
  showToast('🔁 Review session — beat your old scores!', 'info');
  preloadQueueImages(qpQueue).then(() => loadNextQpQuestion()).catch(() => loadNextQpQuestion());
}
function homePractiseWeakest() {
  navigateTo('topicalpractice');
  if (_homeWeakestTopic) tpStartTopic(_homeWeakestTopic);
}

