function rpgWeaponElement(id) {
  const s = String(id || "");
  if (/flame|ember|dragon|phoenix/.test(s)) return "fire";
  if (/frost|glacier|penguin/.test(s)) return "ice";
  if (/oak|sprout|rune|elven|emerald/.test(s)) return "nature";
  if (/void|shadow|obsidian/.test(s)) return "shadow";
  if (/sun|excalibur|golden|gilded|crown|royal/.test(s)) return "holy";
  if (/star|comet|storm|arcane|crystal|wisp/.test(s)) return "arcane";
  return "neutral";
}
