const RPG_TREE_BY_ID = {};
Object.keys(RPG_TREE).forEach(c => RPG_TREE[c].forEach(n => { n.clazz = c; RPG_TREE_BY_ID[n.id] = n; }));
function rpgSkillRank(id) { return (rpgState && rpgState.skills && rpgState.skills[id]) || 0; }
function rpgSkillPointsSpent() { return rpgState ? Object.values(rpgState.skills || {}).reduce((a, b) => a + b, 0) : 0; }
function rpgSkillPointsEarned() {
  const L = rpgLevelInfo().level;
  return Math.min(L - 1, 30) + Math.max(0, Math.floor((L - 30) / 2));
}
