  const kind = rpgWeaponFx(it.id).kind;
  if (rpgState.clazz === "warrior") return kind !== "ranged" && kind !== "magic"; // face-to-face only
  if (rpgState.clazz === "mage") return kind === "magic" || kind === "ranged";   // never melee
