function rpgItemIconSvg(it) {
  const box = it.box || RPG_SLOT_META[it.slot].box;
  if (_rpgArt[it.id]) {
    const [bx, by, bw, bh] = box.split(" ").map(Number);
    return `<svg viewBox="${box}" xmlns="http://www.w3.org/2000/svg"><image href="${escapeHtml(_rpgArt[it.id])}" x="${bx}" y="${by}" width="${bw}" height="${bh}" preserveAspectRatio="xMidYMid meet" style="image-rendering:pixelated;"/></svg>`;
  }
  const rank = RPG_RARITY[it.rarity].rank;
  const [bx, by, bw, bh] = box.split(" ").map(Number);
  const cx = bx + bw / 2, cy = by + bh / 2;
  const auraColor = rank === 6 ? "#ff7ab8" : rank === 5 ? "#ffd76a" : "#b88ae8";
  const aura = rank >= 4
    ? `<ellipse cx="${cx}" cy="${cy}" rx="${(bw * (rank === 6 ? 0.34 : 0.3)).toFixed(1)}" ry="${(bh * (rank === 6 ? 0.42 : 0.38)).toFixed(1)}" fill="${auraColor}" opacity="${rank === 6 ? "0.32" : rank === 5 ? "0.28" : "0.22"}">${rank >= 5 ? svgPulse(0.18, 0.36) : ""}</ellipse>`
    : "";
  const spark = rank >= 5
    ? `<g>${svgStar(bx + bw * 0.18, by + bh * 0.22, bw * 0.05, bw * 0.022, "#fff")}${svgTwinkle(2)}</g><g>${svgStar(bx + bw * 0.84, by + bh * 0.58, bw * 0.04, bw * 0.018, rank === 6 ? "#ff9ad1" : "#ffe9a3")}${svgTwinkle(1.5)}</g>${rank === 6 ? `<g>${svgStar(bx + bw * 0.78, by + bh * 0.18, bw * 0.045, bw * 0.02, "#ffd76a")}${svgTwinkle(1.2)}</g>` : ""}`
    : "";
  const art = it.slot === "pet" && rpgPetEvoEmoji(it) ? svgPetEmoji(rpgPetEvoEmoji(it)) : it.art();
  return `<svg viewBox="${box}" xmlns="http://www.w3.org/2000/svg">${aura}${art}${spark}</svg>`;
}

// ---- Codex: bestiary tiers, titles, houses ----
function rpgKillTier(enemyId) {
  const k = (rpgState && rpgState.kills && rpgState.kills[enemyId]) || 0;
  return k >= 500 ? 3 : k >= 100 ? 2 : k >= 10 ? 1 : 0;
}
function rpgCreditKill(enemyId) {
  if (!rpgState || !enemyId) return;
  const before = rpgKillTier(enemyId);
  rpgState.kills[enemyId] = (rpgState.kills[enemyId] || 0) + 1;
  const after = rpgKillTier(enemyId);
  if (after > before) {
    const e = RPG_ENEMIES_BY_ID[enemyId];
    toast(`📖 Bestiary: ${e ? e.name : enemyId} mastery ${"★".repeat(after)} — +${after}% damage vs them!`, "success");
  }
}
const RPG_TITLES = [
  { id: "slayer1", name: "Monster Hunter", icon: "⚔️", test: () => Object.values(rpgState.kills || {}).reduce((a, b) => a + b, 0) >= 100 },
  { id: "slayer2", name: "Centurion", icon: "🏛️", test: () => Object.values(rpgState.kills || {}).reduce((a, b) => a + b, 0) >= 1000 },
  { id: "crawler", name: "Floor Crawler", icon: "🪜", test: () => (rpgState.stats.bestFloor || 0) >= 10 },
  { id: "delver", name: "Deep Delver", icon: "🏰", test: () => (rpgState.stats.bestFloor || 0) >= 25 },
  { id: "mythic", name: "Mythic Hunter", icon: "✦", test: () => RPG_ITEMS.some(it => it.rarity === "mythic" && rpgState.inventory[it.id]) },
  { id: "collect", name: "Collector", icon: "📦", test: () => Object.keys(rpgState.inventory || {}).length >= 50 },
  { id: "packrat", name: "Pack Rat", icon: "🎁", test: () => (rpgState.stats.packsOpened || 0) >= 20 },
  { id: "duelist", name: "Duelist", icon: "👻", test: () => (rpgState.stats.arenaWins || 0) >= 10 },
  { id: "scholar", name: "Grand Scholar", icon: "📚", test: () => (rpgState.stats.marked || 0) >= 500 },
  { id: "reborn", name: "Starborn", icon: "🌠", test: () => (rpgState.rebirths || 0) >= 1 }
];
function rpgEarnedTitles() { return rpgState ? RPG_TITLES.filter(t => { try { return t.test(); } catch (_) { return false; } }) : []; }
const RPG_HOUSES = [
  { id: "dragons", name: "Dragons", icon: "🐉", color: "#9c2c2c" },
  { id: "phoenix", name: "Phoenix", icon: "🔥", color: "#b7791f" },
  { id: "griffins", name: "Griffins", icon: "🦅", color: "#27406b" },
  { id: "krakens", name: "Krakens", icon: "🐙", color: "#4b3a63" }
];
function rpgHouseOf(uid) {
  let h = 0;
  String(uid || "").split("").forEach(ch => { h = (h * 31 + ch.charCodeAt(0)) % 9973; });
  return RPG_HOUSES[h % 4];
}
function rpgCodexTabHtml() {
  const totalKills = Object.values(rpgState.kills || {}).reduce((a, b) => a + b, 0);
  const beasts = RPG_ENEMIES.map(e => {
    const k = (rpgState.kills || {})[e.id] || 0;
    const tier = rpgKillTier(e.id);
    return `<div class="cdx-beast ${k ? "" : "unknown"}" title="${escapeHtml(e.name)} — ${k} slain${tier ? `, +${tier}% damage` : ""}">
      <span class="cdx-emoji">${k ? e.emoji : "❔"}</span>
      <span class="cdx-count">${k ? k : "?"}</span>
      <span class="cdx-stars">${"★".repeat(tier)}</span>
    </div>`;
  }).join("");
  const ranks = ["common", "uncommon", "rare", "epic", "legendary", "mythic"].map(r => {
    const all = RPG_ITEMS.filter(it => it.rarity === r && (it.price > 0 || it.packOnly));
    const own = all.filter(it => rpgState.inventory[it.id]).length;
    return `<div class="rpg-quest"><span class="rpg-quest-ico" style="color:${RPG_RARITY[r].color};">●</span><span class="rpg-quest-name">${RPG_RARITY[r].label} <b>${own}/${all.length}</b></span><span class="rpg-quest-reward">${Math.round(own / Math.max(1, all.length) * 100)}%</span></div>`;
  }).join("");
  const titles = RPG_TITLES.map(t => {
    const got = rpgEarnedTitles().some(x => x.id === t.id);
    return `<span class="rpg-set-chip ${got ? "on" : ""}">${t.icon} ${t.name}</span>`;
  }).join("");
  const house = rpgHouseOf(currentUser && currentUser.uid);
  return `<div class="section-label">Your house</div>
    <div class="rpg-quest"><span class="rpg-quest-ico">${house.icon}</span><span class="rpg-quest-name">House <b>${house.name}</b> — earn XP to win the monthly house race!</span></div>
    <div class="section-label" style="margin-top:12px;">Bestiary — ${totalKills} monsters slain (mastery = bonus damage)</div>
    <div class="cdx-grid">${beasts}</div>
    <div class="section-label" style="margin-top:12px;">Collection</div>${ranks}
    <div class="section-label" style="margin-top:12px;">Titles</div><div class="rpg-set-row">${titles}</div>`;
}
// ---- Starfall rebirth (prestige at level 60+) ----
function rpgRebirth() {
  if (!rpgState) return;
  const lvl = rpgLevelInfo().level;
  if (lvl < 60) { toast("Starfall unlocks at level 60", "error"); return; }
  let shards = (lvl - 50) + Math.floor((rpgState.stats.bestFloor || 0) / 10);
  if (lvl >= 99) shards = Math.round(shards * 1.5);
  if (!confirm(`⭐ STARFALL — begin again at level 1 for ${shards} Star Shards?\n\nYOU KEEP: all items, gold, pets, upgrades, collections.\nRESETS: level, skill points (refunded), path seal.\nYour gear remembers you — level requirements no longer apply.`)) return;
  rpgState.shards = (rpgState.shards || 0) + shards;
  rpgState.rebirths = (rpgState.rebirths || 0) + 1;
  rpgState.xpBaseline = rpgState.xp;
  rpgState.skills = {};
  rpgState.paths = {};
  rpgState.advRuns = null;
  rpgState.hp = rpgPlayerStats().maxHp;
  rpgSave();
  rpgPublishLeaderboard();
  rpgRenderCharacterPage();
  rpgRenderSide();
  toast(`⭐ STARFALL! +${shards} Star Shards — Rebirth ${rpgState.rebirths}`, "success");
}
const RPG_STAR_SHOP = [
  { id: "gold", name: "Stargold", icon: "🪙", desc: "+5% gold per rank", max: 10, cost: r => 5 * (r + 1) },
  { id: "learn", name: "Starlearn", icon: "📚", desc: "+5% XP per rank", max: 10, cost: r => 5 * (r + 1) },
  { id: "raids", name: "Star Raids", icon: "🏰", desc: "+1 game credit per day", max: 2, cost: () => 40 },
  { id: "nova", name: "Nova the Star-Dragon", icon: "🌟", desc: "Exclusive mythic pet", max: 1, cost: () => 100 }
];
function rpgBuyStar(id) {
  const s = RPG_STAR_SHOP.find(x => x.id === id);
  if (!s || !rpgState) return;
  const cur = id === "nova" ? (rpgState.star.nova ? 1 : 0) : (rpgState.star[id] || 0);
  if (cur >= s.max) return;
  const cost = s.cost(cur);
  if ((rpgState.shards || 0) < cost) { toast(`Need ${cost} Star Shards — rebirth to earn more!`, "error"); return; }
  rpgState.shards -= cost;
  if (id === "nova") { rpgState.star.nova = true; rpgState.inventory.nova_dragon = 1; }
  else rpgState.star[id] = cur + 1;
  rpgSave();
  rpgRenderCharacterPage();
  toast(`⭐ ${s.name}!`, "success");
}
function rpgStarShopHtml() {
  if (!rpgState || (rpgLevelInfo().level < 60 && !(rpgState.rebirths > 0))) return "";
  const rows = RPG_STAR_SHOP.map(s => {
    const cur = s.id === "nova" ? (rpgState.star.nova ? 1 : 0) : (rpgState.star[s.id] || 0);
    const maxed = cur >= s.max;
    return `<div class="rpg-quest"><span class="rpg-quest-ico">${s.icon}</span>
      <span class="rpg-quest-name">${s.name} <b>${cur}/${s.max}</b> — ${s.desc}</span>
      ${maxed ? `<span class="rpg-quest-claimed">MAX</span>` : `<button class="btn btn-ghost btn-sm" type="button" data-rpg-star="${s.id}">⭐ ${s.cost(cur)}</button>`}</div>`;
  }).join("");
  return `<div class="section-label" style="margin-top:16px;">⭐ Starfall — rebirth ${rpgState.rebirths || 0} · ${rpgState.shards || 0} shards</div>
    ${rows}
    <button class="btn btn-primary" type="button" data-rpg-rebirth style="margin-top:8px;">🌠 STARFALL — rebirth for Star Shards</button>`;
}
// ---- Daily quests & practice streak ----
const RPG_QUESTS = [
  { id: "q_mark5", icon: "✍️", name: "Answer 5 questions", key: "marked", need: 5, gold: 50 },
  { id: "q_correct3", icon: "✅", name: "Get 3 questions right", key: "correct", need: 3, gold: 60 },
  { id: "q_wins4", icon: "⚔️", name: "Win 4 battles", key: "wins", need: 4, gold: 45 },
  { id: "q_raid", icon: "🏰", name: "Finish a dungeon raid", key: "advRunsDone", need: 1, gold: 55 },
  { id: "q_floors3", icon: "🪜", name: "Clear 3 dungeon floors", key: "floorsCleared", need: 3, gold: 60 },
  // No quest may be completable by a button that can be pressed again and
  // again for free. "Win an arena duel" was retired for exactly that reason:
  // duels cost no game credit, so it paid 🪙 50 a day for one click.
  { id: "q_correct8", icon: "🎯", name: "Get 8 questions right", key: "correct", need: 8, gold: 50 },
  { id: "q_gold150", icon: "🪙", name: "Earn 150 gold", key: "goldEarned", need: 150, gold: 45 },
  { id: "q_packs", icon: "🎁", name: "Open a booster pack", key: "packsOpened", need: 1, gold: 40 }
];
function rpgEnsureDaily() {
  if (!rpgState) return;
  const day = advToday();
  const cur = rpgState.daily;
  // A retired quest id left in a saved daily set has no entry to read `need`
  // from and would break the quest list, so re-roll the day whenever one of
  // today's picks is no longer in RPG_QUESTS.
  const stale = !!cur && (!Array.isArray(cur.quests) || cur.quests.some(id => !RPG_QUESTS.some(q => q.id === id)));
  if (cur && cur.day === day) {
    if (!stale) return;
    // Same day, but a pick was retired under the student's feet. Swap ONLY the
    // dead slots and mark them spent — re-rolling the whole day here would
    // hand a second full set of quest rewards to anyone who already claimed.
    cur.quests = cur.quests.map((id, i) => {
      if (RPG_QUESTS.some(q => q.id === id)) return id;
      cur.claimed[i] = true;
      return RPG_QUESTS[0].id;
    });
    rpgSave();
    return;
  }
  const seed = day.split("-").join("") * 7 + (currentUser ? currentUser.uid.length : 0);
  const picks = [];
  for (let i = 0; picks.length < 3 && i < 24; i++) {
    const q = RPG_QUESTS[(seed + i * 5) % RPG_QUESTS.length];
    if (!picks.includes(q.id)) picks.push(q.id);
  }
  const base = {};
  RPG_QUESTS.forEach(q => { base[q.key] = (rpgState.stats && rpgState.stats[q.key]) || 0; });
  rpgState.daily = { day, quests: picks, base, claimed: [false, false, false] };
  rpgSave();
}
function rpgQuestProgress(q) {
  const cur = (rpgState.stats && rpgState.stats[q.key]) || 0;
  return Math.max(0, cur - ((rpgState.daily.base && rpgState.daily.base[q.key]) || 0));
}
function rpgClaimQuest(i) {
  rpgEnsureDaily();
  const d = rpgState.daily;
  const q = RPG_QUESTS.find(x => x.id === d.quests[i]);
  if (!q || d.claimed[i] || rpgQuestProgress(q) < q.need) return;
  d.claimed[i] = true;
  if (i === 2) {
    rpgState.packCoupon = 1;
    toast("🎟️ Quest complete — your next booster pack is HALF PRICE!", "success");
  } else {
    rpgState.gold += q.gold;
    toast(`📜 Quest complete: +🪙 ${q.gold}!`, "success");
  }
  rpgSave();
  rpgRenderCharacterPage();
}
function rpgQuestsHtml() {
  rpgEnsureDaily();
  const s = rpgState.streak || { count: 0, best: 0 };
  const rows = rpgState.daily.quests.map((qid, i) => {
    const q = RPG_QUESTS.find(x => x.id === qid);
    if (!q) return "";   // retired quest id — rpgEnsureDaily swaps it out on the next pass
    const prog = Math.min(q.need, rpgQuestProgress(q));
    const done = prog >= q.need;
    const claimed = rpgState.daily.claimed[i];
    const reward = i === 2 ? "🎟️ ½-price pack" : `🪙 ${q.gold}`;
    return `<div class="rpg-quest ${claimed ? "claimed" : done ? "done" : ""}">
      <span class="rpg-quest-ico">${q.icon}</span>
      <span class="rpg-quest-name">${escapeHtml(q.name)} <b>${prog}/${q.need}</b></span>
      ${claimed ? `<span class="rpg-quest-claimed">✓</span>` : done ? `<button class="btn btn-primary btn-sm" type="button" data-rpg-quest="${i}">Claim ${reward}</button>` : `<span class="rpg-quest-reward">${reward}</span>`}
    </div>`;
  }).join("");
  const vc = s.vCount || 0;
  const todayQ = (s.dayKey === advToday()) ? Math.min(10, s.dayMarks || 0) : 0;
  const voucherLine = `<div class="rpg-voucher-streak" title="Practise 10+ questions every day for 30 days in a row to win a $10 Popular voucher.">🎟️ <b>$10 voucher streak</b> · ${vc}/30 days &nbsp;·&nbsp; today ${todayQ}/10 questions
    <div class="rpg-voucher-bar"><div class="rpg-voucher-fill" style="width:${Math.round((vc / 30) * 100)}%;"></div></div></div>`;
  return `<div class="rpg-quests"><div class="section-label" style="margin-top:14px;">Daily quests · 🔥 streak ${s.count || 0}${s.freezes ? ` (🧊×${s.freezes})` : ""}</div>${voucherLine}${rows}</div>`;
}
function rpgCreditStreakDay() {
  const day = advToday();
  let s = rpgState.streak || { count: 0, best: 0, lastDay: null, freezes: 0, freezeProg: 0, dayMarks: 0, milestones: [] };
  if (s.lastDay === day) return;
  const yest = (() => { const d = new Date(); d.setDate(d.getDate() - 1); return d.getFullYear() + "-" + String(d.getMonth() + 1).padStart(2, "0") + "-" + String(d.getDate()).padStart(2, "0"); })();
  if (s.lastDay === yest || !s.lastDay) s.count = (s.lastDay ? s.count : 0) + 1;
  else if (s.freezes > 0) { s.freezes--; s.count++; toast("🧊 Streak freeze used — your flame survives!", ""); }
  else s.count = 1;
  s.lastDay = day;
  s.best = Math.max(s.best || 0, s.count);
  s.milestones = s.milestones || [];
  if (s.count >= 7 && !s.milestones.includes(7)) {
    s.milestones.push(7);
    rpgState.inventory.streak_sprite = 1;
    toast("🔥 7-day practice streak — the Streak Sprite pet joins you!", "success");
  }
  if (s.count >= 30 && !s.milestones.includes(30)) {
    s.milestones.push(30);
    rpgState.auraGold = true;
    toast("🔥 30-day streak — your hero now glows with a golden aura!", "success");
  }
  rpgState.streak = s;
  toast(`🔥 Practice streak: ${s.count} day${s.count === 1 ? "" : "s"}!`, "success");
}
function rpgNoteStreakActivity(correct) {
  if (!rpgState) return;
  rpgEnsureDaily();
  let s = rpgState.streak || { count: 0, best: 0, lastDay: null, freezes: 0, freezeProg: 0, dayMarks: 0, dayKey: null, milestones: [] };
  if (s.dayKey !== advToday()) { s.dayKey = advToday(); s.dayMarks = 0; }
  s.dayMarks = (s.dayMarks || 0) + 1;
  if (correct) {
    s.freezeProg = (s.freezeProg || 0) + 1;
    if (s.freezeProg >= 15 && (s.freezes || 0) < 2) { s.freezeProg = 0; s.freezes = (s.freezes || 0) + 1; toast("🧊 Earned a streak freeze!", "success"); }
  }
  // $10 voucher streak: 10+ questions a day for 30 days straight. Tracked apart
  // from the 3-mark daily streak above so the harder goal has its own counter.
  if ((s.dayMarks || 0) >= 10 && s.vLastDay !== advToday()) {
    s.vCount = (s.vLastDay === advYesterday()) ? (s.vCount || 0) + 1 : 1;
    s.vLastDay = advToday();
    s.vBest = Math.max(s.vBest || 0, s.vCount);
    if (s.vCount >= 30) {
      s.vCycles = (s.vCycles || 0) + 1;
      s.vCount = 0; // cycle complete — a fresh 30-day run can begin
      rpgState.streak = s;
      rpgSave();
      toast("🎟️ 30-day 10-question streak — you've earned a $10 voucher!", "success");
      const cyc = s.vCycles;
      setTimeout(() => { try { rpgOfferStreakVoucher(cyc); } catch (_) {} }, 700);
    }
  }
  rpgState.streak = s;
  if (s.dayMarks >= 3) rpgCreditStreakDay();
}
// ---- Lifecycle ----
async function rpgInit() {
  if (!currentUser) return;
  const uid = currentUser.uid;
  // Load with retry/backoff. If the cloud read keeps failing we must BAIL rather
  // than continue — initialising from blank/stale data and then saving would wipe
  // the student's real progress in Firestore. Better to ask them to refresh.
  let saved, loadOk = false;
  for (let attempt = 0; attempt < 4; attempt++) {
    try { saved = await rpgLoadState(); loadOk = true; break; }
    catch (e) { console.warn("rpg load attempt " + (attempt + 1) + " failed", e); }
    if (!currentUser || currentUser.uid !== uid) return; // signed out while loading
    await new Promise(r => setTimeout(r, 800 * Math.pow(2, attempt)));
  }
  if (!currentUser || currentUser.uid !== uid) return; // signed out while loading
  if (!loadOk) {
    // Do NOT touch rpgState / save / publish — that would clobber the cloud save.
    toast("Couldn't reach your saved hero — your progress is safe. Please check your connection and refresh.", "error");
    return;
  }
  rpgState = rpgHydrate(saved);
  const stats = rpgPlayerStats();
  if (!Number.isFinite(rpgState.hp) || rpgState.hp === null) rpgState.hp = stats.maxHp;
  rpgState.hp = Math.max(1, Math.min(rpgState.hp, stats.maxHp));
  rpgEnsureSvgDefs();
  rpgRolloverMonth();
  rpgApplyVisibility();
  rpgRenderSide();
  rpgRenderBattle();
  if (document.querySelector("#page-character.active")) rpgRenderCharacterPage();
  rpgSave();
  rpgPublishLeaderboard();
  setTimeout(() => { rpgCheckPrizeClaim(); }, 2500); // auto-prompt month-end winners
  setTimeout(() => { try { rpgCheckStreakVoucher(); } catch (_) {} }, 3400); // and unclaimed streak vouchers
  setTimeout(() => { rpgClaimStrikePoints(); }, 1800); // points banked in Science Strike
  // The clawback marker may have arrived before the hero existed — apply it now
  // that it does (it is a no-op once this student's ack key matches).
  try { rpgApplyDuelClawback(); } catch (_) {}
  try { rpgApplyHeroOp(); } catch (_) {}
}
// ---- Points earned in Science Strike (fps.html), claimed here ----
// fps.html is a separate page and must NEVER write the hero document — this
// page owns it wholesale and would race with it. It banks what its questions
// earn into `fps.pendingPoints` on the leaderboard doc it already owns, using
// increment(); this claims the balance into the wallet on the next load and
// decrements by exactly what was taken, so anything banked in between survives.
let _strikeClaimBusy = false;
async function rpgClaimStrikePoints() {
  if (_strikeClaimBusy || !rpgState || !currentUser || RPG_STORAGE_MODE !== 'firestore') return;
  _strikeClaimBusy = true;
  try {
    const ref = doc(db, 'scienceGameLeaderboard', currentUser.uid);
    const snap = await getDoc(ref);
    const pending = Math.round(Number(snap.exists() && snap.data().fps && snap.data().fps.pendingPoints) || 0);
    if (pending <= 0) return;
    const claim = Math.min(pending, 20000);   // sanity ceiling on a single claim
    await setDoc(ref, { fps: { pendingPoints: increment(-claim) } }, { merge: true });
    rpgApplyRewards(claim, 0);
    rpgSave();
    rpgPublishLeaderboard();
    try { tcgUpdateGoldChip(); } catch (e) {}
    toast('🔫 Science Strike: 🪙 +' + claim.toLocaleString() + ' points from the questions you answered — spend them on booster packs!', 'success');
  } catch (e) { console.warn('strike points claim', e); }
  finally { _strikeClaimBusy = false; }
}
// Science Strike opens in its own tab, so the usual way back is switching to
// this one. Re-claim then (at most once a minute) rather than making the
// student reload to see what they earned.
let _strikeClaimAt = 0;
document.addEventListener('visibilitychange', () => {
  if (document.visibilityState !== 'visible' || !rpgState) return;
  if (Date.now() - _strikeClaimAt < 60000) return;
  _strikeClaimAt = Date.now();
  rpgClaimStrikePoints();
});
function rpgOnSignOut() {
  advToken++; adv = null;
  rpgState = null;
  rpgBoardRows = null;
  // Drop the attempt-stats cache: on a shared device the next sign-in must
  // not inherit this student's serving order.
  _qAttemptStats = null; _qAttemptStatsAt = 0; _qAttemptStatsUid = '';
  rpgApplyVisibility();
  const battle = $("rpgBattle");
  if (battle) { battle.style.display = "none"; battle.innerHTML = ""; }
}
function rpgGameHidden() { return !!(rpgState && rpgState.hidden); }
function rpgApplyVisibility() {
  // An employee is hired to write questions: none of the game pages are on
  // EMPLOYEE_PAGES, so the hero, the leaderboard, the dungeon, the arcade and
  // the Hide-game toggle stay gone for them however the hero doc loads.
  const active = !!rpgState && !_isEmployee();
  const show = active && !rpgState.hidden;
  document.querySelectorAll(".rpg-el").forEach(el => { el.style.display = show ? "" : "none"; });
  try { tcgApplyNavVisibility(); } catch (_) {} // Realm of Embers TCG nav follows its own admin/release rules
  try { tcgShowAnnounce(); } catch (_) {}       // …and so does its release announcement (hidden game = no banner)
  try { fpsApplyNavVisibility(); } catch (_) {} // Science Strike nav (released to everyone, still respects Hide game)
  const toggle = $("rpgHideToggle");
  if (!toggle) return;
  toggle.style.display = active ? "" : "none";
  toggle.innerHTML = show ? `<span class="ico">🙈</span> Hide game` : `<span class="ico">🎮</span> Show game`;
  toggle.title = show
    ? "Hide the game to focus on practice — you still earn XP quietly"
    : "Bring back your hero, battles and the leaderboard";
}
function rpgSetHidden(hidden) {
  if (!rpgState) return;
  rpgState.hidden = !!hidden;
  if (hidden && rpgState.battle) rpgState.battle = null; // end any battle quietly — no penalty
  rpgSave();
  rpgApplyVisibility();
  rpgRenderBattle();
  if (hidden && document.querySelector("#page-character.active, #page-leaderboard.active, #page-adventure.active")) navigateTo(rpgHomePage());
  toast(hidden ? "Game hidden — happy focusing! You still earn XP quietly." : "Game on! ⚔️", "success");
}
function rpgNoteHintUsed() { rpgHintUsedQ = true; }
function rpgQuestionChanged() { rpgHintUsedQ = false; }
function rpgResetHero() {
  try { localStorage.removeItem(rpgStorageKey()); } catch (_) {}
  rpgState = rpgHydrate(null);
  rpgState.hp = rpgPlayerStats().maxHp;
  rpgSave();
  rpgPublishLeaderboard();
  rpgApplyVisibility();
  rpgRenderBattle();
  if (document.querySelector("#page-character.active")) rpgRenderCharacterPage();
  toast("Hero reset", "success");
}

// ---- Rewards & battle resolution (called after every AI-marked attempt) ----
function rpgRolloverMonth() {
  const key = rpgMonthKey();
  if (rpgState.monthKey === key) return;
  if (rpgState.monthKey && ((rpgState.monthXp || 0) > 0 || (rpgState.monthQ || 0) > 0)) {
    rpgState.lastMonthKey = rpgState.monthKey;   // keep final standings for prize awarding
    rpgState.lastMonthXp = rpgState.monthXp || 0;
    rpgState.lastMonthQ = rpgState.monthQ || 0;  // last month's unique-question total
    rpgState.lastPapersQ = rpgState.papersQ || 0; // last month's past-paper total
  }
  rpgState.monthKey = key;
  rpgState.monthXp = 0;
  rpgState.monthQ = 0;
  rpgState.papersQ = 0;      // this month's PSLE past-year-paper questions done
  rpgState.monthQids = {};
  rpgState.monthPrints = {};
  rpgRolloverGameScores(key);
}

// A past-year exam-paper question is one filed under a PSLE category. Used for
// the Past Papers leaderboard segment (counted once per month, like monthQ).
function isPastPaperQuestion(q) {
  const cats = (typeof qCategoryList === 'function') ? qCategoryList(q)
    : [((typeof normalizeCategoryValue === 'function' ? normalizeCategoryValue(q && q.category) : (q && q.category)) || '')];
  return cats.some(c => /^PSLE\b/i.test(String(c).trim()));
}

// Make sure the mini-game score store exists and its month bucket is current.
function rpgEnsureGameScores() {
  if (!rpgState) return null;
  if (!rpgState.gameScores) rpgState.gameScores = {};
  ["defenders", "raiders", "spire", "legend", "siege"].forEach(k => {
    if (!rpgState.gameScores[k]) rpgState.gameScores[k] = { best: 0, bestLabel: "", monthBest: 0, monthLabel: "", monthKey: null, lastBest: 0, lastLabel: "", lastKey: null };
  });
  rpgRolloverGameScores(rpgMonthKey());
  return rpgState.gameScores;
}
// Roll each mini-game's month-best into "last month" when the calendar month turns.
function rpgRolloverGameScores(key) {
  if (!rpgState || !rpgState.gameScores) return;
  ["defenders", "raiders", "spire", "legend", "siege"].forEach(k => {
    const g = rpgState.gameScores[k]; if (!g) return;
    if (g.monthKey && g.monthKey !== key) {
      g.lastBest = g.monthBest || 0; g.lastLabel = g.monthLabel || ""; g.lastKey = g.monthKey;
      g.monthBest = 0; g.monthLabel = "";
    }
    g.monthKey = key;
  });
}

// Count one answered question toward THIS month's leaderboard. A question counts
// at most once per month (no repeats); and to stop a student pasting the SAME
// open answer into many questions, an open answer must be non-empty and not a
// duplicate of one already counted this month. Updates state only — the caller
// (rpgOnMarked) saves & republishes. `weight` lets past-paper game mode count a
// question as 2 (the advertised ×2 leaderboard bonus).
function rpgNoteUniqueQuestion(qid, answerText, weight) {
  qid = String(qid || "");
  if (!rpgState || !qid) return;
  rpgRolloverMonth();
  if (!rpgState.monthQids) rpgState.monthQids = {};
  if (!rpgState.monthPrints) rpgState.monthPrints = {};
  if (rpgState.monthQids[qid]) return;                  // this question already counted this month
  const print = rpgAnswerFingerprint(answerText);
  if (print) {
    if (rpgState.monthPrints[print]) return;            // identical answer already used — likely gaming
    rpgState.monthPrints[print] = 1;
  }
  rpgState.monthQids[qid] = 1;
  rpgState.monthQ = (rpgState.monthQ || 0) + Math.max(1, Math.round(Number(weight) || 1));
}

// A small, stable fingerprint of an open answer (letters/digits only). Empty for
// blank or very short answers (e.g. pure multiple-choice) so those count on the
// unique-question rule alone.
function rpgAnswerFingerprint(text) {
  const s = String(text || "").toLowerCase().replace(/[^a-z0-9]+/g, " ").trim();
  if (s.length < 4) return "";
  let h = 0;
  for (let i = 0; i < s.length; i++) h = (Math.imul(h, 31) + s.charCodeAt(i)) | 0;
  return "p" + (h >>> 0).toString(36);
}

// Questions a player did in the PREVIOUS calendar month (handles both the
// not-yet-rolled-over and rolled-over cases), used for month-end prize ranking.
function rpgLastMonthQ(r) {
  const prev = rpgPrevMonthKey();
  if (r.monthKey === prev) return r.monthQ || 0;
  if (r.lastMonthKey === prev) return r.lastMonthQ || 0;
  return 0;
}
// ---- Answer pace --------------------------------------------------------
// The All-Time board rewards questions answered PROPERLY, so it has to know
// whether an answer was considered or fired off. Games clock every answer, so
// their real ms is measured against the same anti-bot floor the points use.
// The practice page has no per-question timer, so the gap since the previous
// marked question stands in — the same 15s signal the admin's rapid-attempt
// column uses. A gap longer than PACE_MAX_MS means the student went away and
// came back, so it counts as neither rushed nor considered.
const PACE_MIN_PRACTICE_MS = 15000;
const PACE_MAX_MS = 360000;
function rpgNotePace(ms, minMs) {
  if (!rpgState) return;
  const now = Date.now();
  let p = rpgState.pace;
  if (!p || typeof p !== 'object') p = rpgState.pace = { n: 0, ok: 0, sumMs: 0, lastAt: 0 };
  const clocked = ms > 0 ? Math.round(ms) : (p.lastAt ? now - p.lastAt : 0);
  p.lastAt = now;
  if (clocked <= 0 || clocked > PACE_MAX_MS) return;   // no usable clock
  p.n = (p.n | 0) + 1;
  p.sumMs = (p.sumMs | 0) + clocked;
  if (clocked >= Math.max(1000, minMs | 0)) p.ok = (p.ok | 0) + 1;
}

// ---- The Science Score: what the All-Time board ranks on -----------------
// XP used to rank it, and XP came from dungeon runs and (until v1.229.0) free
// arena duels — so it measured hours in the game, not science learned.
//
// The base is MARKS EARNED, not questions attempted. That single choice is
// what stops the board being won on volume: an early draft used attempts as
// the base with quality as a multiplier, and 900 questions at 35% still beat
// 400 at 88%. Marks earned is also the honest thing to rank on — a wrong
// answer is practice, but it is not a result.
//
//   base = marks earned    (a marked question contributes its CREDIT, 0…1, so
//          partial credit on a hard CER answer counts; a one-click game MCQ
//          contributes SCORE_GAME_Q, being a smaller piece of work)
//   A    = accuracy, marks earned ÷ work attempted  → ×0.55 (guessing) … ×1.30
//   P    = share answered at a considered pace      → ×0.70 (all rushed) … ×1.00
//
// SCORE = base × (0.55 + 0.75·A) × (0.70 + 0.30·P)
//
// In one line for students: every question you get right is a point, worth
// more when your accuracy is high and less when you rush it.
const SCORE_GAME_Q = 0.5;
const SCORE_ACC_BASE = 0.55, SCORE_ACC_SPAN = 0.75;
const SCORE_PACE_BASE = 0.70, SCORE_PACE_SPAN = 0.30;
const SCORE_PACE_MIN_N = 10;   // fewer clocked answers than this is not enough to judge
function rpgScienceScore(p) {
  const base = Math.max(0, Number(p && p.base) || 0);
  if (base <= 0) return 0;
  const acc = Math.max(0, Math.min(1, Number(p.acc) || 0));
  const pace = p.pace == null ? 1 : Math.max(0, Math.min(1, Number(p.pace) || 0));
  return Math.round(base * (SCORE_ACC_BASE + SCORE_ACC_SPAN * acc) * (SCORE_PACE_BASE + SCORE_PACE_SPAN * pace));
}
// This student's score parts, straight off their own hero state.
function rpgMyScoreParts() {
  const st = (rpgState && rpgState.stats) || {};
  const marked = st.marked | 0;
  // creditSum is the fractional total; heroes from before it existed fall back
  // to the binary correct count, which is the same number for MCQ work.
  const marks = Math.min(marked, Math.max(0, st.creditSum != null ? Number(st.creditSum) || 0 : (st.correct | 0)));
  const gq = st.gameQ | 0, gc = st.gameCorrect | 0;
  const work = marked + SCORE_GAME_Q * gq;
  const base = marks + SCORE_GAME_Q * gc;
  const pc = (rpgState && rpgState.pace) || null;
  const pn = (pc && pc.n) | 0;
  return {
    base: Math.round(base * 10) / 10,
    q: Math.round(work * 10) / 10,
    acc: work > 0 ? Math.min(1, base / work) : 0,
    // Too few clocked answers to judge → treated as unrushed, so a new student
    // is never punished for data nobody has collected yet.
    pace: pn >= SCORE_PACE_MIN_N ? Math.min(1, ((pc.ok | 0) / pn)) : null,
    paceN: pn,
    marked, gameQ: gq
  };
}
function rpgScorePayload() {
  const p = rpgMyScoreParts();
  return { v: rpgScienceScore(p), base: p.base, q: p.q, acc: Math.round(p.acc * 1000) / 1000, pace: p.pace, paceN: p.paceN, marked: p.marked, gameQ: p.gameQ };
}
// A published row's score. Rows published by a build older than v1.231.0 have
// no `score` block; their audit counters still give marks and accuracy, and
// their pace is simply unknown (so treated as unrushed).
// ---- Questions answered inside the games --------------------------------
// What the 🔥 Realm of Embers board ranks on, since v1.232.0. It used to rank
// on total team power, which is downstream of 🪙 points — and points bought
// booster packs, so anyone who found a way to farm points could buy a place on
// the board without answering anything. Questions answered in the games can
// only go up by actually playing and answering.
//
// The counters started in v1.231.0, so every student begins level here.
function rpgRowGameQ(r) {
  const g = (r && r.games) || null;
  if (g) return { q: g.q | 0, correct: g.correct | 0 };
  const a = (r && r.audit) || {};
  if (a.gameQ != null) return { q: a.gameQ | 0, correct: a.gameCorrect | 0 };
  // v1.231.0 rows carry the attempt count on the score block but no correct
  // count — they rank 0 until the student next opens the app.
  return { q: ((r && r.score && r.score.gameQ) | 0), correct: 0 };
}
function rpgRowScore(r) {
  if (r && r.score && r.score.v != null) return r.score.v | 0;
  const a = (r && r.audit) || {};
  const marked = a.marked | 0;
  if (!marked) return 0;
  const correct = Math.min(marked, a.correct | 0);
  return rpgScienceScore({ base: correct, acc: correct / marked, pace: null });
}
function rpgApplyRewards(gold, xp) {
  const learn = (rpgState && rpgState.star && rpgState.star.learn) || 0;
  if (learn && xp > 0) xp = Math.round(xp * (1 + 0.05 * learn));
  try { rpgRaidContribute(xp); } catch (_) {}
  const before = rpgLevelInfo().level;
  const goldPct = rpgPlayerStats().goldPct || 0;
  if (goldPct && gold > 0) gold = Math.round(gold * (1 + goldPct));
  rpgState.gold += gold;
  rpgState.xp += xp;
  rpgRolloverMonth();
  rpgState.monthXp += xp;
  rpgState.stats.goldEarned += gold;
  const after = rpgLevelInfo().level;
  if (after > before) rpgState.hp = rpgPlayerStats().maxHp; // level up = full heal
  return { levelsGained: after - before, newLevel: after };
}
function rpgRollLoot(enemy) {
  if (Math.random() > 0.45 + rpgSurgeBonus("loot")) return null;
  const level = rpgLevelInfo().level;
  const pool = RPG_ITEMS.filter(it => it.price > 0 && !rpgState.inventory[it.id] &&
    RPG_RARITY[it.rarity].rank <= enemy.lootMax && it.levelReq <= level + 1);
  if (!pool.length) return null;
  return pool[Math.floor(Math.random() * pool.length)];
}
function rpgBattleRound(credit) {
  const battle = rpgState.battle;
  const enemy = battle && RPG_ENEMIES_BY_ID[battle.enemyId];
  if (!enemy) { rpgState.battle = null; return null; }
  const out = { lines: [], victory: null, defeat: false, foeDmg: 0, heroDmg: 0 };
  const stats = rpgPlayerStats();
  battle.rounds = (battle.rounds || 0) + 1;
  if (credit > 0) {
    let dmg = stats.atk * (0.9 + Math.random() * 0.35) * (1 + rpgSurgeBonus("dmg"));
    let note = "";
    const wel = rpgWeaponElement(rpgState.equipment.weapon);
    if (RPG_COUNTERS[wel] === enemy.el) { dmg *= 1.25; note += ` — ${RPG_ELEMENTS[wel].icon} super effective!`; }
    if (credit < 0.95) { dmg *= Math.max(0.3, credit); note += " (glancing hit)"; }
    else if (Math.random() * 100 < stats.crit) { dmg *= (stats.critMult || 2); note += " — <b>CRITICAL HIT!</b>"; }
    if (rpgHintUsedQ) { dmg *= 0.6; note += " (hint used)"; }
    dmg = Math.max(1, Math.round(dmg));
    battle.enemyHp = Math.max(0, battle.enemyHp - dmg);
    out.foeDmg = dmg;
    out.lines.push(`You strike <b>${escapeHtml(enemy.name)}</b> for <b>${dmg}</b> damage${note}.`);
    if (battle.enemyHp <= 0) {
      rpgState.stats.wins++;
      try { rpgCreditKill(enemy.id); } catch (_) {}
      const loot = rpgRollLoot(enemy);
      if (loot) {
        if (!rpgState.inventory[loot.id]) rpgRollAffixes(loot, false);
        rpgState.inventory[loot.id] = (rpgState.inventory[loot.id] || 0) + 1;
      }
      out.victory = { gold: enemy.gold, xp: enemy.xp, loot, enemy };
      rpgState.battle = null;
      rpgState.hp = Math.min(stats.maxHp, rpgState.hp + Math.round(stats.maxHp * 0.3));
      out.lines.push(`<b>${escapeHtml(enemy.name)}</b> is defeated! 🎉`);
    }
  } else {
    if (Math.random() * 100 < (stats.dodge || 0)) {
      out.lines.push(`You dodged <b>${escapeHtml(enemy.name)}</b>'s attack! 🌀`);
      return out;
    }
    const edmg = Math.max(1, Math.round(enemy.atk * (0.85 + Math.random() * 0.3) - stats.def * 0.5));
    rpgState.hp = Math.max(0, rpgState.hp - edmg);
    out.heroDmg = edmg;
    out.lines.push(`Wrong answer — <b>${escapeHtml(enemy.name)}</b> strikes you for <b>${edmg}</b>!`);
    if (rpgState.hp <= 0) {
      out.defeat = true;
      rpgState.stats.defeats++;
      rpgState.battle = null;
      rpgState.hp = rpgPlayerStats().maxHp; // gentle: full revive, no gold lost
    }
  }
  return out;
}
// ---- Surge: every 3 correct answers in a row, pick 1 of 3 session boosts.
// Session-only on purpose — skill earns power right now, missing a day costs nothing.
let rpgSurge = { streak: 0, boosts: [] };
const RPG_SURGE_POOL = [
  { id: "gold", icon: "🪙", name: "Gold Rush", desc: "+15% gold this session", v: 0.15 },
  { id: "xp", icon: "📚", name: "Insight", desc: "+10% XP this session", v: 0.1 },
  { id: "dmg", icon: "⚔️", name: "Battle Fury", desc: "+12% battle damage this session", v: 0.12 },
  { id: "loot", icon: "🎁", name: "Lucky Find", desc: "+10% loot drop chance this session", v: 0.1 },
  { id: "heal", icon: "💚", name: "Second Wind", desc: "Restore 35% HP right now", v: 0.35 }
];
function rpgSurgeBonus(id) { return rpgSurge.boosts.filter(b => b.id === id).reduce((a, b) => a + b.v, 0); }
function rpgSurgeNote(credit) {
  rpgSurge.streak = credit >= 0.95 ? rpgSurge.streak + 1 : 0;
  if (rpgSurge.streak > 0 && rpgSurge.streak % 3 === 0) rpgSurgeOffer();
}
function rpgSurgeOffer() {
  if (!rpgState || rpgGameHidden() || $("rpgSurgeCard")) return;
  const picks = RPG_SURGE_POOL.slice().sort(() => Math.random() - 0.5).slice(0, 3);
  const wrap = document.createElement("div");
  wrap.id = "rpgSurgeCard";
  wrap.style.cssText = "position:fixed;inset:0;z-index:4000;display:flex;align-items:center;justify-content:center;background:rgba(15,23,42,0.55);";
  wrap.innerHTML = `<div style="background:#fff;border-radius:14px;padding:18px 20px;max-width:420px;width:92%;box-shadow:0 18px 50px rgba(0,0,0,0.3);">
      <h4 style="margin:0 0 4px;">🔥 SURGE! ${rpgSurge.streak} correct in a row</h4>
      <p class="hint" style="margin:0 0 12px;">Your focus is on fire — choose one boost:</p>
      <div style="display:grid;gap:8px;">${picks.map((s, i) =>
        `<button class="btn btn-ghost" type="button" data-surge="${i}" style="justify-content:flex-start;text-align:left;">
          <b>${s.icon} ${s.name}</b>&nbsp;— ${s.desc}</button>`).join("")}</div>
      <button class="btn btn-ghost btn-sm" type="button" data-surge-skip style="margin-top:10px;">Skip</button>
    </div>`;
  document.body.appendChild(wrap);
  wrap.addEventListener("click", e => {
    if (e.target.closest("[data-surge-skip]")) { wrap.remove(); return; }
    const b = e.target.closest("[data-surge]");
    if (!b) return;
    const s = picks[Number(b.dataset.surge)];
    if (s.id === "heal") {
      const max = rpgPlayerStats().maxHp;
      rpgState.hp = Math.min(max, (rpgState.hp || 0) + Math.round(max * s.v));
      rpgSave();
      rpgRenderBattle();
    } else rpgSurge.boosts.push(s);
    toast(`🔥 Surge: ${s.name}!`, "success");
    wrap.remove();
  });
}
// Hook called from recordCerPerformance after EVERY AI-marked question:
// score / total is the marked result for the whole question.
function rpgOnMarked(q, score, total, opts = {}) {
  if (!rpgState || !q || !total) return;
  const credit = Math.max(0, Math.min(1, (Number(score) || 0) / total));
  const diff = rpgQuestionDifficulty(q);
  const qid = String(q.id || "");
  const seen = rpgState.seenQ || (rpgState.seenQ = {});
  const repeatAttempt = !opts.simulated && qid && (seen[qid] || 0) > 0;
  if (!opts.simulated && qid) seen[qid] = (seen[qid] || 0) + 1;
  let gold = Math.round((6 + diff / 100) * credit);
  let xp = Math.round((16 + diff / 45) * credit);
  if (credit <= 0) { gold = 0; xp = 3; } // effort XP — progress never stalls completely
  if (repeatAttempt) { gold = Math.round(gold * 0.4); xp = Math.round(xp * 0.5); }
  if (gold > 0 && rpgSurgeBonus("gold")) gold = Math.round(gold * (1 + rpgSurgeBonus("gold")));
  if (xp > 0 && rpgSurgeBonus("xp")) xp = Math.round(xp * (1 + rpgSurgeBonus("xp")));
  rpgState.stats.marked++;
  if (credit >= 0.95) rpgState.stats.correct++;
  // Fractional total alongside the binary count: the Science Score ranks on
  // marks EARNED, so a part-right CER answer has to be worth part of a mark.
  rpgState.stats.creditSum = Math.round(((Number(rpgState.stats.creditSum) || 0) + credit) * 100) / 100;
  if (!opts.simulated) {
    try { rpgNoteStreakActivity(credit >= 0.95); } catch (_) {}
    try { rpgSurgeNote(credit); } catch (_) {}
    // No per-question timer on this page, so pass 0 and let rpgNotePace use
    // the gap since the previous marked question.
    try { rpgNotePace(0, PACE_MIN_PRACTICE_MS); } catch (_) {}
  }

  rpgEnsureBattle(); // a foe is always present, so every answer lands on an enemy
  const round = rpgState.battle ? rpgBattleRound(credit) : null;
  if (round && round.victory) { gold += round.victory.gold; xp += round.victory.xp; }
  const lvl = rpgApplyRewards(gold, xp);
  if (!opts.simulated) { const _bq = rpgState.monthQ || 0; rpgNoteUniqueQuestion(qid, opts.answerText); if ((rpgState.monthQ || 0) > _bq) { try { commNoteEncounterProgress(q); } catch (_) {} if (isPastPaperQuestion(q)) rpgState.papersQ = (rpgState.papersQ || 0) + 1; } try { _noteQuestionForCredit(qid); } catch (_) {} try { commQuestRunCapture(q, credit); } catch (_) {} }
  rpgHintUsedQ = false;
  rpgSave();
  rpgPublishLeaderboard();
  if (rpgGameHidden()) return; // rewards and the leaderboard still update quietly
  rpgRenderBattle();
  if (document.querySelector("#page-character.active")) rpgRenderCharacterPage();

  if (round) {
    // On a kill the arena already re-rendered with the next foe, so don't splash
    // the killing blow's damage onto the freshly spawned enemy.
    if (round.foeDmg && !round.victory) { rpgFloat("rpgFoeTile", `-${round.foeDmg}`, "dmg"); rpgHitFlash("rpgFoeTile"); }
    if (round.heroDmg) { rpgFloat("rpgHeroTile", `-${round.heroDmg}`, "hurt"); rpgHitFlash("rpgHeroTile"); }
    if (round.lines.length) rpgSetLog(round.lines.join(" "));
  }

  const lineParts = [];
  if (round && round.foeDmg) lineParts.push(`⚔️ ${round.foeDmg} damage dealt`);
  if (round && round.heroDmg) lineParts.push(`💢 took ${round.heroDmg} damage`);
  if (gold > 0) lineParts.push(`🪙 +${gold} gold`);
  lineParts.push(`✨ +${xp} XP`);
  if (repeatAttempt) lineParts.push(`(repeat question — reduced reward)`);
  if (lvl.levelsGained > 0) lineParts.push(`⬆️ LEVEL UP! Now Lv ${lvl.newLevel}`);
  const lineEl = $("rpgRewardLine");
  if (lineEl) {
    lineEl.innerHTML = lineParts.map(p => `<span>${escapeHtml(p)}</span>`).join("");
    lineEl.style.display = "flex";
  }

  if (!rpgState.battleMin) { // keep the big pop-ups out of view while hidden
    if (round && round.victory) rpgShowVictory(round.victory, lvl);
    else if (round && round.defeat) rpgShowDefeat(round);
    else if (lvl.levelsGained > 0) rpgShowLevelUp(lvl.newLevel);
  }
}

// ---- Battle control ----
function rpgEnemiesOfTier(tier) {
  const t = Math.max(1, Math.min(10, tier));
  const list = RPG_ENEMIES.filter(e => e.tier === t);
  return list.length ? list : RPG_ENEMIES;
}
function rpgRandomEnemy(tier) {
  const list = rpgEnemiesOfTier(tier);
  return list[Math.floor(Math.random() * list.length)];
}
function rpgPickEnemy() {
  const level = rpgLevelInfo().level;
  const tier = Math.max(1, Math.min(10, level + (Math.random() < 0.3 ? 1 : 0)));
  return rpgRandomEnemy(tier);
}
function rpgStartBattle() {
  if (!rpgState) return;
  const enemy = rpgPickEnemy();
  rpgState.battle = { enemyId: enemy.id, enemyHp: enemy.maxHp, rounds: 0, startedAt: new Date().toISOString() };
  rpgSave();
  rpgRenderBattle();
  rpgSetLog(`A wild <b>${escapeHtml(enemy.name)}</b> appears! ${escapeHtml(enemy.flavor)} Answer the question below to attack.`);
}
// An enemy is always waiting: spawn one whenever the arena is empty so students
// can attack just by answering questions — no "Start battle" click needed.
function rpgEnsureBattle() {
  if (!rpgState || rpgState.hidden || rpgState.battle) return false;
  const enemy = rpgPickEnemy();
  rpgState.battle = { enemyId: enemy.id, enemyHp: enemy.maxHp, rounds: 0, startedAt: new Date().toISOString() };
  rpgSave();
  return true;
}
function rpgFlee() {
  if (!rpgState || !rpgState.battle) return;
  const enemy = RPG_ENEMIES_BY_ID[rpgState.battle.enemyId];
  rpgState.battle = null;
  rpgSave();
  rpgRenderBattle();
  toast(`You fled from ${enemy ? enemy.name : "the battle"} — no harm done`, "");
}
function rpgSimulate(verdict) {
  if (!rpgState) return;
  const q = { id: "sim", level: "P6", title: "Preview" };
  const score = verdict === "correct" ? 2 : verdict === "partial" ? 1 : 0;
  rpgOnMarked(q, score, 2, { simulated: true });
}

// ---- UI: sidebar hero card ----
function rpgRenderSide() {
  if (!rpgState) return;
  const info = rpgLevelInfo();
  const stats = rpgPlayerStats();
  const lv = $("rpgSideLevel"), gd = $("rpgSideGold"), hp = $("rpgSideHp"), xpEl = $("rpgSideXp"), chip = $("rpgTopChipText");
  if (lv) lv.textContent = "Lv " + info.level;
  if (gd) gd.textContent = "🪙 " + rpgState.gold;
  if (hp) hp.style.width = Math.round((rpgState.hp / stats.maxHp) * 100) + "%";
  if (xpEl) xpEl.style.width = Math.round((info.into / info.need) * 100) + "%";
  if (chip) chip.textContent = `Lv ${info.level} · 🪙 ${rpgState.gold}`;
  const cr = $("rpgSideCredits");
  if (cr) {
    if (currentUser && currentUser.role === "student") {
      const left = _creditsLeft(), need = _creditsToNextReward();
      cr.style.display = "";
      cr.textContent = `🎮 ${left} game credit${left === 1 ? "" : "s"} today · ${need} more Q${need === 1 ? "" : "s"} → +1`;
    } else {
      cr.style.display = "none";
    }
  }
}

// ---- UI: battle banner on the practice pages ----
// The banner lives in ONE element (#rpgBattle) that hops between the
// `.rpg-battle-host` containers on whichever practice page is active.
function rpgHpBar(current, max, extraClass = "") {
  const pct = Math.max(0, Math.min(100, Math.round((current / max) * 100)));
  return `<div class="rpg-bar ${extraClass}"><div class="rpg-bar-fill hp" style="width:${pct}%;"></div><div class="rpg-bar-label">${current} / ${max}</div></div>`;
}
function rpgSimRowHtml() {
  if (!rpgCanPreview()) return "";
  return `<div class="rpg-sim">Preview controls:
    <button type="button" data-rpg-act="sim-correct">✓ correct</button>
    <button type="button" data-rpg-act="sim-partial">≈ partial</button>
    <button type="button" data-rpg-act="sim-wrong">✗ wrong</button>
    <button type="button" data-rpg-act="sim-gold">+500 🪙</button>
    <button type="button" data-rpg-act="sim-reset">reset hero</button>
  </div>`;
}
// Pin the battle strip just below the active page's sticky header by
// measuring the header height into a CSS variable (adapts across breakpoints).
function rpgSyncStripTop() {
  const host = document.querySelector(".page.active .rpg-battle-host");
  const page = host && host.closest(".page");
  const hdr = page && page.querySelector(".page-header");
  const h = hdr ? Math.round(hdr.getBoundingClientRect().height) : 0;
  document.documentElement.style.setProperty("--rpg-strip-top", h + "px");
}
function rpgRenderBattle() {
  const host = document.querySelector(".page.active .rpg-battle-host");
  let wrap = $("rpgBattle");
  if (!wrap) {
    if (!host) return;
    wrap = document.createElement("div");
    wrap.id = "rpgBattle";
    wrap.className = "rpg-battle";
    wrap.addEventListener("click", rpgBattleClick);
  }
  if (host && wrap.parentElement !== host) host.appendChild(wrap);
  if (!rpgState || rpgState.hidden || !wrap.parentElement) { wrap.style.display = "none"; wrap.innerHTML = ""; return; }
  wrap.style.display = "";
  rpgSyncStripTop();
  requestAnimationFrame(rpgSyncStripTop);
  rpgEnsureBattle(); // an enemy is always on the field — no "Start battle" click needed
  const stats = rpgPlayerStats();
  const info = rpgLevelInfo();
  const battle = rpgState.battle;
  const enemy = battle && RPG_ENEMIES_BY_ID[battle.enemyId];
  const rewardLine = `<div class="rpg-reward-line" id="rpgRewardLine" style="display:none;"></div>`;
  if (rpgState.battleMin) {
    // Hidden from view, but the game goes on — the gold earned shows as a small
    // number here, and #rpgRewardLine still flashes each +gold/+XP after answers.
    wrap.innerHTML = `<div class="rpg-battle-card">
      <div class="rpg-battle-head">
        <span class="rpg-battle-title">⚔️ Battle hidden</span>
        <span class="rpg-mini-gold">🪙 ${(rpgState.gold || 0).toLocaleString()}</span>
        <button class="btn btn-sm" type="button" data-rpg-act="max" title="Show the battle again">👁️ Show</button>
      </div>
    </div>${rewardLine}`;
    return;
  }
  if (!battle || !enemy) {
    wrap.innerHTML = `<div class="rpg-battle-card">
      <div class="rpg-battle-head">
        <span class="rpg-battle-title">⚔️ Battle mode</span>
        <span class="rpg-battle-sub">Fight monsters by solving questions — correct answers attack, wrong answers let the enemy strike.</span>
        <button class="btn btn-sm" type="button" data-rpg-act="character">🛡️ Lv ${info.level}</button>
        <button class="btn btn-primary btn-sm" type="button" data-rpg-act="start">Start battle</button>
        <button class="btn btn-sm" type="button" data-rpg-act="min" title="Hide the game — keep earning gold in a small strip">🙈 Hide</button>
      </div>
      ${rpgSimRowHtml()}
    </div>${rewardLine}`;
    return;
  }
  wrap.innerHTML = `<div class="rpg-battle-card">
    <div class="rpg-battle-head">
      <span class="rpg-battle-title">⚔️ Battle!</span>
      <span class="rpg-battle-sub">Submit your answers — a correct answer is an attack.</span>
      <button class="btn btn-sm" type="button" data-rpg-act="flee">🏃 Flee</button>
      <button class="btn btn-sm" type="button" data-rpg-act="min" title="Hide the game — keep earning gold in a small strip">🙈 Hide</button>
    </div>
    <div class="rpg-arena">
      <div class="rpg-fighter" id="rpgHeroTile">
        <div class="rpg-fighter-art">${rpgAvatarSvg()}</div>
        <div class="rpg-fighter-info">
          <div class="rpg-fighter-name">${escapeHtml(currentUser && currentUser.name || "You")}</div>
          <div class="rpg-fighter-lv">Lv ${info.level} · ⚔️${stats.atk} 🛡️${stats.def}</div>
          ${rpgHpBar(rpgState.hp, stats.maxHp)}
        </div>
      </div>
      <div class="rpg-vs">VS</div>
      <div class="rpg-fighter" id="rpgFoeTile">
        <div class="rpg-fighter-art"><span class="rpg-foe-emoji">${enemy.emoji}</span></div>
        <div class="rpg-fighter-info">
          <div class="rpg-fighter-name">${escapeHtml(enemy.name)} ${RPG_ELEMENTS[enemy.el] ? RPG_ELEMENTS[enemy.el].icon : ""}</div>
          <div class="rpg-fighter-lv">Lv ${enemy.tier} · ${escapeHtml(enemy.flavor)}</div>
          ${rpgHpBar(battle.enemyHp, enemy.maxHp)}
        </div>
      </div>
    </div>
    <div class="rpg-log" id="rpgLog"></div>
    ${rpgSimRowHtml()}
  </div>${rewardLine}`;
}
function rpgBattleClick(e) {
  const btn = e.target.closest("[data-rpg-act]");
  if (!btn || !rpgState) return;
  const act = btn.dataset.rpgAct;
  if (act === "start") rpgStartBattle();
  else if (act === "flee") rpgFlee();
  else if (act === "min") { rpgState.battleMin = true; rpgSave(); rpgRenderBattle(); toast("Battle hidden — you're still earning gold & XP 🪙", ""); }
  else if (act === "max") { rpgState.battleMin = false; rpgSave(); rpgRenderBattle(); }
  else if (act === "character") navigateTo("character");
  // The preview row is only RENDERED for teachers, but the handler has to check
  // too: these hand out points on a repeatable click, and a data-rpg-act button
  // can be put back into the page from a student's console.
  else if (act === "sim-correct") { if (rpgCanPreview()) rpgSimulate("correct"); }
  else if (act === "sim-partial") { if (rpgCanPreview()) rpgSimulate("partial"); }
  else if (act === "sim-wrong") { if (rpgCanPreview()) rpgSimulate("wrong"); }
  else if (act === "sim-gold") { if (rpgCanPreview()) { rpgState.gold += 500; rpgSave(); rpgRenderBattle(); toast("+500 gold (preview)", "success"); } }
  else if (act === "sim-reset") {
    if (!confirm("Reset your hero? This clears gold, items and battle progress.")) return;
    rpgResetHero();
  }
}
function rpgSetLog(html) {
  const log = $("rpgLog");
  if (log) log.innerHTML = html;
}
function rpgFloat(tileId, text, cls) {
  const tile = $(tileId);
  if (!tile) return;
  const el = document.createElement("span");
  el.className = "rpg-float " + cls;
  el.textContent = text;
  tile.appendChild(el);
  setTimeout(() => el.remove(), 1200);
}
function rpgHitFlash(tileId) {
  const tile = $(tileId);
  if (!tile) return;
  tile.classList.add("hit");
  setTimeout(() => tile.classList.remove("hit"), 450);
}

// ---- UI: reward overlays ----
function rpgShowReward(title, bodyHtml) {
  $("rpgRewardTitle").textContent = title;
  $("rpgRewardBody").innerHTML = bodyHtml;
  $("rpgRewardOverlay").classList.add("show");
}
function rpgLootCardHtml(loot) {
  if (!loot) return "";
  const rar = RPG_RARITY[loot.rarity];
  return `<div class="rpg-loot-card" style="--rar:${rar.color};">
    <div class="rpg-item-art t-${loot.rarity}">${rpgItemIconSvg(loot)}</div>
    <div><div class="rpg-item-rarity" style="--rar:${rar.color};">${rar.label} drop!</div>
    <div class="rpg-item-name">${escapeHtml(rpgDisplayName(loot))}</div>
    <div class="rpg-item-stats">${escapeHtml(rpgStatLine(loot))} — added to your inventory</div></div>
  </div>`;
}
function rpgShowVictory(victory, lvl) {
  rpgShowReward("Victory! 🎉",
    `<div class="rpg-reward-hero">
      <span class="big">${victory.enemy.emoji}</span>
      <h4>${escapeHtml(victory.enemy.name)} defeated!</h4>
      <p>Your science was too powerful.</p>
      <div class="rpg-reward-stats"><span>🪙 +${victory.gold} gold</span><span>✨ +${victory.xp} XP</span></div>
      ${lvl.levelsGained > 0 ? `<div class="rpg-reward-stats" style="color:var(--accent-orange);"><span>⬆️ LEVEL UP — now Lv ${lvl.newLevel}!</span></div>` : ""}
      ${rpgLootCardHtml(victory.loot)}
    </div>`);
}
function rpgShowDefeat() {
  rpgShowReward("Retreat! 🛏️",
    `<div class="rpg-reward-hero">
      <span class="big">😵</span>
      <h4>You were knocked out…</h4>
      <p>You retreat to the academy and recover to full health. No gold lost — heroes learn from every battle. Review the feedback and try again!</p>
    </div>`);
}
function rpgShowLevelUp(newLevel) {
  rpgShowReward("Level up! ⬆️",
    `<div class="rpg-reward-hero">
      <span class="big">🌟</span>
      <h4>You reached Lv ${newLevel}!</h4>
      <p>+10 max HP, +1 ATK — and you're fully healed. New gear may have unlocked in the shop.</p>
    </div>`);
}

// ---- UI: character page ----
function rpgRenderCharacterPage() {
  if (!rpgState) return;
  const stats = rpgPlayerStats();
  const info = rpgLevelInfo();
  rpgState.hp = Math.min(rpgState.hp, stats.maxHp);
  $("rpgAvatarFrame").innerHTML = rpgAvatarSvg();
  const _g = rpgState.gender || null;
  const _genderRow = $("rpgGenderRow");
  if (_genderRow) _genderRow.innerHTML =
    `<button type="button" class="rpg-gender-btn${_g === "male" ? " on" : ""}" onclick="rpgSetGender('male')">👦 Male</button>
     <button type="button" class="rpg-gender-btn${_g === "female" ? " on" : ""}" onclick="rpgSetGender('female')">👧 Female</button>`;
  $("rpgHeroName").textContent = (currentUser && currentUser.name) || "Hero";
  $("rpgHeroBars").innerHTML =
    `<div class="rpg-hero-title">Lv ${info.level} science adventurer · ${rpgState.stats.wins} battles won${rpgState.stats.bestFloor ? ` · 🏰 best floor ${rpgState.stats.bestFloor}` : ``} · ${rpgState.monthXp || 0} XP this month</div>
    <div class="rpg-bar-row"><div class="rpg-bar-cap"><span>HP</span><span>${rpgState.hp} / ${stats.maxHp}</span></div>
      <div class="rpg-bar light"><div class="rpg-bar-fill hp" style="width:${Math.round((rpgState.hp / stats.maxHp) * 100)}%;"></div></div></div>
    <div class="rpg-bar-row"><div class="rpg-bar-cap"><span>XP</span><span>${info.into} / ${info.need}</span></div>
      <div class="rpg-bar light"><div class="rpg-bar-fill xp" style="width:${Math.round((info.into / info.need) * 100)}%;"></div></div></div>`;
  const setsHtml = rpgSetCounts().filter(x => x.count > 0).map(({ set, count }) =>
    `<span class="rpg-set-chip ${count >= set.need ? "on" : ""}" title="${escapeHtml(set.name)} (${set.need} pieces): ${escapeHtml(set.text)}">${set.icon} ${escapeHtml(set.name)} ${count}/${set.need}${count >= set.need ? " ✓" : ""}</span>`).join("");
  $("rpgHeroStats").innerHTML =
    `<div class="rpg-stat-chip"><b>${stats.atk}</b><span>⚔️ Attack</span></div>
    <div class="rpg-stat-chip"><b>${stats.def}</b><span>🛡️ Defence</span></div>
    <div class="rpg-stat-chip"><b>${stats.crit}%</b><span>✨ Crit</span></div>
    <div class="rpg-stat-chip"><b>${rpgState.gold}</b><span>🪙 Gold</span></div>` +
    (setsHtml ? `<div class="rpg-set-row">${setsHtml}</div>` : "") + rpgQuestsHtml();
  $("rpgEquipRow").innerHTML = RPG_SLOTS.map(slot => {
    const it = RPG_ITEMS_BY_ID[rpgState.equipment[slot]];
    const meta = RPG_SLOT_META[slot];
    if (!it) return `<div class="rpg-slot" data-rpg-slot="${slot}" title="Empty ${meta.label} slot"><span class="rpg-slot-empty">${meta.icon}</span><span class="rpg-slot-label">${meta.label}</span></div>`;
    return `<div class="rpg-slot filled t-${it.rarity}" data-rpg-slot="${slot}" title="${escapeHtml(it.name)} — click to unequip" style="border-color:${RPG_RARITY[it.rarity].color};">${rpgItemIconSvg(it)}<span class="rpg-slot-label">${meta.label}</span></div>`;
  }).join("");
  rpgRenderTab();
}
function rpgCompareHtml(it) {
  const cur = RPG_ITEMS_BY_ID[rpgState.equipment[it.slot]];
  if (!cur || cur.id === it.id) return "";
  const a = rpgItemStats(it), b = rpgItemStats(cur);
  const parts = [];
  [["atk", "ATK"], ["def", "DEF"], ["crit", "CRIT"], ["hp", "HP"]].forEach(([k, label]) => {
    const d = a[k] - b[k];
    if (d) parts.push(`<span class="${d > 0 ? "up" : "down"}">${d > 0 ? "▲+" : "▼"}${d} ${label}</span>`);
  });
  return parts.length ? `<div class="rpg-item-diff" title="Compared with your equipped ${escapeHtml(cur.name)}">${parts.join(" ")}</div>` : "";
}
function rpgItemCardHtml(it, mode) {
  const rar = RPG_RARITY[it.rarity];
  const level = rpgLevelInfo().level;
  const owned = !!rpgState.inventory[it.id];
  const equipped = rpgState.equipment[it.slot] === it.id;
  const locked = it.levelReq > level;
  const up = rpgUpgradeLevel(it.id);
  const el = it.slot === "weapon" ? rpgWeaponElement(it.id) : "neutral";
  const setOf = rpgSetOf(it.id);
  const setCount = setOf ? rpgSetCounts().find(x => x.set.id === setOf.id).count : 0;
  let action = "";
  if (mode === "inventory") {
    action = equipped
      ? `<button class="btn btn-ghost" type="button" data-rpg-unequip="${it.slot}">Unequip</button>`
      : locked
        ? `<button class="btn btn-ghost" type="button" disabled>Needs Lv ${it.levelReq}</button>`
        : !rpgClassCanEquip(it)
          ? `<button class="btn btn-ghost" type="button" disabled>🚫 ${RPG_CLASSES[rpgState.clazz].name}</button>`
          : `<button class="btn btn-primary" type="button" data-rpg-equip="${it.id}">Equip</button>`;
    action += up >= RPG_UPGRADE_MAX
      ? `<button class="btn btn-ghost" type="button" disabled>⚒️ MAX</button>`
      : `<button class="btn btn-ghost" type="button" data-rpg-upgrade="${it.id}" ${rpgState.gold < rpgUpgradeCost(it) ? "disabled" : ""} title="+8% to all stats per upgrade level">⚒️ +${up + 1} · 🪙 ${rpgUpgradeCost(it)}</button>`;
    action += `<button class="btn btn-ghost" type="button" data-rpg-reroll="${it.id}" ${rpgState.gold < rpgRerollCost(it) ? "disabled" : ""} title="Reroll this item's magic prefix/suffix">🔮 🪙 ${rpgRerollCost(it)}</button>`;
  } else if (mode === "showcase") {
    action = owned
      ? `<button class="btn btn-ghost" type="button" disabled>Owned ✓</button>`
      : `<button class="btn btn-ghost" type="button" disabled>🎁 Pack only</button>`;
  } else {
    // Keep the Buy button clickable even when you can't afford it yet — rpgBuy()
    // shows a helpful toast ("Not enough gold"). Level-locked items show a clear
    // lock chip instead of a dead "Buy" button.
    action = owned
      ? `<button class="btn btn-ghost" type="button" disabled>Owned</button>`
      : locked
        ? `<button class="btn btn-ghost" type="button" disabled>🔒 Needs Lv ${it.levelReq}</button>`
        : `<button class="btn btn-primary" type="button" data-rpg-buy="${it.id}"${rpgState.gold < it.price ? ' style="opacity:.6"' : ""}>Buy · 🪙 ${it.price}</button>`;
  }
  return `<div class="rpg-item ${locked ? "locked" : ""}" style="--rar:${rar.color};">
    ${equipped ? `<span class="rpg-item-badge">Equipped</span>` : (mode === "shop" && owned ? `<span class="rpg-item-badge">Owned</span>` : "")}
    <div class="rpg-item-art t-${it.rarity}">${rpgItemIconSvg(it)}</div>
    <div class="rpg-item-rarity">${rar.label} · ${RPG_SLOT_META[it.slot].label}${el !== "neutral" ? ` · ${RPG_ELEMENTS[el].icon}` : ""}</div>
    <div class="rpg-item-name">${escapeHtml(rpgDisplayName(it))}${up ? ` <span class="rpg-item-up">+${up}</span>` : ""}</div>
    <div class="rpg-item-stats">${escapeHtml(rpgStatLine(it))}${RPG_SKILLS[it.id] ? `<div class="rpg-item-skill">${RPG_SKILLS[it.id].icon} ${escapeHtml(RPG_SKILLS[it.id].name)} · ${RPG_SKILLS[it.id].cd}s</div>` : ""}${it.slot === "pet" && rpgPetStage(it) ? `<div class="rpg-item-setline">⭐ Stage ${rpgPetStage(it) + 1}${rpgPetBondPct(it.id) ? ` · Bond +${rpgPetBondPct(it.id)}%` : ""}</div>` : ""}${setOf ? `<div class="rpg-item-setline" title="${escapeHtml(setOf.name)} (${setOf.need} pieces): ${escapeHtml(setOf.text)}">${setOf.icon} ${escapeHtml(setOf.name)} ${setCount}/${setOf.need}</div>` : ""}${it.classBonus ? `<div class="rpg-item-setline">${RPG_CLASSES[it.classBonus.clazz].icon} ${RPG_CLASSES[it.classBonus.clazz].name} synergy${rpgState.clazz === it.classBonus.clazz ? " ✓" : ""}</div>` : ""}${rpgCompareHtml(it)}${!rpgClassCanEquip(it) ? `<div class="rpg-item-req">${rpgClassEquipNote(it)}</div>` : ""}${locked ? `<div class="rpg-item-req">Requires Lv ${it.levelReq}</div>` : ""}</div>
    ${action}
  </div>`;
}
function rpgShopFilterHtml() {
  const chips = [["all", "All"]].concat(RPG_SLOTS.map(s => [s, RPG_SLOT_META[s].label]));
  return `<div class="rpg-filter-row">${chips.map(([key, label]) =>
    `<button class="rpg-filter-chip ${rpgShopSlot === key ? "active" : ""}" type="button" data-rpg-filter="${key}">${label}</button>`).join("")}</div>`;
}
function rpgRenderTab() {
  const body = $("rpgTabBody");
  if (!body) return;
  document.querySelectorAll(".rpg-tab[data-rpgtab]").forEach(b => b.classList.toggle("active", b.dataset.rpgtab === rpgCharTab));
  const goldRow = `<div class="rpg-gold-row">Your gold: <b>🪙 ${rpgState.gold}</b><span style="margin-left:auto;">Earn more by solving questions ✍️</span></div>`;
  if (rpgCharTab === "skills") {
    body.innerHTML = rpgSkillsTabHtml();
    return;
  }
  if (rpgCharTab === "codex") {
    body.innerHTML = rpgCodexTabHtml();
    return;
  }
  if (rpgCharTab === "packs") {
    body.innerHTML = goldRow + rpgPacksTabHtml();
    return;
  }
  if (rpgCharTab === "inventory") {
    const owned = RPG_ITEMS.filter(it => rpgState.inventory[it.id]);
    body.innerHTML = goldRow + (owned.length
      ? `<div class="rpg-grid">${owned.map(it => rpgItemCardHtml(it, "inventory")).join("")}</div>`
      : `<div class="empty-note">No items yet — defeat monsters or visit the shop!</div>`);
  } else {
    const sorted = RPG_ITEMS.filter(it => it.price > 0 && !it.packOnly && (rpgShopSlot === "all" || it.slot === rpgShopSlot)).slice().sort((a, b) =>
      RPG_SLOTS.indexOf(a.slot) - RPG_SLOTS.indexOf(b.slot) || a.price - b.price);
    body.innerHTML = goldRow + rpgShopFilterHtml() + `<div class="rpg-grid">${sorted.map(it => rpgItemCardHtml(it, "shop")).join("")}</div>`;
  }
}
const RPG_PACK_COST = 275;
const RPG_PACK_RATES = [["mythic", 1], ["legendary", 5], ["epic", 10], ["rare", 22], ["uncommon", 27], ["common", 35]];
let rpgPackToken = 0;
function rpgSkillsTabHtml() {
  if (!rpgState.clazz) {
    return `<div class="section-label">Choose your class</div><div class="class-cards">` +
      Object.keys(RPG_CLASSES).map(c => `<div class="class-card">
        <span class="class-ico">${RPG_CLASSES[c].icon}</span>
        <h4>${RPG_CLASSES[c].name}</h4>
        <p>${RPG_CLASSES[c].desc}</p>
        <button class="btn btn-primary" type="button" data-rpg-class="${c}">Become a ${RPG_CLASSES[c].name}</button>
      </div>`).join("") + `</div>
      <p class="hint" style="margin-top:10px;">You earn 1 skill point every level (max level 99). Active skills auto-cast in the dungeon; passive skills are always on.</p>`;
  }
  const c = RPG_CLASSES[rpgState.clazz];
  const level = rpgLevelInfo().level;
  const nodes = RPG_TREE[rpgState.clazz];
  const chosen = rpgPathOf(rpgState.clazz);
  const nodeHtml = n => {
    const r = rpgSkillRank(n.id);
    const reqs = n.req ? [].concat(n.req) : [];
    const reqOk = !reqs.length || reqs.some(rid => rpgSkillRank(rid) > 0);
    const lvlOk = level >= n.lvl;
    const pathLocked = n.path && chosen && chosen !== n.path;
    const rivLocked = n.riv && r === 0 && rpgSkillRank(n.riv) > 0;
    const state = pathLocked || rivLocked ? "sealed" : r >= n.max ? "maxed" : (reqOk && lvlOk && rpgSkillPoints() > 0 ? "avail" : "locked");
    const eff = n.p ? rpgPassiveDesc(n.p) : advSkillDesc(rpgTreeActiveDef(Object.assign({}, n)));
    const tip = pathLocked
      ? `${n.name} — sealed: you walk the ${RPG_PATH_NAMES[rpgState.clazz][chosen - 1]} path.`
      : rivLocked
      ? `${n.name} — sealed: you chose ${RPG_TREE_BY_ID[n.riv].name} for this tier.`
      : `${n.name} (${r}/${n.max}) — ${eff}. Requires level ${n.lvl}${reqs.length ? ` and ${reqs.map(rid => RPG_TREE_BY_ID[rid].name).join(" or ")}` : ""}.${n.riv ? ` CHOICE: rival of ${RPG_TREE_BY_ID[n.riv].name}.` : ""}${n.ks ? " KEYSTONE: power at a price!" : ""}`;
    return `<div class="sk-node ${state}${n.ks ? " sk-ks" : ""}${n.lvl >= 90 ? " sk-cap" : ""}" data-rpg-skill="${n.id}" title="${escapeHtml(tip)}">
      <span class="sk-ico">${n.icon}</span>
      <span class="sk-rank">${r}/${n.max}</span>
      <span class="sk-name">${escapeHtml(n.name)}</span>
      <span class="sk-lvl">${n.ks ? "KEYSTONE" : n.lvl >= 90 ? "CAPSTONE" : `Lv ${n.lvl}`}${n.a ? " · AUTO" : ""}</span>
    </div>`;
  };
  const base = nodes.filter(n => !n.path).sort((a, b) => a.lvl - b.lvl);
  const pathCols = [1, 2, 3].map(p => {
    const list = nodes.filter(n => n.path === p).sort((a, b) => a.lvl - b.lvl);
    const name = RPG_PATH_NAMES[rpgState.clazz][p - 1];
    const head = chosen === p ? `<div class="sk-path-head on">🛤️ ${name} — YOUR PATH</div>`
      : chosen ? `<div class="sk-path-head off">🔒 ${name}</div>`
      : `<div class="sk-path-head">${name}</div>`;
    // rival skills render side by side as a "pick one" tier
    const seen = new Set();
    const rows = list.map(n => {
      if (seen.has(n.id)) return "";
      seen.add(n.id);
      const rv = n.riv && list.find(m => m.id === n.riv && !seen.has(m.id));
      if (!rv) return nodeHtml(n);
      seen.add(rv.id);
      return `<div class="sk-pair">${nodeHtml(n)}<span class="sk-or">or</span>${nodeHtml(rv)}</div>`;
    }).join("");
    return `<div class="sk-col ${chosen && chosen !== p ? "sealed-col" : ""}">${head}${rows}</div>`;
  }).join("");
  const earned = rpgSkillPointsEarned();
  return `<div class="sk-head">
      <span class="chip">${c.icon} ${c.name}</span>
      <span class="chip topic">✦ ${rpgSkillPoints()} of ${earned} point${earned === 1 ? "" : "s"} free</span>
      ${chosen ? `<span class="chip" style="background:var(--accent-orange-light);color:#9a5a13;">🛤️ ${RPG_PATH_NAMES[rpgState.clazz][chosen - 1]}</span>` : `<span class="chip" style="background:var(--accent-red-light);color:var(--accent-red);">Choose ONE path — the others lock!</span>`}
      <span style="flex:1;"></span>
      <button class="btn btn-ghost btn-sm" type="button" data-rpg-skillreset>↩️ Refund points</button>
      <button class="btn btn-ghost btn-sm" type="button" data-rpg-classreset>🔄 Change class</button>
    </div>
    <div class="section-label">Core training (always open)</div>
    <div class="sk-base">${base.map(nodeHtml).join("")}</div>
    <div class="section-label" style="margin-top:12px;">Specialisation paths — pick one, live with it</div>
    <div class="sk-tree">${pathCols}</div>
    ${rpgStarShopHtml()}
    <p class="hint" style="margin-top:10px;">Points are scarce: 1 per level to 30, then 1 every 2 levels. Every tier on your path is a CHOICE — pick one of two rival skills and the other seals. Keystones trade a weakness for great power. Refunding is free and unseals your tier choices (but not your path until you re-choose).</p>`;
}
function rpgPacksTabHtml() {
  const mythics = RPG_ITEMS.filter(it => it.rarity === "mythic");
  const full = RPG_PACK_COST;
  const price = rpgPackPrice();
  const gold = (rpgState && rpgState.gold) || 0;
  const allN = Math.floor(gold / full);
  return `<div class="pack-shop">
    <div class="pack-hero"><span class="pack-hero-box">🎁</span>
      <div><h4>Booster Pack</h4><p>One random item from the entire armoury — and the <b class="pack-mythic-text">only</b> way to get Mythic gear. Open a batch to see your whole haul at once.</p></div>
    </div>
    <div class="pack-buy-row">
      <button class="btn btn-primary" type="button" data-rpg-pack ${gold < price ? "disabled" : ""}>🎁 Open 1 · 🪙 ${price}${rpgState.packCoupon ? " (½ price!)" : ""}</button>
      <button class="btn btn-outline" type="button" data-rpg-pack-n="10" ${gold < 10 * full ? "disabled" : ""}>Open ×10 · 🪙 ${(10 * full).toLocaleString()}</button>
      <button class="btn btn-outline" type="button" data-rpg-pack-n="50" ${gold < 50 * full ? "disabled" : ""}>Open ×50 · 🪙 ${(50 * full).toLocaleString()}</button>
      <button class="btn btn-outline" type="button" data-rpg-pack-all ${allN < 1 ? "disabled" : ""}>Spend all 🪙${allN > 0 ? ` · ×${allN}` : ""}</button>
    </div>
    <div class="pack-rates">${RPG_PACK_RATES.map(([r, p]) => `<span class="pack-rate" style="border-color:${RPG_RARITY[r].color};color:${RPG_RARITY[r].color};">${RPG_RARITY[r].label} ${p}%</span>`).join("")}<span class="pack-rate">Duplicates refund gold</span></div>
    <div class="section-label" style="margin-top:16px;">Mythic treasures</div>
    <div class="rpg-grid">${mythics.map(it => rpgItemCardHtml(it, "showcase")).join("")}</div>
  </div>`;
}
function rpgRollPackRarity() {
  const roll = Math.random() * 100;
  let acc = 0;
  for (const [rar, p] of RPG_PACK_RATES) { acc += p; if (roll < acc) return rar; }
  return "common";
}
function rpgPackPrice() { return rpgState && rpgState.packCoupon ? Math.round(RPG_PACK_COST / 2) : RPG_PACK_COST; }
function rpgOpenPack() {
  if (!rpgState) return;
  const price = rpgPackPrice();
  if (rpgState.gold < price) { toast(`A pack costs 🪙 ${price} — solve more questions!`, "error"); return; }
  rpgState.gold -= price;
  if (rpgState.packCoupon) { rpgState.packCoupon = 0; toast("🎟️ Half-price coupon used!", ""); }
  const rarity = rpgRollPackRarity();
  const pool = RPG_ITEMS.filter(it => it.rarity === rarity && (it.packOnly || it.price > 0));
  const it = pool[Math.floor(Math.random() * pool.length)];
  const dup = !!rpgState.inventory[it.id];
  let refund = 0;
  if (dup) { refund = Math.max(30, Math.round((it.price || 1500) * 0.4)); rpgState.gold += refund; }
  else { rpgState.inventory[it.id] = 1; rpgRollAffixes(it, true); }
  rpgState.stats.packsOpened = (rpgState.stats.packsOpened || 0) + 1;
  rpgSave();
  rpgPublishLeaderboard();
  const token = ++rpgPackToken;
  $("rpgPackBody").innerHTML = `<div class="pack-stage"><div class="pack-flash" id="packFlash"></div><span class="pack-box">🎁</span></div>`;
  const again = $("rpgPackAgain");
  if (again) again.style.display = "none";
  $("rpgPackOverlay").classList.add("show");
  setTimeout(() => { if (rpgPackToken === token) rpgPackReveal(it, dup, refund); }, 1550);
}
function rpgPackReveal(it, dup, refund) {
  const rar = RPG_RARITY[it.rarity];
  const rank = rar.rank;
  const mythic = it.rarity === "mythic";
  const body = $("rpgPackBody");
  body.innerHTML = `<div class="pack-stage">
    <div class="pack-flash on" style="background:${rar.color};"></div>
    <span class="pack-burst" style="border-color:${rar.color};"></span>
    <div class="pack-reveal">
      <div class="pack-rarity ${mythic ? "pack-mythic-text" : ""}" style="${mythic ? "" : `color:${rar.color};`}">${mythic ? "✦ MYTHIC ✦" : rar.label}</div>
      <div class="pack-item-art t-${it.rarity}">${rpgItemIconSvg(it)}</div>
      <div class="pack-name">${escapeHtml(rpgDisplayName(it))}</div>
      <div class="pack-sub">${escapeHtml(rpgStatLine(it))}${RPG_SKILLS[it.id] ? ` · ${RPG_SKILLS[it.id].icon} ${escapeHtml(RPG_SKILLS[it.id].name)}` : ""}</div>
      <div class="pack-sub">${dup ? `Duplicate — refunded <b>🪙 ${refund}</b>` : "✨ Added to your inventory!"}</div>
    </div>
  </div>`;
  const stage = body.querySelector ? body.querySelector(".pack-stage") : null;
  if (stage) {
    const emojis = mythic ? ["💖", "✨", "⭐"] : rank >= 5 ? ["✨", "⭐"] : ["✨"];
    for (let i = 0; i < (rank >= 5 ? 14 : 7); i++) {
      const s = document.createElement("span");
      s.className = "adv-pop";
      s.textContent = emojis[i % emojis.length];
      if (s.style && s.style.setProperty) {
        s.style.setProperty("--dx", (Math.random() * 220 - 110).toFixed(0) + "px");
        s.style.setProperty("--dy", (Math.random() * 200 - 100).toFixed(0) + "px");
        s.style.left = "48%";
        s.style.top = "42%";
        s.style.animationDelay = (Math.random() * 0.25).toFixed(2) + "s";
        s.style.animationDuration = "1.3s";
      }
      stage.appendChild(s);
      setTimeout(() => s.remove(), 1700);
    }
  }
  const again = $("rpgPackAgain");
  if (again) {
    again.style.display = "";
    again.disabled = rpgState.gold < rpgPackPrice();
    again.textContent = `Open another · 🪙 ${rpgPackPrice()}`;
  }
  if (document.querySelector("#page-character.active")) rpgRenderCharacterPage();
  toast(dup ? `Duplicate ${it.name} → +🪙 ${refund}` : `${rar.label} pull: ${it.name}!`, rank >= 5 ? "success" : "");
}
// Roll ONE pack and apply it to inventory/refund — state only. The caller handles
// gold, save and the reveal. Mirrors the single-open core (rpgOpenPack).
function _rpgRollPack() {
  const rarity = rpgRollPackRarity();
  const pool = RPG_ITEMS.filter(it => it.rarity === rarity && (it.packOnly || it.price > 0));
  const it = pool[Math.floor(Math.random() * pool.length)];
  const dup = !!rpgState.inventory[it.id];
  let refund = 0;
  if (dup) { refund = Math.max(30, Math.round((it.price || 1500) * 0.4)); rpgState.gold += refund; }
  else { rpgState.inventory[it.id] = 1; rpgRollAffixes(it, true); }
  rpgState.stats.packsOpened = (rpgState.stats.packsOpened || 0) + 1;
  return { it, dup, refund };
}
// Open many packs at once (×10, ×50, or "spend all") and show the whole haul in
// one summary — no per-pack animation. The half-price coupon applies to pack 1.
function rpgOpenPacks(requested) {
  if (!rpgState) return;
  const full = RPG_PACK_COST;
  let n = 0, g = rpgState.gold, coupon = !!rpgState.packCoupon;
  while (n < requested) {
    const price = (coupon && n === 0) ? Math.round(full / 2) : full;
    if (g < price) break;
    g -= price; n++;
    if (n >= 500) break; // safety cap per click
  }
  if (n < 1) { toast(`A pack costs 🪙 ${rpgPackPrice()} — solve more questions!`, "error"); return; }
  ++rpgPackToken; // cancel any pending single-pack reveal
  let spent = 0, refund = 0;
  const results = [];
  for (let i = 0; i < n; i++) {
    const price = (rpgState.packCoupon && i === 0) ? Math.round(full / 2) : full;
    rpgState.gold -= price; spent += price;
    if (rpgState.packCoupon && i === 0) rpgState.packCoupon = 0;
    const r = _rpgRollPack();
    refund += r.refund;
    results.push(r);
  }
  rpgSave();
  rpgPublishLeaderboard();
  rpgShowPackSummary(results, spent, refund, n);
  if (document.querySelector("#page-character.active")) rpgRenderCharacterPage();
}
function rpgShowPackSummary(results, spent, refund, n) {
  const order = ["mythic", "legendary", "epic", "rare", "uncommon", "common"];
  const tally = {};
  results.forEach(r => { tally[r.it.rarity] = (tally[r.it.rarity] || 0) + 1; });
  const tallyHtml = order.filter(r => tally[r]).map(r =>
    `<span class="pack-rate" style="border-color:${RPG_RARITY[r].color};color:${RPG_RARITY[r].color};">${RPG_RARITY[r].label} ×${tally[r]}</span>`).join("");
  const newCount = results.filter(r => !r.dup).length;
  const dupCount = results.length - newCount;
  const sorted = results.slice().sort((a, b) => RPG_RARITY[b.it.rarity].rank - RPG_RARITY[a.it.rarity].rank);
  // Show every pull for small batches; for big ones, show the rare+ highlights.
  const showAll = results.length <= 50;
  const rareRank = RPG_RARITY.rare.rank;
  const shown = showAll ? sorted : sorted.filter(r => RPG_RARITY[r.it.rarity].rank >= rareRank);
  const cards = shown.map(r => {
    const rar = RPG_RARITY[r.it.rarity];
    return `<div class="pack-haul-card" style="--rar:${rar.color};">
      <div class="pack-item-art t-${r.it.rarity}">${rpgItemIconSvg(r.it)}</div>
      <div style="min-width:0;">
        <div style="font-size:0.58rem;font-weight:700;letter-spacing:.1em;text-transform:uppercase;color:${rar.color};">${rar.label}</div>
        <div class="rpg-item-name" style="white-space:nowrap;overflow:hidden;text-overflow:ellipsis;">${escapeHtml(rpgDisplayName(r.it))}</div>
        <div style="font-size:0.7rem;color:var(--text-muted);">${r.dup ? `dup · +🪙 ${r.refund}` : "✨ new"}</div>
      </div>
    </div>`;
  }).join("");
  const hidden = results.length - shown.length;
  const more = hidden > 0 ? `<p class="pack-sub" style="margin-top:8px;">…and ${hidden} more common/uncommon item${hidden === 1 ? "" : "s"}.</p>` : "";
  const body = $("rpgPackBody");
  if (body) body.innerHTML = `
    <div style="text-align:center;">
      <div class="pack-name">Opened ${n} pack${n === 1 ? "" : "s"} 🎁</div>
      <div class="pack-sub" style="margin-bottom:10px;"><b style="color:var(--primary);">${newCount}</b> new · <b>${dupCount}</b> duplicate${dupCount === 1 ? "" : "s"} · spent 🪙 ${spent.toLocaleString()}${refund ? ` · refunded 🪙 ${refund.toLocaleString()}` : ""}</div>
      <div class="pack-rates" style="justify-content:center;margin-bottom:12px;">${tallyHtml}</div>
      <div class="pack-haul">${cards}</div>
      ${more}
    </div>`;
  const overlay = $("rpgPackOverlay");
  if (overlay) overlay.classList.add("show");
  const again = $("rpgPackAgain");
  if (again) again.style.display = "none";
  const best = sorted[0];
  if (best) toast(`Opened ${n} pack${n === 1 ? "" : "s"} — ${newCount} new item${newCount === 1 ? "" : "s"}!`, RPG_RARITY[best.it.rarity].rank >= 5 ? "success" : "");
}
function rpgEquip(itemId) {
  const it = RPG_ITEMS_BY_ID[itemId];
  if (!it || !rpgState.inventory[itemId]) return;
  if (it.levelReq > rpgLevelInfo().level && !(rpgState.rebirths > 0)) { toast(`Reach Lv ${it.levelReq} to equip ${it.name}`, "error"); return; }
  if (!rpgClassCanEquip(it)) { toast(rpgClassEquipNote(it), "error"); return; }
  rpgState.equipment[it.slot] = itemId;
  rpgState.hp = Math.min(rpgState.hp, rpgPlayerStats().maxHp);
  rpgSave();
  rpgPublishLeaderboard();
  rpgRenderCharacterPage();
  rpgRenderBattle();
  toast(`${it.name} equipped ⚔️`, "success");
}
function rpgUnequip(slot) {
  if (!rpgState.equipment[slot]) return;
  rpgState.equipment[slot] = null;
  rpgState.hp = Math.min(rpgState.hp, rpgPlayerStats().maxHp);
  rpgSave();
  rpgPublishLeaderboard();
  rpgRenderCharacterPage();
  rpgRenderBattle();
}
function rpgBuy(itemId) {
  const it = RPG_ITEMS_BY_ID[itemId];
  if (!it || rpgState.inventory[itemId]) return;
  if (it.levelReq > rpgLevelInfo().level) { toast(`Reach Lv ${it.levelReq} first`, "error"); return; }
  if (rpgState.gold < it.price) { toast("Not enough gold — solve more questions!", "error"); return; }
  rpgState.gold -= it.price;
  rpgState.inventory[itemId] = 1;
  rpgSave();
  rpgRenderCharacterPage();
  toast(`Bought ${it.name}! Equip it from your inventory`, "success");
}

// ---- Leaderboard (shared collection: scienceGameLeaderboard/{uid}) ----
// Students publish a small game-only summary (no learning data) that all
// signed-in users can read. Firestore rules must allow read for signed-in
// users and write only to your own doc.
function rpgMonthKey(d = new Date()) { return d.getFullYear() + "-" + String(d.getMonth() + 1).padStart(2, "0"); }
function rpgPrevMonthKey() { const d = new Date(); d.setDate(1); d.setMonth(d.getMonth() - 1); return rpgMonthKey(d); }
// Compact per-game leaderboard payload (best score all-time + this/last month).
function rpgGameBoardData(key) {
  rpgEnsureGameScores();
  const g = (rpgState.gameScores && rpgState.gameScores[key]) || {};
  return {
    best: g.best || 0, bestLabel: g.bestLabel || "",
    month: g.monthBest || 0, monthLabel: g.monthLabel || "", monthKey: g.monthKey || null,
    last: g.lastBest || 0, lastLabel: g.lastLabel || "", lastKey: g.lastKey || null
  };
}
let rpgPublishTimer = null;
function rpgPublishLeaderboard() {
  if (!rpgState || !currentUser || currentUser.role !== "student" || RPG_STORAGE_MODE !== "firestore") return;
  clearTimeout(rpgPublishTimer);
  rpgPublishTimer = setTimeout(() => {
    if (!rpgState || !currentUser) return;
    // merge:true — Science Strike (fps.html) stores its leaderboard stats in a
    // `fps` field on this same doc; a plain overwrite would wipe them.
    setDoc(doc(db, "scienceGameLeaderboard", currentUser.uid), {
      uid: currentUser.uid,
      name: currentUser.name || "Student",
      level: rpgLevelInfo().level,
      xp: rpgState.xp,
      monthXp: rpgState.monthXp || 0,
      monthKey: rpgState.monthKey || rpgMonthKey(),
      lastMonthXp: rpgState.lastMonthXp || 0,
      lastMonthKey: rpgState.lastMonthKey || null,
      monthQ: rpgState.monthQ || 0,
      lastMonthQ: rpgState.lastMonthQ || 0,
      papersQ: rpgState.papersQ || 0,
      lastPapersQ: rpgState.lastPapersQ || 0,
      wins: (rpgState.stats && rpgState.stats.wins) || 0,
      bestFloor: (rpgState.stats && rpgState.stats.bestFloor) || 0,
      arenaWins: (rpgState.stats && rpgState.stats.arenaWins) || 0,
      rebirths: rpgState.rebirths || 0,
      // Science Score — what the All-Time board ranks on. Computed here, on the
      // owner's own client, because only it has the pace data.
      score: rpgScorePayload(),
      // Questions answered inside the games — what the 🔥 Embers board ranks on.
      // Every game mode funnels through rpgAwardGameQuestion, so this counts
      // Defenders, Raiders, Spire, Legends, Slayers, Ember Siege and the
      // Realm of Embers trainer in one number.
      games: {
        q: (rpgState.stats && rpgState.stats.gameQ) | 0,
        correct: (rpgState.stats && rpgState.stats.gameCorrect) | 0
      },
      // Admin audit trail (Usage → 🕵️ Activity & points). The wallet lives in
      // the student's own hero doc, which a teacher cannot read, so the numbers
      // needed to explain a board position travel with the published row.
      audit: {
        gold: rpgState.gold | 0,
        goldEarned: (rpgState.stats && rpgState.stats.goldEarned) | 0,
        marked: (rpgState.stats && rpgState.stats.marked) | 0,
        correct: (rpgState.stats && rpgState.stats.correct) | 0,
        gameQ: (rpgState.stats && rpgState.stats.gameQ) | 0,
        gameCorrect: (rpgState.stats && rpgState.stats.gameCorrect) | 0,
        arenaWins: (rpgState.stats && rpgState.stats.arenaWins) | 0,
        arenaLosses: (rpgState.stats && rpgState.stats.arenaLosses) | 0,
        packsOpened: (rpgState.stats && rpgState.stats.packsOpened) | 0,
        advRuns: (rpgState.stats && rpgState.stats.advRunsDone) | 0,
        floors: (rpgState.stats && rpgState.stats.floorsCleared) | 0,
        credits: (rpgState.credits && rpgState.credits.balance) | 0,
        duelClawback: rpgState.duelClawbackAck || null,
        at: new Date().toISOString()
      },
      house: rpgHouseOf(currentUser.uid).id,
      clazz: rpgState.clazz || null,
      equipment: rpgState.equipment,
      td: rpgGameBoardData("defenders"),
      raid: rpgGameBoardData("raiders"),
      spire: rpgGameBoardData("spire"),
      legend: rpgGameBoardData("legend"),   // Ember Legends — best wave reached
      siege: rpgGameBoardData("siege"),     // Ember Siege — deepest wave held
      // Realm of Embers TCG: a complete team of 5 is published so other students
      // can be matched against it in the Battle Arena (null until then).
      tcg: (rpgState.tcg && Array.isArray(rpgState.tcg.team) && rpgState.tcg.team.length === 5) ? {
        team: rpgState.tcg.team.slice(0, 5),
        power: tcgTeamPower(rpgState.tcg.team),
        // Both progression tracks travel with the team so an opponent fights
        // at the strength their owner actually built.
        lvl: Math.max(1, Math.round(rpgState.tcg.team.reduce((a, id) => a + tcgLevel(id), 0) / 5)),
        mlvl: Math.max(1, Math.round(rpgState.tcg.team.reduce((a, id) => a + tcgMergeLevel(id), 0) / 5)),
        wins: rpgState.tcg.wins | 0,
        losses: rpgState.tcg.losses | 0,
        dex: Object.keys(rpgState.tcg.cards || {}).length,
        floor: Math.max(1, ((rpgState.tcg.dungeon || {}).level | 0)),
        clears: (rpgState.tcg.dungeon || {}).cleared | 0,
        artifact: rpgState.tcg.artifact || null
      } : null,
      updatedAt: new Date().toISOString()
    }, { merge: true }).catch(e => console.warn("leaderboard publish", e));
  }, 1200);
}
// ---- Class raid boss: one shared weekly HP pool the whole class chips away ----
const RAID_MAX_HP = 20000, RAID_BOUNTY = 250;
function rpgRaidWeek() { return "W" + Math.floor(Date.now() / 604800000); }
let rpgRaidPending = 0, rpgRaidTimer = null, rpgRaidCache = null;
function rpgRaidContribute(points) {
  if (!points || !currentUser || RPG_STORAGE_MODE !== "firestore" || currentUser.role !== "student") return;
  rpgRaidPending += Math.round(points);
  clearTimeout(rpgRaidTimer);
  rpgRaidTimer = setTimeout(() => {
    const pts = rpgRaidPending;
    rpgRaidPending = 0;
    setDoc(doc(db, "scienceRaidBoss", "current"), { weekKey: rpgRaidWeek(), maxHp: RAID_MAX_HP, name: "Ancient Science Devourer", emoji: "🐲", dealt: increment(pts) }, { merge: true })
      .catch(e => console.warn("raid", e));
  }, 4000);
}
async function rpgRaidHtml() {
  if (RPG_STORAGE_MODE !== "firestore") return "";
  try {
    const snap = await getDoc(doc(db, "scienceRaidBoss", "current"));
    let d = snap.exists() ? snap.data() : null;
    if (!d || d.weekKey !== rpgRaidWeek()) {
      d = { weekKey: rpgRaidWeek(), maxHp: RAID_MAX_HP, dealt: 0, name: "Ancient Science Devourer", emoji: "🐲" };
      setDoc(doc(db, "scienceRaidBoss", "current"), d).catch(() => {});
    }
    rpgRaidCache = d;
    const left = Math.max(0, (d.maxHp || RAID_MAX_HP) - (d.dealt || 0));
    const pct = Math.round(left / (d.maxHp || RAID_MAX_HP) * 100);
    const dead = left <= 0;
    const claimed = rpgState && rpgState.raidClaim === rpgRaidWeek();
    return `<div class="rpg-raid">
      <span class="rpg-raid-boss">${d.emoji || "🐲"}</span>
      <div class="rpg-raid-main">
        <div class="rpg-raid-name">${escapeHtml(d.name || "Raid Boss")} — <b>class raid</b> ${dead ? "· DEFEATED! 🎉" : ""}</div>
        <div class="rpg-bar light"><div class="rpg-bar-fill hp" style="width:${pct}%;"></div><div class="rpg-bar-label">${left} / ${d.maxHp}</div></div>
        <div class="rpg-raid-sub">Every XP your class earns is damage. New boss every week.</div>
      </div>
      ${dead && !claimed && rpgState ? `<button class="btn btn-primary btn-sm" type="button" data-rpg-raidclaim>🎁 Claim 🪙 ${RAID_BOUNTY}</button>` : ""}
    </div>`;
  } catch (e) { console.warn("raid load", e); return ""; }
}
let rpgBoardTab = "month";
let rpgBoardRows = null;
// Accounts retired by an admin password reset: their leaderboard docs are
// deleted where rules allow, but this shared map (written by the admin,
// readable like the other admin settings docs) hides any that survive.
let _retiredUidsCache = null;
async function _getRetiredUids() {
  if (_retiredUidsCache) return _retiredUidsCache;
  const owner = (currentUser && currentUser.role === 'admin') ? currentUser.uid : adminUid;
  const out = new Set();
  if (owner) {
    try {
      const s = await getDoc(doc(db, 'users', owner, 'settings', 'retiredAccounts'));
      const uids = (s.exists() && s.data().uids) || {};
      Object.keys(uids).forEach(u => { if (uids[u]) out.add(u); });
    } catch (e) { console.warn('retired map read', e); }
  }
  _retiredUidsCache = out;
  return out;
}
// ---- Leaderboard bans ---------------------------------------------------
// A student the teacher has excluded from the boards — a place won with points
// earned in a way the teacher has ruled out should not outrank classmates who
// answered questions for theirs. A ban changes NOTHING about the student's own
// hero, wallet, cards or progress; it only removes them from the rankings, and
// it is reversible.
//
// Bans are SCOPED, because the fair remedy is usually narrower than "every
// board": a student who farmed points into Realm of Embers should come off the
// Embers family and still be able to compete honestly on questions.
//
// Filtering happens at RENDER, per tab — not at fetch — so one predicate
// serves the main board, the board inside Realm of Embers and the prize
// winners table. Read from the same shared-settings path as retiredAccounts,
// so the student's OWN client filters them out too and republishing cannot put
// them back.
const BOARD_BAN_SCOPES = {
  all:    { label: 'Every leaderboard', short: 'all boards', tabs: null },
  embers: { label: '🔥 Realm of Embers family (Embers, Siege, Legends)', short: 'Embers family', tabs: ['tcg', 'siege', 'legend'] }
};
// Which board tab a prize category is decided on — so a scoped ban keeps a
// student out of the winners table for exactly the boards they are off.
const PRIZE_CATEGORY_TAB = {
  questions: 'month', defenders: 'td', raiders: 'raid', spire: 'spire',
  legends: 'legend', siege: 'siege', strike: 'fps', embers: 'tcg'
};
let _boardBansCache = null;          // uid -> scope key, or null until first read
function rpgBoardBanMap() { return _boardBansCache || {}; }
// Is `uid` off the board `tab` shows? An unknown scope is treated as 'all',
// so a typo in the settings doc fails closed rather than silently doing nothing.
function rpgBoardBanned(uid, tab) {
  const scope = rpgBoardBanMap()[uid];
  if (!scope) return false;
  const def = BOARD_BAN_SCOPES[scope];
  if (!def || !def.tabs) return true;
  return def.tabs.indexOf(tab) >= 0;
}
async function _getBoardBans() {
  if (_boardBansCache) return _boardBansCache;
  const owner = (currentUser && currentUser.role === 'admin') ? currentUser.uid : adminUid;
  const out = {};
  if (owner) {
    try {
      const s = await getDoc(doc(db, 'users', owner, 'settings', 'boardBans'));
      const d = (s.exists() && s.data()) || {};
      const uids = d.uids || {}, scopes = d.scopes || {};
      // `uids[uid] === true` with no scope is a ban written before scopes
      // existed — those meant every board, so they stay that way.
      Object.keys(uids).forEach(u => { if (uids[u]) out[u] = scopes[u] || 'all'; });
      _boardBansCache = out;   // only cache a real read — caching the empty map
    } catch (e) { console.warn('board bans read', e); }  // before adminUid is known
  }                                                      // would un-ban everyone for the session
  return out;
}
// Every published row. Bans are applied per tab at render, so this is what the
// boards start from and what the admin audit view reads.
let _rpgBoardRowsRaw = null;
function rpgBoardRowsRaw() { return _rpgBoardRowsRaw || []; }
async function rpgFetchLeaderboard(force) {
  if (rpgBoardRows && !force) return rpgBoardRows;
  const rows = [];
  try {
    const retired = await _getRetiredUids();
    await _getBoardBans();   // populate the map the render-time predicate reads
    const snap = await getDocs(collection(db, "scienceGameLeaderboard"));
    snap.forEach(d => {
      const r = d.data();
      if (!r || !r.uid || !r.name) return;
      if (retired.has(r.uid) || retired.has(d.id)) return;
      rows.push(r);
    });
  } catch (e) { console.warn("leaderboard load", e); return null; }
  _rpgBoardRowsRaw = rows;
  rpgBoardRows = rows;
  return rows;
}
// The "td" / "raid" tabs rank by this month's best mini-game score; "month" /
// "lastmonth" rank by UNIQUE QUESTIONS DONE; "alltime" ranks by XP; "fps"
// (Science Strike) ranks by all-time correct answers from fps.html's `fps` field.
function rpgIsGameTab() { return rpgBoardTab === "td" || rpgBoardTab === "raid" || rpgBoardTab === "spire" || rpgBoardTab === "legend" || rpgBoardTab === "siege"; }
// How many winners a game board pays. Ember Legends pays the top 5; the older
// arcade boards pay the top 3.
function rpgGameTopN(tab) { return tab === "legend" ? 5 : 3; }   // Siege and the older arcade boards pay 3
// Months a board runs WITHOUT a prize. The board still ranks exactly as usual;
// only the badge, the row highlight and the month-end claim prompt are
// suppressed for the months listed here. Keyed by board tab
// ("td" = Science Defenders, "spire" = Science Spire, "raid" = Science Raiders).
const RPG_NO_PRIZE_MONTHS = { td: ["2026-08"], spire: ["2026-08"] };
function rpgPrizeOffFor(tab, monthKey) {
  const months = RPG_NO_PRIZE_MONTHS[tab];
  return !!(months && months.indexOf(monthKey) >= 0);
}
function rpgBoardMetric(r) {
  if (rpgBoardTab === "alltime") return rpgRowScore(r);
  if (rpgBoardTab === "fps") return (r.fps && r.fps.correct) | 0;
  // Realm of Embers TCG: ranked by TOTAL TEAM POWER, the same metric the board
  // inside the TCG page uses.
  if (rpgBoardTab === "tcg") return rpgRowGameQ(r).correct;
  if (rpgBoardTab === "month") return r.monthKey === rpgMonthKey() ? (r.monthQ || 0) : 0;
  if (rpgBoardTab === "papers") return r.monthKey === rpgMonthKey() ? (r.papersQ || 0) : 0;
  if (rpgIsGameTab()) {
    const g = r[rpgBoardTab]; // r.td / r.raid
    return g && g.monthKey === rpgMonthKey() ? (g.month || 0) : 0;
  }
  // lastmonth
  const prev = rpgPrevMonthKey();
  if (r.monthKey === prev) return r.monthQ || 0;          // not active yet this month
  if (r.lastMonthKey === prev) return r.lastMonthQ || 0;  // rolled over
  return 0;
}
function rpgBoardUnit() { return rpgBoardTab === "alltime" ? "score" : rpgBoardTab === "fps" || rpgBoardTab === "tcg" ? "correct" : rpgIsGameTab() ? "pts" : "questions"; }
// Pretty value for a row: game tabs show the run's label (e.g. "Floor 7 · 142 kills").
function rpgBoardValueHtml(r) {
  const sub = (rpgBoardTab === "month" || rpgBoardTab === "papers") ? "this month" : rpgBoardTab === "lastmonth" ? "last month" : rpgIsGameTab() ? "best this month" : "all-time";
  if (rpgBoardTab === "fps") {
    const f = r.fps || {};
    return `${r.shownVal} correct<span>🌊 wave ${f.bestWave | 0} · 👾 ${f.kills | 0} kills</span>`;
  }
  if (rpgBoardTab === "tcg") {
    const t = r.tcg || {};
    const g = rpgRowGameQ(r);
    const pct = g.q > 0 ? Math.round(g.correct / g.q * 100) : null;
    const extra = t.power ? ` · ⚔️ ${(t.power | 0).toLocaleString()} power` : "";
    return `${r.shownVal.toLocaleString()} correct<span>🎮 ${g.q.toLocaleString()} answered in games${pct != null ? ` · ${pct}%` : ""}${extra}</span>`;
  }
  if (rpgIsGameTab()) {
    const g = r[rpgBoardTab] || {};
    const lbl = (g.monthKey === rpgMonthKey() && g.monthLabel) ? g.monthLabel : (r.shownVal + " pts");
    return `${escapeHtml(lbl)}<span>${sub}</span>`;
  }
  // All-Time shows how the score was built, so the ranking explains itself.
  if (rpgBoardTab === "alltime") {
    const s = r.score || {};
    const a = r.audit || {};
    const q = s.q != null ? s.q : (a.marked | 0);
    const acc = s.acc != null ? Math.round(s.acc * 100) : (a.marked ? Math.round(Math.min(a.marked, a.correct | 0) / a.marked * 100) : null);
    const pace = s.pace != null ? Math.round(s.pace * 100) : null;
    const bits = [`✍️ ${Math.round(q).toLocaleString()} answered`];
    if (acc != null) bits.push(`✅ ${acc}% right`);
    bits.push(pace != null ? `🕒 ${pace}% unrushed` : `🕒 pace pending`);
    return `${r.shownVal.toLocaleString()} score<span>${bits.join(" · ")}</span>`;
  }
  return `${r.shownVal} ${rpgBoardUnit()}<span>${sub}</span>`;
}
function rpgPrizeBadge(rank) {
  if (rpgBoardTab === "papers") return "";   // ranking board only — no prize attached
  if (rpgBoardTab === "fps") return rank <= 3 ? `<span class="rpg-board-prize">🎁 $10 voucher</span>` : "";
  if (rpgBoardTab === "tcg") return rank <= 6 ? `<span class="rpg-board-prize">🎁 $10 voucher</span>` : "";
  if (rpgIsGameTab()) {
    if (rpgPrizeOffFor(rpgBoardTab, rpgMonthKey())) return "";  // month runs without a prize
    return rank <= rpgGameTopN(rpgBoardTab) ? `<span class="rpg-board-prize">🎁 $10 voucher</span>` : "";
  }
  if (rpgBoardTab !== "alltime") return rank <= 5 ? `<span class="rpg-board-prize">🎁 $10 voucher</span>` : "";
  if (rank === 1) return `<span class="rpg-board-prize">🏆 $200 voucher</span>`;
  if (rank === 2) return `<span class="rpg-board-prize">🥈 $100 voucher</span>`;
  if (rank === 3) return `<span class="rpg-board-prize">🥉 $50 voucher</span>`;
  return "";
}
function rpgRowClass(rank) {
  if (rpgBoardTab === "papers") return "";
  if (rpgBoardTab === "fps") return rank <= 3 ? `prize-${rank}` : "";
  if (rpgBoardTab === "tcg") return rank <= 3 ? `prize-${rank}` : rank <= 6 ? "prize-month" : "";
  if (rpgIsGameTab()) {
    if (rpgPrizeOffFor(rpgBoardTab, rpgMonthKey())) return "";
    return rank <= 3 ? `prize-${rank}` : rank <= rpgGameTopN(rpgBoardTab) ? "prize-month" : "";
  }
  if (rpgBoardTab !== "alltime") return rank <= 5 ? "prize-month" : "";
  return rank <= 3 ? `prize-${rank}` : "";
}
// One calm line above the rows: what this tab pays out, or that the month is
// running without a prize.
function rpgBoardNote() {
  if (rpgBoardTab === "tcg")
    return `<div class="rpg-board-note">🔥 <b>Realm of Embers:</b> the <b>top 6</b> by <b>questions answered correctly inside the games</b> each win a <b>$10 Popular voucher</b>. Defenders, Raiders, Spire, Legends, Slayers, 🌋 Ember Siege and the 🎓 trainer all count — nothing you buy can move this board. Counting from August 2026, so everyone starts level.</div>`;
  if (rpgBoardTab === "legend" && !rpgPrizeOffFor("legend", rpgMonthKey()))
    return `<div class="rpg-board-note">⚔️ <b>Ember Legends:</b> the <b>top 5</b> by best wave reached this month each win a <b>$10 Popular voucher</b>.</div>`;
  if (rpgBoardTab === "siege" && !rpgPrizeOffFor("siege", rpgMonthKey()))
    return `<div class="rpg-board-note">🌋 <b>Ember Siege:</b> the <b>top 3</b> by deepest wave held this month each win a <b>$10 Popular voucher</b>.</div>`;
  if (rpgIsGameTab() && rpgPrizeOffFor(rpgBoardTab, rpgMonthKey())) {
    const game = rpgBoardTab === "td" ? "Science Defenders" : rpgBoardTab === "spire" ? "Science Spire"
      : rpgBoardTab === "legend" ? "Ember Legends" : rpgBoardTab === "siege" ? "Ember Siege" : "Science Raiders";
    const month = new Date().toLocaleString("en-SG", { month: "long" });
    return `<div class="rpg-board-note muted">🚫 <b>No prize in ${month}</b> — ${game} is a ranking board this month. Climb it anyway: your score still counts.</div>`;
  }
  return "";
}
async function rpgRenderLeaderboard(force = false) {
  const body = $("rpgBoardBody");
  if (!body) return;
  document.querySelectorAll("[data-rpgboard]").forEach(b => b.classList.toggle("active", b.dataset.rpgboard === rpgBoardTab));
  // Ember Legends is beta-gated, so its board and its prize line stay hidden
  // until the admin releases it — no advertising a prize nobody can play for.
  const legendOn = elgAccessAllowed();
  const legendTab = document.querySelector('[data-rpgboard="legend"]');
  if (legendTab) legendTab.style.display = legendOn ? "" : "none";
  const legendLine = document.getElementById("prizeLineLegends");
  if (legendLine) legendLine.style.display = legendOn ? "" : "none";
  if (!legendOn && rpgBoardTab === "legend") rpgBoardTab = "month";
  if (!rpgBoardRows) body.innerHTML = `<div class="empty-note">Loading leaderboard…</div>`;
  rpgRaidHtml().then(h => { const el = $("rpgRaidSlot"); if (el) el.innerHTML = h; });
  const fetched = await rpgFetchLeaderboard(force);
  if (fetched === null) {
    body.innerHTML = `<div class="empty-note">Couldn't load the leaderboard. Ensure your Firestore rules let signed-in users read the <b>scienceGameLeaderboard</b> collection.</div>`;
    return;
  }
  // overlay your own live state so the board never lags behind your last answer
  const rows = fetched.slice();
  if (rpgState && currentUser && currentUser.role === "student") {
    const mine = {
      uid: currentUser.uid, name: currentUser.name || "You",
      level: rpgLevelInfo().level, xp: rpgState.xp,
      monthXp: rpgState.monthXp || 0, monthKey: rpgState.monthKey || rpgMonthKey(),
      lastMonthXp: rpgState.lastMonthXp || 0, lastMonthKey: rpgState.lastMonthKey || null,
      monthQ: rpgState.monthQ || 0, lastMonthQ: rpgState.lastMonthQ || 0,
      papersQ: rpgState.papersQ || 0, lastPapersQ: rpgState.lastPapersQ || 0,
      wins: (rpgState.stats && rpgState.stats.wins) || 0, bestFloor: (rpgState.stats && rpgState.stats.bestFloor) || 0,
      arenaWins: (rpgState.stats && rpgState.stats.arenaWins) || 0, rebirths: rpgState.rebirths || 0,
      score: rpgScorePayload(),
      games: { q: (rpgState.stats && rpgState.stats.gameQ) | 0, correct: (rpgState.stats && rpgState.stats.gameCorrect) | 0 },
      house: rpgHouseOf(currentUser.uid).id, clazz: rpgState.clazz || null,
      equipment: rpgState.equipment,
      td: rpgGameBoardData("defenders"), raid: rpgGameBoardData("raiders"), spire: rpgGameBoardData("spire"), legend: rpgGameBoardData("legend"), siege: rpgGameBoardData("siege"),
      updatedAt: new Date().toISOString()
    };
    const i = rows.findIndex(r => r.uid === currentUser.uid);
    // merge over the fetched row — it may carry fields we don't track locally
    // (e.g. Science Strike's `fps` stats, published by fps.html)
    if (i >= 0) rows[i] = Object.assign({}, rows[i], mine); else rows.push(mine);
  }
  const list = rows.filter(r => !rpgBoardBanned(r.uid, rpgBoardTab))
    .map(r => Object.assign({}, r, { shownVal: rpgBoardMetric(r) }))
    .filter(r => r.shownVal > 0)
    .sort((a, b) => b.shownVal - a.shownVal || String(a.updatedAt || "").localeCompare(String(b.updatedAt || "")));
  if (!list.length) {
    const why = rpgBoardTab === "month" ? "No questions done this month yet — be the first on the board!"
      : rpgBoardTab === "papers" ? "No past-year exam-paper questions done this month yet — practise a PSLE paper question to top this board! Tip: paper questions answered in a game's past-paper mode count ×2."
      : rpgBoardTab === "lastmonth" ? "No questions were recorded last month."
      : rpgBoardTab === "td" ? "No Science Defenders runs this month yet — play to claim the top spot!"
      : rpgBoardTab === "raid" ? "No Science Raiders runs this month yet — dive in to top the board!"
      : rpgBoardTab === "spire" ? "No Science Spire climbs this month yet — build a deck and claim the top!"
      : rpgBoardTab === "legend" ? "No Ember Legends runs this month yet — take a monster into the arena and set the first wave!"
      : rpgBoardTab === "siege" ? "No Ember Siege runs this month yet — defend the gate and set the deepest wave!"
      : rpgBoardTab === "fps" ? "No Science Strike answers yet — jump into a run and answer questions to claim the board!"
      : rpgBoardTab === "tcg" ? "Nobody on the board yet — answer questions inside any Realm of Embers game mode to claim the top spot!"
      : rpgBoardTab === "alltime" ? "No Science Scores yet — answer questions to build one. Your score rebuilds as each student opens the app."
      : "No heroes on the board yet — solve questions to earn XP!";
    body.innerHTML = rpgBoardNote() + `<div class="empty-note">${why}</div>`;
    return;
  }
  const myUid = currentUser && currentUser.uid;
  // house race: this month's questions done summed by house
  let houseBar = "";
  if (rpgBoardTab === "month") {
    const tot = {};
    rows.forEach(r => { const h = r.house || rpgHouseOf(r.uid).id; tot[h] = (tot[h] || 0) + (r.monthKey === rpgMonthKey() ? r.monthQ || 0 : 0); });
    const maxT = Math.max(1, ...RPG_HOUSES.map(h => tot[h.id] || 0));
    houseBar = `<div class="rpg-houses">` + RPG_HOUSES.map(h =>
      `<div class="rpg-house-row"><span>${h.icon} ${h.name}</span><div class="rpg-house-bar"><div style="width:${Math.round((tot[h.id] || 0) / maxT * 100)}%;background:${h.color};"></div></div><b>${tot[h.id] || 0}</b></div>`).join("") + `</div>`;
  }
  body.innerHTML = rpgBoardNote() + houseBar + list.slice(0, 50).map((r, i) => {
    const rank = i + 1;
    const me = r.uid === myUid;
    const medal = rank === 1 ? "🥇" : rank === 2 ? "🥈" : rank === 3 ? "🥉" : rank;
    return `<div class="rpg-board-row ${rpgRowClass(rank)} ${me ? "me" : ""}">
      <div class="rpg-board-rank">${medal}</div>
      <div class="rpg-board-ava">${rpgAvatarSvg(r.equipment || {})}</div>
      <div class="rpg-board-main">
        <div class="rpg-board-name">${r.clazz && RPG_CLASSES[r.clazz] ? RPG_CLASSES[r.clazz].icon + " " : ""}${escapeHtml(r.name)}${r.rebirths ? ` <span class="rpg-item-up" title="Starfall rebirths">R${r.rebirths}</span>` : ""}${me ? `<span class="rpg-you-tag">You</span>` : ""}</div>
        <div class="rpg-board-meta">${(RPG_HOUSES.find(h => h.id === (r.house || rpgHouseOf(r.uid).id)) || RPG_HOUSES[0]).icon} Lv ${r.level || 1} · ${r.wins || 0} battles won${r.bestFloor ? ` · 🏰 F${r.bestFloor}` : ""}${r.arenaWins ? ` · ⚔️ ${r.arenaWins}W` : ""}</div>
      </div>
      ${rpgPrizeBadge(rank)}
      ${!me && r.equipment && currentUser && currentUser.role === "student" ? `<button class="btn btn-ghost btn-sm" type="button" data-rpg-duel="${escapeHtml(r.uid)}">⚔️ Duel</button>` : ""}
      <div class="rpg-board-xp">${rpgBoardValueHtml(r)}</div>
    </div>`;
  }).join("");
  rpgCheckPrizeClaim();
  setTimeout(() => { try { rpgCheckStreakVoucher(); } catch (_) {} }, 1200);
}

// ---- Month-end prize claim ---------------------------------------------
// Three monthly $10 prizes, each prompting last month's winners to claim:
//   • questions: top 5 by unique questions done
//   • td:        top 3 by best Science Defenders score
//   • raid:      top 3 by best Science Raiders score
// Each category is acknowledged separately (prizeAck[<key>]) and stored as its
// own prizeClaims doc (uid_<key>) so a student can win more than one.
let _prizePromptShown = false;
let _prizeClaimCtx = null;
// Which prize a claim doc belongs to, from its ack key — the admin's claims
// list groups by this, so a new game needs its own name here.
function _prizeCategoryOf(ctx) {
  const k = String((ctx && ctx.ackKey) || "");
  if (k === (ctx && ctx.monthKey)) return "questions";
  if (k.endsWith("_td")) return "defenders";
  if (k.endsWith("_raid")) return "raiders";
  if (k.endsWith("_legend")) return "legends";
  if (k.endsWith("_siege")) return "siege";
  if (k.endsWith("_spire")) return "spire";
  if (k.endsWith("_tcg")) return "embers";
  if (k.endsWith("_fps")) return "strike";
  return "questions";
}
function rpgLastMonthGame(r, key) { // key: "td" | "raid"
  const g = r[key]; if (!g) return 0;
  const prev = rpgPrevMonthKey();
  if (g.monthKey === prev) return g.month || 0;   // not yet rolled over
  if (g.lastKey === prev) return g.last || 0;     // rolled over
  return 0;
}
function rpgLastMonthGameLabel(r, key) {
  const g = r[key]; if (!g) return "";
  const prev = rpgPrevMonthKey();
  if (g.monthKey === prev) return g.monthLabel || "";
  if (g.lastKey === prev) return g.lastLabel || "";
  return "";
}
async function rpgCheckPrizeClaim() {
  try {
    if (_prizePromptShown || !rpgState || !currentUser || currentUser.role !== "student" || RPG_STORAGE_MODE !== "firestore") return;
    const prev = rpgPrevMonthKey();
    rpgState.prizeAck = rpgState.prizeAck || {};
    const rows = await rpgFetchLeaderboard(false);
    if (!rows) return;
    const cats = [
      { key: prev,          topN: 5, noun: "questions done", game: "the leaderboard",
        rank: rows.map(r => ({ uid: r.uid, v: rpgLastMonthQ(r) })) },
      { key: prev + "_td",  topN: 3, noun: "in Science Defenders", game: "Science Defenders", tab: "td",
        rank: rows.map(r => ({ uid: r.uid, v: rpgLastMonthGame(r, "td"),   detail: rpgLastMonthGameLabel(r, "td") })) },
      { key: prev + "_raid",topN: 3, noun: "in Science Raiders", game: "Science Raiders", tab: "raid",
        rank: rows.map(r => ({ uid: r.uid, v: rpgLastMonthGame(r, "raid"), detail: rpgLastMonthGameLabel(r, "raid") })) }
      ,{ key: prev + "_legend", topN: 5, noun: "in Ember Legends", game: "Ember Legends", tab: "legend",
        rank: rows.map(r => ({ uid: r.uid, v: rpgLastMonthGame(r, "legend"), detail: rpgLastMonthGameLabel(r, "legend") })) }
      ,{ key: prev + "_siege", topN: 3, noun: "in Ember Siege", game: "Ember Siege", tab: "siege",
        rank: rows.map(r => ({ uid: r.uid, v: rpgLastMonthGame(r, "siege"), detail: rpgLastMonthGameLabel(r, "siege") })) }
      // Science Spire has no month-end claim of its own (see RPG_NO_PRIZE_MONTHS).
    ].filter(c => !rpgPrizeOffFor(c.tab, prev));   // months listed as prize-free never prompt
    for (const c of cats) {
      if (rpgState.prizeAck[c.key]) continue;
      const ranked = c.rank.filter(r => r.v > 0).sort((a, b) => b.v - a.v);
      const idx = ranked.findIndex(r => r.uid === currentUser.uid);
      if (idx < 0 || idx >= c.topN) continue;
      try {
        const snap = await getDoc(doc(db, "prizeClaims", currentUser.uid + "_" + c.key));
        if (snap.exists()) { rpgState.prizeAck[c.key] = "claimed"; rpgSave(); continue; }
      } catch (_) {}
      _prizePromptShown = true;
      _showPrizeClaim(c, idx + 1, ranked[idx]);
      return; // one prompt at a time; others re-checked next sign-in
    }
  } catch (e) { console.warn("prize claim check", e); }
}
// 30-day / 10-questions-a-day streak voucher. Reuses the same claim overlay and
// submit path as the monthly prizes; each completed 30-day cycle is its own
// claim doc (uid_streak30_<cycle>) so a student can win it again.
function rpgOfferStreakVoucher(cycle) {
  if (!rpgState || !currentUser || currentUser.role !== "student" || RPG_STORAGE_MODE !== "firestore") return;
  _prizeClaimCtx = { ackKey: "streak30_" + cycle, monthKey: advToday(), rank: 0, value: 30, noun: "30-day practice streak", game: "", detail: "30-day 10-question streak", category: "streak" };
  const el = id => document.getElementById(id);
  if (el("prizeClaimMsg")) el("prizeClaimMsg").innerHTML =
    `Incredible — you practised <b>10+ questions every day for 30 days straight</b>! Enter your details and we'll send your <b>$10 Popular voucher</b>.`;
  if (el("prizePhone")) el("prizePhone").value = "";
  if (el("prizeAddress")) el("prizeAddress").value = "";
  if (el("prizeClaimOverlay")) el("prizeClaimOverlay").classList.add("active");
  _prizePromptShown = true;
}
async function rpgCheckStreakVoucher() {
  try {
    if (_prizePromptShown || !rpgState || !currentUser || currentUser.role !== "student" || RPG_STORAGE_MODE !== "firestore") return;
    const cycles = (rpgState.streak && rpgState.streak.vCycles) || 0;
    if (cycles < 1) return;
    rpgState.prizeAck = rpgState.prizeAck || {};
    for (let c = 1; c <= cycles; c++) {
      const ackKey = "streak30_" + c;
      if (rpgState.prizeAck[ackKey]) continue;
      try {
        const snap = await getDoc(doc(db, "prizeClaims", currentUser.uid + "_" + ackKey));
        if (snap.exists()) { rpgState.prizeAck[ackKey] = "claimed"; rpgSave(); continue; }
      } catch (_) {}
      rpgOfferStreakVoucher(c);
      return;
    }
  } catch (e) { console.warn("streak voucher check", e); }
}
function _showPrizeClaim(cat, rank, entry) {
  _prizeClaimCtx = { ackKey: cat.key, monthKey: rpgPrevMonthKey(), rank, value: entry.v, noun: cat.noun, game: cat.game, detail: entry.detail || "" };
  const ord = rank === 1 ? "1st" : rank === 2 ? "2nd" : rank === 3 ? "3rd" : rank + "th";
  const el = id => document.getElementById(id);
  const what = cat.key === rpgPrevMonthKey()
    ? `with <b>${entry.v}</b> question${entry.v === 1 ? "" : "s"} done — the <b>top 5</b>!`
    : `in <b>${escapeHtml(cat.game)}</b>${entry.detail ? ` (<b>${escapeHtml(entry.detail)}</b>)` : ""} — the <b>top ${cat.topN}</b>!`;
  if (el("prizeClaimMsg")) el("prizeClaimMsg").innerHTML =
    `You finished <b>${ord}</b> last month ${what} Enter your details and we'll send your <b>$10 Popular voucher</b>.`;
  if (el("prizePhone")) el("prizePhone").value = "";
  if (el("prizeAddress")) el("prizeAddress").value = "";
  if (el("prizeClaimOverlay")) el("prizeClaimOverlay").classList.add("active");
}
function _closePrizeClaim() {
  const o = document.getElementById("prizeClaimOverlay");
  if (o) o.classList.remove("active");
}
function dismissPrizeClaim() { _closePrizeClaim(); } // closes for now; re-prompts next sign-in
async function submitPrizeClaim() {
  if (!_prizeClaimCtx || !currentUser) return;
  const phone = (document.getElementById("prizePhone").value || "").trim();
  const address = (document.getElementById("prizeAddress").value || "").trim();
  if (!phone || !address) { showToast("Please enter your contact number and address", "error"); return; }
  const ctx = _prizeClaimCtx;
  try {
    await setDoc(doc(db, "prizeClaims", currentUser.uid + "_" + ctx.ackKey), {
      uid: currentUser.uid,
      name: currentUser.name || "",
      email: currentUser.email || "",
      monthKey: ctx.monthKey,
      category: ctx.category || _prizeCategoryOf(ctx),
      rank: ctx.rank,
      questions: ctx.ackKey === ctx.monthKey ? ctx.value : 0,
      score: ctx.value,
      scoreLabel: ctx.detail || "",
      phone, address,
      physical: false, deliveryMethod: "mail",
      status: "pending",
      createdAt: new Date().toISOString()
    });
    rpgState.prizeAck = rpgState.prizeAck || {};
    rpgState.prizeAck[ctx.ackKey] = "claimed";
    rpgSave();
    _closePrizeClaim();
    _prizePromptShown = false;       // allow another category's prompt this session
    showToast("🎉 Claim submitted — we'll send your $10 voucher soon!", "success");
    setTimeout(() => { try { rpgCheckPrizeClaim(); } catch (_) {} setTimeout(() => { try { rpgCheckStreakVoucher(); } catch (_) {} }, 600); }, 800);
  } catch (e) { console.warn("prize claim save", e); showToast("Could not submit — check your connection and try again", "error"); }
}
// Physical (in-person) students collect the voucher in class — confirm here
// instead of giving a mailing address.
async function claimPhysical() {
  if (!_prizeClaimCtx || !currentUser) return;
  const phone = (document.getElementById("prizePhone").value || "").trim();
  const ctx = _prizeClaimCtx;
  try {
    await setDoc(doc(db, "prizeClaims", currentUser.uid + "_" + ctx.ackKey), {
      uid: currentUser.uid,
      name: currentUser.name || "",
      email: currentUser.email || "",
      monthKey: ctx.monthKey,
      category: ctx.category || _prizeCategoryOf(ctx),
      rank: ctx.rank,
      questions: ctx.ackKey === ctx.monthKey ? ctx.value : 0,
      score: ctx.value,
      scoreLabel: ctx.detail || "",
      phone, address: "",
      physical: true, deliveryMethod: "collect",
      status: "pending",
      createdAt: new Date().toISOString()
    });
    rpgState.prizeAck = rpgState.prizeAck || {};
    rpgState.prizeAck[ctx.ackKey] = "claimed";
    rpgSave();
    _closePrizeClaim();
    _prizePromptShown = false;       // allow another category's prompt this session
    showToast("🏫 Confirmed — collect your $10 voucher in class!", "success");
    setTimeout(() => { try { rpgCheckPrizeClaim(); } catch (_) {} setTimeout(() => { try { rpgCheckStreakVoucher(); } catch (_) {} }, 600); }, 800);
  } catch (e) { console.warn("physical claim save", e); showToast("Could not submit — check your connection and try again", "error"); }
}

// =====================================================================
// COMMUNITY BOARD  +  ENCOUNTER QUESTS
//   community       — bulletin-board feed (admin posts auto-approved,
//                     student messages start 'pending' until approved)
//   encounterQuests — timed surprise quests; first student to finish N
//                     questions before the timer ends wins a $10 voucher
//                     (delivered through the normal prizeClaims flow)
// =====================================================================
let _commPosts = [], _commQuests = [];
let _commUnsub = null, _questUnsub = null, _questTick = null, _questSeen = {};
let _commImg = {};                 // dataURL keyed by file-input id
let _questMode = 'auto';            // admin authoring mode: 'auto' | 'race' | 'score'
let _questPick = new Set();         // selected question ids (score mode)
let _questRun = null;              // active score-quest run for this student
let _questOffered = {};            // guards the win overlay per quest id
let _questScorePub = {};           // debounce timers for score publishing

function _commCanFirestore() { return RPG_STORAGE_MODE === 'firestore' && db && currentUser; }
function _commTypeLabel(t) { return ({ news: 'News', guidance: 'Guidance', photo: 'Photo', update: 'Update' })[t] || 'Update'; }

// ---- identity: avatars + status ----------------------------------------
// Mr Chung (the teacher) always posts as the owl professor with the top
// "Polymath" rank. Students pick an animal avatar and climb the ranks by
// posting more — the rank is computed live from their approved-post count.
const COMM_ADMIN_AVATAR = '🦉';
const COMM_ADMIN_NAME    = 'Mr Chung';
const COMM_ADMIN_STATUS  = 'Polymath';
const COMM_AVATARS = ['🦊','🐼','🦁','🐯','🐨','🐸','🐧','🦄','🐢','🐬','🦋','🐝','🦖','🐙','🐺','🐰'];
const COMM_DEFAULT_AVATAR = '🦊';
// Ranks unlocked by number of approved posts (most-posts-first).
const COMM_STATUS_TIERS = [
  { min: 30, label: 'Luminary' },
  { min: 18, label: 'Sage' },
  { min: 10, label: 'Scholar' },
  { min: 5,  label: 'Explorer' },
  { min: 1,  label: 'Contributor' },
  { min: 0,  label: 'Newcomer' },
];
function _isSuperAdmin() { return !!(currentUser && currentUser.email === SUPER_ADMIN_EMAIL); }
function _commStudentStatus(count) {
  for (const t of COMM_STATUS_TIERS) if (count >= t.min) return t.label;
  return 'Newcomer';
}
// Posts needed to reach the next rank (null once at the top).
function _commNextTier(count) {
  const higher = COMM_STATUS_TIERS.filter(t => t.min > count).sort((a, b) => a.min - b.min);
  return higher.length ? { label: higher[0].label, need: higher[0].min - count } : null;
}
// How many approved posts a student has on the board right now.
function _commPostCount(uid) {
  if (!uid) return 0;
  return _commPosts.filter(p => p.authorUid === uid && p.status === 'approved' && p.authorRole !== 'admin').length;
}
function _commMyAvatar() { return (currentUser && currentUser.avatar) || COMM_DEFAULT_AVATAR; }
function _commTimeAgo(iso) {
  const t = new Date(iso).getTime(); if (!t) return '';
  const s = Math.floor((Date.now() - t) / 1000);
  if (s < 60) return 'just now';
  if (s < 3600) return Math.floor(s / 60) + 'm ago';
  if (s < 86400) return Math.floor(s / 3600) + 'h ago';
  const d = Math.floor(s / 86400);
  return d < 7 ? d + 'd ago' : new Date(iso).toLocaleDateString();
}
function _fmtCountdown(ms) {
  if (ms < 0) ms = 0;
  const s = Math.floor(ms / 1000), h = Math.floor(s / 3600), m = Math.floor((s % 3600) / 60), ss = s % 60;
  return (h > 0 ? h + ':' : '') + String(m).padStart(2, '0') + ':' + String(ss).padStart(2, '0');
}
// Human-friendly elapsed time (e.g. "2m 5s") for fastest-to-finish quests.
function _fmtDuration(ms) {
  const s = Math.max(0, Math.round((Number(ms) || 0) / 1000));
  const m = Math.floor(s / 60), ss = s % 60;
  return m ? (m + 'm ' + ss + 's') : (ss + 's');
}

// ---- image attach: downscale client-side, upload to Storage (inline fallback)
function commPreviewImg(input, prevId) {
  const file = input.files && input.files[0];
  const prev = document.getElementById(prevId);
  if (!file) { if (prev) { prev.style.display = 'none'; prev.src = ''; } _commImg[input.id] = null; return; }
  _commDownscale(file, 1280, 0.82).then(dataUrl => {
    _commImg[input.id] = dataUrl;
    if (prev) { prev.src = dataUrl; prev.style.display = ''; }
  }).catch(() => showToast('Could not read that image', 'error'));
}
function _commDownscale(file, maxDim, quality) {
  return new Promise((res, rej) => {
    const r = new FileReader();
    r.onload = () => {
      const img = new Image();
      img.onload = () => {
        let w = img.width, h = img.height;
        const scale = Math.min(1, maxDim / Math.max(w, h));
        w = Math.round(w * scale); h = Math.round(h * scale);
        const c = document.createElement('canvas'); c.width = w; c.height = h;
        c.getContext('2d').drawImage(img, 0, 0, w, h);
        res(c.toDataURL('image/jpeg', quality));
      };
      img.onerror = rej; img.src = r.result;
    };
    r.onerror = rej; r.readAsDataURL(file);
  });
}
async function _commUploadImage(dataUrl, id) {
  if (!dataUrl) return '';
  try {
    const refp = storageRef(storage, 'community/' + id + '.jpg');
    await uploadString(refp, dataUrl, 'data_url');
    return await getDownloadURL(refp);
  } catch (e) {
    console.warn('community image upload failed, inlining', e);
    return dataUrl.length < 900000 ? dataUrl : '';   // small images can live in the doc
  }
}
function _commClearImg(inputId, prevId) {
  _commImg[inputId] = null;
  const i = document.getElementById(inputId); if (i) i.value = '';
  const p = document.getElementById(prevId); if (p) { p.style.display = 'none'; p.src = ''; }
}

// ---- posting -----------------------------------------------------------
async function commAdminPost() {
  if (!_isAdmin() || !_commCanFirestore()) return;
  const type = (document.getElementById('commPostType').value) || 'news';
  const title = (document.getElementById('commPostTitle').value || '').trim();
  const text = (document.getElementById('commPostText').value || '').trim();
  const pin = !!document.getElementById('commPostPin').checked;
  const imgData = _commImg['commPostImg'];
  if (!text && !title && !imgData) { showToast('Add some text or an image', 'error'); return; }
  showToast('Posting…', 'info');
  try {
    const id = currentUser.uid + '_' + Date.now();
    const imageUrl = imgData ? await _commUploadImage(imgData, id) : '';
    await setDoc(doc(db, 'community', id), {
      type, title, text, imageUrl,
      authorUid: currentUser.uid,
      authorName: _isSuperAdmin() ? COMM_ADMIN_NAME : (currentUser.name || 'Teacher'),
      authorRole: 'admin', authorAvatar: COMM_ADMIN_AVATAR, authorStatus: COMM_ADMIN_STATUS,
      status: 'approved', pinned: pin, createdAt: new Date().toISOString()
    });
    document.getElementById('commPostText').value = '';
    document.getElementById('commPostTitle').value = '';
    document.getElementById('commPostPin').checked = false;
    _commClearImg('commPostImg', 'commPostImgPrev');
    showToast('Posted to the board ✓', 'success');
  } catch (e) { console.warn('admin post', e); showToast('Could not post — check your connection', 'error'); }
}
async function commStudentPost() {
  if (!_commCanFirestore()) { showToast('Sign in to post', 'error'); return; }
  const text = (document.getElementById('commMsgText').value || '').trim();
  const imgData = _commImg['commMsgImg'];
  if (!text && !imgData) { showToast('Write a message or attach an image', 'error'); return; }
  showToast('Sending…', 'info');
  try {
    const id = currentUser.uid + '_' + Date.now();
    const imageUrl = imgData ? await _commUploadImage(imgData, id) : '';
    await setDoc(doc(db, 'community', id), {
      type: 'message', title: '', text, imageUrl,
      authorUid: currentUser.uid, authorName: currentUser.name || 'Student', authorRole: 'student',
      authorAvatar: _commMyAvatar(),
      status: 'pending', pinned: false, createdAt: new Date().toISOString()
    });
    document.getElementById('commMsgText').value = '';
    _commClearImg('commMsgImg', 'commMsgImgPrev');
    showToast('Sent for approval — the teacher will review it 👍', 'success');
  } catch (e) { console.warn('student post', e); showToast('Could not send — check your connection', 'error'); }
}
async function commApprove(id) { if (!_isAdmin()) return; try { await updateDoc(doc(db, 'community', id), { status: 'approved', approvedAt: new Date().toISOString() }); showToast('Approved — now public ✓', 'success'); } catch (e) { console.warn(e); showToast('Could not approve', 'error'); } }
async function commReject(id) { if (!_isAdmin()) return; if (!confirm('Reject and remove this message?')) return; commDelete(id); }
async function commPin(id, val) { if (!_isAdmin()) return; try { await updateDoc(doc(db, 'community', id), { pinned: (val === true || val === 'true') }); } catch (e) { console.warn(e); } }
async function commDelete(id) { if (!_isAdmin()) return; try { await deleteDoc(doc(db, 'community', id)); showToast('Removed', 'success'); } catch (e) { console.warn(e); showToast('Could not remove', 'error'); } }

// ---- encounter quests --------------------------------------------------
// Two authoring modes:
//   race  — first student to finish N fresh questions wins (mode:'race')
//   score — admin hand-picks the exact questions; the student with the
//           highest percentage when the timer ends wins (mode:'score')
function commQuestMode(mode) {
  _questMode = (mode === 'score' || mode === 'race') ? mode : 'auto';
  document.querySelectorAll('#commTabQuest .comm-mode-btn').forEach(b =>
    b.classList.toggle('active', b.dataset.qmode === _questMode));
  const auto = document.getElementById('commQuestAutoFields');
  const race = document.getElementById('commQuestRaceFields');
  const score = document.getElementById('commQuestScoreFields');
  if (auto) auto.style.display = _questMode === 'auto' ? '' : 'none';
  if (race) race.style.display = _questMode === 'race' ? '' : 'none';
  if (score) score.style.display = _questMode === 'score' ? '' : 'none';
  if (_questMode === 'score') { commPopulateQuestFilters(); commRenderQuestPicker(); }
}
// Fill the picker's Topic / Source / Concept dropdowns from the live bank,
// reusing the same helpers the worksheet builder uses.
function commPopulateQuestFilters() {
  const topicSel = document.getElementById('cqFilterTopic');
  if (topicSel) {
    const prev = topicSel.value;
    const topics = [...new Set((questionBank || []).flatMap(q => qTopicList(q)))].sort();
    topicSel.innerHTML = '<option value="">All Topics</option>';
    topics.forEach(t => { const o = document.createElement('option'); o.value = t; o.textContent = t; topicSel.appendChild(o); });
    if (prev && topics.includes(prev)) topicSel.value = prev;
  }
  const srcSel = document.getElementById('cqFilterSource');
  if (srcSel) {
    const prev = srcSel.value;
    const sources = [...new Set((questionBank || []).map(questionSource).filter(Boolean))].sort();
    srcSel.innerHTML = '<option value="">All Sources</option>';
    sources.forEach(s => { const o = document.createElement('option'); o.value = s; o.textContent = s; srcSel.appendChild(o); });
    if (prev && sources.includes(prev)) srcSel.value = prev;
  }
  const conSel = document.getElementById('cqFilterConcept');
  if (conSel) {
    const prev = conSel.value;
    const counts = new Map();
    (questionBank || []).forEach(q => qConceptLabels(q).forEach(c => {
      const k = c.toLowerCase();
      const rec = counts.get(k) || { label: c, n: 0 };
      rec.n++; counts.set(k, rec);
    }));
    const concepts = [...counts.values()].sort((a, b) => a.label.localeCompare(b.label));
    conSel.innerHTML = '<option value="">All Concepts</option>';
    concepts.forEach(c => {
      const o = document.createElement('option');
      o.value = c.label; o.textContent = '🏷 ' + c.label + ' (' + c.n + ')';
      conSel.appendChild(o);
    });
    if (prev && concepts.some(c => c.label === prev)) conSel.value = prev;
  }
}
// Full question-bank picker — same filtering, cards and expandable preview as
// the worksheet builder, but writing into the encounter-quest selection set.
function commRenderQuestPicker() {
  const grid = document.getElementById('commQuestPickList'); if (!grid) return;
  const levelFilter = document.getElementById('cqFilterLevel')?.value || '';
  const topicFilter = document.getElementById('cqFilterTopic')?.value || '';
  const catFilter = document.getElementById('cqFilterCategory')?.value || '';
  const sourceFilter = document.getElementById('cqFilterSource')?.value || '';
  const formatFilter = document.getElementById('cqFilterFormat')?.value || '';
  const conceptFilter = (document.getElementById('cqFilterConcept')?.value || '').toLowerCase();
  const searchRaw = (document.getElementById('cqSearch')?.value || '').trim().toLowerCase();

  const filtered = (questionBank || []).filter(q => {
    if (!q || q.id == null) return false;
    if (topicFilter && !qMatchesTopic(q, topicFilter)) return false;
    if (catFilter && !qMatchesCategory(q, catFilter)) return false;
    if (sourceFilter && questionSource(q) !== sourceFilter) return false;
    if (formatFilter === 'mcq' && !qpHasMcq(q)) return false;
    if (formatFilter === 'written' && !qpHasWritten(q)) return false;
    if (!qMatchesConceptLabel(q, conceptFilter)) return false;
    if (levelFilter && getTopicLevel(q.topic || '') !== levelFilter) return false;
    if (searchRaw) { if (!extractQuestionSearchText(q).includes(searchRaw)) return false; }
    return true;
  });

  if (!filtered.length) {
    grid.innerHTML = '<div class="empty-state"><h3>No questions found</h3><p>Try adjusting your filters</p></div>';
    _updatePickCount();
    return;
  }
  grid.innerHTML = filtered.map(q => {
    const id = String(q.id);
    const checked = _questPick.has(id);
    const qLevel = getTopicLevel(q.topic || '');
    const qCategory = normalizeCategoryValue(q.category);
    const qSource = questionSource(q);
    return '<div class="ws-q-card' + (checked ? ' selected' : '') + '" data-qid="' + id + '" onclick="commPickCardClick(\'' + id + '\', event)" style="cursor:pointer;">' +
      '<div class="ws-q-top">' +
        '<input type="checkbox" ' + (checked ? 'checked' : '') + ' onchange="commTogglePick(\'' + id + '\', this.checked)">' +
        '<div class="ws-q-info">' +
          '<div class="ws-q-title">' + escapeHtml(q.title || ('Question ' + id)) + '</div>' +
          '<div class="ws-q-meta">' +
            '<span class="qb-tag category">' + escapeHtml(qCategory) + '</span>' +
            '<span class="qb-tag topic">' + escapeHtml(q.topic || '') + '</span>' +
            qSecondaryTagsHtml(q) +
            '<span class="qb-tag">' + escapeHtml(qLevel) + '</span>' +
            (qSource ? '<span class="qb-tag source" title="' + escapeHtml(qSource) + '">' + escapeHtml(qSource) + '</span>' : '') +
          '</div>' +
        '</div>' +
        '<button class="ws-q-expand-btn" onclick="event.stopPropagation();commTogglePickPreview(\'' + id + '\', this)" title="Preview question">' +
          '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><polyline points="6 9 12 15 18 9"/></svg>' +
        '</button>' +
      '</div>' +
      '<div class="ws-q-preview" id="cqPreview_' + id + '"></div>' +
    '</div>';
  }).join('');
  _updatePickCount();
}
function commTogglePickPreview(id, btn) {
  const previewEl = document.getElementById('cqPreview_' + id);
  if (!previewEl) return;
  if (previewEl.classList.contains('open')) {
    previewEl.classList.remove('open'); btn.classList.remove('expanded');
  } else {
    if (!previewEl.dataset.rendered) { previewEl.innerHTML = renderQuestionPreviewHtml(id); previewEl.dataset.rendered = '1'; }
    previewEl.classList.add('open'); btn.classList.add('expanded');
  }
}
function commTogglePick(id, on) {
  id = String(id);
  if (on) _questPick.add(id); else _questPick.delete(id);
  const card = document.querySelector('#commQuestPickList .ws-q-card[data-qid="' + id + '"]');
  if (card) { card.classList.toggle('selected', on); const cb = card.querySelector('input[type="checkbox"]'); if (cb) cb.checked = on; }
  _updatePickCount();
}
function commPickCardClick(id, event) {
  if (event.target.closest('.ws-q-expand-btn') || event.target.closest('.ws-q-preview')) return;
  if (event.target.tagName === 'INPUT') return;   // checkbox handles itself
  commTogglePick(id, !_questPick.has(String(id)));
}
function commClearPick() { _questPick.clear(); commRenderQuestPicker(); }
function _updatePickCount() { const el = document.getElementById('commQuestPickCount'); if (el) el.textContent = _questPick.size; }

async function commCreateQuest() {
  if (!_isAdmin() || !_commCanFirestore()) return;
  const title = (document.getElementById('commQuestTitle').value || '').trim() || '⚡ Encounter Quest';
  const desc = (document.getElementById('commQuestDesc').value || '').trim();
  const hours = Math.max(0.25, parseFloat(document.getElementById('commQuestHours').value) || 3);
  const now = Date.now(), id = 'q_' + now;
  const base = {
    title, desc, prize: '$10 voucher',
    startAt: new Date(now).toISOString(), endAt: new Date(now + hours * 3600000).toISOString(), hours,
    status: 'active', winnerUid: '', winnerName: '', winnerAt: '',
    createdBy: currentUser.uid, createdAt: new Date().toISOString()
  };
  let payload, feedText;
  if (_questMode === 'auto') {
    const winSel = document.getElementById('commQuestWin');
    const win = ['highest', 'fastest', 'graded'].includes(winSel && winSel.value) ? winSel.value : 'highest';
    const format = (document.getElementById('commQuestFormat').value === 'written') ? 'written' : 'mcq';
    const count = Math.max(1, parseInt(document.getElementById('commQuestAutoCount').value, 10) || 5);
    const topic = (document.getElementById('commQuestAutoTopic').value || '').trim();
    payload = Object.assign({ mode: 'auto', win, format, count, total: count, topic: topic || '', scores: {} }, base);
    const fmtLabel = format === 'mcq' ? 'MCQ' : 'open-ended';
    const winLabel = win === 'fastest' ? 'fastest to finish wins' : win === 'graded' ? 'Mr Chung picks the winner' : 'highest score wins';
    feedText = (desc ? desc + '\n\n' : '') + 'Tap “Attempt quest now!” — you\'ll get ' + count + ' ' + fmtLabel +
      ' question' + (count === 1 ? '' : 's') + (topic ? ' on ' + topic : '') + ' chosen just for you (new ones first, then any you found tricky before). ' +
      winLabel.charAt(0).toUpperCase() + winLabel.slice(1) + ' — reward: $10 voucher!';
  } else if (_questMode === 'score') {
    const ids = Array.from(_questPick);
    if (!ids.length) { showToast('Pick at least one question for a Highest-score quest', 'error'); return; }
    payload = Object.assign({ mode: 'score', questionIds: ids, total: ids.length, count: ids.length, scores: {} }, base);
    feedText = (desc ? desc + '\n\n' : '') + 'Tap “Start quest”, answer all ' + ids.length + ' questions, and the student with the highest percentage when the timer ends wins a $10 voucher!';
  } else {
    const count = Math.max(1, parseInt(document.getElementById('commQuestCount').value, 10) || 10);
    const topic = (document.getElementById('commQuestTopic').value || '').trim();
    payload = Object.assign({ mode: 'race', count, topic: topic || '' }, base);
    feedText = (desc ? desc + '\n\n' : '') + 'Finish ' + count + ' questions' + (topic ? ' on ' + topic : '') + ' before the timer runs out — the first to finish wins a $10 voucher!';
  }
  try {
    await setDoc(doc(db, 'encounterQuests', id), payload);
    // announce it on the feed too (pinned)
    await setDoc(doc(db, 'community', 'quest_' + id), {
      type: 'update', title: '⚡ New Encounter Quest: ' + title,
      text: feedText,
      imageUrl: '', authorUid: currentUser.uid,
      authorName: _isSuperAdmin() ? COMM_ADMIN_NAME : (currentUser.name || 'Teacher'),
      authorRole: 'admin', authorAvatar: COMM_ADMIN_AVATAR, authorStatus: COMM_ADMIN_STATUS,
      status: 'approved', pinned: true, createdAt: new Date().toISOString()
    });
    document.getElementById('commQuestTitle').value = '';
    document.getElementById('commQuestDesc').value = '';
    if (_questMode === 'score') commClearPick();
    showToast('⚡ Quest launched — students see it now!', 'success');
  } catch (e) { console.warn('create quest', e); showToast('Could not launch the quest', 'error'); }
}
async function commEndQuest(id) {
  if (!_isAdmin()) return;
  if (!confirm('End this quest now?')) return;
  try { await updateDoc(doc(db, 'encounterQuests', id), { status: 'ended', endedAt: new Date().toISOString() }); } catch (e) { console.warn(e); }
}
function _activeQuests() {
  const now = Date.now();
  return _commQuests.filter(q => q.status === 'active' && !q.winnerUid && new Date(q.endAt).getTime() > now);
}
function _questProgress(q) { return (rpgState && rpgState.encounter && rpgState.encounter[q._id]) || 0; }

// Count a freshly-answered unique question toward any live quest. Called from
// rpgOnMarked only when a genuinely new unique question was recorded.
function commNoteEncounterProgress(q) {
  if (!rpgState || !currentUser || currentUser.role !== 'student') return;
  // Only "first to finish" (race) quests are won by answering questions anywhere.
  // Score and auto quests are resolved via their own run flow, not this counter.
  const active = _activeQuests().filter(quest => quest.mode === 'race' || !quest.mode);
  if (!active.length) return;
  rpgState.encounter = rpgState.encounter || {};
  active.forEach(quest => {
    if (quest.topic && q && q.topic && String(q.topic).toLowerCase() !== String(quest.topic).toLowerCase()) return;
    const cur = (rpgState.encounter[quest._id] || 0) + 1;
    rpgState.encounter[quest._id] = cur;
    if (cur >= quest.count) commTryWinQuest(quest);
  });
  rpgSave();
  _renderQuestBanners();
}
async function commTryWinQuest(quest) {
  if (!_commCanFirestore()) return;
  rpgState.encounter = rpgState.encounter || {};
  if (rpgState.encounter['_tried_' + quest._id]) return;     // attempt the race once
  rpgState.encounter['_tried_' + quest._id] = 1; rpgSave();
  try {
    const snap = await getDoc(doc(db, 'encounterQuests', quest._id));
    if (!snap.exists()) return;
    const d = snap.data();
    if (d.winnerUid) {
      if (d.winnerUid !== currentUser.uid) showToast('⚡ ' + (d.winnerName || 'Another student') + ' finished first — watch out for the next quest!', 'info');
      return;
    }
    if (d.status !== 'active' || new Date(d.endAt).getTime() < Date.now()) { showToast('That quest already ended.', 'info'); return; }
    await updateDoc(doc(db, 'encounterQuests', quest._id), {
      winnerUid: currentUser.uid, winnerName: currentUser.name || 'Student',
      winnerAt: new Date().toISOString(), status: 'ended'
    });
    commOfferQuestPrize(quest);
  } catch (e) { console.warn('win quest', e); }
}
function commOfferQuestPrize(quest) {
  _questOffered[quest._id] = 1;
  const isScore = quest.mode === 'score';
  const isAuto = quest.mode === 'auto';
  const myScore = (isScore || isAuto) && quest.scores ? quest.scores[currentUser.uid] : null;
  const myPct = myScore ? Math.round(myScore.pct || 0) : null;
  const myTime = myScore && myScore.elapsedMs != null ? myScore.elapsedMs : (quest.winnerTimeMs != null ? quest.winnerTimeMs : null);
  _prizeClaimCtx = { ackKey: 'enc_' + quest._id, monthKey: rpgMonthKey(), rank: 1, value: (isScore || isAuto ? (myPct != null ? myPct : quest.total || 0) : quest.count), noun: 'Encounter Quest', game: 'Encounter Quest', detail: (quest.title || 'Encounter Quest'), category: 'encounter' };
  const el = id => document.getElementById(id);
  let how;
  if (isAuto) {
    how = quest.win === 'fastest' ? ('fastest to finish' + (myTime != null ? ' in <b>' + _fmtDuration(myTime) + '</b>' : '') + '!')
        : quest.win === 'graded' ? 'Mr Chung picked you as the winner!'
        : 'top scorer' + (myPct != null ? ' with <b>' + myPct + '%</b>' : '') + '!';
  } else if (isScore) {
    how = 'top scorer' + (myPct != null ? ' with <b>' + myPct + '%</b>' : '') + '!';
  } else {
    how = 'first to finish ' + quest.count + ' questions!';
  }
  if (el('prizeClaimMsg')) el('prizeClaimMsg').innerHTML =
    '🏆 You won the <b>' + escapeHtml(quest.title || 'Encounter Quest') + '</b> — ' + how +
    ' Enter your details and we\'ll send your <b>$10 Popular voucher</b>.';
  if (el('prizePhone')) el('prizePhone').value = '';
  if (el('prizeAddress')) el('prizeAddress').value = '';
  if (el('prizeClaimOverlay')) el('prizeClaimOverlay').classList.add('active');
  showToast('🏆 You won the encounter quest!', 'success');
}

// ---- score-mode quest run (student answers the admin-picked questions) ----
function commStartQuestRun(questId) {
  const quest = _commQuests.find(q => q._id === questId);
  if (!quest || quest.mode !== 'score') return;
  if (!(currentUser && currentUser.role === 'student')) return;
  const left = new Date(quest.endAt).getTime() - Date.now();
  if (quest.winnerUid || quest.status === 'ended' || left <= 0) { showToast('That quest has ended.', 'info'); return; }
  const ids = Array.isArray(quest.questionIds) ? quest.questionIds.map(String) : [];
  const byId = {}; (Array.isArray(questionBank) ? questionBank : []).forEach(q => { if (q && q.id != null) byId[String(q.id)] = q; });
  const queue = ids.map(id => byId[id]).filter(Boolean);
  if (!queue.length) { showToast('These quest questions aren\'t available on your device yet — try again shortly.', 'error'); return; }
  _questRun = { questId: quest._id, ids, total: ids.length, best: {} };
  qpQueue = queue;
  qpIndex = -1;
  qpAnswered = 0;
  qpSessionResults = [];
  showToast('⚡ Quest started — answer them all, your best % counts!', 'success');
  navigateTo('quickpractice');
  preloadQueueImages(qpQueue).then(() => loadNextQpQuestion()).catch(() => loadNextQpQuestion());
}
// ---- auto-fed quest run: the system picks each student's questions ----
// Priority: questions the student hasn't done yet, then ones they previously
// struggled with (best score < 50%), then anything else to fill the count.
async function commStartAutoQuest(questId) {
  const quest = _commQuests.find(q => q._id === questId);
  if (!quest || quest.mode !== 'auto') return;
  if (!(currentUser && currentUser.role === 'student')) return;
  const left = new Date(quest.endAt).getTime() - Date.now();
  if (quest.winnerUid || quest.status === 'ended' || left <= 0) { showToast('That quest has ended.', 'info'); return; }
  const count = Math.max(1, quest.count || quest.total || 5);
  const format = quest.format === 'written' ? 'written' : 'mcq';
  const topic = (quest.topic || '').trim().toLowerCase();
  const pool = (Array.isArray(questionBank) ? questionBank : []).filter(q => {
    if (!q || q.id == null) return false;
    if (!qInSyllabus(q)) return false;             // not in syllabus → practice-excluded
    if (format === 'mcq' ? !qpHasMcq(q) : !qpHasWritten(q)) return false;
    if (topic && String(q.topic || '').toLowerCase() !== topic) return false;
    return qWithinStudentLevel(q); // never quest a student above their level
  });
  if (!pool.length) { showToast('No ' + (format === 'mcq' ? 'MCQ' : 'open-ended') + ' questions available' + (quest.topic ? ' on ' + quest.topic : '') + ' yet.', 'error'); return; }
  showToast('Picking your questions…', 'info');
  // Best recorded fraction (0–1) per question from this student's attempt log.
  const _stats = await loadAttemptStats();
  const bestByQ = {};
  Object.keys(_stats).forEach(id => { bestByQ[id] = _stats[id].best; });
  const shuffle = arr => { for (let i = arr.length - 1; i > 0; i--) { const j = Math.floor(Math.random() * (i + 1)); [arr[i], arr[j]] = [arr[j], arr[i]]; } return arr; };
  const seen = id => bestByQ[id] !== undefined;
  const unseen = shuffle(pool.filter(q => !seen(String(q.id))));
  const struggled = pool.filter(q => seen(String(q.id)) && bestByQ[String(q.id)] < 0.5)
    .sort((a, b) => (bestByQ[String(a.id)] || 0) - (bestByQ[String(b.id)] || 0));
  const rest = shuffle(pool.filter(q => seen(String(q.id)) && bestByQ[String(q.id)] >= 0.5));
  const ordered = [];
  const add = list => list.forEach(q => { if (ordered.length < count && !ordered.some(x => String(x.id) === String(q.id))) ordered.push(q); });
  add(unseen); add(struggled); add(rest);
  const queue = ordered.slice(0, count);
  if (!queue.length) { showToast('Couldn\'t pick questions — try again shortly.', 'error'); return; }
  _questRun = { questId: quest._id, mode: 'auto', win: quest.win || 'highest', ids: queue.map(q => String(q.id)), total: queue.length, best: {}, answered: new Set(), startedAt: Date.now(), _finished: false };
  qpQueue = queue; qpIndex = -1; qpAnswered = 0; qpSessionResults = [];
  const winMsg = quest.win === 'fastest' ? 'fastest to finish wins — go!' : quest.win === 'graded' ? 'do your best, Mr Chung grades!' : 'highest score wins!';
  showToast('⚡ Quest started — ' + winMsg, 'success');
  navigateTo('quickpractice');
  preloadQueueImages(qpQueue).then(() => loadNextQpQuestion()).catch(() => loadNextQpQuestion());
}
// Called from rpgOnMarked for every real marked question. If a score-quest run
// is live and this question belongs to it, record the student's best credit
// for that question and publish a fresh percentage to Firestore (debounced).
function commQuestRunCapture(q, credit) {
  if (!_questRun || !q || q.id == null) return;
  const qid = String(q.id);
  if (!_questRun.ids.includes(qid)) return;
  const c = Math.max(0, Math.min(1, Number(credit) || 0));
  if (c > (_questRun.best[qid] || 0)) _questRun.best[qid] = c;
  _questRun.answered = _questRun.answered || new Set();
  _questRun.answered.add(qid);
  _publishQuestScore(_questRun.questId);
  // Auto quests fire a finish handler once every fed question has been answered.
  if (_questRun.mode === 'auto' && !_questRun._finished && _questRun.answered.size >= (_questRun.total || 0)) {
    _questRun._finished = true;
    _commAutoFinished(_questRun);
  }
}
function _questRunDone() { return _questRun && _questRun.answered ? _questRun.answered.size : (_questRun ? Object.keys(_questRun.best).length : 0); }
function _questRunPct() {
  if (!_questRun) return 0;
  const total = _questRun.total || 1;
  const sum = Object.values(_questRun.best).reduce((s, v) => s + v, 0);
  return Math.round((sum / total) * 100);
}
function _publishQuestScore(questId) {
  if (!_questRun || _questRun.questId !== questId || !_commCanFirestore()) return;
  if (_questScorePub[questId]) return;                     // debounce a burst of marks
  _questScorePub[questId] = setTimeout(async () => {
    _questScorePub[questId] = null;
    if (!_questRun || _questRun.questId !== questId) return;
    const total = _questRun.total || 1;
    const done = _questRunDone();
    const pct = _questRunPct();
    // Never let a partial re-attempt lower a better score already recorded.
    const prev = _commQuests.find(q => q._id === questId);
    const prevPct = prev && prev.scores && prev.scores[currentUser.uid] ? (prev.scores[currentUser.uid].pct || 0) : -1;
    if (pct < prevPct) return;
    const entry = { name: currentUser.name || 'Student', pct, done, total, at: new Date().toISOString() };
    if (_questRun.mode === 'auto') {
      entry.win = _questRun.win;
      if (_questRun.startedAt) entry.elapsedMs = Date.now() - _questRun.startedAt;
      entry.finished = done >= total;
    }
    try {
      await updateDoc(doc(db, 'encounterQuests', questId), { ['scores.' + currentUser.uid]: entry });
    } catch (e) { console.warn('publish quest score', e); }
  }, 800);
}
// Auto quest: the student just answered the last fed question.
async function _commAutoFinished(run) {
  const quest = _commQuests.find(q => q._id === run.questId) || { _id: run.questId };
  const total = run.total || 1;
  const pct = _questRunPct();
  const elapsedMs = run.startedAt ? Date.now() - run.startedAt : 0;
  if (_commCanFirestore()) {
    const prev = _commQuests.find(q => q._id === run.questId);
    const prevPct = prev && prev.scores && prev.scores[currentUser.uid] ? (prev.scores[currentUser.uid].pct || 0) : -1;
    // For "highest", keep a better earlier score; always record for the others.
    if (!(run.win === 'highest' && pct < prevPct)) {
      try {
        await updateDoc(doc(db, 'encounterQuests', run.questId), {
          ['scores.' + currentUser.uid]: { name: currentUser.name || 'Student', pct, done: total, total, win: run.win, elapsedMs, finished: true, at: new Date().toISOString() }
        });
      } catch (e) { console.warn('auto finish publish', e); }
    }
  }
  if (run.win === 'fastest') {
    _commClaimFastest(quest, elapsedMs, pct);
  } else if (run.win === 'graded') {
    showToast('✅ Done in ' + _fmtDuration(elapsedMs) + ' — Mr Chung will grade and pick the winner!', 'success');
  } else {
    showToast('✅ Quest complete — you scored ' + pct + '%! Highest score at the deadline wins.', 'success');
  }
}
// Fastest-to-finish: the first student to complete all their questions wins.
async function _commClaimFastest(quest, elapsedMs, pct) {
  if (!_commCanFirestore()) return;
  try {
    const snap = await getDoc(doc(db, 'encounterQuests', quest._id));
    if (!snap.exists()) return;
    const d = snap.data();
    if (d.winnerUid) {
      if (d.winnerUid !== currentUser.uid) showToast('⚡ ' + (d.winnerName || 'Another student') + ' finished first — watch for the next quest!', 'info');
      return;
    }
    if (d.status !== 'active' || new Date(d.endAt).getTime() < Date.now()) { showToast('That quest already ended.', 'info'); return; }
    await updateDoc(doc(db, 'encounterQuests', quest._id), {
      winnerUid: currentUser.uid, winnerName: currentUser.name || 'Student',
      winnerAt: new Date().toISOString(), winnerTimeMs: elapsedMs, winnerPct: pct, status: 'ended'
    });
    commOfferQuestPrize(Object.assign({ _id: quest._id }, d));
  } catch (e) { console.warn('claim fastest', e); }
}
// Admin resolves a score quest once the timer is up: highest percentage wins
// (ties broken by more questions done, then earliest submission).
async function commAwardTopScorer(questId) {
  if (!_isAdmin() || !_commCanFirestore()) return;
  try {
    const snap = await getDoc(doc(db, 'encounterQuests', questId));
    if (!snap.exists()) return;
    const d = snap.data();
    if (d.winnerUid) { showToast('A winner is already set.', 'info'); return; }
    const scores = d.scores || {};
    const entries = Object.keys(scores).map(uid => Object.assign({ uid }, scores[uid]));
    if (!entries.length) { showToast('No students attempted this quest — nothing to award.', 'info'); return; }
    let top;
    if (d.win === 'fastest') {
      // Fastest to finish: only students who completed all questions, shortest time first.
      const finishers = entries.filter(e => e.finished || (e.total && e.done >= e.total));
      const pool = finishers.length ? finishers : entries;
      pool.sort((a, b) => ((a.elapsedMs == null ? Infinity : a.elapsedMs) - (b.elapsedMs == null ? Infinity : b.elapsedMs)) || (b.pct || 0) - (a.pct || 0));
      top = pool[0];
    } else {
      entries.sort((a, b) => (b.pct || 0) - (a.pct || 0) || (b.done || 0) - (a.done || 0) || String(a.at || '').localeCompare(String(b.at || '')));
      top = entries[0];
    }
    const detail = d.win === 'fastest' ? (top.elapsedMs != null ? _fmtDuration(top.elapsedMs) : 'fastest') : (Math.round(top.pct || 0) + '%');
    if (!confirm('Award the $10 voucher to ' + (top.name || 'top student') + ' (' + detail + ')?')) return;
    await updateDoc(doc(db, 'encounterQuests', questId), {
      winnerUid: top.uid, winnerName: top.name || 'Student', winnerPct: Math.round(top.pct || 0), winnerTimeMs: top.elapsedMs || 0,
      winnerAt: new Date().toISOString(), status: 'ended'
    });
    showToast('🏆 ' + (top.name || 'Top student') + ' wins with ' + detail + '!', 'success');
  } catch (e) { console.warn('award top scorer', e); showToast('Could not award the winner', 'error'); }
}
// "Mr Chung grades" mode: the teacher hand-picks the winner from the entrants.
async function commAwardTo(questId, uid) {
  if (!_isAdmin() || !_commCanFirestore()) return;
  try {
    const snap = await getDoc(doc(db, 'encounterQuests', questId));
    if (!snap.exists()) return;
    const d = snap.data();
    if (d.winnerUid) { showToast('A winner is already set.', 'info'); return; }
    const s = (d.scores || {})[uid];
    if (!s) { showToast('That student has no entry.', 'error'); return; }
    if (!confirm('Award the $10 voucher to ' + (s.name || 'this student') + '?')) return;
    await updateDoc(doc(db, 'encounterQuests', questId), {
      winnerUid: uid, winnerName: s.name || 'Student', winnerPct: Math.round(s.pct || 0), winnerTimeMs: s.elapsedMs || 0,
      winnerAt: new Date().toISOString(), status: 'ended'
    });
    showToast('🏆 ' + (s.name || 'Student') + ' wins!', 'success');
  } catch (e) { console.warn('award to', e); showToast('Could not award the winner', 'error'); }
}

// ---- realtime subscriptions + rendering --------------------------------
function commStartGlobalWatch() {
  if (!_commCanFirestore() || _questUnsub) return;
  try {
    _questUnsub = onSnapshot(collection(db, 'encounterQuests'), snap => {
      _commQuests = []; snap.forEach(d => _commQuests.push(Object.assign({ _id: d.id }, d.data())));
      _activeQuests().forEach(q => {
        if (!_questSeen[q._id]) {
          _questSeen[q._id] = 1;
          if (currentUser && currentUser.role === 'student') {
            const how = q.mode === 'auto'
              ? (q.win === 'fastest' ? ' — finish fastest to win $10!' : q.win === 'graded' ? ' — do your best, Mr Chung grades to win $10!' : ' — score the highest to win $10!')
              : (q.mode === 'score' ? ' — score the highest to win $10!' : ' — finish ' + q.count + ' questions to win $10!');
            showToast('⚡ New Encounter Quest: ' + (q.title || '') + how, 'info');
          }
        }
      });
      // A score quest the admin just awarded to me → offer the prize claim.
      if (currentUser && currentUser.role === 'student') {
        const ack = (rpgState && rpgState.prizeAck) || {};
        _commQuests.forEach(q => {
          const awardable = q.mode === 'score' || (q.mode === 'auto' && q.win !== 'fastest');
          if (awardable && q.winnerUid === currentUser.uid && !_questOffered[q._id] && !ack['enc_' + q._id]) {
            commOfferQuestPrize(q);
          }
        });
      }
      _renderQuestChip(); _renderQuestBanners();
    }, e => console.warn('quest sub', e));
    if (!_questTick) _questTick = setInterval(() => { _renderQuestChip(); _renderQuestBanners(); }, 1000);
  } catch (e) { console.warn('quest watch', e); }
}
function _commSubscribeFeed() {
  if (!_commCanFirestore() || _commUnsub) return;
  try {
    _commUnsub = onSnapshot(collection(db, 'community'), snap => {
      _commPosts = []; snap.forEach(d => _commPosts.push(Object.assign({ _id: d.id }, d.data())));
      _renderCommFeed(); _renderCommPending(); renderCommAvatarPicker();
    }, e => { console.warn('community sub', e); const f = document.getElementById('commFeed'); if (f) f.innerHTML = '<div class="empty-note">Couldn\'t load the board — check the Firestore rules for the <b>community</b> collection.</div>'; });
  } catch (e) { console.warn('community sub', e); }
}
function _renderQuestChip() {
  const chip = document.getElementById('questChip'); if (!chip) return;
  if (!(currentUser && currentUser.role === 'student')) { chip.classList.remove('show'); return; }
  const qs = _activeQuests();
  if (!qs.length) { chip.classList.remove('show'); return; }
  qs.sort((a, b) => new Date(a.endAt) - new Date(b.endAt));
  const left = new Date(qs[0].endAt).getTime() - Date.now();
  chip.innerHTML = '⚡ Quest ' + _fmtCountdown(left);
  chip.classList.add('show');
}
// Sub-content for an auto-fed quest banner (student attempt button / admin award UI).
function _commAutoBannerSub(q, live) {
  const student = currentUser && currentUser.role === 'student';
  const win = q.win || 'highest';
  const fmt = q.format === 'written' ? 'open-ended' : 'MCQ';
  const nq = q.count || q.total || '';
  const winLabel = win === 'fastest' ? 'fastest to finish wins' : win === 'graded' ? 'Mr Chung grades' : 'highest score wins';
  const scores = q.scores || {};
  const entries = Object.keys(scores).map(uid => Object.assign({ uid }, scores[uid]));
  const n = entries.length;
  if (student) {
    const my = scores[currentUser.uid] || null;
    if (live) {
      const label = my ? '🔁 Attempt again' : '⚡ Attempt quest now!';
      const btn = '<button class="btn btn-primary btn-sm" onclick="commStartAutoQuest(\'' + q._id + '\')">' + label + '</button>';
      let mine = '';
      if (my) {
        mine = win === 'fastest'
          ? (my.finished ? ' Your time: <b>' + _fmtDuration(my.elapsedMs) + '</b>.' : ' Answered ' + (my.done || 0) + '/' + (my.total || nq) + '.')
          : ' Your score: <b>' + Math.round(my.pct || 0) + '%</b>.';
      }
      return '<div class="cq-progress">' + nq + ' ' + fmt + ' questions picked for you · ' + winLabel + '.' + mine + '</div>' + btn;
    }
    if (!n) return '<div class="cq-progress">Time\'s up — no entries this round.</div>';
    return '<div class="cq-progress">Time\'s up — waiting for the result…</div>';
  }
  // admin
  if (!n) return '<div class="cq-progress">' + (live ? 'Live' : 'Time\'s up') + ' — no attempts yet · ' + nq + ' ' + fmt + ' q · ' + winLabel + '.</div>';
  if (win === 'graded') {
    return '<div class="cq-progress">' + n + ' student' + (n === 1 ? '' : 's') + ' attempted · pick the winner:</div>' + _commGradedChooser(q);
  }
  let lead;
  if (win === 'fastest') {
    lead = entries.filter(e => e.finished || (e.total && e.done >= e.total)).sort((a, b) => (a.elapsedMs == null ? Infinity : a.elapsedMs) - (b.elapsedMs == null ? Infinity : b.elapsedMs))[0];
  } else {
    lead = entries.slice().sort((a, b) => (b.pct || 0) - (a.pct || 0))[0];
  }
  const leadTxt = lead ? (' · leader ' + escapeHtml(lead.name || 'student') + ' ' + (win === 'fastest' ? _fmtDuration(lead.elapsedMs) : Math.round(lead.pct || 0) + '%')) : '';
  const awardBtn = ' <button class="btn btn-outline btn-sm" onclick="commAwardTopScorer(\'' + q._id + '\')">🏆 Award winner</button>';
  return '<div class="cq-progress">' + n + ' student' + (n === 1 ? '' : 's') + ' attempted' + leadTxt + awardBtn + '</div>';
}
function _commGradedChooser(q) {
  const scores = q.scores || {};
  const entries = Object.keys(scores).map(uid => Object.assign({ uid }, scores[uid])).sort((a, b) => (b.pct || 0) - (a.pct || 0));
  if (!entries.length) return '';
  return entries.map(e =>
    '<div class="cq-grade-row"><span>' + escapeHtml(e.name || 'Student') + ' — ' + Math.round(e.pct || 0) + '%' +
    (e.elapsedMs != null ? ' · ' + _fmtDuration(e.elapsedMs) : '') + (e.finished ? ' ✅' : '') + '</span>' +
    '<button class="btn btn-outline btn-sm" onclick="commAwardTo(\'' + q._id + '\',\'' + e.uid + '\')">🏆 Award</button></div>'
  ).join('');
}
function _renderQuestBanners() {
  const area = document.getElementById('commQuestArea'); if (!area) return;
  // Hide dead quests: once a quest ends with no winner there's nothing to act on,
  // so drop it — except keep it for the admin while there are entries left to award.
  const list = _commQuests.filter(q => {
    const isExpired = q.status === 'ended' || new Date(q.endAt).getTime() <= Date.now();
    if (!isExpired) return true;                 // still live
    if (q.winnerUid) return true;                // ended with a winner — celebrate it
    const hasEntries = q.scores && Object.keys(q.scores).length;
    return _isAdmin() && (q.mode === 'score' || q.mode === 'auto') && hasEntries; // admin can still award
  }).sort((a, b) => String(b.createdAt || '').localeCompare(String(a.createdAt || ''))).slice(0, 16);
  if (!list.length) { area.innerHTML = ''; return; }
  const student = currentUser && currentUser.role === 'student';
  // Finished quests that already have a winner are just trophies — collapse them
  // into one slim recap card so they don't crowd the board. Everything else
  // (live quests, and ended ones the admin can still award) stays a banner.
  const wonList = list.filter(q => !!q.winnerUid).slice(0, 5);
  const bannerList = list.filter(q => !q.winnerUid).slice(0, 4);
  const bannersHtml = bannerList.map(q => {
    const isScore = q.mode === 'score';
    const isAuto = q.mode === 'auto';
    const left = new Date(q.endAt).getTime() - Date.now();
    const expired = q.status === 'ended' || left <= 0;
    let timer, sub;
    if (expired) {
      timer = '⌛<span>ENDED</span>';
      if (isAuto) {
        sub = _commAutoBannerSub(q, false);
      } else if (isScore) {
        const scores = q.scores || {};
        const n = Object.keys(scores).length;
        const awardBtn = _isAdmin() ? ' <button class="btn btn-outline btn-sm" onclick="commAwardTopScorer(\'' + q._id + '\')">🏆 Award top scorer</button>' : '';
        sub = '<div class="cq-progress">Time\'s up — ' + (n ? n + ' student' + (n === 1 ? '' : 's') + ' attempted. ' + (_isAdmin() ? 'Award the highest %.' : 'Waiting for the result…') : 'no entries this round.') + awardBtn + '</div>';
      } else {
        sub = '<div class="cq-progress">Time\'s up — no winner this round.</div>';
      }
    } else {
      timer = _fmtCountdown(left) + '<span>LEFT</span>';
      if (isAuto) {
        sub = _commAutoBannerSub(q, true);
      } else if (isScore) {
        if (student) {
          const my = (q.scores && q.scores[currentUser.uid]) || null;
          const startBtn = '<button class="btn btn-primary btn-sm" onclick="commStartQuestRun(\'' + q._id + '\')">▶ ' + (my ? 'Improve your score' : 'Start quest') + '</button>';
          sub = '<div class="cq-progress">Answer ' + (q.total || 0) + ' questions — highest % wins.' +
            (my ? ' Your score: <b>' + Math.round(my.pct || 0) + '%</b>' : '') + '</div>' + startBtn;
        } else {
          const scores = q.scores || {};
          const lead = Object.values(scores).sort((a, b) => (b.pct || 0) - (a.pct || 0))[0];
          sub = '<div class="cq-progress">Reward: ' + escapeHtml(q.prize || '$10 voucher') + ' · ' + (q.total || 0) + ' picked questions · highest % wins' +
            (lead ? ' · leader ' + escapeHtml(lead.name || 'student') + ' ' + Math.round(lead.pct || 0) + '%' : '') + '</div>';
        }
      } else {
        const prog = _questProgress(q);
        sub = student
          ? '<div class="cq-progress">Your progress: ' + Math.min(prog, q.count) + ' / ' + q.count + ' questions' + (prog >= q.count ? ' ✅' : '') + '</div>'
          : '<div class="cq-progress">Reward: ' + escapeHtml(q.prize || '$10 voucher') + ' · ' + q.count + ' questions' + (q.topic ? ' · ' + escapeHtml(q.topic) : '') + '</div>';
      }
    }
    const endBtn = _isAdmin() && !expired ? ' <button class="btn btn-outline btn-sm" onclick="commEndQuest(\'' + q._id + '\')">End</button>' : '';
    return '<div class="comm-quest-banner' + (expired ? ' ended' : '') + '">' +
      '<span class="cq-emoji">⚡</span>' +
      '<div class="cq-main"><div class="cq-title">' + escapeHtml(q.title || 'Encounter Quest') + endBtn + '</div>' +
      (q.desc ? '<div class="cq-desc">' + escapeHtml(q.desc) + '</div>' : '') + sub + '</div>' +
      '<div class="cq-timer">' + timer + '</div></div>';
  }).join('');
  area.innerHTML = bannersHtml + _renderQuestWinnersStrip(wonList);
}
// Collapse finished, already-won flash quizzes into one compact recap card.
function _renderQuestWinnersStrip(wonList) {
  if (!wonList || !wonList.length) return '';
  const rows = wonList.map(q => {
    const isAuto = q.mode === 'auto', isScore = q.mode === 'score';
    const how = (isAuto && q.win === 'fastest' && q.winnerTimeMs != null) ? _fmtDuration(q.winnerTimeMs)
      : ((isScore || isAuto) && q.winnerPct != null && !(isAuto && q.win === 'fastest')) ? Math.round(q.winnerPct) + '%' : '';
    const score = how ? '<span class="cqw-score">' + escapeHtml(how) + '</span>' : '';
    const quest = q.title ? ' <span class="cqw-quest">· ' + escapeHtml(q.title) + '</span>' : '';
    return '<div class="cqw-row"><span class="cqw-trophy">🏆</span>' +
      '<div class="cqw-body"><span class="cqw-name">' + escapeHtml(q.winnerName || 'A student') + '</span> won the $10 voucher' + quest + '</div>' +
      score + '</div>';
  }).join('');
  return '<div class="comm-quest-winners"><div class="cqw-head">🏆 Recent Flash Quiz winners</div>' + rows + '</div>';
}
// Built-in Science Strike release announcement — rendered client-side at the
// top of the feed (not a Firestore doc, so it can't be un-pinned or deleted
// and needs no write). The game is fully released, so it always shows.
function _commFpsAnnouncePost() {
  return {
    _id: '__fpsAnnounce', _builtin: true,
    type: 'news', pinned: true, status: 'approved',
    title: '🎉 NEW GAME RELEASED — 🔫 Science Strike!',
    text: 'An open-world roguelite shooter where science questions power up your loot. Survive infinite waves, hunt rarer and rarer gear, and answer a question every 15 seconds to boost your luck. The leaderboard is live on the Leaderboard page (🔫 Strike tab) — ranked by correct answers, and the top 3 win a $10 Popular voucher each. Find Science Strike in the sidebar. Good luck!',
    _ctaHtml: '<div class="comm-actions"><button class="btn btn-primary" onclick="openFpsGame()">🔫 Play Science Strike</button></div>',
    authorUid: '', authorName: COMM_ADMIN_NAME, authorRole: 'admin',
    authorAvatar: COMM_ADMIN_AVATAR, authorStatus: COMM_ADMIN_STATUS,
    createdAt: ''
  };
}
// The same release news as the banner, pinned to the top of the feed for as
// long as the game is live (nothing to dismiss — it just sits there).
function _commTcgAnnouncePost() {
  if (!tcgReleased()) return null;
  return {
    _id: '__tcgAnnounce', _builtin: true,
    type: 'news', pinned: true, status: 'approved',
    title: '🃏 NEW GAME RELEASED — Realm of Embers TCG!',
    text: 'Collect all 151 legendary monsters! Spend the points you earn answering questions on booster packs, level your monsters up, build a team of 5 and battle other trainers in the Arena — then take on the infinite Dungeon. Every monster has a star rating from 1★ to 7★, and only three 7★ legends exist in the whole set. Find it in your sidebar under 🃏 Realm of Embers TCG.',
    _ctaHtml: '<div class="comm-actions"><button class="btn btn-primary" onclick="tcgOpenFromAnnounce()">🃏 Open my first pack</button></div>',
    authorUid: '', authorName: COMM_ADMIN_NAME, authorRole: 'admin',
    authorAvatar: COMM_ADMIN_AVATAR, authorStatus: COMM_ADMIN_STATUS,
    createdAt: (_tcgConfig && _tcgConfig.releasedAt) || ''
  };
}
function _commPostHtml(p, moderate) {
  const admin = _isAdmin();
  const isStaff = p.authorRole === 'admin';
  const tag = isStaff
    ? '<span class="comm-tag ' + (p.type || 'update') + '">' + _commTypeLabel(p.type) + '</span>'
    : (p.status === 'pending' ? '<span class="comm-tag pending">Pending</span>' : '');
  const img = p.imageUrl ? '<img class="comm-img" src="' + escapeHtml(p.imageUrl) + '" onclick="window.open(this.src,\'_blank\')" alt="">' : '';
  const ava = escapeHtml(p.authorAvatar || (isStaff ? COMM_ADMIN_AVATAR : '🧑‍🎓'));
  const statusLabel = isStaff ? COMM_ADMIN_STATUS : _commStudentStatus(_commPostCount(p.authorUid));
  const statusPill = '<span class="comm-status' + (isStaff ? ' polymath' : '') + '">' + escapeHtml(statusLabel) + '</span>';
  let actions = '';
  if (p._builtin) actions = '';   // no moderation on the synthetic announcement — there's no doc behind it
  else if (moderate) actions = '<div class="comm-actions"><button class="btn btn-primary" onclick="commApprove(\'' + p._id + '\')">✓ Approve</button><button class="btn btn-outline" onclick="commReject(\'' + p._id + '\')">✕ Reject</button></div>';
  else if (admin) actions = '<div class="comm-actions"><button class="btn btn-outline" onclick="commPin(\'' + p._id + '\',\'' + (p.pinned ? 'false' : 'true') + '\')">' + (p.pinned ? '📌 Unpin' : '📌 Pin') + '</button><button class="btn btn-outline" onclick="commDelete(\'' + p._id + '\')">🗑 Delete</button></div>';
  return '<div class="comm-post' + (p.pinned && !moderate ? ' pinned' : '') + '">' +
    '<div class="comm-ava' + (isStaff ? ' admin' : '') + '">' + ava + '</div>' +
    '<div class="comm-body">' +
    '<div class="comm-meta"><span class="comm-author">' + escapeHtml(p.authorName || 'Anonymous') + '</span>' + statusPill + tag +
    '<span class="comm-time">' + _commTimeAgo(p.createdAt) + '</span>' + (p.pinned && !moderate ? ' 📌' : '') + '</div>' +
    (p.title ? '<div class="comm-title">' + escapeHtml(p.title) + '</div>' : '') +
    (p.text ? '<div class="comm-text">' + escapeHtml(p.text) + '</div>' : '') +
    img + (p._ctaHtml || '') + actions +
    '</div></div>';
}
function _renderCommFeed() {
  const feed = document.getElementById('commFeed'); if (!feed) return;
  const posts = _commPosts.filter(p => p.status === 'approved')
    .sort((a, b) => (b.pinned ? 1 : 0) - (a.pinned ? 1 : 0) || String(b.createdAt || '').localeCompare(String(a.createdAt || '')));
  const fpsPost = _commFpsAnnouncePost();
  if (fpsPost) posts.unshift(fpsPost);
  const tcgPost = _commTcgAnnouncePost();   // newest release sits above the Strike one
  if (tcgPost) posts.unshift(tcgPost);
  if (!posts.length) { feed.innerHTML = '<div class="empty-note">No posts yet. ' + (_isAdmin() ? 'Share the first update above!' : 'Check back soon!') + '</div>'; return; }
  feed.innerHTML = posts.map(p => _commPostHtml(p, false)).join('');
}
function _renderCommPending() {
  const wrap = document.getElementById('commPending'), card = document.getElementById('commPendingCard');
  if (!wrap || !card) return;
  if (!_isAdmin()) { card.style.display = 'none'; return; }
  const pend = _commPosts.filter(p => p.status === 'pending').sort((a, b) => String(b.createdAt || '').localeCompare(String(a.createdAt || '')));
  const cnt = document.getElementById('commPendingCount'); if (cnt) cnt.textContent = pend.length;
  card.style.display = pend.length ? '' : 'none';
  wrap.innerHTML = pend.map(p => _commPostHtml(p, true)).join('');
}
function _commWireTabs() {
  document.querySelectorAll('#commAdminTools .comm-tab').forEach(t => {
    t.onclick = () => {
      document.querySelectorAll('#commAdminTools .comm-tab').forEach(x => x.classList.toggle('active', x === t));
      document.getElementById('commTabPost').classList.toggle('active', t.dataset.commtab === 'post');
      document.getElementById('commTabQuest').classList.toggle('active', t.dataset.commtab === 'quest');
    };
  });
}
// Load the signed-in student's saved animal avatar, then paint the picker.
async function _commLoadMyProfile() {
  if (!(currentUser && currentUser.role === 'student')) return;
  if (!currentUser.avatar && _commCanFirestore()) {
    try {
      const snap = await getDoc(doc(db, 'userProfiles', currentUser.uid));
      const a = snap.exists() && snap.data().avatar;
      currentUser.avatar = (a && COMM_AVATARS.includes(a)) ? a : COMM_DEFAULT_AVATAR;
    } catch (e) { console.warn('avatar load', e); currentUser.avatar = COMM_DEFAULT_AVATAR; }
  }
  renderCommAvatarPicker();
}
function renderCommAvatarPicker() {
  const row = document.getElementById('commAvatarRow'); if (!row) return;
  if (!(currentUser && currentUser.role === 'student')) return;
  const mine = _commMyAvatar();
  row.innerHTML = COMM_AVATARS.map(a =>
    '<button type="button" class="comm-ava-btn' + (a === mine ? ' selected' : '') +
    '" onclick="commPickAvatar(\'' + a + '\')" aria-label="Pick avatar ' + a + '">' + a + '</button>'
  ).join('');
  const count = _commPostCount(currentUser.uid);
  const st = document.getElementById('commMyStatus');
  if (st) st.textContent = _commStudentStatus(count);
  const hint = document.getElementById('commRankHint');
  if (hint) {
    const next = _commNextTier(count);
    hint.textContent = next
      ? ('You have ' + count + ' approved post' + (count === 1 ? '' : 's') + ' — ' + next.need + ' more to reach ' + next.label + '!')
      : ('You have ' + count + ' approved posts — top rank reached! 🏆');
  }
}
async function commPickAvatar(emoji) {
  if (!(currentUser && currentUser.role === 'student') || !COMM_AVATARS.includes(emoji)) return;
  currentUser.avatar = emoji;
  renderCommAvatarPicker();
  if (_commCanFirestore()) {
    try { await setDoc(doc(db, 'userProfiles', currentUser.uid), { avatar: emoji }, { merge: true }); showToast('Avatar updated ✓', 'success'); }
    catch (e) { console.warn('avatar save', e); showToast('Could not save avatar', 'error'); }
  }
}
function renderCommunity() {
  const pc = document.getElementById('commPendingCard'); if (pc && !_isAdmin()) pc.style.display = 'none';
  _commWireTabs();
  _commSubscribeFeed();
  commStartGlobalWatch();
  _commLoadMyProfile();
  _renderCommFeed(); _renderCommPending(); _renderQuestBanners();
}

// ---- Adventure mode (idle side-scrolling auto-battler, MOBA-style skills) ----
const ADV_MAX_RUNS = 3, ADV_WAVES = 5, ADV_FLOORS_PER_RAID = 3;
// Dungeon reward pacing. The auto-battler is an idle BONUS — answering
// questions is the real road to level 99 (~165k XP total). These scale the
// raid payouts right down, fodder gives gold but no XP, and the floor-clear
// bonus is capped, so a pure-dungeon climb to 99 takes well over a year of
// daily raids while still rewarding automated play. Tune these to taste.
const ADV_XP_SCALE = 0.03, ADV_GOLD_SCALE = 0.15;
const ADV_TICK_MS = 100, ADV_HERO_ATK_MS = 1100;
let adv = null;       // active run state
let advToken = 0;     // invalidates timers from finished/abandoned runs

function advToday() {
  const d = new Date();
  return d.getFullYear() + "-" + String(d.getMonth() + 1).padStart(2, "0") + "-" + String(d.getDate()).padStart(2, "0");
}
function advYesterday() {
  const d = new Date(); d.setDate(d.getDate() - 1);
  return d.getFullYear() + "-" + String(d.getMonth() + 1).padStart(2, "0") + "-" + String(d.getDate()).padStart(2, "0");
}
function advRunsUsed() {
  const r = rpgState && rpgState.advRuns;
  return r && r.day === advToday() ? (r.used || 0) : 0;
}
// Dungeon raids now draw from the same daily game-credit pool as the arcade
// mini-games — "runs left" is just the shared credit balance.
function advRunsLeft() { return _creditsLeft(); }
// The floor the next raid resumes on. Saved across raids/days so the dungeon is
// a continuous climb — each raid advances it by up to ADV_FLOORS_PER_RAID.
function advDungeonFloor() { return Math.max(1, Math.floor((rpgState && rpgState.dungeonFloor) || 1)); }
function advAfter(ms, fn) {
  const t = advToken;
  setTimeout(() => { if (adv && advToken === t) fn(); }, ms);
}
// weapon → auto-attack style + element effects
function rpgWeaponFx(itemId) {
  const id = String(itemId || "");
  let kind = "slash";
  if (!id) kind = "punch";
  else if (/bow|piercer/.test(id)) kind = "ranged";
  else if (/staff|wand|scepter|crook/.test(id)) kind = "magic";
  else if (/axe|hammer|scythe/.test(id)) kind = "chop";
  else if (/spear|trident|halberd/.test(id)) kind = "thrust";
  let color = "#dbe3ea", emoji = "✨";
  if (/flame|ember|dragon|phoenix/.test(id)) { color = "#ff6b35"; emoji = "🔥"; }
  else if (/frost|glacier|penguin/.test(id)) { color = "#8fd4ee"; emoji = "❄️"; }
  else if (/oak|sprout|rune|elven|emerald/.test(id)) { color = "#0f7a5a"; emoji = "🍃"; }
  else if (/void|shadow|obsidian/.test(id)) { color = "#9b7fd4"; emoji = "🌀"; }
  else if (/star|comet|storm/.test(id)) { color = "#ffd76a"; emoji = "⭐"; }
  else if (/sun|excalibur|golden|gilded|crown|royal/.test(id)) { color = "#ffd76a"; emoji = "✨"; }
  else if (/arcane|crystal|wisp/.test(id)) { color = "#b79ae0"; emoji = "💫"; }
  return { kind, color, emoji };
}
