function advSkillDesc(d) {
  const bits = [];
  if (d.kind === "hit") bits.push(`strikes for ${Math.round(d.mult * 100)}% damage`);
  if (d.kind === "multi") bits.push(`${d.hits} quick strikes of ${Math.round(d.mult * 100)}%`);
  if (d.kind === "volley") bits.push(`fires ${d.hits} arrows of ${Math.round(d.mult * 100)}% at random enemies (some may miss)`);
  if (d.kind === "aoe") bits.push(`hits ALL enemies for ${Math.round(d.mult * 100)}%`);
  if (d.kind === "chain") bits.push(`chain lightning across ${d.jumps + 1} enemies`);
  if (d.kind === "pierce") bits.push(`pierces armour for ${Math.round(d.mult * 100)}%`);
  if (d.kind === "heal") bits.push(`heals ${Math.round(d.pct * 100)}% HP`);
  if (d.kind === "slow") bits.push("chills all enemies, slowing their attacks");
  if (d.kind === "block") bits.push("blocks the next enemy hit");
  if (d.pierce && d.kind !== "pierce") bits.push("ignores armour");
  if (d.exec) bits.push("double damage on weakened enemies");
  if (d.poison) bits.push("poisons");
  if (d.burn) bits.push("burns");
  if (d.chill) bits.push("chills");
  if (d.stun) bits.push("stuns");
  if (d.lifesteal) bits.push(`heals ${Math.round(d.lifesteal * 100)}% of damage dealt`);
  if (d.healPct) bits.push(`restores ${Math.round(d.healPct * 100)}% HP`);
  return `${d.name} (${d.cd}s): ` + bits.join(", ");
}
function advWaveTiers(floorOffset = 0) {
  // difficulty follows the FLOOR, not the hero's level — levelling up must
  // always make earlier floors easier. Raw tiers may exceed 10 on deep
  // floors — enemies are picked at tier 10 and scaled up instead, so the
  // dungeon never stops getting harder.
  const f = floorOffset + 1;
  return [f - 1, f, f, f + 1, f + 2].map(t => Math.max(1, t));
}
// hordes: waves are packed with weak fodder so AOE, chain and volleys mow them down
function advWaveComp(w) {
  const t = adv.tiers[w], mt = Math.max(1, t - 1);
  const fodder = n => Array.from({ length: n }, () => ({ tier: mt, minion: true }));
  if (w === ADV_WAVES - 1) return [{ tier: t, boss: true }].concat(fodder(4));
  if (w === 0) return fodder(3);
  if (w === 1) return [{ tier: t }].concat(fodder(3));
  if (w === 2) return [{ tier: t }].concat(fodder(4));
  return [{ tier: t }].concat(fodder(5));
}
