    boss: false, minion: false, hp: g.maxHp, max: g.maxHp, scale: 1, ranged: gKind === "magic" || gKind === "ranged",
    wx: Math.round(w * 0.66), reached: false, slot: 0, speed: 0.07, armor: Math.floor(g.def * 0.4),
