const ADV_BEAT_EPOCH = Date.now();
let advRafLast = 0;
function advRaf(ts) {
  if (!adv || !adv.rafOn) return;
  const dt = Math.max(0, Math.min(60, advRafLast ? ts - advRafLast : 16));
  advRafLast = ts;
  // ease scroll speed toward its target; consume kill-lurch boosts
  const target = adv.phase === "fight" || adv.phase === "between" ? adv.scrollTarget || 0 : 0;
  adv.scroll += (target - adv.scroll) * Math.min(1, dt / 220);
  adv.scroll = Math.max(0, Math.min(160, adv.scroll));
  let dx = adv.scroll * dt / 1000;
  if (adv.lurch > 0) { const l = Math.min(adv.lurch, dt * 0.12); dx += l; adv.lurch -= l; }
  if (dx) adv.worldX += dx;
  if (!Number.isFinite(adv.worldX)) adv.worldX = 0;
  const wEl = $("advFoes");
  if (wEl && wEl.style) wEl.style.transform = `translate3d(${-Math.round(adv.worldX)}px,0,0)`;
  const stage = $("advStage");
  if (stage && stage.classList) stage.classList.toggle("walking", adv.scroll > 12);
  if (typeof requestAnimationFrame === "function") requestAnimationFrame(advRaf);
}
