  try {
    const snap = await getDoc(doc(db, 'users', uid, 'settings', 'tcgConfig'));
    _tcgConfig = snap.exists() ? (snap.data() || {}) : { released: false };
  } catch (e) { console.warn('tcg config load', e); _tcgConfig = _tcgConfig || { released: false }; }
