// Pull real questions from the live question bank (the database) — including the
// ones with diagrams/pictures — as long as they have an auto-gradable multiple-
// choice part. The full stem (text + images) is rendered so students answer the
// actual syllabus questions, not plain text. Best-effort; safe if the bank is empty.
// HTML → plain text with entities DECODED (an inert DOMParser document, so
// nothing in the markup can load or run). stripHtml keeps entities encoded,
// which double-escapes once a consumer runs escapeHtml over the result.
function _htmlPlainText(html) {
  try {
    return (new DOMParser().parseFromString(String(html || ''), 'text/html').body.textContent || '')
      .replace(/\s+/g, ' ').trim();
  } catch (e) { return stripHtml(html); }
}
function _tcgBankQuestions() {
  const out = [];
  try {
    (typeof questionBank !== 'undefined' && Array.isArray(questionBank) ? questionBank : []).forEach(q => {
      if (!q || (q.status && q.status !== 'approved') || !Array.isArray(q.blocks)) return;
      if (!qInSyllabus(q)) return;   // retired topics never reach the Realm of Embers TCG quiz
      const mcq = q.blocks.find(b => b && b.type === 'mcq' && b.correctId && Array.isArray(b.options) && b.options.length >= 2);
      if (!mcq) return;
      const ai = mcq.options.findIndex(o => o.id === mcq.correctId);
      if (ai < 0) return;
      const opts = mcq.options.map(o => stripHtml(o.text || '').trim());
      if (opts.some(t => !t)) return;
      let html = '', hasStem = false;
      q.blocks.forEach(b => {
        if (!b) return;
        if (b.type === 'text' && b.content && stripHtml(b.content).trim()) { html += '<div class="qp-qtext">' + b.content + '</div>'; hasStem = true; }
        else if (b.type === 'image' && b.url) { html += '<div class="tcg-quiz-img"><img src="' + escapeHtml(transformImageUrl(b.url)) + '" onerror="handleImgError(this)" loading="lazy" decoding="async" style="' + imgSizeStyle(b) + '"></div>'; hasStem = true; }
      });
      if (!hasStem) return;
      // The question's explanation block rides along so the modes that teach
      // after the answer (the Legends arena and the trainer) can show it.
      // Decoded to real text — stripHtml would leave &amp;/&lt; entities in,
      // and the consumers escapeHtml the string again on render.
      const exB = q.blocks.find(b => b && b.type === 'explanation' && b.content && stripHtml(b.content).trim());
      out.push({ id: q.id || '', html: html, opts: opts, a: ai, ex: exB ? _htmlPlainText(exB.content) : '', db: true });
    });
  } catch (e) {}
  return out;
}
// Fallback pool: quick built-in questions, used only when the bank has no
// auto-gradable questions yet (so training never hard-breaks).
function _tcgFallbackQuestions() {
  return TCG_QUIZ.map(x => ({ html: '<div class="qp-qtext">' + escapeHtml(x.q) + '</div>', opts: x.opts, a: x.a, ex: x.ex, db: false }));
}
// Prefer real database questions; fall back to the built-in set if there are none.
function _tcgQuizPool() { const db = _tcgBankQuestions(); return db.length ? db : _tcgFallbackQuestions(); }
function _tcgShuffle(a) { a = a.slice(); for (let i = a.length - 1; i > 0; i--) { const j = Math.floor(Math.random() * (i + 1)); const t = a[i]; a[i] = a[j]; a[j] = t; } return a; }
// Persistent per-student trainer rotation: every question served in Monster
// Cards training is stamped, and the pool is ordered least-recently-served
// first — so closing/reopening the trainer (or switching monsters) no longer
// reshuffles recently-answered questions straight back in.
function _tcgServedKey() { return 'tcgTrainServed_' + ((currentUser && currentUser.uid) || 'guest'); }
function _tcgServedLoad() { try { return JSON.parse(localStorage.getItem(_tcgServedKey())) || {}; } catch (e) { return {}; } }
function _tcgServedMark(id) { if (!id) return; try { const m = _tcgServedLoad(); m[id] = Date.now(); localStorage.setItem(_tcgServedKey(), JSON.stringify(m)); } catch (e) {} }
let _tcgQuiz = null;
function tcgTrainCard(id) {
  const s = tcgState();
  if (!s || !s.cards[id]) { showToast('Collect this monster first', 'error'); return; }
  tcgClosePreview();
  const existing = document.getElementById('tcgTrainOverlay'); if (existing) existing.remove();
  const pool = _tcgQuizPool();
  if (!pool.length) { showToast('No practice questions available yet', 'error'); return; }
  // Shuffle for a random tie-break, then serve least-recently-trained first.
  const servedMap = _tcgServedLoad();
  const ordered = _tcgShuffle(pool).sort((a, b) => (servedMap[a.id] || 0) - (servedMap[b.id] || 0));
  _tcgQuiz = { id, pool: ordered, i: 0, answered: false, cur: null };
  const c = TCG_BY_ID[id];
  const o = document.createElement('div');
  o.className = 'tcg-overlay'; o.id = 'tcgTrainOverlay';
  o.addEventListener('click', e => { if (e.target === o) tcgCloseTrain(); });
  o.innerHTML = '<div class="tcg-train-modal">'
    + '<div class="tcg-train-topbar"><div class="tcg-train-title">🎓 Training <b>' + escapeHtml(tcgShortName(c)) + '</b></div>'
    + '<button type="button" class="tcg-train-x" onclick="tcgCloseTrain()">✕</button></div>'
    + '<div class="tcg-train-status" id="tcgqStatus"></div>'
    + '<div class="tcg-quiz" id="tcgqBody"></div>'
    + '</div>';
  document.body.appendChild(o);
  _tcgQuizStatus();
  _tcgQuizRender();
}
function _tcgQuizStatus(flash) {
  const st = document.getElementById('tcgqStatus'); if (!st || !_tcgQuiz) return;
  const id = _tcgQuiz.id, level = tcgLevel(id), prog = tcgLvlProg(id), maxed = level >= TCG_LVL_MAX;
  st.innerHTML = '<span class="tcg-lvl-tag big">Lv ' + level + '</span>'
    + (maxed ? '<span class="tcg-lvl-max">MAX</span>'
      : '<span class="tcg-xpbar wide"><i style="width:' + Math.round(prog / TCG_LVL_STEP * 100) + '%;"></i></span>'
        + '<span class="tcg-quiz-count">' + prog + ' / ' + TCG_LVL_STEP + ' to Lv ' + (level + 1) + '</span>');
  if (flash) { st.classList.remove('flash'); void st.offsetWidth; st.classList.add('flash'); }
}
function _tcgQuizRender() {
  const body = document.getElementById('tcgqBody'); if (!body || !_tcgQuiz) return;
  const level = tcgLevel(_tcgQuiz.id);
  if (level >= TCG_LVL_MAX) {
    body.innerHTML = '<div class="tcg-quiz-done">🌟 <b>' + escapeHtml(tcgShortName(TCG_BY_ID[_tcgQuiz.id])) + '</b> is fully trained to Level ' + TCG_LVL_MAX + ' — max stats and skill!'
      + '<div style="margin-top:14px;"><button class="btn btn-primary" type="button" onclick="tcgCloseTrain()">Done</button></div></div>';
    return;
  }
  _tcgQuiz.answered = false;
  _tcgQuiz.at = performance.now();   // clocked so the shared anti-rush gate applies here too
  const q = _tcgQuiz.pool[_tcgQuiz.i % _tcgQuiz.pool.length];
  _tcgQuiz.cur = q;
  if (q && q.id) _tcgServedMark(q.id);
  body.innerHTML = '<div class="tcg-quiz-q">' + (q.html || escapeHtml(q.q || '')) + '</div>'
    + '<div class="tcg-quiz-opts">'
    + q.opts.map((o, idx) => '<button type="button" class="tcg-quiz-opt" data-i="' + idx + '" onclick="_tcgQuizAnswer(' + idx + ')">'
        + '<span class="tcg-quiz-let">' + (idx + 1) + '</span>' + escapeHtml(o) + '</button>').join('')
    + '</div>'
    + '<div class="tcg-quiz-fb" id="tcgqFb"></div>';
}
function _tcgQuizAnswer(idx) {
  if (!_tcgQuiz || _tcgQuiz.answered) return;
  _tcgQuiz.answered = true;
  const q = _tcgQuiz.cur;
  const correct = idx === q.a;
  // Training answers on real bank questions count as attempts everywhere else:
  // stamp the shared game rotation and write the teacher-visible attempt log,
  // so practice/quests/games stop re-serving trainer-grinded questions as new.
  if (q.db && q.id) {
    try { _gqMark(q.id); } catch (e) {}
    if (currentUser && currentUser.role === 'student') {
      try { noteAttemptLocally(q.id, correct ? 1 : 0, 1); } catch (e) {}
      try {
        addDoc(collection(db, 'questionAttempts'), {
          uid: currentUser.uid, email: currentUser.email, displayName: currentUser.name,
          questionId: q.id, questionTitle: '', score: correct ? 1 : 0, totalBlanks: 1,
          answerHash: '', ms: 0, timestamp: Timestamp.now(), mode: 'tcg-train'
        }).catch(err => console.warn('tcg attempt log failed', err));
      } catch (e) {}
    }
  }
  // Training answers pay points like every other game mode — training a
  // monster up and saving for the next booster pack are the same session now.
  const pts = rpgAwardGameQuestion(q && q.id, correct, _tcgQuiz.at ? performance.now() - _tcgQuiz.at : 0);
  const ptsBit = pts ? ' <span class="tcg-fb-pts">🪙 +' + pts + ' points</span>' : '';
  const body = document.getElementById('tcgqBody');
  const btns = body ? body.querySelectorAll('.tcg-quiz-opt') : [];
  btns.forEach(b => { b.disabled = true; const i = +b.dataset.i; if (i === q.a) b.classList.add('right'); else if (i === idx) b.classList.add('wrong'); });
  let msg = '';
  if (correct) {
    const res = tcgAddLevelProgress(_tcgQuiz.id);
    _tcgQuizStatus(true);
    if (res && res.leveledUp) {
      _tcgLevelUpBurst();
      msg = '<div class="tcg-fb-ok">✅ Correct! <b>Level up! → Lv ' + res.level + '</b>' + (res.skillUp ? ' · ⬆ <b>Skill upgraded!</b>' : '') + (res.maxed ? ' · 🌟 MAX level!' : '') + ptsBit + '</div>';
      showToast(tcgShortName(TCG_BY_ID[_tcgQuiz.id]) + ' reached Level ' + res.level + (res.skillUp ? ' — skill upgraded!' : '') + '!', 'success');
    } else if (res && res.max) {
      msg = '<div class="tcg-fb-ok">✅ Correct! This monster is already fully trained.' + ptsBit + '</div>';
    } else {
      msg = '<div class="tcg-fb-ok">✅ Correct! ' + (res ? res.progress : 0) + ' / ' + TCG_LVL_STEP + ' toward the next level.' + ptsBit + '</div>';
    }
  } else {
    msg = '<div class="tcg-fb-no">❌ Not quite — the correct answer is <b>(' + (q.a + 1) + ')</b>. Keep going, the next one counts!' + ptsBit + '</div>';
  }
  if (q.ex) msg += '<div class="tcg-fb-ex">' + escapeHtml(q.ex) + '</div>';
  msg += '<div style="margin-top:14px;text-align:center;"><button class="btn btn-primary" type="button" onclick="_tcgQuizNext()">Next question ▶</button></div>';
  const fb = document.getElementById('tcgqFb');
  if (fb) fb.innerHTML = msg;
}
function _tcgQuizNext() { if (!_tcgQuiz) return; _tcgQuiz.i++; _tcgQuizRender(); }
function _tcgLevelUpBurst() {
  const modal = document.querySelector('.tcg-train-modal'); if (!modal) return;
  const d = document.createElement('div'); d.className = 'tcg-levelup-burst'; d.textContent = 'LEVEL UP!';
  modal.appendChild(d); setTimeout(() => d.remove(), 1300);
}
function tcgCloseTrain() {
  _tcgQuiz = null;
  const o = document.getElementById('tcgTrainOverlay'); if (o) o.remove();
  try { tcgRenderBody(); } catch (_) {}
}

// -- Packs tab --
function tcgPacksHtml(s) {
  const gold = (rpgState && rpgState.gold) | 0;
  const oddsLine = p => [1, 2, 3, 4, 5, 6, 7].filter(n => p.odds[n]).map(n => n + '★ ' + p.odds[n] + '%').join(' · ');
  return '<div class="tcg-section-note">Booster packs are the <b>only</b> way to collect monsters <b>and 🔱 artifacts</b>. You have <b>🪙 ' + gold.toLocaleString() + ' points</b> — every question you answer <b>anywhere</b> pays into this wallet: practice, 🎓 training, 🌋 Ember Siege, and every game in the sidebar (Defenders, Raiders, Spire, Legends, Slayers and 🔫 Science Strike).'
    + (_isAdmin() ? ' <button class="btn btn-ghost" style="font-size:0.75rem;" onclick="tcgAdminGold()">＋500 🪙 test points (admin)</button>' : '') + '</div>'
    + '<div class="tcg-packs">' + TCG_PACKS.map(p =>
      '<div class="tcg-pack tcg-pack-' + p.tier + '">'
      + '<div class="tcg-pack-art">' + tcgPackArt(p.tier) + '</div>'
      + '<h4>' + escapeHtml(p.name) + '</h4>'
      + '<div class="tcg-pack-desc">' + escapeHtml(p.desc) + '</div>'
      + '<div class="tcg-pack-odds">' + oddsLine(p) + (p.bonusOdds ? '<br><b>Bonus card:</b> ' + Object.keys(p.bonusOdds).map(n => n + '★ ' + p.bonusOdds[n] + '%').join(' · ') : '') + '</div>'
      + '<button class="btn btn-primary" ' + (gold < p.cost ? 'disabled style="opacity:.55;"' : '') + ' onclick="tcgBuyPack(\'' + p.id + '\')">Open · 🪙 ' + p.cost + '</button>'
      + '</div>').join('') + '</div>'
    + '<div class="tcg-section-note tcg-merge-note" style="margin-top:22px;">'
    +   '<b>⟡ Repeats are never wasted.</b> Pull a monster you already own and the copy <b>merges into it automatically</b> — no button, nothing to sort. '
    +   'Every merge is a <b>merge level</b> (1 → ' + TCG_MERGE_MAX + '), a track completely separate from the 🎓 training levels you earn by answering questions, '
    +   'and each one adds <b>1.2% to every stat</b> in <b>all three game modes</b>.'
    +   '<div class="tcg-merge-rates">' + [1, 2, 3, 4, 5, 6, 7].map(n =>
          '<span' + (n >= 6 ? ' class="hot"' : '') + '>' + n + '★ <b>+' + tcgMergeGain(n) + '</b></span>').join('') + '</div>'
    +   '<span style="opacity:.8;">6★ and 7★ repeats are the rarest thing in the game, so they climb this track far faster — a single 7★ repeat is worth '
    +   tcgMergeGain(7) + ' merge levels.</span>'
    + '</div>'
    + '<div class="tcg-section-note" style="margin-top:14px;">Opened so far: <b>' + (s.packs | 0) + ' pack' + (s.packs === 1 ? '' : 's') + '</b></div>';
}
function tcgAdminGold() {
  if (!_isAdmin() || !rpgState) return;
  rpgState.gold = (rpgState.gold | 0) + 500;
  rpgSave(); tcgUpdateGoldChip(); tcgRenderBody();
  showToast('+500 test points (admin preview)', 'success');
}
// Admin play-test helper: grant one copy of every monster AND every artifact
// so everything can be tried without opening packs. Only fills gaps — owned
// counts and levels stay untouched.
function tcgAdminGrantAll() {
  if (!_isAdmin()) return;
  const s = tcgState();
  if (!s) { showToast('Answer a question anywhere in the app to wake your hero first, then try again', 'error'); return; }
  let addedC = 0, addedA = 0;
  TCG_CARDS.forEach(c => { if (!s.cards[c.id]) { s.cards[c.id] = 1; addedC++; } });
  s.artifacts = s.artifacts || {};
  TCG_ARTIFACTS.forEach(a => { if (!s.artifacts[a.id]) { s.artifacts[a.id] = 1; addedA++; } });
  if (!addedC && !addedA) { showToast('You already own all ' + TCG_CARDS.length + ' cards and all ' + TCG_ARTIFACTS.length + ' artifacts ✔', 'success'); return; }
  rpgSave();
  showToast('🃏 +' + addedC + ' cards · 🔱 +' + addedA + ' artifacts — everything unlocked!', 'success');
  tcgRenderBody();
}
function tcgBuyPack(packId) {
  const p = TCG_PACKS.find(x => x.id === packId);
  const s = tcgState();
  if (!p || !s || !rpgState) return;
  if (((rpgState.gold | 0)) < p.cost) { showToast('Not enough points — answer more questions to earn 🪙 ' + p.cost, 'error'); return; }
  rpgState.gold = (rpgState.gold | 0) - p.cost;
  const pulls = [];
  let mergedLevels = 0, mergedCards = 0;
  for (let i = 0; i < p.cards; i++) {
    const odds = (p.bonusOdds && i === p.cards - 1) ? p.bonusOdds : p.odds;
    const card = _tcgRollCard(odds);
    const isNew = !s.cards[card.id];
    s.cards[card.id] = (s.cards[card.id] | 0) + 1;
    // A repeat is absorbed the moment it is pulled — no button to press.
    const merge = isNew ? null : tcgMergeAbsorb(card.id, 1);
    if (merge && merge.gained > 0) { mergedLevels += merge.gained; mergedCards++; }
    pulls.push({ card, isNew, merge });
  }
  // Bonus artifact slot — the other pack prize, revealed as one extra card.
  if (p.artChance && Math.random() < p.artChance) {
    const arti = _tcgRollArtifact(p.odds);
    s.artifacts = s.artifacts || {};
    const isNew = !s.artifacts[arti.id];
    s.artifacts[arti.id] = (s.artifacts[arti.id] | 0) + 1;
    pulls.push({ arti, isNew });
  }
  s.packs = (s.packs | 0) + 1;
  rpgSave();
  try { rpgPublishLeaderboard(); } catch (e) {}
  tcgUpdateGoldChip();
  tcgShowReveal(p, pulls);
  if (mergedLevels) {
    setTimeout(() => showToast('⟡ ' + mergedCards + ' repeat' + (mergedCards === 1 ? '' : 's') + ' merged — +'
      + mergedLevels + ' merge level' + (mergedLevels === 1 ? '' : 's') + ', stats up!', 'success'), 700);
  }
}
// -- Pack opening ceremony --
function tcgShowReveal(pack, pulls) {
  const old = document.getElementById('tcgRevealOverlay');
  if (old) old.remove();
  const o = document.createElement('div');
  o.className = 'tcg-overlay';
  o.id = 'tcgRevealOverlay';
  o.innerHTML = '<div class="tcg-reveal-inner">'
    + '<div class="tcg-reveal-title">' + pack.em + ' ' + escapeHtml(pack.name) + ' opened!</div>'
    + '<div class="tcg-reveal-sub">Tap each card to flip it over…</div>'
    + '<div class="tcg-reveal-row">' + pulls.map((pl, i) =>
        '<div class="tcg-flip" id="tcgflip-' + i + '" data-stars="' + (pl.card || pl.arti).stars + '" style="animation-delay:' + (i * 0.12) + 's;" onclick="tcgFlipCard(' + i + ')" title="Hover halo hints at the rarity…">'
        + '<div class="tcg-flip-inner">'
        +   '<div class="tcg-flip-back">' + tcgCardBackHtml() + '</div>'
        +   '<div class="tcg-flip-front">' + (pl.arti ? tcgArtifactCardHtml(pl.arti, { isNew: pl.isNew }) : tcgCardHtml(pl.card, { isNew: pl.isNew, mergedBy: pl.merge })) + '</div>'
        + '</div></div>').join('') + '</div>'
    + '<div style="display:flex;gap:10px;justify-content:center;flex-wrap:wrap;">'
    +   '<button class="btn tcg-overlay-btn" onclick="tcgFlipAll()">🔄 Flip all</button>'
    +   '<button class="btn btn-primary" onclick="tcgCloseReveal()">Done</button>'
    + '</div></div>';
  document.body.appendChild(o);
  o._pulls = pulls;
}
function tcgFlipCard(i) {
  const o = document.getElementById('tcgRevealOverlay');
  const f = document.getElementById('tcgflip-' + i);
  if (!o || !f || f.classList.contains('flipped')) return;
  f.classList.add('flipped');
  const pl = o._pulls && o._pulls[i];
  const stars = pl && (pl.card || pl.arti).stars;
  if (stars >= 5) tcgConfetti(stars >= 7 ? 90 : 45);
}
function tcgFlipAll() {
  const o = document.getElementById('tcgRevealOverlay');
  if (!o) return;
  (o._pulls || []).forEach((_, i) => setTimeout(() => tcgFlipCard(i), i * 220));
}
function tcgCloseReveal() {
  const o = document.getElementById('tcgRevealOverlay');
  if (o) o.remove();
  tcgRenderBody();
}
function tcgConfetti(n) {
  const colors = ['#f59e0b', '#ec4899', '#8b5cf6', '#2d6ca8', '#22c55e', '#ef4444', '#fde047'];
  for (let i = 0; i < n; i++) {
    const c = document.createElement('div');
    c.className = 'tcg-confetti';
    c.style.left = Math.random() * 100 + 'vw';
    c.style.background = colors[i % colors.length];
    c.style.animationDuration = (1.6 + Math.random() * 1.6) + 's';
    c.style.animationDelay = (Math.random() * 0.5) + 's';
    document.body.appendChild(c);
    setTimeout(() => c.remove(), 4000);
  }
}
