      for (const t of targets) { const res = _tcgDamage(unit, t, sk.pow, false); _tcgHitFx(t, res); }
      _tcgLog('<b>' + escapeHtml(tcgShortName(unit.card)) + '</b> unleashes <b>' + escapeHtml(sk.name) + '</b> on the whole enemy team!');
      await tcgSleep(760);
