// Artifact badge pinned to the battle stage (opponent top-left, you top-right).
// Hover — or tap on touch screens — reveals the full artifact card so the
// effect can be read mid-battle. Shows a muted "no artifact" pill when empty.
function _tcgArtiBadge(art, side, ownerLabel) {
  if (!art) {
    return '<div class="tcgb-arti ' + side + ' none"><span class="tcgb-arti-owner">' + escapeHtml(ownerLabel) + '</span>'
      + '<span class="tcgb-arti-pill">🔱 No artifact</span></div>';
  }
  return '<div class="tcgb-arti ' + side + '" onclick="this.classList.toggle(\'open\')" title="' + escapeHtml(art.name + ' — ' + art.blurb) + '">'
    + '<span class="tcgb-arti-owner">' + escapeHtml(ownerLabel) + '</span>'
    + '<span class="tcgb-arti-pill">' + art.icon + ' <b>' + escapeHtml(art.name) + '</b></span>'
    + '<div class="tcgb-arti-card">' + tcgArtifactCardHtml(art) + '</div>'
    + '</div>';
}
function _tcgUnitHtml(u) {
  // 5-a-side: staggered double columns spread over the full stage height with
  // ~29% same-column spacing so a sprite never overlaps a neighbouring plate.
  const posOwn = [{ r: '22%', b: '60%' }, { r: '0%', b: '45.5%' }, { r: '22%', b: '31%' }, { r: '0%', b: '16.5%' }, { r: '22%', b: '2%' }];
  const posFoe = [{ l: '22%', t: '2%' }, { l: '0%', t: '16.5%' }, { l: '22%', t: '31%' }, { l: '0%', t: '45.5%' }, { l: '22%', t: '60%' }];
  const p = u.side === 'R' ? posOwn[u.slot] : posFoe[u.slot];
  const style = (p.l ? 'left:' + p.l + ';' : '') + (p.r ? 'right:' + p.r + ';' : '') + (p.t ? 'top:' + p.t + ';' : '') + (p.b ? 'bottom:' + p.b + ';' : '');
  const url = tcgAvatarUrl(u.card.id);
  return '<div class="tcgb-unit ' + (u.side === 'L' ? 'left' : 'right') + '" id="tcgbu-' + u.uid + '" style="' + style + '">'
    + '<span class="tcgb-sprite">' + (url ? '<img src="' + escapeHtml(url) + '" alt="">' : u.card.em) + '</span>'
    + '<div class="tcgb-plate">'
    +   '<div class="tcgb-name">' + escapeHtml(tcgShortName(u.card)) + '</div>'
    +   '<div class="tcgb-stars">' + '★'.repeat(u.card.stars) + '</div>'
    +   '<div class="tcgb-lvl" title="Training level ' + u.level + ' · merge level ' + u.merge + '">Lv ' + u.level + (u.merge > 1 ? ' <i>⟡' + u.merge + '</i>' : '') + '</div>'
    +   '<div class="tcgb-hpbar"><div style="width:100%;"></div></div>'
    +   '<div class="tcgb-hptext">' + u.maxHp + ' / ' + u.maxHp + '</div>'
    +   '<div class="tcgb-status"></div>'
    + '</div></div>';
}
function tcgBattleSpeed(mult) {
  if (_tcgBattle) _tcgBattle.speed = mult;
  document.querySelectorAll('[data-tcgspeed]').forEach(b => b.classList.toggle('on', +b.dataset.tcgspeed === mult));
}
function tcgSkipBattle() { if (_tcgBattle) _tcgBattle.skip = true; }
function tcgCloseBattle() {
  if (_tcgBattle) _tcgBattle.token++;
  _tcgBattle = null;
  const o = document.getElementById('tcgBattleOverlay');
  if (o) o.remove();
  tcgRenderBody();
}
async function tcgFindBattle() {
  const s = tcgState();
  if (!s || s.team.length !== 5) { showToast('Pick 5 monsters on the My Team tab first', 'error'); return; }
  showToast('Looking for an opponent…', 'info');
  const opp = await tcgFindOpponent();
  tcgRunBattle(s.team.slice(), { name: (currentUser && currentUser.name) || 'You' }, opp);
}
async function tcgRunBattle(myTeam, me, opp) {
  const old = document.getElementById('tcgBattleOverlay');
  if (old) old.remove();
  _tcgBattle = { token: 1, speed: 1, skip: false };
  const token = _tcgBattle.token;
  // BOTH progression tracks come into the Arena and the Dungeon: the training
  // level from answering questions AND the merge level from repeat copies.
  const mine = myTeam.map((id, i) => _tcgMkUnit(id, 'R', i, tcgLevel(id), tcgMergeLevel(id)));
  // Scale the opponent to ~85% of your team's average level so matches stay
  // competitive as your monsters grow.
  const myAvg = Math.round(myTeam.reduce((a, id) => a + tcgLevel(id), 0) / Math.max(1, myTeam.length));
  const myAvgMerge = Math.round(myTeam.reduce((a, id) => a + tcgMergeLevel(id), 0) / Math.max(1, myTeam.length));
  // Dungeon keepers bring their own fixed level; arena opponents scale to you.
  const oppLvl = opp.lvl || Math.max(1, Math.round(myAvg * 0.85));
  // A real opponent brings their own published merge average; ghosts and arena
  // fill-ins mirror yours at 85% so merging never trivialises the ladder.
  const oppMerge = opp.mlvl || Math.max(1, Math.round(myAvgMerge * 0.85));
  const theirs = opp.tcgTeam.map((id, i) => _tcgMkUnit(id, 'L', i, oppLvl, oppMerge));
  // Endless dungeon growth: past Floor 40 keeper stats keep multiplying forever.
  if (opp.statMult && opp.statMult > 1) theirs.forEach(u => {
    u.maxHp = Math.round(u.maxHp * opp.statMult); u.hp = u.maxHp;
    u.atk = Math.round(u.atk * opp.statMult);
    u.def = Math.round(u.def * opp.statMult);
    u.heal = Math.round(u.heal * opp.statMult);
  });
  // Your chosen strategy drives your team's targeting/healing; the opponent uses
  // sensible defaults. Your equipped artifact buffs your whole team.
  const s0 = tcgState();
  const myStrat = (s0 && s0.strategy) || { attack: 'lowhp', heal: 'mosthurt' };
  mine.forEach(u => { u.strat = { attack: myStrat.attack, heal: myStrat.heal }; });
  const myCtx = { phoenixLeft: 0 };
  mine.forEach(u => { u.ctx = myCtx; });
  if (s0 && s0.artifact) _tcgApplyArtifact(mine, s0.artifact, myCtx);
  const myArt = tcgArtifactById(s0 && s0.artifact);
  // A real opponent's published artifact buffs their team too — fair is fair.
  const theirCtx = { phoenixLeft: 0 };
  theirs.forEach(u => { u.ctx = theirCtx; });
  if (opp.artifact) _tcgApplyArtifact(theirs, opp.artifact, theirCtx);
  const oppArt = tcgArtifactById(opp.artifact);
  const o = document.createElement('div');
  o.className = 'tcg-overlay';
  o.id = 'tcgBattleOverlay';
  o.innerHTML = '<div class="tcgb-wrap">'
    + '<div class="tcgb-topbar">'
    +   '<div class="tcgb-vsline">' + escapeHtml(opp.name) + (opp.ghost ? ' <small>(ghost trainer)</small>' : '') + ' <small>vs</small> ' + escapeHtml(me.name)
    +     '<div class="tcgb-plan"><span>' + (myArt ? myArt.icon + ' ' + escapeHtml(myArt.name) : 'No artifact') + '</span>'
    +       '<span>🎯 ' + escapeHtml((TCG_STRATS_ATK.find(x => x.id === myStrat.attack) || {}).name || 'Finisher') + '</span>'
    +       '<span>➕ ' + escapeHtml((TCG_STRATS_HEAL.find(x => x.id === myStrat.heal) || {}).name || 'Triage') + '</span></div>'
    +   '</div>'
    +   '<div class="tcgb-controls">'
    +     '<button type="button" data-tcgspeed="1" class="on" onclick="tcgBattleSpeed(1)">1×</button>'
    +     '<button type="button" data-tcgspeed="2" onclick="tcgBattleSpeed(2)">2×</button>'
    +     '<button type="button" data-tcgspeed="4" onclick="tcgBattleSpeed(4)">4×</button>'
    +     '<button type="button" onclick="tcgSkipBattle()">⏭ Skip</button>'
    +     '<button type="button" onclick="tcgCloseBattle()">✕</button>'
    +   '</div>'
    + '</div>'
    + '<div class="tcgb-stage" id="tcgbStage">'
    +   '<div class="tcgb-vs-splash"><div class="who">' + escapeHtml(opp.name) + '</div><div class="vs">VS</div><div class="who">' + escapeHtml(me.name) + '</div></div>'
    +   _tcgArtiBadge(oppArt, 'left', opp.name) + _tcgArtiBadge(myArt, 'right', 'Your team')
    +   theirs.map(_tcgUnitHtml).join('') + mine.map(_tcgUnitHtml).join('')
    +   '<div class="tcgb-flash"></div>'
    +   '<div class="tcgb-result" id="tcgbResult"></div>'
    + '</div>'
    + '<div class="tcgb-log" id="tcgbLog">The battle begins…</div>'
    + '</div>';
  document.body.appendChild(o);
  const stage = document.getElementById('tcgbStage');
  await tcgSleep(2100); // VS splash
  let round = 0;
  while (round < 30) {
    round++;
    if (!_tcgBattle || _tcgBattle.token !== token) return; // closed
    const order = mine.concat(theirs).filter(u => u.hp > 0).sort((a, b) => b.spd - a.spd || Math.random() - 0.5);
    for (const u of order) {
      if (!_tcgBattle || _tcgBattle.token !== token) return;
      if (u.hp <= 0) continue;
      const allies = u.side === 'R' ? mine : theirs;
      const foes = u.side === 'R' ? theirs : mine;
      if (!foes.some(f => f.hp > 0) || !allies.some(a => a.hp > 0)) break;
      await _tcgAct(stage, u, allies, foes);
      [].concat(mine, theirs).forEach(_tcgRefreshUnit);
      if (!theirs.some(f => f.hp > 0) || !mine.some(f => f.hp > 0)) break;
    }
    if (!theirs.some(f => f.hp > 0) || !mine.some(f => f.hp > 0)) break;
  }
  if (!_tcgBattle || _tcgBattle.token !== token) return;
  const myLeft = mine.reduce((a, u) => a + u.hp / u.maxHp, 0);
  const theirLeft = theirs.reduce((a, u) => a + u.hp / u.maxHp, 0);
  const win = theirLeft <= 0 ? true : myLeft <= 0 ? false : myLeft >= theirLeft;
  const s = tcgState();
  let subMsg = win ? 'Your monsters carried the day 🏆' : escapeHtml(opp.name) + ' takes this one — train up and try again!';
  if (s) {
    if (opp.dungeon) {
      // Dungeon progression: +1 floor per win, more if the floor was crushed.
      s.dungeon = s.dungeon || { level: 1, cleared: 0 };
      if (win) {
        const ease = myLeft / Math.max(1, mine.length); // avg HP fraction left
        const adv = ease >= 0.9 ? 5 : ease >= 0.7 ? 3 : 1;
        s.dungeon.level = Math.max(s.dungeon.level | 0, opp.dungeon + adv);
        s.dungeon.cleared = (s.dungeon.cleared | 0) + 1;
        subMsg = adv > 1
          ? 'Floor ' + opp.dungeon + ' crushed! You skip ahead ' + (adv - 1) + ' floors — next stop: Floor ' + s.dungeon.level + ' 🏰'
          : 'Floor ' + opp.dungeon + ' cleared — next stop: Floor ' + s.dungeon.level + ' 🏰';
      } else {
        subMsg = 'Floor ' + opp.dungeon + ' stands strong. Train your monsters and challenge it again!';
      }
    } else {
      if (win) s.wins = (s.wins | 0) + 1; else s.losses = (s.losses | 0) + 1;
    }
    rpgSave();
    try { rpgPublishLeaderboard(); } catch (e) {}
  }
  const res = document.getElementById('tcgbResult');
  if (res) {
    res.innerHTML = '<div class="word ' + (win ? 'win' : 'lose') + '">' + (win ? 'VICTORY!' : 'DEFEAT') + '</div>'
      + '<div class="sub">' + subMsg + '</div>'
      + '<button class="btn btn-primary" onclick="tcgCloseBattle()">Continue</button>';
    res.classList.add('show');
  }
  if (win) tcgConfetti(70);
  _tcgLog(opp.dungeon
    ? (win ? '<b>Victory!</b> ' + subMsg : '<b>Defeat.</b> ' + subMsg)
    : (win ? '<b>Victory!</b> Record: ' + ((s && s.wins) | 0) + 'W – ' + ((s && s.losses) | 0) + 'L' : '<b>Defeat.</b> Record: ' + ((s && s.wins) | 0) + 'W – ' + ((s && s.losses) | 0) + 'L'));
}

