// =====================================================================
// SCIENCE SPIRE — SPELLBOOK: card packs, collection & deck builder.
// Cards bought from Spell Packs (with the same gold/points earned from
// questions that buy Mythic equipment) are PERMANENT account assets — stored on
// rpgState.spireCards and synced to Firestore, exactly like the RPG inventory.
// The chosen starting deck (rpgState.spireDeck) is pushed into the game iframe.
// Card pictures come from designed vector art in the game; admins may override
// any card with their own image (settings/spireCardArt → cardId:url), making
// cards "game objects" too — the same model as the character sprites above.
// The card ids/cost/type/rarity MUST mirror science-spire.html's CARDS map.
// =====================================================================
const SPIRE_CARDS = {
  strike:      { name:'Strike',       type:'attack', cost:1, rarity:'common',    art:'🗡️', basic:true, desc:'Deal 6 damage.' },
  defend:      { name:'Defend',       type:'skill',  cost:1, rarity:'common',    art:'🛡️', basic:true, desc:'Gain 5 Block.' },
  bash:        { name:'Bash',         type:'attack', cost:2, rarity:'common',    art:'🔨', desc:'Deal 8 and apply 2 Vulnerable.' },
  jab:         { name:'Quick Jab',    type:'attack', cost:0, rarity:'common',    art:'🤜', desc:'Deal 3 damage.' },
  guard:       { name:'Iron Guard',   type:'skill',  cost:2, rarity:'common',    art:'🪨', desc:'Gain 11 Block.' },
  cleave:      { name:'Cleave',       type:'attack', cost:1, rarity:'uncommon',  art:'🪓', desc:'Deal 5 to ALL enemies.' },
  pommel:      { name:'Pommel Strike',type:'attack', cost:1, rarity:'uncommon',  art:'⚔️', desc:'Deal 7 and draw 1 card.' },
  focus:       { name:'Focus',        type:'skill',  cost:0, rarity:'uncommon',  art:'🌀', desc:'Draw 2 cards.' },
  adrenal:     { name:'Adrenaline',   type:'skill',  cost:0, rarity:'uncommon',  art:'⚡', desc:'Gain 1 Energy & draw 1.' },
  weaken:      { name:'Weaken Ray',   type:'skill',  cost:1, rarity:'uncommon',  art:'🔬', desc:'Apply 2 Weak to ALL enemies.' },
  poison:      { name:'Acid Flask',   type:'skill',  cost:1, rarity:'uncommon',  art:'🧪', desc:'Apply 5 Poison.' },
  fireball:    { name:'Fireball',     type:'attack', cost:2, rarity:'rare',      art:'🔥', desc:'Deal 14 damage. Lingers (Burn 3).' },
  shieldwall:  { name:'Shield Wall',  type:'skill',  cost:2, rarity:'rare',      art:'🏰', desc:'Gain 18 Block & draw 1.' },
  doublestrike:{ name:'Twin Fang',    type:'attack', cost:1, rarity:'rare',      art:'🦷', desc:'Deal 6 twice.' },
  rage:        { name:'Berserk',      type:'power',  cost:1, rarity:'rare',      art:'😤', desc:'Gain 2 Strength permanently.' },
  meteor:      { name:'Meteor',       type:'attack', cost:3, rarity:'epic',      art:'☄️', desc:'Deal 11 to ALL enemies, 4 Vulnerable.' },
  lifesteal:   { name:'Vampiric Bite',type:'attack', cost:2, rarity:'epic',      art:'🩸', desc:'Deal 12 and heal 6 HP.' },
  fortress:    { name:'Bulwark',      type:'power',  cost:2, rarity:'epic',      art:'🛡️', desc:'Gain 4 Block at the start of every turn.' },
  apex:        { name:'Apex Nova',    type:'attack', cost:3, rarity:'legendary', art:'🌟', desc:'Deal 9 to ALL, gain 1 Energy & Strength.' },
  singularity: { name:'Singularity',  type:'attack', cost:2, rarity:'legendary', art:'🕳️', desc:'Deal damage = 30% of target max HP.' }
};
const SPIRE_RAR = {
  common:    { label:'Common',    color:'#c8ced4', rank:1, refund:18 },
  uncommon:  { label:'Uncommon',  color:'#88c8f4', rank:2, refund:34 },
  rare:      { label:'Rare',      color:'#ffd76a', rank:3, refund:60 },
  epic:      { label:'Epic',      color:'#caa6f0', rank:4, refund:100 },
  legendary: { label:'Legendary', color:'#f6a6e0', rank:5, refund:170 }
};
const SPIRE_TYPE_COLOR = { attack:'#d06b57', skill:'#5fae93', power:'#a98cdf', relic:'#cba74e' };
const SPIRE_PACK_COST = 200;
const SPIRE_PACK_RATES = [["legendary",4],["epic",9],["rare",20],["uncommon",30],["common",37]];
const SPIRE_MAX_COPIES = 6;     // pack stacking cap per collectible card
const SPIRE_DECK_MAX = 30;
const SPIRE_DECK_MIN = 10;
const SPIRE_BASIC_MAX = 10;     // copies of a free basic you may field

// ---- card-art overrides (admin pictures), mirrors loadSpireOverrides ----
let _spireCardArtCache = null;  // { cardId: url }
function _spireCardArtRef(uid){ return doc(db, 'users', uid, 'settings', 'spireCardArt'); }
async function loadSpireCardArt(force){
  if (_spireCardArtCache && !force) return _spireCardArtCache;
  const uid = _spireOwnerUid();
  if (!uid){ _spireCardArtCache = {}; return _spireCardArtCache; }
  try {
    const snap = await getDoc(_spireCardArtRef(uid));
    _spireCardArtCache = (snap.exists() && snap.data().overrides) ? snap.data().overrides : {};
  } catch (e){ console.warn('spire card art load failed', e); _spireCardArtCache = _spireCardArtCache || {}; }
  return _spireCardArtCache;
}

// ---- deck helpers ----
function spireMaxInDeck(id){
  const c = SPIRE_CARDS[id]; if (!c) return 0;
  if (c.basic) return SPIRE_BASIC_MAX;
  return (rpgState && rpgState.spireCards[id]) || 0;
}
function spireDeckCount(id){ return (rpgState ? rpgState.spireDeck : []).filter(x => x === id).length; }
function spireResolvedDeck(){
  if (!rpgState || !Array.isArray(rpgState.spireDeck)) return [];
  const used = {};
  return rpgState.spireDeck.filter(id => {
    if (!SPIRE_CARDS[id]) return false;
    used[id] = (used[id] || 0) + 1;
    return used[id] <= spireMaxInDeck(id);
  });
}
function spireSyncGame(){ rpgSave(); pushSpireAssets(); }

// ---- packs (spend gold, grant permanent cards) ----
function spireRollRarity(){
  const roll = Math.random() * 100; let acc = 0;
  for (const [r, p] of SPIRE_PACK_RATES){ acc += p; if (roll < acc) return r; }
  return 'common';
}
function _spireRollCard(){
  const rarity = spireRollRarity();
  const pool = Object.keys(SPIRE_CARDS).filter(id => SPIRE_CARDS[id].rarity === rarity && !SPIRE_CARDS[id].basic);
  const id = pool[Math.floor(Math.random() * pool.length)];
  const have = (rpgState.spireCards[id] || 0);
  let refund = 0;
  if (have >= SPIRE_MAX_COPIES){ refund = SPIRE_RAR[rarity].refund; rpgState.gold += refund; }
  else rpgState.spireCards[id] = have + 1;
  return { id, rarity, refund, capped: have >= SPIRE_MAX_COPIES };
}
function spireOpenCardPacks(requested){
  if (!rpgState) return;
  let n = 0, g = rpgState.gold;
  while (n < requested && g >= SPIRE_PACK_COST){ g -= SPIRE_PACK_COST; n++; if (n >= 500) break; }
  if (n < 1){ showToast(`A Spell Pack costs 🪙 ${SPIRE_PACK_COST} — answer more questions to earn points!`, 'error'); return; }
  let spent = 0, refund = 0; const results = [];
  for (let i = 0; i < n; i++){ rpgState.gold -= SPIRE_PACK_COST; spent += SPIRE_PACK_COST; const r = _spireRollCard(); refund += r.refund; results.push(r); }
  rpgState.stats.packsOpened = (rpgState.stats.packsOpened || 0) + n;
  spireSyncGame();
  spireRenderCardPack(results, spent, refund, n);
  spireRenderBook();
}
function spireRenderCardPack(results, spent, refund, n){
  const order = ['legendary','epic','rare','uncommon','common'];
  const sorted = results.slice().sort((a,b) => SPIRE_RAR[b.rarity].rank - SPIRE_RAR[a.rarity].rank);
  const tally = {}; results.forEach(r => tally[r.rarity] = (tally[r.rarity] || 0) + 1);
  const tallyHtml = order.filter(r => tally[r]).map(r =>
    `<span class="spire-pack-rate" style="border-color:${SPIRE_RAR[r].color};color:${SPIRE_RAR[r].color};">${SPIRE_RAR[r].label} ×${tally[r]}</span>`).join('');
  const cards = sorted.map(r => spireMiniCard(r.id, { context:'pack', tag: r.capped ? `dup · +🪙 ${r.refund}` : '✨ new' })).join('');
  const top = sorted[0];
  const head = n === 1
    ? `<div style="text-align:center;font-family:'Cinzel',Georgia,serif;letter-spacing:.06em;color:${SPIRE_RAR[top.rarity].color};font-weight:800;font-size:1.05rem;">${top.rarity==='legendary'?'✦ LEGENDARY ✦':SPIRE_RAR[top.rarity].label}</div>`
    : `<div style="text-align:center;margin-bottom:8px;">${tallyHtml}</div>`;
  const body = document.getElementById('spireCardPackBody');
  if (body) body.innerHTML =
    `${head}<div class="spire-card-grid" style="justify-content:center;margin:12px 0;">${cards}</div>
     <div style="text-align:center;color:#b6a880;font-size:.82rem;">Opened <b>${n}</b> pack${n===1?'':'s'} · spent 🪙 ${spent.toLocaleString()}${refund?` · refunded 🪙 ${refund.toLocaleString()}`:''}</div>`;
  const ov = document.getElementById('spireCardPackOverlay'); if (ov) ov.classList.add('show');
}

// ---- mini gilded card (collection / deck / pack views) ----
function spireCardArtThumb(id){
  const ov = _spireCardArtCache && _spireCardArtCache[id];
  if (ov) return `<img src="${escapeHtml(ov)}" alt="" onerror="this.style.display='none'">`;
  return `<span>${SPIRE_CARDS[id].art}</span>`;
}
function spireMiniCard(id, opts){
  opts = opts || {};
  const c = SPIRE_CARDS[id]; if (!c) return '';
  const gemColor = SPIRE_RAR[c.rarity].color;
  const inDeck = spireDeckCount(id), max = spireMaxInDeck(id);
  let badge = '';
  if (opts.context === 'collection'){
    const owned = c.basic ? '∞' : ((rpgState.spireCards[id] || 0));
    badge = `<div class="sbadge">${inDeck>0?`▶ ${inDeck} · `:''}×${owned}</div>`;
  } else if (opts.tag){ badge = `<div class="sbadge">${escapeHtml(opts.tag)}</div>`; }
  const locked = opts.context === 'collection' && !c.basic && !(rpgState.spireCards[id] > 0);
  const attr = opts.action ? ` data-spire-${opts.action}="${id}"` : '';
  return `<div class="smini ${c.type}${locked?' locked':''}"${attr} title="${escapeHtml(c.name)} — ${escapeHtml(c.desc)}">
    <span class="scost">${c.cost}</span><span class="sgem" style="background:${gemColor};"></span>
    <div class="sart">${locked ? '🔒' : spireCardArtThumb(id)}</div>
    <div class="sname">${escapeHtml(c.name)}</div>
    <div class="smeta">${c.type}${c.rarity!=='common'?` · ${c.rarity}`:''}</div>
    ${badge}
  </div>`;
}

// ---- Spellbook overlay (shop + deck builder) ----
function spireBookOpen(){
  if (!rpgState){ showToast('Sign in to collect cards', 'error'); return; }
  loadSpireCardArt().then(() => { spireRenderBook(); const ov = document.getElementById('spireBookOverlay'); if (ov) ov.classList.add('show'); });
}
function spireRenderBook(){
  const body = document.getElementById('spireBookBody'); if (!body) return;
  const gold = (rpgState && rpgState.gold) || 0;
  const ratesHtml = SPIRE_PACK_RATES.map(([r,p]) =>
    `<span class="spire-pack-rate" style="border-color:${SPIRE_RAR[r].color};color:${SPIRE_RAR[r].color};">${SPIRE_RAR[r].label} ${p}%</span>`).join('');
  const deck = spireResolvedDeck();
  const deckChips = deck.length
    ? deck.map(id => `<span class="spire-deck-chip" data-spire-remove="${id}" title="Remove from deck">${SPIRE_CARDS[id].art} ${escapeHtml(SPIRE_CARDS[id].name)} <span class="x">✕</span></span>`).join('')
    : `<span style="color:#9c8f6c;font-style:italic;align-self:center;">Empty — add at least ${SPIRE_DECK_MIN} cards, or you'll start with the default Strike/Defend deck.</span>`;
  const allIds = Object.keys(SPIRE_CARDS);
  const ownedIds = allIds.filter(id => SPIRE_CARDS[id].basic || (rpgState.spireCards[id] > 0));
  const lockedIds = allIds.filter(id => !SPIRE_CARDS[id].basic && !(rpgState.spireCards[id] > 0));
  const order = id => SPIRE_RAR[SPIRE_CARDS[id].rarity].rank;
  ownedIds.sort((a,b) => order(a) - order(b) || a.localeCompare(b));
  lockedIds.sort((a,b) => order(a) - order(b) || a.localeCompare(b));
  const collection = ownedIds.map(id => spireMiniCard(id, { context:'collection', action:'add' })).join('');
  const locked = lockedIds.map(id => spireMiniCard(id, { context:'collection' })).join('');
  const deckSizeColor = deck.length < SPIRE_DECK_MIN ? '#e8a04a' : '#7be0a2';
  body.innerHTML = `
    <div class="spire-points">🪙 <b>${gold.toLocaleString()}</b> points</div>
    <div class="spire-pack-hero">
      <span class="spire-pack-box">🎁</span>
      <div>
        <h4>Spell Pack</h4>
        <p>One random card from the spire's armoury — the way to grow your collection. Cards you pull are <b>yours forever</b>. Duplicates past ×${SPIRE_MAX_COPIES} refund points.</p>
        <div class="spire-pack-buy">
          <button class="btn btn-primary" type="button" data-spire-pack="1" ${gold < SPIRE_PACK_COST ? 'disabled' : ''}>🎁 Open 1 · 🪙 ${SPIRE_PACK_COST}</button>
          <button class="btn btn-outline" type="button" data-spire-pack="10" ${gold < 10*SPIRE_PACK_COST ? 'disabled' : ''}>Open ×10 · 🪙 ${(10*SPIRE_PACK_COST).toLocaleString()}</button>
          <button class="btn btn-outline" type="button" data-spire-pack="all" ${gold < SPIRE_PACK_COST ? 'disabled' : ''}>Spend all 🪙</button>
        </div>
        <div style="margin-top:8px;">${ratesHtml}</div>
      </div>
    </div>
    <div class="spire-sec-head">Your starting deck <span style="color:${deckSizeColor};font-weight:800;">${deck.length}/${SPIRE_DECK_MAX}</span>
      <button class="btn btn-ghost" type="button" data-spire-deck-clear style="margin-left:auto;font-size:.78rem;">Clear</button></div>
    <div class="spire-deck-strip">${deckChips}</div>
    <div class="spire-sec-head">Collection — click a card to add it to your deck</div>
    <div class="spire-card-grid">${collection}</div>
    ${locked ? `<div class="spire-sec-head" style="opacity:.7;">Not yet collected — open packs to unlock</div><div class="spire-card-grid">${locked}</div>` : ''}
  `;
}
function spireDeckAdd(id){
  if (!rpgState || !SPIRE_CARDS[id]) return;
  if (spireDeckCount(id) >= spireMaxInDeck(id)){ showToast(SPIRE_CARDS[id].basic ? `Max ${SPIRE_BASIC_MAX} copies of a basic` : 'You own no more copies — open packs!', 'error'); return; }
  if (rpgState.spireDeck.length >= SPIRE_DECK_MAX){ showToast(`Deck is full (${SPIRE_DECK_MAX} cards)`, 'error'); return; }
  rpgState.spireDeck.push(id);
  spireSyncGame(); spireRenderBook();
}
function spireDeckRemove(id){
  if (!rpgState) return;
  const i = rpgState.spireDeck.lastIndexOf(id);
  if (i >= 0){ rpgState.spireDeck.splice(i, 1); spireSyncGame(); spireRenderBook(); }
}
function spireDeckClear(){ if (rpgState){ rpgState.spireDeck = []; spireSyncGame(); spireRenderBook(); } }

// ---- ADMIN: card-art override uploader (mirrors the spire sprite uploader) ----
async function _spireCardArtApply(id, dataUrl){
  const status = document.getElementById('scardstatus-' + id);
  try {
    if (status) status.textContent = 'Uploading…';
    if (!/^data:image\//i.test(dataUrl)) throw new Error('Not an image');
    const scaled = await _scaleDownDataUrl(dataUrl, SPIRE_MAX_SIDE);
    const url = await uploadImageDataUrl(scaled);
    const uid = _spireOwnerUid(); if (!uid) throw new Error('Not signed in');
    await setDoc(_spireCardArtRef(uid), { overrides: { [id]: url } }, { merge: true });
    _spireCardArtCache = _spireCardArtCache || {}; _spireCardArtCache[id] = url;
    await pushSpireAssets();
    await loadGameAssets();
    showToast('Card art updated', 'success');
  } catch (e){ console.error('spire card art failed', e); showToast('Update failed: ' + (e && e.message ? e.message : e), 'error'); if (status) status.textContent = 'Failed'; }
}
function onSpireCardPaste(id, e){
  const items = (e.clipboardData && e.clipboardData.items) || [];
  for (const it of items){ if (it.type && it.type.startsWith('image/')){ e.preventDefault(); _raidersFileToDataUrl(it.getAsFile(), du => _spireCardArtApply(id, du)); return; } }
  showToast('No image in clipboard — copy a PNG first', 'error');
}
function onSpireCardDrop(id, e){ e.preventDefault(); if (e.currentTarget) e.currentTarget.classList.remove('drag'); const file = e.dataTransfer && e.dataTransfer.files && e.dataTransfer.files[0]; _raidersFileToDataUrl(file, du => _spireCardArtApply(id, du)); }
function onSpireCardPick(id, e){ const file = e.target && e.target.files && e.target.files[0]; _raidersFileToDataUrl(file, du => _spireCardArtApply(id, du)); if (e.target) e.target.value = ''; }
async function resetSpireCardArt(id){
  try { const uid = _spireOwnerUid(); if (!uid) return;
    await setDoc(_spireCardArtRef(uid), { overrides: { [id]: deleteField() } }, { merge: true });
    if (_spireCardArtCache) delete _spireCardArtCache[id];
    await pushSpireAssets(); await loadGameAssets(); showToast('Reset to default art', 'success');
  } catch (e){ console.error('spire card art reset failed', e); showToast('Reset failed', 'error'); }
}
// Builds the admin "Spire Cards" art-override grid (ga-* markup), appended by
// loadGameAssets after the Spire character section. Returns an HTML string.
function spireCardArtAdminHtml(){
  let html = '<h2 class="ga-game">🃏 Science Spire — Card Art <span style="font-weight:400;font-size:0.8rem;color:#94a3b8;">— paste a PNG to replace any card\'s picture; default is the built-in vector art</span></h2><div class="ga-cards">';
  Object.keys(SPIRE_CARDS).filter(id => !SPIRE_CARDS[id].basic).forEach(id => {
    const c = SPIRE_CARDS[id]; const url = (_spireCardArtCache || {})[id];
    const thumb = url ? ('<img src="' + escapeHtml(url) + '" alt="' + escapeHtml(c.name) + '">') : ('<div style="font-size:34px;line-height:64px;text-align:center;opacity:.7;">' + c.art + '</div>');
    html += '<div class="ga-card" id="scardcard-' + id + '">'
      + '<div class="ga-prev">' + thumb + '</div>'
      + '<div class="ga-name">' + escapeHtml(c.name) + '</div>'
      + '<div class="ga-zone" tabindex="0"'
      +   ' onpaste="onSpireCardPaste(\'' + id + '\', event)"'
      +   ' ondragover="event.preventDefault(); this.classList.add(\'drag\')"'
      +   ' ondragleave="this.classList.remove(\'drag\')"'
      +   ' ondrop="onSpireCardDrop(\'' + id + '\', event)"'
      +   ' onclick="this.focus()">Click, then paste a PNG — or drop one here</div>'
      + '<div class="ga-actions">'
      +   '<label class="btn btn-outline ga-mini">Upload<input type="file" accept="image/*" style="display:none" onchange="onSpireCardPick(\'' + id + '\', event)"></label>'
      +   (url ? '<button class="btn btn-ghost ga-mini" onclick="resetSpireCardArt(\'' + id + '\')">Reset</button>' : '')
      + '</div>'
      + '<div class="ga-status ' + (url ? 'custom' : '') + '" id="scardstatus-' + id + '">' + (url ? '● Custom' : 'Default') + '</div>'
      + '</div>';
  });
  return html + '</div>';
}

// ---- wiring ----
function spireBookWire(){
  const ov = document.getElementById('spireBookOverlay');
  if (ov && !ov._wired){
    ov._wired = true;
    ov.querySelectorAll('[data-close]').forEach(b => b.addEventListener('click', () => ov.classList.remove('show')));
    ov.addEventListener('click', e => { if (e.target === ov) ov.classList.remove('show'); });
    ov.addEventListener('click', e => {
      const pack = e.target.closest('[data-spire-pack]');
      if (pack){ const v = pack.dataset.spirePack; spireOpenCardPacks(v === 'all' ? Infinity : Number(v)); return; }
      if (e.target.closest('[data-spire-deck-clear]')){ spireDeckClear(); return; }
      const add = e.target.closest('[data-spire-add]'); if (add){ spireDeckAdd(add.dataset.spireAdd); return; }
      const rem = e.target.closest('[data-spire-remove]'); if (rem){ spireDeckRemove(rem.dataset.spireRemove); return; }
    });
  }
  const po = document.getElementById('spireCardPackOverlay');
  if (po && !po._wired){
    po._wired = true;
    po.querySelectorAll('[data-close]').forEach(b => b.addEventListener('click', () => po.classList.remove('show')));
    po.addEventListener('click', e => { if (e.target === po) po.classList.remove('show'); });
  }
  const openBtn = document.getElementById('spireBookBtn');
  if (openBtn && !openBtn._wired){ openBtn._wired = true; openBtn.addEventListener('click', spireBookOpen); }
}
spireBookWire();

// =====================================================================
// MESSAGING — admin <-> students (top-level `messages` collection, mirrors how
// `flaggedQuestions` is used: authenticated users create docs and query them).
// A message: { fromUid, fromName, fromRole, toUid ('all' = broadcast), text,
// ts, read, kind ('dm'|'flagReply'), flagId?, questionTitle? }.
// =====================================================================
let _messages = [];
function _myUid() { return currentUser && currentUser.uid; }
function _teacherUid() { return (currentUser && currentUser.role === 'admin') ? currentUser.uid : adminUid; }
function _msgTime(m) { try { return m.ts ? (m.ts.toDate ? m.ts.toDate().getTime() : new Date(m.ts).getTime()) : 0; } catch (e) { return 0; } }

async function _fetchMsgs(field, value) {
  try {
    const snap = await getDocs(query(collection(db, 'messages'), where(field, '==', value)));
    return snap.docs.map(d => ({ ...d.data(), _id: d.id }));
  } catch (e) { console.warn('messages query failed', field, e); return []; }
}
async function loadMessages() {
  const uid = _myUid(); if (!uid) return [];
  const parts = await Promise.all([_fetchMsgs('toUid', uid), _fetchMsgs('fromUid', uid), _fetchMsgs('toUid', 'all')]);
  const map = {};
  parts.flat().forEach(m => { map[m._id] = m; });
  _messages = Object.values(map).sort((a, b) => _msgTime(a) - _msgTime(b));
  return _messages;
}
async function sendMessageDoc(toUid, toName, text, extra) {
  const t = (text || '').trim(); if (!t) return false;
  const u = currentUser; if (!u) return false;
  const data = Object.assign({
    fromUid: u.uid, fromName: u.name || '', fromRole: u.role || 'student',
    toUid: toUid, toName: toName || '', text: t, ts: Timestamp.now(), read: false, kind: 'dm'
  }, extra || {});
  try { await addDoc(collection(db, 'messages'), data); return true; }
  catch (e) { console.error('sendMessage failed', e); showToast('Message failed: ' + (e && e.message ? e.message : e), 'error'); return false; }
}
function _isIncomingUnread(m) {
  const uid = _myUid();
  return !m.read && m.fromUid !== uid && (m.toUid === uid || (currentUser.role === 'student' && m.toUid === 'all'));
}
function unreadCount() { return _messages.filter(_isIncomingUnread).length; }
function updateMsgBadge() {
  const n = unreadCount();
  ['msgUnreadAdmin', 'msgUnreadStudent'].forEach(id => {
    const el = document.getElementById(id);
    if (el) { el.textContent = n; el.style.display = n ? '' : 'none'; }
  });
}
async function _markRead(filterFn) {
  const toMark = _messages.filter(m => _isIncomingUnread(m) && filterFn(m));
  await Promise.all(toMark.map(m => updateDoc(doc(db, 'messages', m._id), { read: true }).then(() => { m.read = true; }).catch(() => {})));
  updateMsgBadge();
}

function _msgBubble(m, mine) {
  const who = mine ? 'You' : (m.fromName || (m.fromRole === 'admin' ? 'Teacher' : 'Student'));
  const ctx = (m.kind === 'flagReply' && m.questionTitle) ? `<div class="msg-ctx">Re: flagged “${escapeHtml(m.questionTitle)}”</div>` : '';
  const time = _msgTime(m) ? formatDateTimeSGT(new Date(_msgTime(m))) : '';
  return `<div class="msg-row ${mine ? 'mine' : ''}"><div class="msg-bubble ${mine ? 'mine' : ''}">${ctx}<div class="msg-who">${escapeHtml(who)}</div><div class="msg-text">${escapeHtml(m.text || '')}</div><div class="msg-time">${escapeHtml(time)}</div></div></div>`;
}

async function loadMessagesPage() {
  const sub = document.getElementById('messagesSubtitle');
  if (sub) sub.textContent = currentUser && currentUser.role === 'admin'
    ? 'Reply to students, or broadcast an announcement to everyone'
    : 'Message your teacher — replies and announcements appear here';
  await loadMessages();
  if (currentUser && currentUser.role === 'admin') renderAdminMessages(); else renderStudentMessages();
  updateMsgBadge();
}

function renderStudentMessages() {
  const c = document.getElementById('messagesContainer'); if (!c) return;
  const uid = currentUser.uid;
  const msgs = _messages.slice().sort((a, b) => _msgTime(a) - _msgTime(b));
  const bubbles = msgs.length ? msgs.map(m => _msgBubble(m, m.fromUid === uid)).join('') : '<div class="msg-empty">No messages yet. Say hello to your teacher 👋</div>';
  const teacher = _teacherUid();
  c.innerHTML = `<div class="msg-card">
      <div class="msg-card-title">💬 Your teacher</div>
      <div class="msg-thread" id="msgThreadScroll">${bubbles}</div>
      <div class="msg-compose">
        <textarea id="studentMsgInput" class="msg-input" rows="2" placeholder="${teacher ? 'Message your teacher…' : 'Teacher not set up yet'}"${teacher ? '' : ' disabled'}></textarea>
        <button class="btn btn-primary" onclick="sendStudentMsg()"${teacher ? '' : ' disabled'}>Send</button>
      </div>
    </div>`;
  const sc = document.getElementById('msgThreadScroll'); if (sc) sc.scrollTop = sc.scrollHeight;
  _markRead(m => m.toUid === uid || m.toUid === 'all');
}

function renderAdminMessages() {
  const c = document.getElementById('messagesContainer'); if (!c) return;
  const me = currentUser.uid;
  const threads = {};
  _messages.forEach(m => {
    let other, name;
    if (m.toUid === 'all') { other = 'all'; name = '📢 All students'; }
    else if (m.fromUid === me) { other = m.toUid; name = m.toName || m.toUid; }
    else { other = m.fromUid; name = m.fromName || m.fromUid; }
    if (!threads[other]) threads[other] = { uid: other, name, msgs: [] };
    if (name && name !== other) threads[other].name = name;
    threads[other].msgs.push(m);
  });
  const list = Object.values(threads).sort((a, b) => _msgTime(b.msgs[b.msgs.length - 1]) - _msgTime(a.msgs[a.msgs.length - 1]));
  let html = `<div class="msg-card">
      <div class="msg-card-title">📢 Broadcast to all students</div>
      <div class="msg-compose">
        <textarea id="adminBroadcastInput" class="msg-input" rows="2" placeholder="Announcement sent to every student…"></textarea>
        <button class="btn btn-primary" onclick="sendBroadcast()">Send to all</button>
      </div>
    </div>`;
  if (!list.length) html += '<div class="msg-empty">No conversations yet. Student messages and your flag replies will appear here.</div>';
  list.forEach(t => {
    const bubbles = t.msgs.slice().sort((a, b) => _msgTime(a) - _msgTime(b)).map(m => _msgBubble(m, m.fromUid === me)).join('');
    if (t.uid === 'all') {
      html += `<div class="msg-card"><div class="msg-card-title">📢 Broadcast history</div><div class="msg-thread">${bubbles}</div></div>`;
      return;
    }
    const unread = t.msgs.filter(m => !m.read && m.fromUid === t.uid).length;
    html += `<div class="msg-card">
        <div class="msg-card-title">${escapeHtml(t.name)} ${unread ? `<span class="msg-unread-dot">${unread} new</span>` : ''}</div>
        <div class="msg-thread">${bubbles}</div>
        <div class="msg-compose">
          <input id="threadInput_${escapeHtml(t.uid)}" class="msg-input" placeholder="Reply to ${escapeHtml(t.name)}…">
          <button class="btn btn-primary" onclick="sendThreadReply('${escapeHtml(t.uid)}')">Send</button>
        </div>
      </div>`;
  });
  c.innerHTML = html;
  _markRead(m => m.toUid === me);
}

async function sendStudentMsg() {
  const t = _teacherUid();
  if (!t) { showToast('Teacher not available yet', 'error'); return; }
  const el = document.getElementById('studentMsgInput'); const text = el ? el.value.trim() : '';
  if (!text) return;
  if (await sendMessageDoc(t, 'Teacher', text)) { el.value = ''; await loadMessagesPage(); }
}
async function sendBroadcast() {
  const el = document.getElementById('adminBroadcastInput'); const text = el ? el.value.trim() : '';
  if (!text) return;
  if (await sendMessageDoc('all', 'All students', text)) { el.value = ''; showToast('Broadcast sent', 'success'); await loadMessagesPage(); }
}
async function sendThreadReply(uid) {
  const el = document.getElementById('threadInput_' + uid); const text = el ? el.value.trim() : '';
  if (!text) return;
  const ref = _messages.find(m => m.fromUid === uid || m.toUid === uid);
  const name = ref ? (ref.fromUid === uid ? ref.fromName : ref.toName) : '';
  if (await sendMessageDoc(uid, name || '', text)) { el.value = ''; await loadMessagesPage(); }
}

// Reply to a flagged question — sends a message to the student who flagged it.
async function replyToFlag(docId) {
  const f = flaggedQuestions.find(x => x._docId === docId); if (!f) return;
  const input = document.getElementById('flagReply_' + docId);
  const text = input ? input.value.trim() : '';
  if (!text) { showToast('Type a reply first', 'error'); return; }
  if (!f.flaggedByUid) { showToast('No student account on this flag', 'error'); return; }
  const ok = await sendMessageDoc(f.flaggedByUid, f.flaggedBy || '', text, { kind: 'flagReply', flagId: docId, questionTitle: f.questionTitle || '' });
  if (!ok) return;
  try { await updateDoc(doc(db, 'flaggedQuestions', docId), { reply: text, repliedAt: Timestamp.now() }); } catch (e) {}
  f.reply = text;
  showToast('Reply sent to ' + (f.flaggedBy || 'student'), 'success');
  renderFlaggedQuestions();
}

